INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35141, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "国", "is_correct": true, "explanation": "政府や法律を持つ政治的なまとまりとして、「国は法律を作る」という文に合う。"}, {"text": "椅子", "is_correct": false, "explanation": "座る家具で、法律を作る主体にはならない。"}, {"text": "花", "is_correct": false, "explanation": "植物で、法律を作ることはできないので文が成り立たない。"}, {"text": "魚", "is_correct": false, "explanation": "生き物で、国民のために法律を作ることはない。"}], "explanations": {"国": "政府や法律を持つ政治的なまとまりとして、「国は法律を作る」という文に合う。", "椅子": "座る家具で、法律を作る主体にはならない。", "花": "植物で、法律を作ることはできないので文が成り立たない。", "魚": "生き物で、国民のために法律を作ることはない。"}, "sentence_index": 0, "correct_answer": "国"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "国は、来月の上映会で主人公が冒険する。", "explanation": "上映会で主人公が冒険するのは「映画」。「国」は政治的なまとまりなので、作品には使わない。"}, {"text": "国は、来月の卒業式で校歌を歌う。", "explanation": "卒業式で校歌を歌うのは「生徒」。「国」は政治的なまとまりなので、歌を歌う主体にはならない。"}, {"text": "国は、家の中のルールを作ります。", "explanation": "家の中のルールを決めるのは「家族」。「国」は社会全体の法律を作るもので、家庭内のルールには合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc1fa91a-7aca-4910-94dc-199f440e31bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35141, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "国", "is_correct": true, "explanation": "選挙を行い、国民が参加する政治的な区分を指すので、「その国では選挙に行ける」と自然につながる。"}, {"text": "傘", "is_correct": false, "explanation": "雨具で、選挙の行われる区分にはならない。"}, {"text": "皿", "is_correct": false, "explanation": "食器で、選挙制度の話には合わない。"}, {"text": "靴", "is_correct": false, "explanation": "履く物で、選挙に行ける場所を示す語としては合わない。"}], "explanations": {"国": "選挙を行い、国民が参加する政治的な区分を指すので、「その国では選挙に行ける」と自然につながる。", "傘": "雨具で、選挙の行われる区分にはならない。", "皿": "食器で、選挙制度の話には合わない。", "靴": "履く物で、選挙に行ける場所を示す語としては合わない。"}, "sentence_index": 6, "correct_answer": "国"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この国は冬に着ると暖かい。", "explanation": "冬に着ると暖かいのは「セーター」。「国」は政治的なまとまりなので、衣類には使わない。"}, {"text": "国は柔らかくて、寝ると気持ちがいい。", "explanation": "寝ると気持ちがいいのは「ベッド」。「国」は政治的な区分なので、家具には使わない。"}, {"text": "国は、お坊さんが毎朝お経をあげる場所です。", "explanation": "お経をあげる場所は「寺」。「国」は政治的なまとまりで、宗教の場所とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc1fa91a-7aca-4910-94dc-199f440e31bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35141, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この国が政府は、来年から学費を無料にすると発表しました。", "corrected_sentence": "この国の政府は、来年から学費を無料にすると発表しました。", "error_description": "「国の政府」と、国を政府の所属先として「の」で結ぶのが正しい。「国が政府は」は主語が二つ並び、不自然になる。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc1fa91a-7aca-4910-94dc-199f440e31bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35141, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "隣の国を国境の問題で話し合っています。", "corrected_sentence": "隣の国と国境の問題で話し合っています。", "error_description": "話し合う相手は「と」で示す。「国を」は目的語になり、「話し合う」の相手として文が成り立たない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc1fa91a-7aca-4910-94dc-199f440e31bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35142, 3, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc1fa91a-7aca-4910-94dc-199f440e31bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
