INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35142, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "あるものをこえて、むこうへいく。", "primary_collocate": null, "pronunciation": "こえる", "ipa": "koeɾɯ", "syllable_count": 3, "sentences": [{"text": "山を越えると、小さな村が見えてきます。", "target_word": "越える", "complexity_tier": "T3", "furigana": "山[やま]を越[こ]えると、小[ちい]さな村[むら]が見[み]えてきます。", "sentence_source": "generated"}, {"text": "電車は国境を越えて、となりの国へ入りました。", "target_word": "越えて", "complexity_tier": "T4", "furigana": "電車[でんしゃ]は国境[こっきょう]を越[こ]えて、となりの国[くに]へ入[はい]りました。", "sentence_source": "generated"}, {"text": "私たちは朝早く、峠を越えました。", "target_word": "越えました", "complexity_tier": "T3", "furigana": "私[わたし]たちは朝早[あさはや]く、峠[とうげ]を越[こ]えました。", "sentence_source": "generated"}, {"text": "川を越えた所に、大きな公園があります。", "target_word": "越えた", "complexity_tier": "T3", "furigana": "川[かわ]を越[こ]えた所[ところ]に、大[おお]きな公園[こうえん]があります。", "sentence_source": "generated"}, {"text": "鳥は海を越えて、あたたかい国へ飛んでいきます。", "target_word": "越えて", "complexity_tier": "T3", "furigana": "鳥[とり]は海[うみ]を越[こ]えて、あたたかい国[くに]へ飛[と]んでいきます。", "sentence_source": "generated"}, {"text": "この谷を越えれば、目的地はもうすぐです。", "target_word": "越えれば", "complexity_tier": "T4", "furigana": "この谷[たに]を越[こ]えれば、目的地[もくてきち]はもうすぐです。", "sentence_source": "generated"}, {"text": "雪の山は危ないので、越えない方がいいと、ガイドが言いました。", "target_word": "越えない", "complexity_tier": "T4", "furigana": "雪[ゆき]の山[やま]は危[あぶ]ないので、越[こ]えない方[ほう]がいいと、ガイドが言[い]いました。", "sentence_source": "generated"}, {"text": "あの森を越えれば、目的の町に着きます。", "target_word": "越えれば", "complexity_tier": "T3", "furigana": "あの森[もり]を越[こ]えれば、目的[もくてき]の町[まち]に着[つ]きます。", "sentence_source": "generated"}, {"text": "ボールがフェンスを越えて、道に落ちました。", "target_word": "越えて", "complexity_tier": "T3", "furigana": "ボールがフェンスを越[こ]えて、道[みち]に落[お]ちました。", "sentence_source": "generated"}, {"text": "あの丘を越えたら、海が見えるはずです。", "target_word": "越えた", "complexity_tier": "T3", "furigana": "あの丘[おか]を越[こ]えたら、海[うみ]が見[み]えるはずです。", "sentence_source": "generated"}], "morphological_forms": [{"form": "越えます", "label": "ます形"}, {"form": "越えて", "label": "て形"}, {"form": "越えた", "label": "た形"}, {"form": "越えない", "label": "ない形"}], "register": "丁寧", "sense_fingerprint": "山・川・境などを通り越して向こう側へ行く", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '82bc3f5f-a777-4e8f-a68b-12799a2d2b95') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35142, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "越える", "is_correct": true, "explanation": "山を通り過ぎて向こうへ行く意味で、「山を越えると村が見える」と自然に続く。"}, {"text": "磨く", "is_correct": false, "explanation": "表面をみがく動作で、山を対象にしても村が見える話にはならない。"}, {"text": "織る", "is_correct": false, "explanation": "糸で布を作る動作で、山を対象にする文として合わない。"}, {"text": "煮る", "is_correct": false, "explanation": "食材を熱する動作で、山を対象にすると文が成り立たない。"}], "explanations": {"越える": "山を通り過ぎて向こうへ行く意味で、「山を越えると村が見える」と自然に続く。", "磨く": "表面をみがく動作で、山を対象にしても村が見える話にはならない。", "織る": "糸で布を作る動作で、山を対象にする文として合わない。", "煮る": "食材を熱する動作で、山を対象にすると文が成り立たない。"}, "sentence_index": 0, "correct_answer": "越える"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "友達はケーキを越えて、庭へ走っていった。", "explanation": "ケーキを通り過ぎる場面は「越える」に合わない。「越える」は山や川などを通り過ぎる意味なので、食べ物には使わない。"}, {"text": "来月、隣の町へ越えて、新しい家に住みます。", "explanation": "住まいを変えるときは「越す」（引っ越す）。「越える」は境や山を通り過ぎる意味なので、住まいには使わない。"}, {"text": "私たちはバスを越えて駅へ行きました。", "explanation": "バスに乗る動作は「乗る」。「越える」は山や川などを通り過ぎるときに使うので、乗り物には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc1fa91a-7aca-4910-94dc-199f440e31bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35142, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "越えない", "is_correct": true, "explanation": "「越えない方がいい」と、山を通り過ぎることを避ける忠告の形として自然に続く。"}, {"text": "借りない", "is_correct": false, "explanation": "借りる動作を否定する形で、山を対象にすると「借りない方がいい」は意味が合わない。"}, {"text": "洗わない", "is_correct": false, "explanation": "洗う動作の否定形で、山を対象にする忠告としては合わない。"}, {"text": "縫わない", "is_correct": false, "explanation": "布などを縫う動作の否定形で、山には使えない。"}], "explanations": {"越えない": "「越えない方がいい」と、山を通り過ぎることを避ける忠告の形として自然に続く。", "借りない": "借りる動作を否定する形で、山を対象にすると「借りない方がいい」は意味が合わない。", "洗わない": "洗う動作の否定形で、山を対象にする忠告としては合わない。", "縫わない": "布などを縫う動作の否定形で、山には使えない。"}, "sentence_index": 6, "correct_answer": "越えない"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "あの階段を越えたら、屋上に出られます。", "explanation": "階段は上るもの。「上る」が正しく、「越える」は境を通り過ぎる意味なので階段には合わない。"}, {"text": "彼はノートを越えて、宿題を始めた。", "explanation": "ノートに書き込むのは「書く」。「越える」は山や川などを通り過ぎる意味なので、ノートには使わない。"}, {"text": "彼女はピアノを越えて、きれいな音を出した。", "explanation": "楽器を演奏する動作は「弾く」。「越える」は境や山を通り過ぎる意味で、楽器には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc1fa91a-7aca-4910-94dc-199f440e31bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35142, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "あの峠に越えたら、町が見えるはずです。", "corrected_sentence": "あの峠を越えたら、町が見えるはずです。", "error_description": "「越える」は通り過ぎる対象に「を」を取る。「峠に越える」は場所を示す「に」が誤りで、「峠を越える」が正しい。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "越えて", "is_correct": true, "explanation": "「国境を越えて、となりの国へ入りました」と、動作をつなぐ「て形」。"}, {"text": "越えよう", "is_correct": false, "explanation": "意志の形で、過去に国境を越えた事実と合わず、文が成り立たない。"}, {"text": "越えます", "is_correct": false, "explanation": "「ます形」は文を終える形で、「越えます、となりの国へ」と続けられない。"}, {"text": "越えない", "is_correct": false, "explanation": "「ない形」は否定を表すので、国境を越えた事実と矛盾する。"}], "correct_form": "越えて", "base_form": "越える", "form_label": "て形", "sentence_index": 1, "explanations": {"越えて": "「国境を越えて、となりの国へ入りました」と、動作をつなぐ「て形」。", "越えよう": "意志の形で、過去に国境を越えた事実と合わず、文が成り立たない。", "越えます": "「ます形」は文を終える形で、「越えます、となりの国へ」と続けられない。", "越えない": "「ない形」は否定を表すので、国境を越えた事実と矛盾する。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc1fa91a-7aca-4910-94dc-199f440e31bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35142, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "あの山へ越えれば、古い宿場町に着きます。", "corrected_sentence": "あの山を越えれば、古い宿場町に着きます。", "error_description": "「越える」は通り過ぎる対象に「を」を取る。「山へ越える」は方向を示す「へ」が誤りで、「山を越える」が正しい。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "越えれば", "is_correct": true, "explanation": "「あの森を越えれば、目的の町に着きます」と、条件を表す「ば形」として文に合う。"}, {"text": "越えろ", "is_correct": false, "explanation": "命令形で、「越えろ、目的の町に着きます」と文が続かず、条件の文にもならない。"}, {"text": "越えた", "is_correct": false, "explanation": "過去の形で、条件を表す「ば」と続かず、「越えた、目的の町に着きます」は文として成り立たない。"}, {"text": "越えさせる", "is_correct": false, "explanation": "使役の形で、人に越えさせる意味になり、この文の内容と合わない。"}], "correct_form": "越えれば", "base_form": "越える", "form_label": "仮定形（ば形）", "sentence_index": 7, "explanations": {"越えれば": "「あの森を越えれば、目的の町に着きます」と、条件を表す「ば形」として文に合う。", "越えろ": "命令形で、「越えろ、目的の町に着きます」と文が続かず、条件の文にもならない。", "越えた": "過去の形で、条件を表す「ば」と続かず、「越えた、目的の町に着きます」は文として成り立たない。", "越えさせる": "使役の形で、人に越えさせる意味になり、この文の内容と合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc1fa91a-7aca-4910-94dc-199f440e31bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35146, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "へ", "options": [{"text": "へ", "is_correct": true, "explanation": "「海へ行く」で行き先を示す。正しい。"}, {"text": "で", "is_correct": false, "explanation": "「海で行く」は場所での動作になり、移動の方向を示せない。"}, {"text": "が", "is_correct": false, "explanation": "「海が行く」は海を主語にする文で、友達と行く文脈に合わない。"}, {"text": "の", "is_correct": false, "explanation": "「海の行く予定」は連体修飾になり、行き先が示せない。"}], "correct_answer": "へ", "explanations": {"へ": "「海へ行く」で行き先を示す。正しい。", "で": "「海で行く」は場所での動作になり、移動の方向を示せない。", "が": "「海が行く」は海を主語にする文で、友達と行く文脈に合わない。", "の": "「海の行く予定」は連体修飾になり、行き先が示せない。"}, "error_tags": {"へ": "方向", "で": "動作の場所", "が": "主語", "の": "連体修飾"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "来る", "is_correct": true, "explanation": "「行く」の対義語。離れる方向の行くに対し、話し手の方へ向かう来るが対になる。"}, {"text": "食べる", "is_correct": false, "explanation": "動作の種類が違い、「行く」の対義語ではない。"}, {"text": "話す", "is_correct": false, "explanation": "移動の動詞ではなく、「行く」の対義語ではない。"}, {"text": "買う", "is_correct": false, "explanation": "移動ではなく取引の動詞で、「行く」の対義語ではない。"}], "correct_answer": "来る", "explanations": {"来る": "「行く」の対義語。離れる方向の行くに対し、話し手の方へ向かう来るが対になる。", "食べる": "動作の種類が違い、「行く」の対義語ではない。", "話す": "移動の動詞ではなく、「行く」の対義語ではない。", "買う": "移動ではなく取引の動詞で、「行く」の対義語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc1fa91a-7aca-4910-94dc-199f440e31bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35146, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「返しに行く」で目的を示す。正しい。"}, {"text": "を", "is_correct": false, "explanation": "「返しを行く」は目的を示せず、文が成立しない。"}, {"text": "で", "is_correct": false, "explanation": "「返しで行く」は手段のように読め、目的の意味にならない。"}, {"text": "が", "is_correct": false, "explanation": "「返しが行く」は主語にする文として不自然。"}], "correct_answer": "に", "explanations": {"に": "「返しに行く」で目的を示す。正しい。", "を": "「返しを行く」は目的を示せず、文が成立しない。", "で": "「返しで行く」は手段のように読め、目的の意味にならない。", "が": "「返しが行く」は主語にする文として不自然。"}, "error_tags": {"に": "目的", "を": "目的語", "で": "手段", "が": "主語"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "来る", "is_correct": true, "explanation": "「行く」の対義語。話し手の方へ向かう意味で、行くと対になる。"}, {"text": "歩く", "is_correct": false, "explanation": "移動の仕方であり、「行く」の対義語ではない。"}, {"text": "書く", "is_correct": false, "explanation": "文字を記す動作で移動ではないため、「行く」の対義語ではない。"}, {"text": "読む", "is_correct": false, "explanation": "目で文字を追う動作で移動ではないため、「行く」の対義語ではない。"}], "correct_answer": "来る", "explanations": {"来る": "「行く」の対義語。話し手の方へ向かう意味で、行くと対になる。", "歩く": "移動の仕方であり、「行く」の対義語ではない。", "書く": "文字を記す動作で移動ではないため、「行く」の対義語ではない。", "読む": "目で文字を追う動作で移動ではないため、「行く」の対義語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc1fa91a-7aca-4910-94dc-199f440e31bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35146, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "どこかへ いく こと。", "primary_collocate": null, "pronunciation": "いく", "ipa": "ikɯ", "syllable_count": 2, "sentences": [{"text": "毎朝、八時に学校へ行きます。", "target_word": "行きます", "complexity_tier": "T2", "furigana": "毎朝[まいあさ]、八時[はちじ]に学校[がっこう]へ行[い]きます。", "sentence_source": "generated"}, {"text": "明日は友達と海へ行く予定です。", "target_word": "行く", "complexity_tier": "T2", "furigana": "明日[あした]は友達[ともだち]と海[うみ]へ行[い]く予定[よてい]です。", "sentence_source": "generated"}, {"text": "病院へ行ったら、先生がやさしく話してくれました。", "target_word": "行った", "complexity_tier": "T3", "furigana": "病院[びょういん]へ行[い]ったら、先生[せんせい]がやさしく話[はな]してくれました。", "sentence_source": "generated"}, {"text": "日曜日に、家族でデパートへ行きます。", "target_word": "行きます", "complexity_tier": "T2", "furigana": "日曜日[にちようび]に、家族[かぞく]でデパートへ行[い]きます。", "sentence_source": "generated"}, {"text": "雨がふっているので、外には行きたくありません。", "target_word": "行きたく", "complexity_tier": "T3", "furigana": "雨[あめ]がふっているので、外[そと]には行[い]きたくありません。", "sentence_source": "generated"}, {"text": "駅までは歩いて行く方が早いです。", "target_word": "行く", "complexity_tier": "T3", "furigana": "駅[えき]までは歩[ある]いて行[い]く方[ほう]が早[はや]いです。", "sentence_source": "generated"}, {"text": "私はまだ京都に行ったことがありません。", "target_word": "行った", "complexity_tier": "T3", "furigana": "私[わたし]はまだ京都[きょうと]に行[い]ったことがありません。", "sentence_source": "generated"}, {"text": "図書館へ本をかえしに行きます。", "target_word": "行きます", "complexity_tier": "T3", "furigana": "図書館[としょかん]へ本[ほん]をかえしに行[い]きます。", "sentence_source": "generated"}, {"text": "夏休みに、おばあさんの家へ行って、スイカを食べました。", "target_word": "行って", "complexity_tier": "T4", "furigana": "夏休[なつやす]みに、おばあさんの家[いえ]へ行[い]って、スイカを食[た]べました。", "sentence_source": "generated"}, {"text": "今夜は、レストランへ行かないで、家で食べましょう。", "target_word": "行かない", "complexity_tier": "T4", "furigana": "今夜[こんや]は、レストランへ行[い]かないで、家[いえ]で食[た]べましょう。", "sentence_source": "generated"}], "morphological_forms": [{"form": "行きます", "label": "ます形"}, {"form": "行って", "label": "て形"}, {"form": "行った", "label": "た形"}, {"form": "行かない", "label": "ない形"}], "register": "丁寧", "sense_fingerprint": "今いる所から別の場所へ移動する", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '82bc3f5f-a777-4e8f-a68b-12799a2d2b95') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35146, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "行きます", "is_correct": true, "explanation": "「学校へ行きます」で、毎朝の習慣を丁寧に述べる動詞。正しい。"}, {"text": "食べます", "is_correct": false, "explanation": "「学校へ食べます」は意味が通らない。場所への移動を表せない。"}, {"text": "読みます", "is_correct": false, "explanation": "「学校へ読みます」は文が成立しない。移動の動詞ではない。"}, {"text": "洗います", "is_correct": false, "explanation": "「学校へ洗います」は意味が通らない。移動の意味がない。"}], "explanations": {"行きます": "「学校へ行きます」で、毎朝の習慣を丁寧に述べる動詞。正しい。", "食べます": "「学校へ食べます」は意味が通らない。場所への移動を表せない。", "読みます": "「学校へ読みます」は文が成立しない。移動の動詞ではない。", "洗います": "「学校へ洗います」は意味が通らない。移動の意味がない。"}, "sentence_index": 0, "correct_answer": "行きます"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "友達が、私の部屋に行きました。", "explanation": "ここは〈来る〉の意味。相手が話し手のいる部屋に向かった場合は〈来る〉を使い、〈行く〉は話し手のいる所から離れる移動に使う。"}, {"text": "先生が、私の家に行きます。", "explanation": "ここは〈来る〉の意味。話し手の家へ相手が向かう場合は〈来る〉を使い、〈行く〉とは言わない。"}, {"text": "届いた荷物は、今朝、玄関へ行きました。", "explanation": "ここは〈届く・着く〉の意味。物が主語のときは〈行く〉を使わず、〈届く〉を使う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc1fa91a-7aca-4910-94dc-199f440e31bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35146, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "行った", "is_correct": true, "explanation": "「〜たことがある」で経験を表す形。正しい。"}, {"text": "食べた", "is_correct": false, "explanation": "「京都に食べたことがない」は意味が通らない。"}, {"text": "読んだ", "is_correct": false, "explanation": "「京都に読んだことがない」は文として成立しない。"}, {"text": "洗った", "is_correct": false, "explanation": "「京都に洗ったことがない」は意味が通らない。"}], "explanations": {"行った": "「〜たことがある」で経験を表す形。正しい。", "食べた": "「京都に食べたことがない」は意味が通らない。", "読んだ": "「京都に読んだことがない」は文として成立しない。", "洗った": "「京都に洗ったことがない」は意味が通らない。"}, "sentence_index": 6, "correct_answer": "行った"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "祖父は、穏やかに行きました。", "explanation": "ここは〈亡くなる（逝く）〉の意味。どこかへ移動する〈行く〉の意味では合わない。"}, {"text": "窓の外の景色が次々と行った。", "explanation": "ここは〈過ぎる〉の意味。景色が通り過ぎる場合は〈過ぎる〉を使い、〈行く〉は使わない。"}, {"text": "この薬は、子どもにも行きます。", "explanation": "ここは〈効く〉の意味。薬の効き目を表すのは〈効く〉で、〈行く〉とは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc1fa91a-7aca-4910-94dc-199f440e31bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35146, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "週末、家族と山で行く予定です。", "corrected_sentence": "週末、家族と山へ行く予定です。", "error_description": "「行く」の行き先を示す助詞が「で」になっている。方向を表す「へ」が正しい。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "行く", "is_correct": true, "explanation": "「予定」を修飾する辞書形。ここでは正しい形。"}, {"text": "行った", "is_correct": false, "explanation": "過去形。これから行く予定の文に合わない。"}, {"text": "行って", "is_correct": false, "explanation": "て形は「予定」を直接修飾できない。文が成立しない。"}, {"text": "行き", "is_correct": false, "explanation": "連用形で、文を言い切れず「予定」にも直接続かない。文が成立しない。"}], "correct_form": "行く", "base_form": "行く", "form_label": "辞書形", "sentence_index": 1, "explanations": {"行く": "「予定」を修飾する辞書形。ここでは正しい形。", "行った": "過去形。これから行く予定の文に合わない。", "行って": "て形は「予定」を直接修飾できない。文が成立しない。", "行き": "連用形で、文を言い切れず「予定」にも直接続かない。文が成立しない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc1fa91a-7aca-4910-94dc-199f440e31bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35146, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "昨日、友達と映画館へ行かった。", "corrected_sentence": "昨日、友達と映画館へ行った。", "error_description": "「行く」の過去形が誤って「行かった」になっている。正しい過去形は「行った」。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "行きます", "is_correct": true, "explanation": "ます形。丁寧な文の中で「返しに行きます」と予定を述べる正しい形。"}, {"text": "行き", "is_correct": false, "explanation": "連用形で、丁寧な文を言い切れない。文が成立しない。"}, {"text": "行けば", "is_correct": false, "explanation": "仮定形は条件節になり、文を言い切れない。"}, {"text": "行か", "is_correct": false, "explanation": "未然形だけでは文を言い切れず、文が成立しない。"}], "correct_form": "行きます", "base_form": "行く", "form_label": "ます形", "sentence_index": 7, "explanations": {"行きます": "ます形。丁寧な文の中で「返しに行きます」と予定を述べる正しい形。", "行き": "連用形で、丁寧な文を言い切れない。文が成立しない。", "行けば": "仮定形は条件節になり、文を言い切れない。", "行か": "未然形だけでは文を言い切れず、文が成立しない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc1fa91a-7aca-4910-94dc-199f440e31bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35150, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「科学が進歩して」で主語を示す。正しい。"}, {"text": "を", "is_correct": false, "explanation": "「科学を進歩して」は目的語にできず、文が成立しない。"}, {"text": "に", "is_correct": false, "explanation": "「科学に進歩して」は意味が通らない。"}, {"text": "の", "is_correct": false, "explanation": "「科学の進歩して」は連体修飾にならず、文が成立しない。"}], "correct_answer": "が", "explanations": {"が": "「科学が進歩して」で主語を示す。正しい。", "を": "「科学を進歩して」は目的語にできず、文が成立しない。", "に": "「科学に進歩して」は意味が通らない。", "の": "「科学の進歩して」は連体修飾にならず、文が成立しない。"}, "error_tags": {"が": "主語", "を": "目的語", "に": "位置・対象", "の": "連体修飾"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc1fa91a-7aca-4910-94dc-199f440e31bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35150, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「科学のテスト」で名詞を修飾する。正しい。"}, {"text": "が", "is_correct": false, "explanation": "「科学がテスト」は意味が通らない。"}, {"text": "を", "is_correct": false, "explanation": "「科学をテスト」は目的語として成立しない。"}, {"text": "に", "is_correct": false, "explanation": "「科学にテスト」は文脈に合わない。"}], "correct_answer": "の", "explanations": {"の": "「科学のテスト」で名詞を修飾する。正しい。", "が": "「科学がテスト」は意味が通らない。", "を": "「科学をテスト」は目的語として成立しない。", "に": "「科学にテスト」は文脈に合わない。"}, "error_tags": {"の": "連体修飾", "が": "主語", "を": "目的語", "に": "位置"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc1fa91a-7aca-4910-94dc-199f440e31bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35150, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "世界のことを、よくしらべて、せつめいすること。", "primary_collocate": null, "pronunciation": "かがく", "ipa": "kaɡakɯ", "syllable_count": 3, "sentences": [{"text": "科学の授業で、水が氷になる実験をしました。", "target_word": "科学", "complexity_tier": "T3", "furigana": "科学[かがく]の授業[じゅぎょう]で、水[みず]が氷[こおり]になる実験[じっけん]をしました。", "sentence_source": "generated"}, {"text": "科学が進歩して、病気がなおる人が増えました。", "target_word": "科学", "complexity_tier": "T3", "furigana": "科学[かがく]が進歩[しんぽ]して、病気[びょうき]がなおる人[ひと]が増[ふ]えました。", "sentence_source": "generated"}, {"text": "私は科学が好きなので、将来は研究の仕事をしたいです。", "target_word": "科学", "complexity_tier": "T4", "furigana": "私[わたし]は科学[かがく]が好[す]きなので、将来[しょうらい]は研究[けんきゅう]の仕事[しごと]をしたいです。", "sentence_source": "generated"}, {"text": "この不思議な現象は、科学で説明することができます。", "target_word": "科学", "complexity_tier": "T4", "furigana": "この不思議[ふしぎ]な現象[げんしょう]は、科学[かがく]で説明[せつめい]することができます。", "sentence_source": "generated"}, {"text": "昔の人が信じていたことが、科学で間違いだとわかりました。", "target_word": "科学", "complexity_tier": "T4", "furigana": "昔[むかし]の人[ひと]が信[しん]じていたことが、科学[かがく]で間違[まちが]いだとわかりました。", "sentence_source": "generated"}, {"text": "科学の本を読むと、宇宙のことがよくわかります。", "target_word": "科学", "complexity_tier": "T3", "furigana": "科学[かがく]の本[ほん]を読[よ]むと、宇宙[うちゅう]のことがよくわかります。", "sentence_source": "generated"}, {"text": "科学は、世界のしくみを調べて明らかにする学問です。", "target_word": "科学", "complexity_tier": "T4", "furigana": "科学[かがく]は、世界[せかい]のしくみを調[しら]べて明[あき]らかにする学問[がくもん]です。", "sentence_source": "generated"}, {"text": "弟は科学のテストで、百点をとりました。", "target_word": "科学", "complexity_tier": "T3", "furigana": "弟[おとうと]は科学[かがく]のテストで、百点[ひゃくてん]をとりました。", "sentence_source": "generated"}, {"text": "科学のおかげで、私たちの生活は便利になりました。", "target_word": "科学", "complexity_tier": "T3", "furigana": "科学[かがく]のおかげで、私[わたし]たちの生活[せいかつ]は便利[べんり]になりました。", "sentence_source": "generated"}, {"text": "科学の力で、地球の環境を守る方法を考えています。", "target_word": "科学", "complexity_tier": "T4", "furigana": "科学[かがく]の力[ちから]で、地球[ちきゅう]の環境[かんきょう]を守[まも]る方法[ほうほう]を考[かんが]えています。", "sentence_source": "generated"}], "morphological_forms": [{"form": "科学", "label": "基本形"}], "register": "丁寧", "sense_fingerprint": "自然や世界のしくみを調べて説明する学問", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 1 above tier T2: contains vocabulary far above tier T2: なおる (Zipf 2.48)']::text[], '82bc3f5f-a777-4e8f-a68b-12799a2d2b95') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35150, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "科学", "is_correct": true, "explanation": "「科学の授業」で、実験を行う学問の授業。正しい。"}, {"text": "体育", "is_correct": false, "explanation": "「体育の授業で水が氷になる実験」は内容が合わない。"}, {"text": "音楽", "is_correct": false, "explanation": "「音楽の授業で水が氷になる実験」は内容が合わない。"}, {"text": "国語", "is_correct": false, "explanation": "「国語の授業で水が氷になる実験」は内容が合わない。"}], "explanations": {"科学": "「科学の授業」で、実験を行う学問の授業。正しい。", "体育": "「体育の授業で水が氷になる実験」は内容が合わない。", "音楽": "「音楽の授業で水が氷になる実験」は内容が合わない。", "国語": "「国語の授業で水が氷になる実験」は内容が合わない。"}, "sentence_index": 0, "correct_answer": "科学"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この薬は、科学の成分で作られています。", "explanation": "ここは〈化学〉の意味。物質の成分を指すのは〈化学〉で、学問の分野を指す〈科学〉とは合わない。"}, {"text": "彼は科学が豊富で、歴史の質問に何でも答える。", "explanation": "ここは〈知識〉の意味。知識の量を表すのは〈知識〉で、〈科学〉は豊富さの対象にならない。"}, {"text": "職人の科学は、長年の修業で身につきます。", "explanation": "ここは〈技術〉の意味。職人の腕前は〈技術〉で、〈科学〉とは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc1fa91a-7aca-4910-94dc-199f440e31bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35150, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "科学", "is_correct": true, "explanation": "「世界のしくみを調べて明らかにする学問」を指す。正しい。"}, {"text": "音楽", "is_correct": false, "explanation": "音楽は世界のしくみを調べる学問ではなく、文の内容に合わない。"}, {"text": "料理", "is_correct": false, "explanation": "料理は世界のしくみを調べる学問ではなく、文の内容に合わない。"}, {"text": "手芸", "is_correct": false, "explanation": "手芸は世界のしくみを調べる学問ではなく、文の内容に合わない。"}], "explanations": {"科学": "「世界のしくみを調べて明らかにする学問」を指す。正しい。", "音楽": "音楽は世界のしくみを調べる学問ではなく、文の内容に合わない。", "料理": "料理は世界のしくみを調べる学問ではなく、文の内容に合わない。", "手芸": "手芸は世界のしくみを調べる学問ではなく、文の内容に合わない。"}, "sentence_index": 6, "correct_answer": "科学"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は科学で、人生の意味をいつも考えている。", "explanation": "ここは〈哲学〉の意味。人生の意味を考えるのは〈哲学〉で、自然のしくみを調べる〈科学〉とは合わない。"}, {"text": "その絵は、科学の表現がとても豊かだ。", "explanation": "ここは〈芸術〉の意味。絵の表現は〈芸術〉で、〈科学〉の表現とは言わない。"}, {"text": "ピアノの科学で、聴く人を感動させた。", "explanation": "ここは〈演奏〉の意味。人を感動させるのは演奏で、〈科学〉では表せない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc1fa91a-7aca-4910-94dc-199f440e31bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
