INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35150, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "先生は科学の知識を豊富です。", "corrected_sentence": "先生は科学の知識が豊富です。", "error_description": "「豊富」は形容動詞で、主語を示すには「が」を使う。「を」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc1fa91a-7aca-4910-94dc-199f440e31bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35152, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「考えが顔に出る」で主語を示す。正しい。"}, {"text": "で", "is_correct": false, "explanation": "「考えで顔に出る」は手段の意味にならず不自然。"}, {"text": "に", "is_correct": false, "explanation": "「考えに顔に出る」は文として成立しない。"}, {"text": "の", "is_correct": false, "explanation": "「考えの顔に出る」は連体修飾として成立しない。"}], "correct_answer": "が", "explanations": {"が": "「考えが顔に出る」で主語を示す。正しい。", "で": "「考えで顔に出る」は手段の意味にならず不自然。", "に": "「考えに顔に出る」は文として成立しない。", "の": "「考えの顔に出る」は連体修飾として成立しない。"}, "error_tags": {"が": "主語", "で": "手段", "に": "位置", "の": "連体修飾"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc1fa91a-7aca-4910-94dc-199f440e31bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35152, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「考えがわからない」で、わからない対象の主語を示す。正しい。"}, {"text": "を", "is_correct": false, "explanation": "「わからない」は「が」で対象を示すため、「考えをわからない」は不自然。"}, {"text": "と", "is_correct": false, "explanation": "「考えとわからない」は並列や引用の形にならず、文が成立しない。"}, {"text": "へ", "is_correct": false, "explanation": "「考えへわからない」は方向を表せず、文が成立しない。"}], "correct_answer": "が", "explanations": {"が": "「考えがわからない」で、わからない対象の主語を示す。正しい。", "を": "「わからない」は「が」で対象を示すため、「考えをわからない」は不自然。", "と": "「考えとわからない」は並列や引用の形にならず、文が成立しない。", "へ": "「考えへわからない」は方向を表せず、文が成立しない。"}, "error_tags": {"が": "主語", "を": "目的語", "と": "並列", "へ": "方向"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc1fa91a-7aca-4910-94dc-199f440e31bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35152, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "心の中で思うこと。", "primary_collocate": null, "pronunciation": "かんがえ", "ipa": "kaŋɡae", "syllable_count": 4, "sentences": [{"text": "頭の中に、ふと変な考えが浮かんだ。", "target_word": "考え", "complexity_tier": "T3", "furigana": "頭[あたま]の中[なか]に、ふと変[へん]な考[かんが]えが浮[う]かんだ。", "sentence_source": "generated"}, {"text": "彼は隠そうとしても、考えが顔に出る人だ。", "target_word": "考え", "complexity_tier": "T3", "furigana": "彼[かれ]は隠[かく]そうとしても、考[かんが]えが顔[かお]に出[で]る人[ひと]だ。", "sentence_source": "generated"}, {"text": "長い間一人で歩いているうちに、いろいろな考えが頭をよぎった。", "target_word": "考え", "complexity_tier": "T3", "furigana": "長[なが]い間[あいだ]一人[ひとり]で歩[ある]いているうちに、いろいろな考[かんが]えが頭[あたま]をよぎった。", "sentence_source": "generated"}, {"text": "悪い考えを捨てて、前向きにやろうと決めた。", "target_word": "考え", "complexity_tier": "T3", "furigana": "悪[わる]い考[かんが]えを捨[す]てて、前向[まえむ]きにやろうと決[き]めた。", "sentence_source": "generated"}, {"text": "彼女は考えにふけっていて、私の声が聞こえなかった。", "target_word": "考え", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は考[かんが]えにふけっていて、私[わたし]の声[こえ]が聞[き]こえなかった。", "sentence_source": "generated"}, {"text": "夜、布団に入ると、いろいろな考えが次々と頭に浮かんでくる。", "target_word": "考え", "complexity_tier": "T3", "furigana": "夜[よる]、布団[ふとん]に入[はい]ると、いろいろな考[かんが]えが次々[つぎつぎ]と頭[あたま]に浮[う]かんでくる。", "sentence_source": "generated"}, {"text": "突然いい考えが浮かんだので、すぐにメモした。", "target_word": "考え", "complexity_tier": "T3", "furigana": "突然[とつぜん]いい考[かんが]えが浮[う]かんだので、すぐにメモした。", "sentence_source": "generated"}, {"text": "彼は話さないので、心の中の考えがわからない。", "target_word": "考え", "complexity_tier": "T3", "furigana": "彼[かれ]は話[はな]さないので、心[こころ]の中[なか]の考[かんが]えがわからない。", "sentence_source": "generated"}, {"text": "不安な考えが頭から離れなくて、眠れなかった。", "target_word": "考え", "complexity_tier": "T3", "furigana": "不安[ふあん]な考[かんが]えが頭[あたま]から離[はな]れなくて、眠[ねむ]れなかった。", "sentence_source": "generated"}, {"text": "母は笑っていたが、心の中では別の考えを持っていたようだ。", "target_word": "考え", "complexity_tier": "T3", "furigana": "母[はは]は笑[わら]っていたが、心[こころ]の中[なか]では別[べつ]の考[かんが]えを持[も]っていたようだ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "考え", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "心の中に浮かぶ思い・思いつき(個人の頭の中の思考)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '82bc3f5f-a777-4e8f-a68b-12799a2d2b95') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35152, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "考え", "is_correct": true, "explanation": "頭に浮かぶ思いを指す。正しい。"}, {"text": "匂い", "is_correct": false, "explanation": "頭に浮かぶものではなく、「変な匂いが浮かんだ」は不自然。"}, {"text": "味", "is_correct": false, "explanation": "頭に浮かぶものではなく、「変な味が浮かんだ」は不自然。"}, {"text": "熱", "is_correct": false, "explanation": "頭に浮かぶものではなく、「変な熱が浮かんだ」は不自然。"}], "explanations": {"考え": "頭に浮かぶ思いを指す。正しい。", "匂い": "頭に浮かぶものではなく、「変な匂いが浮かんだ」は不自然。", "味": "頭に浮かぶものではなく、「変な味が浮かんだ」は不自然。", "熱": "頭に浮かぶものではなく、「変な熱が浮かんだ」は不自然。"}, "sentence_index": 0, "correct_answer": "考え"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "怒りの考えが爆発して、部屋の物を投げた。", "explanation": "ここは〈感情〉の意味。怒りのような感情は爆発するが、〈考え〉は爆発しない。"}, {"text": "昨夜の考えはとても楽しくて、目が覚めなかった。", "explanation": "ここは〈夢〉の意味。眠っている間に見るものは〈夢〉で、〈考え〉とは言わない。"}, {"text": "遠くから、誰かの考えが近づいてくる。", "explanation": "ここは〈足音〉の意味。近づいてくるのは足音や気配で、〈考え〉は近づかない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc1fa91a-7aca-4910-94dc-199f440e31bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35152, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "考え", "is_correct": true, "explanation": "頭に浮かぶ思いを指す。正しい。"}, {"text": "温度", "is_correct": false, "explanation": "頭に浮かぶものではなく、「いい温度が浮かんだ」は意味が通らない。"}, {"text": "重さ", "is_correct": false, "explanation": "頭に浮かぶものではなく、「いい重さが浮かんだ」は意味が通らない。"}, {"text": "体重", "is_correct": false, "explanation": "頭に浮かぶものではなく、「いい体重が浮かんだ」は意味が通らない。"}], "explanations": {"考え": "頭に浮かぶ思いを指す。正しい。", "温度": "頭に浮かぶものではなく、「いい温度が浮かんだ」は意味が通らない。", "重さ": "頭に浮かぶものではなく、「いい重さが浮かんだ」は意味が通らない。", "体重": "頭に浮かぶものではなく、「いい体重が浮かんだ」は意味が通らない。"}, "sentence_index": 6, "correct_answer": "考え"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "祖父は鼻の考えがとても鋭い。", "explanation": "ここは〈感覚〉の意味。鋭いのは鼻の感覚で、〈考え〉の鋭さとは言わない。"}, {"text": "その曲は、考えを聴くと落ち着く。", "explanation": "ここは〈音楽〉の意味。曲は聴くもので、〈考え〉は聴けない。"}, {"text": "窓から、やわらかな考えが差し込んだ。", "explanation": "ここは〈光〉の意味。差し込むのは光で、〈考え〉は差し込まない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc1fa91a-7aca-4910-94dc-199f440e31bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35152, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "その話は、ぼくの考えを同じだ。", "corrected_sentence": "その話は、ぼくの考えと同じだ。", "error_description": "「考え」に続く助詞が「を」になっている。「同じ」には「と」を使うのが正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc1fa91a-7aca-4910-94dc-199f440e31bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35152, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼の考えに聞いた。", "corrected_sentence": "彼の考えを聞いた。", "error_description": "「考え」の後に続く助詞が「に」になっている。「聞く」の対象を示す「を」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc1fa91a-7aca-4910-94dc-199f440e31bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35153, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「考えが違う」で主語を示す。正しい。"}, {"text": "を", "is_correct": false, "explanation": "「考えを違う」は述語と合わず文が成立しない。"}, {"text": "で", "is_correct": false, "explanation": "「考えで違う」は意味が通らない。"}, {"text": "に", "is_correct": false, "explanation": "「考えに違う」は文として成立しない。"}], "correct_answer": "が", "explanations": {"が": "「考えが違う」で主語を示す。正しい。", "を": "「考えを違う」は述語と合わず文が成立しない。", "で": "「考えで違う」は意味が通らない。", "に": "「考えに違う」は文として成立しない。"}, "error_tags": {"が": "主語", "を": "目的語", "で": "手段", "に": "位置"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc1fa91a-7aca-4910-94dc-199f440e31bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
