INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35153, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "あることについて、心の中でまとめられた意見や判断。", "primary_collocate": null, "pronunciation": "かんがえ", "ipa": "kaŋɡae", "syllable_count": 4, "sentences": [{"text": "私の考えを言わせてもらうと、この計画は急ぎすぎだ。", "target_word": "考え", "complexity_tier": "T3", "furigana": "私[わたし]の考[かんが]えを言[い]わせてもらうと、この計画[けいかく]は急[いそ]ぎすぎだ。", "sentence_source": "generated"}, {"text": "兄と私は、お金の使い方について考えが違う。", "target_word": "考え", "complexity_tier": "T3", "furigana": "兄[あに]と私[わたし]は、お金[かね]の使[つか]い方[かた]について考[かんが]えが違[ちが]う。", "sentence_source": "generated"}, {"text": "会議では、全員が自分の考えを発表した。", "target_word": "考え", "complexity_tier": "T3", "furigana": "会議[かいぎ]では、全員[ぜんいん]が自分[じぶん]の考[かんが]えを発表[はっぴょう]した。", "sentence_source": "generated"}, {"text": "その問題について、先生の考えを聞いてみたい。", "target_word": "考え", "complexity_tier": "T3", "furigana": "その問題[もんだい]について、先生[せんせい]の考[かんが]えを聞[き]いてみたい。", "sentence_source": "generated"}, {"text": "彼は一度決めた考えを簡単には変えない。", "target_word": "考え", "complexity_tier": "T3", "furigana": "彼[かれ]は一度[いちど]決[き]めた考[かんが]えを簡単[かんたん]には変[か]えない。", "sentence_source": "generated"}, {"text": "親の考えに反対して、私は一人で町を出た。", "target_word": "考え", "complexity_tier": "T3", "furigana": "親[おや]の考[かんが]えに反対[はんたい]して、私[わたし]は一人[ひとり]で町[まち]を出[で]た。", "sentence_source": "generated"}, {"text": "君の考えには賛成だが、時間が足りないと思う。", "target_word": "考え", "complexity_tier": "T3", "furigana": "君[きみ]の考[かんが]えには賛成[さんせい]だが、時間[じかん]が足[た]りないと思[おも]う。", "sentence_source": "generated"}, {"text": "市長は新しい図書館を作るという考えを示した。", "target_word": "考え", "complexity_tier": "T3", "furigana": "市長[しちょう]は新[あたら]しい図書館[としょかん]を作[つく]るという考[かんが]えを示[しめ]した。", "sentence_source": "generated"}, {"text": "二人の考えが合わなくて、話し合いは長引いた。", "target_word": "考え", "complexity_tier": "T3", "furigana": "二人[ふたり]の考[かんが]えが合[あ]わなくて、話[はな]し合[あ]いは長引[ながび]いた。", "sentence_source": "generated"}, {"text": "自分の考えをはっきり言うのは、大切なことだ。", "target_word": "考え", "complexity_tier": "T3", "furigana": "自分[じぶん]の考[かんが]えをはっきり言[い]うのは、大切[たいせつ]なことだ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "考え", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "ある事柄についてまとめた自分の意見・判断・方針", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '82bc3f5f-a777-4e8f-a68b-12799a2d2b95') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35153, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "考え", "is_correct": true, "explanation": "「言わせてもらう」の対象となる意見を指す。正しい。"}, {"text": "靴", "is_correct": false, "explanation": "言うものではなく、「私の靴を言わせてもらうと」は不自然。"}, {"text": "荷物", "is_correct": false, "explanation": "言うものではなく、「私の荷物を言わせてもらうと」は不自然。"}, {"text": "切符", "is_correct": false, "explanation": "言うものではなく、「私の切符を言わせてもらうと」は不自然。"}], "explanations": {"考え": "「言わせてもらう」の対象となる意見を指す。正しい。", "靴": "言うものではなく、「私の靴を言わせてもらうと」は不自然。", "荷物": "言うものではなく、「私の荷物を言わせてもらうと」は不自然。", "切符": "言うものではなく、「私の切符を言わせてもらうと」は不自然。"}, "sentence_index": 0, "correct_answer": "考え"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "布の考えを水に浸した。", "explanation": "ここは〈布地〉の意味。布は水に浸すが、〈考え〉は水に浸せない。"}, {"text": "料理の考えを買いに行った。", "explanation": "ここは〈材料〉の意味。料理の材料は買うが、〈考え〉は買えない。"}, {"text": "熱で考えを測った。", "explanation": "ここは〈体温〉の意味。熱は体温計で測るが、〈考え〉は測れない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc1fa91a-7aca-4910-94dc-199f440e31bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35153, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "考え", "is_correct": true, "explanation": "「君の考えには賛成だ」で、意見を指す。正しい。"}, {"text": "帽子", "is_correct": false, "explanation": "賛成の対象になるものではなく、「君の帽子には賛成だ」は不自然。"}, {"text": "財布", "is_correct": false, "explanation": "賛成の対象になるものではなく、「君の財布には賛成だ」は不自然。"}, {"text": "鍵", "is_correct": false, "explanation": "賛成の対象になるものではなく、「君の鍵には賛成だ」は不自然。"}], "explanations": {"考え": "「君の考えには賛成だ」で、意見を指す。正しい。", "帽子": "賛成の対象になるものではなく、「君の帽子には賛成だ」は不自然。", "財布": "賛成の対象になるものではなく、「君の財布には賛成だ」は不自然。", "鍵": "賛成の対象になるものではなく、「君の鍵には賛成だ」は不自然。"}, "sentence_index": 6, "correct_answer": "考え"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "料金の考えを払った。", "explanation": "ここは〈料金〉の意味。料金は払うが、〈考え〉は払えない。"}, {"text": "雨の日に考えをさした。", "explanation": "ここは〈傘〉の意味。傘はさすが、〈考え〉はさせない。"}, {"text": "ドアを開けて、考えを閉めた。", "explanation": "ここは〈扉〉の意味。ドアは閉めるが、〈考え〉は閉められない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc1fa91a-7aca-4910-94dc-199f440e31bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35153, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼は考えがまとめた。", "corrected_sentence": "彼は考えをまとめた。", "error_description": "「まとめる」は「考えを」と目的語に「を」を使う。「が」では不自然。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc1fa91a-7aca-4910-94dc-199f440e31bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
