INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35154, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "あたらしいものをみつけること", "primary_collocate": null, "pronunciation": "はっけん", "ipa": "hakkeɴ", "syllable_count": 4, "sentences": [{"text": "新しい花を発見した。", "target_word": "発見", "complexity_tier": "T1", "furigana": "新[あたら]しい花[はな]を発見[はっけん]した。", "sentence_source": "generated"}, {"text": "発見はおもしろいです。", "target_word": "発見", "complexity_tier": "T2", "furigana": "発見[はっけん]はおもしろいです。", "sentence_source": "generated"}, {"text": "公園で、めずらしい虫を発見した。", "target_word": "発見", "complexity_tier": "T3", "furigana": "公園[こうえん]で、めずらしい虫[むし]を発見[はっけん]した。", "sentence_source": "generated"}, {"text": "弟が古いコインを発見しました。", "target_word": "発見", "complexity_tier": "T2", "furigana": "弟[おとうと]が古[ふる]いコインを発見[はっけん]しました。", "sentence_source": "generated"}, {"text": "この発見はみんなを驚かせた。", "target_word": "発見", "complexity_tier": "T3", "furigana": "この発見[はっけん]はみんなを驚[おどろ]かせた。", "sentence_source": "generated"}, {"text": "発見したときは、うれしかった。", "target_word": "発見", "complexity_tier": "T3", "furigana": "発見[はっけん]したときは、うれしかった。", "sentence_source": "generated"}, {"text": "科学者の発見で、世界が変わった。", "target_word": "発見", "complexity_tier": "T3", "furigana": "科学者[かがくしゃ]の発見[はっけん]で、世界[せかい]が変[か]わった。", "sentence_source": "generated"}, {"text": "海の中で新しい魚が発見された。", "target_word": "発見", "complexity_tier": "T3", "furigana": "海[うみ]の中[なか]で新[あたら]しい魚[さかな]が発見[はっけん]された。", "sentence_source": "generated"}, {"text": "宝の地図が発見されれば、探しに行きたい。", "target_word": "発見", "complexity_tier": "T4", "furigana": "宝[たから]の地図[ちず]が発見[はっけん]されれば、探[さが]しに行[い]きたい。", "sentence_source": "generated"}, {"text": "彼女は毎日、小さな発見を日記に書いている。", "target_word": "発見", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は毎日[まいにち]、小[ちい]さな発見[はっけん]を日記[にっき]に書[か]いている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "発見する", "label": "活用"}, {"form": "発見した", "label": "活用"}, {"form": "発見された", "label": "活用"}, {"form": "発見者", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 新しいものを見つけること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04fdc735-03d9-474b-95d7-448c4529ef13') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35154, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "発見", "is_correct": true, "explanation": "新しい花を見つけたという意味に合う。"}, {"text": "卒業", "is_correct": false, "explanation": "形は合うが、花を卒業するとは意味が合わない。"}, {"text": "結婚", "is_correct": false, "explanation": "形は合うが、花と結婚するとは意味が合わない。"}, {"text": "出発", "is_correct": false, "explanation": "形は合うが、花を出発するとは意味が合わない。"}], "explanations": {"発見": "新しい花を見つけたという意味に合う。", "卒業": "形は合うが、花を卒業するとは意味が合わない。", "結婚": "形は合うが、花と結婚するとは意味が合わない。", "出発": "形は合うが、花を出発するとは意味が合わない。"}, "sentence_index": 0, "correct_answer": "発見"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "弟は古いコインを発見で食べました。", "explanation": "発見は食べる行為の手段ではなく、意味が合わない。"}, {"text": "弟が古いコインの発見を、お皿にのせて食べました。", "explanation": "発見は見つけることで、食べられる物ではない。"}, {"text": "弟は発見に乗って、学校へ行きました。", "explanation": "発見は乗り物ではなく、乗ることはできない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '973d70d1-217e-4815-b7ed-fa2c2a2f118b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35154, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "発見", "is_correct": true, "explanation": "科学者の発見が世界を変えたという意味に合う。"}, {"text": "散歩", "is_correct": false, "explanation": "形は合うが、科学者の散歩で世界が変わるとは意味が合わない。"}, {"text": "掃除", "is_correct": false, "explanation": "形は合うが、世界が変わった原因として意味が合わない。"}, {"text": "昼寝", "is_correct": false, "explanation": "形は合うが、世界が変わる理由として意味が合わない。"}], "explanations": {"発見": "科学者の発見が世界を変えたという意味に合う。", "散歩": "形は合うが、科学者の散歩で世界が変わるとは意味が合わない。", "掃除": "形は合うが、世界が変わった原因として意味が合わない。", "昼寝": "形は合うが、世界が変わる理由として意味が合わない。"}, "sentence_index": 6, "correct_answer": "発見"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼女は毎日、小さな発見を冷蔵庫に入れて食べている。", "explanation": "発見は気づきや出来事で、食べ物ではない。"}, {"text": "彼女は毎日、小さな発見を電車の中で着ている。", "explanation": "発見は着る物ではない。"}, {"text": "彼女は毎日、小さな発見に水をやっている。", "explanation": "発見は育てる植物ではなく、水をやる対象にならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '973d70d1-217e-4815-b7ed-fa2c2a2f118b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
