INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35155, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "まだ知られていなかった物事を見つけ出すこと。また、その見つけ出した物事。", "primary_collocate": null, "pronunciation": "はっけん", "ipa": "hakkeɴ", "syllable_count": 4, "sentences": [{"text": "中央銀行による大規模な資産買入オペレーション、すなわち量的緩和政策は、単なる流動性の供給にとどまらず、国債市場における価格発見機能を歪曲せしめる側面を孕んでいる。", "target_word": "発見", "complexity_tier": "T6", "furigana": "中央[ちゅうおう]銀行[ぎんこう]による大規模[だいきぼ]な資産[しさん]買入[かいいれ]オペレーション、すなわち量的[りょうてき]緩和[かんわ]政策[せいさく]は、単[たん]なる流動性[りゅうどうせい]の供給[きょうきゅう]にとどまらず、国債[こくさい]市場[しじょう]における価格[かかく]発見[はっけん]機能[きのう]を歪曲[わいきょく]せしめる側面[そくめん]を孕[はら]んでいる。", "sentence_source": "mined"}, {"text": "新しい星を発見した。", "target_word": "発見", "complexity_tier": "T1", "furigana": "新[あたら]しい星[ほし]を発見[はっけん]した。", "sentence_source": "generated"}, {"text": "これは大きな発見です。", "target_word": "発見", "complexity_tier": "T2", "furigana": "これは大[おお]きな発見[はっけん]です。", "sentence_source": "generated"}, {"text": "発見が遅れて、被害が広がった。", "target_word": "発見", "complexity_tier": "T3", "furigana": "発見[はっけん]が遅[おく]れて、被害[ひがい]が広[ひろ]がった。", "sentence_source": "generated"}, {"text": "博士は新しい薬の発見に成功した。", "target_word": "発見", "complexity_tier": "T3", "furigana": "博士[はかせ]は新[あたら]しい薬[くすり]の発見[はっけん]に成功[せいこう]した。", "sentence_source": "generated"}, {"text": "古い手紙の発見は、町の話題になった。", "target_word": "発見", "complexity_tier": "T3", "furigana": "古[ふる]い手紙[てがみ]の発見[はっけん]は、町[まち]の話題[わだい]になった。", "sentence_source": "generated"}, {"text": "歯医者が小さな虫歯を発見した。", "target_word": "発見", "complexity_tier": "T3", "furigana": "歯医者[はいしゃ]が小[ちい]さな虫歯[むしば]を発見[はっけん]した。", "sentence_source": "generated"}, {"text": "探検隊は洞窟で古代の壁画を発見した。", "target_word": "発見", "complexity_tier": "T3", "furigana": "探検隊[たんけんたい]は洞窟[どうくつ]で古代[こだい]の壁画[へきが]を発見[はっけん]した。", "sentence_source": "generated"}, {"text": "子どもにとって毎日は小さな発見の連続だ。", "target_word": "発見", "complexity_tier": "T3", "furigana": "子[こ]どもにとって毎日[まいにち]は小[ちい]さな発見[はっけん]の連続[れんぞく]だ。", "sentence_source": "generated"}, {"text": "発見された遺跡は、博物館に展示されている。", "target_word": "発見", "complexity_tier": "T4", "furigana": "発見[はっけん]された遺跡[いせき]は、博物館[はくぶつかん]に展示[てんじ]されている。", "sentence_source": "generated"}, {"text": "偶然の発見がきっかけで、研究が進んだ。", "target_word": "発見", "complexity_tier": "T3", "furigana": "偶然[ぐうぜん]の発見[はっけん]がきっかけで、研究[けんきゅう]が進[すす]んだ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "発見する", "label": "活用"}, {"form": "発見された", "label": "活用"}, {"form": "発見者", "label": "派生"}, {"form": "再発見", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 未知の物事を見つけ出すこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T1: contains vocabulary far above tier T1: せしめる (Zipf 2.46)','sentence 7 above tier T1: 3 words above tier T1 (max 2): 探検 (Zipf 3.83), 洞窟 (Zipf 3.97), 壁画 (Zipf 3.29)']::text[], '04fdc735-03d9-474b-95d7-448c4529ef13') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35155, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "発見", "is_correct": true, "explanation": "「価格発見機能」という経済用語で意味が合う。"}, {"text": "天気", "is_correct": false, "explanation": "形は合うが、「価格天気機能」は意味が合わない。"}, {"text": "料理", "is_correct": false, "explanation": "形は合うが、市場の機能として意味が合わない。"}, {"text": "花火", "is_correct": false, "explanation": "形は合うが、国債市場の機能として意味が合わない。"}], "explanations": {"発見": "「価格発見機能」という経済用語で意味が合う。", "天気": "形は合うが、「価格天気機能」は意味が合わない。", "料理": "形は合うが、市場の機能として意味が合わない。", "花火": "形は合うが、国債市場の機能として意味が合わない。"}, "sentence_index": 0, "correct_answer": "発見"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "発見を食べたら、とてもおいしかった。", "explanation": "発見は見つけること自体で、食べ物ではない。"}, {"text": "毎朝、駅まで発見で歩いている。", "explanation": "発見は手段や乗り物ではないので、「で」で移動手段にできない。"}, {"text": "発見を着て、学校へ行った。", "explanation": "発見は着る物ではなく、意味が合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '973d70d1-217e-4815-b7ed-fa2c2a2f118b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35155, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "発見", "is_correct": true, "explanation": "虫歯を見つけたという意味に合う。"}, {"text": "発売", "is_correct": false, "explanation": "形は合うが、虫歯を発売するとは意味が合わない。"}, {"text": "開店", "is_correct": false, "explanation": "形は合うが、虫歯を開店するとは意味が合わない。"}, {"text": "卒業", "is_correct": false, "explanation": "形は合うが、虫歯を卒業するとは意味が合わない。"}], "explanations": {"発見": "虫歯を見つけたという意味に合う。", "発売": "形は合うが、虫歯を発売するとは意味が合わない。", "開店": "形は合うが、虫歯を開店するとは意味が合わない。", "卒業": "形は合うが、虫歯を卒業するとは意味が合わない。"}, "sentence_index": 6, "correct_answer": "発見"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "毎日、発見でラーメンを三杯食べた。", "explanation": "発見は食べ方や道具ではなく、「で」で使えない。"}, {"text": "発見を飲んだら、頭が痛くなった。", "explanation": "発見は飲み物ではなく、意味が合わない。"}, {"text": "発見した雨が昨日から降り続けている。", "explanation": "雨は見つけ出す新しい物事ではなく、発見の対象にならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '973d70d1-217e-4815-b7ed-fa2c2a2f118b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35155, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "博士は新しい星を発見になった。", "corrected_sentence": "博士は新しい星を発見した。", "error_description": "「星を」に続く述語は「発見した」。「発見になった」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '973d70d1-217e-4815-b7ed-fa2c2a2f118b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35155, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "古代の壁画は洞窟に発見された。", "corrected_sentence": "古代の壁画は洞窟で発見された。", "error_description": "発見された場所は「で」で示す。「に」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '973d70d1-217e-4815-b7ed-fa2c2a2f118b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35158, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「言葉が」の主語を示す格助詞で、「伝わらない」の主語として入る。正解。"}, {"text": "を", "is_correct": false, "explanation": "目的語を示すが、「言葉を伝わらない」は自動詞の文として成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "相手や場所を示すが、「言葉に伝わらない」は不自然で、主語には「が」が必要。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示すが、「言葉へ伝わらない」は文として通じない。"}], "correct_answer": "が", "explanations": {"が": "「言葉が」の主語を示す格助詞で、「伝わらない」の主語として入る。正解。", "を": "目的語を示すが、「言葉を伝わらない」は自動詞の文として成り立たない。", "に": "相手や場所を示すが、「言葉に伝わらない」は不自然で、主語には「が」が必要。", "へ": "方向を示すが、「言葉へ伝わらない」は文として通じない。"}, "error_tags": {"を": "対象", "に": "相手・位置", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc1fa91a-7aca-4910-94dc-199f440e31bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35158, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc1fa91a-7aca-4910-94dc-199f440e31bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35158, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "きもちやたよりが、ひとからひとへととどきます。", "primary_collocate": null, "pronunciation": "つたわる", "ipa": "tsɯtawaɾɯ", "syllable_count": 4, "sentences": [{"text": "私の気持ちが彼女に伝わったかどうか、心配だ。", "target_word": "伝わった", "complexity_tier": "T3", "furigana": "私[わたし]の気持[きも]ちが彼女[かのじょ]に伝[つた]わったかどうか、心配[しんぱい]だ。", "sentence_source": "generated"}, {"text": "大きな声で話さないと、後ろの人まで言葉が伝わらない。", "target_word": "伝わらない", "complexity_tier": "T3", "furigana": "大[おお]きな声[こえ]で話[はな]さないと、後[うし]ろの人[ひと]まで言葉[ことば]が伝[つた]わらない。", "sentence_source": "generated"}, {"text": "悪い知らせは、その日のうちに家族へ伝わった。", "target_word": "伝わった", "complexity_tier": "T3", "furigana": "悪[わる]い知[し]らせは、その日[ひ]のうちに家族[かぞく]へ伝[つた]わった。", "sentence_source": "generated"}, {"text": "電話の声から、母の喜びが伝わってきた。", "target_word": "伝わって", "complexity_tier": "T3", "furigana": "電話[でんわ]の声[こえ]から、母[はは]の喜[よろこ]びが伝[つた]わってきた。", "sentence_source": "generated"}, {"text": "手紙を書いたので、感謝の気持ちが伝わるといいな。", "target_word": "伝わる", "complexity_tier": "T3", "furigana": "手紙[てがみ]を書[か]いたので、感謝[かんしゃ]の気持[きも]ちが伝[つた]わるといいな。", "sentence_source": "generated"}, {"text": "英語が下手でも、笑顔で話せば気持ちは伝わる。", "target_word": "伝わる", "complexity_tier": "T3", "furigana": "英語[えいご]が下手[へた]でも、笑顔[えがお]で話[はな]せば気持[きも]ちは伝[つた]わる。", "sentence_source": "generated"}, {"text": "メールだと冗談が伝わらないことがある。", "target_word": "伝わらない", "complexity_tier": "T3", "furigana": "メールだと冗談[じょうだん]が伝[つた]わらないことがある。", "sentence_source": "generated"}, {"text": "先生の熱い思いが生徒たちにも伝わり、教室が静かになった。", "target_word": "伝わり", "complexity_tier": "T3", "furigana": "先生[せんせい]の熱[あつ]い思[おも]いが生徒[せいと]たちにも伝[つた]わり、教室[きょうしつ]が静[しず]かになった。", "sentence_source": "generated"}, {"text": "彼の優しさは、言葉がなくても伝わってくる。", "target_word": "伝わって", "complexity_tier": "T3", "furigana": "彼[かれ]の優[やさ]しさは、言葉[ことば]がなくても伝[つた]わってくる。", "sentence_source": "generated"}, {"text": "彼女の悲しみが伝わって、私も泣きそうになった。", "target_word": "伝わって", "complexity_tier": "T3", "furigana": "彼女[かのじょ]の悲[かな]しみが伝[つた]わって、私[わたし]も泣[な]きそうになった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "伝わる", "label": "終止形"}, {"form": "伝わらない", "label": "否定形"}, {"form": "伝わり", "label": "連用形"}, {"form": "伝わって", "label": "テ形"}, {"form": "伝わった", "label": "タ形"}, {"form": "伝われば", "label": "仮定形"}], "register": "neutral", "sense_fingerprint": "気持ち・知らせ・言葉などが人から人へ届く、相手に通じる", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '82bc3f5f-a777-4e8f-a68b-12799a2d2b95') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35158, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "伝わった", "is_correct": true, "explanation": "「かどうか」の前に過去の形が入り、気持ちが相手に届いたかどうかを表す。正解。"}, {"text": "伝えた", "is_correct": false, "explanation": "他動詞で目的語が必要。「気持ちが伝えた」は主語と合わず、ここには入らない。"}, {"text": "伝わって", "is_correct": false, "explanation": "テ形は「かどうか」に続かないため、文が成立しない。"}, {"text": "伝わり", "is_correct": false, "explanation": "連用形は「かどうか」に続かないため、文が成立しない。"}], "explanations": {"伝わった": "「かどうか」の前に過去の形が入り、気持ちが相手に届いたかどうかを表す。正解。", "伝えた": "他動詞で目的語が必要。「気持ちが伝えた」は主語と合わず、ここには入らない。", "伝わって": "テ形は「かどうか」に続かないため、文が成立しない。", "伝わり": "連用形は「かどうか」に続かないため、文が成立しない。"}, "sentence_index": 0, "correct_answer": "伝わった"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "注文した品が、昨日ようやく私の家に伝わった。", "explanation": "ここは〈届く〉の意味。品物は届くものなので、伝わるは使わない。伝わるは情報や気持ちが相手に通じることに使う。"}, {"text": "霧の中から、向こうの山が伝わってきた。", "explanation": "ここは〈見える〉の意味。山は見えるものであり、伝わるは情報や感情が相手に通じることに使うため合わない。"}, {"text": "母が部屋に伝わってきた。", "explanation": "ここは〈来る〉の意味。人の移動には〈来る〉を使い、伝わるは情報や気持ちにだけ使う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc1fa91a-7aca-4910-94dc-199f440e31bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35158, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "伝わらない", "is_correct": true, "explanation": "否定形で「伝わらないことがある」と続き、冗談が届かない場合を表す。正解。"}, {"text": "伝えない", "is_correct": false, "explanation": "他動詞で目的語が必要。「冗談が伝えない」は主語と合わず成立しない。"}, {"text": "伝われ", "is_correct": false, "explanation": "命令形は「〜ことがある」に続かず、文が成立しない。"}, {"text": "伝わろう", "is_correct": false, "explanation": "意志形は「〜ことがある」に続かず、文が成立しない。"}], "explanations": {"伝わらない": "否定形で「伝わらないことがある」と続き、冗談が届かない場合を表す。正解。", "伝えない": "他動詞で目的語が必要。「冗談が伝えない」は主語と合わず成立しない。", "伝われ": "命令形は「〜ことがある」に続かず、文が成立しない。", "伝わろう": "意志形は「〜ことがある」に続かず、文が成立しない。"}, "sentence_index": 6, "correct_answer": "伝わらない"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "昨夜から、電話が伝わらない。", "explanation": "ここは〈通じる〉の意味。回線がつながらない状態は〈通じる〉で表し、伝わるは情報や気持ちに使う。"}, {"text": "新しいメンバーが、ついに仲間に伝わった。", "explanation": "ここは〈加わる〉（仲間に入る）の意味。仲間に入ることは加わるで表し、伝わるは気持ちや知らせが相手に通じることに使うため合わない。"}, {"text": "弟の背が一気に伝わった。", "explanation": "ここは〈伸びる〉（背が高くなる）の意味。背が高くなることは伸びるで表し、伝わるは気持ちや知らせに使うため合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc1fa91a-7aca-4910-94dc-199f440e31bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35158, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "窓の外から、子どもたちの笑い声が伝えてきた。", "corrected_sentence": "窓の外から、子どもたちの笑い声が伝わってきた。", "error_description": "誤りは「伝えてきた」。「伝える」は他動詞で目的語を取るため、主語が「笑い声」の文には合わない。正しくは自動詞の「伝わってきた」。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "伝わらない", "is_correct": true, "explanation": "「ないと」と呼応する否定形で、言葉が後ろの人に届かない状況を表す。正解。"}, {"text": "伝わる", "is_correct": false, "explanation": "肯定形にすると「届かない」という意味が消え、「ないと」の条件と合わない。"}, {"text": "伝われば", "is_correct": false, "explanation": "仮定形は「届けば」の意味になり、「大きな声で話さないと」の条件文と噛み合わない。"}, {"text": "伝わった", "is_correct": false, "explanation": "過去形は、今の話題である届かない状況と時制が合わない。"}], "correct_form": "伝わらない", "base_form": "伝わる", "form_label": "否定形", "sentence_index": 1, "explanations": {"伝わらない": "「ないと」と呼応する否定形で、言葉が後ろの人に届かない状況を表す。正解。", "伝わる": "肯定形にすると「届かない」という意味が消え、「ないと」の条件と合わない。", "伝われば": "仮定形は「届けば」の意味になり、「大きな声で話さないと」の条件文と噛み合わない。", "伝わった": "過去形は、今の話題である届かない状況と時制が合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc1fa91a-7aca-4910-94dc-199f440e31bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35158, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "祖母の話が孫たちをしっかり伝わった。", "corrected_sentence": "祖母の話が孫たちにしっかり伝わった。", "error_description": "誤りは助詞「を」。「伝わる」は相手を「に」で示すため、「孫たちを」は誤り。正しくは「孫たちに」。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "伝わり", "is_correct": true, "explanation": "連用形（中止形）。「思いが伝わり、〜」と後ろの文へつなぐ正しい形。"}, {"text": "伝われ", "is_correct": false, "explanation": "命令形。文の途中で命じる形になり、説明の流れと合わない。"}, {"text": "伝わろう", "is_correct": false, "explanation": "意志形。話し手の意志を表し、事実を述べる文と合わない。"}, {"text": "伝えて", "is_correct": false, "explanation": "他動詞で目的語が必要。「思いが伝えて」は主語と合わず、文が成立しない。"}], "correct_form": "伝わり", "base_form": "伝わる", "form_label": "連用形", "sentence_index": 7, "explanations": {"伝わり": "連用形（中止形）。「思いが伝わり、〜」と後ろの文へつなぐ正しい形。", "伝われ": "命令形。文の途中で命じる形になり、説明の流れと合わない。", "伝わろう": "意志形。話し手の意志を表し、事実を述べる文と合わない。", "伝えて": "他動詞で目的語が必要。「思いが伝えて」は主語と合わず、文が成立しない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc1fa91a-7aca-4910-94dc-199f440e31bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35160, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「学校の近く」の名詞を修飾する形を作る格助詞。正解。"}, {"text": "を", "is_correct": false, "explanation": "目的語を示すが、「学校を近くに」は成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "場所を示すが、「学校で近くに大きな公園」は不自然で文が通らない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示すが、「学校へ近くに大きな公園」は文として通じない。"}], "correct_answer": "の", "explanations": {"の": "「学校の近く」の名詞を修飾する形を作る格助詞。正解。", "を": "目的語を示すが、「学校を近くに」は成り立たない。", "で": "場所を示すが、「学校で近くに大きな公園」は不自然で文が通らない。", "へ": "方向を示すが、「学校へ近くに大きな公園」は文として通じない。"}, "error_tags": {"を": "対象", "で": "場所・手段", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc1fa91a-7aca-4910-94dc-199f440e31bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35160, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc1fa91a-7aca-4910-94dc-199f440e31bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35160, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "子どもたちがべんきょうするためのところです。", "primary_collocate": null, "pronunciation": "がっこう", "ipa": "ɡakkoː", "syllable_count": 4, "sentences": [{"text": "毎朝、八時に学校へ行きます。", "target_word": "学校", "complexity_tier": "T3", "furigana": "毎朝[まいあさ]、八時[はちじ]に学校[がっこう]へ行[い]きます。", "sentence_source": "generated"}, {"text": "学校の近くに大きな公園があります。", "target_word": "学校", "complexity_tier": "T3", "furigana": "学校[がっこう]の近[ちか]くに大[おお]きな公園[こうえん]があります。", "sentence_source": "generated"}, {"text": "雨が降ったので、学校まで母が車で送ってくれた。", "target_word": "学校", "complexity_tier": "T3", "furigana": "雨[あめ]が降[ふ]ったので、学校[がっこう]まで母[はは]が車[くるま]で送[おく]ってくれた。", "sentence_source": "generated"}, {"text": "弟は学校で友だちと遊ぶのが好きだ。", "target_word": "学校", "complexity_tier": "T3", "furigana": "弟[おとうと]は学校[がっこう]で友[とも]だちと遊[あそ]ぶのが好[す]きだ。", "sentence_source": "generated"}, {"text": "この学校には、千人ぐらいの子どもが通っている。", "target_word": "学校", "complexity_tier": "T3", "furigana": "この学校[がっこう]には、千人[せんにん]ぐらいの子[こ]どもが通[かよ]っている。", "sentence_source": "generated"}, {"text": "熱があったので、きのうは学校を休んだ。", "target_word": "学校", "complexity_tier": "T3", "furigana": "熱[ねつ]があったので、きのうは学校[がっこう]を休[やす]んだ。", "sentence_source": "generated"}, {"text": "学校が終わってから、毎日サッカーの練習をする。", "target_word": "学校", "complexity_tier": "T3", "furigana": "学校[がっこう]が終[お]わってから、毎日[まいにち]サッカーの練習[れんしゅう]をする。", "sentence_source": "generated"}, {"text": "新しい学校は、駅から歩いて五分のところにある。", "target_word": "学校", "complexity_tier": "T3", "furigana": "新[あたら]しい学校[がっこう]は、駅[えき]から歩[ある]いて五分[ごふん]のところにある。", "sentence_source": "generated"}, {"text": "夏休みの間、学校のプールは使えない。", "target_word": "学校", "complexity_tier": "T3", "furigana": "夏休[なつやす]みの間[あいだ]、学校[がっこう]のプールは使[つか]えない。", "sentence_source": "generated"}, {"text": "学校で習ったことを、家で母に話した。", "target_word": "学校", "complexity_tier": "T3", "furigana": "学校[がっこう]で習[なら]ったことを、家[いえ]で母[はは]に話[はな]した。", "sentence_source": "generated"}], "morphological_forms": [{"form": "学校", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "子どもが通って勉強する場所・施設としての学校", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '82bc3f5f-a777-4e8f-a68b-12799a2d2b95') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35160, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "学校", "is_correct": true, "explanation": "「行く」の目的地を表す名詞。「毎朝、八時に学校へ行く」は自然な文。正解。"}, {"text": "教科書", "is_correct": false, "explanation": "行き先にはならず、「教科書へ行きます」は成り立たない。"}, {"text": "宿題", "is_correct": false, "explanation": "行き先にはならず、「宿題へ行きます」は成り立たない。"}, {"text": "手紙", "is_correct": false, "explanation": "行き先にはならず、「手紙へ行きます」は成り立たない。"}], "explanations": {"学校": "「行く」の目的地を表す名詞。「毎朝、八時に学校へ行く」は自然な文。正解。", "教科書": "行き先にはならず、「教科書へ行きます」は成り立たない。", "宿題": "行き先にはならず、「宿題へ行きます」は成り立たない。", "手紙": "行き先にはならず、「手紙へ行きます」は成り立たない。"}, "sentence_index": 0, "correct_answer": "学校"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "学校が試験を受けて、無事に合格した。", "explanation": "ここは〈学生〉の意味。試験を受けて合格するのは人で、学校は場所や機関を指すので合わない。"}, {"text": "彼は大学で、学校を専攻して卒業した。", "explanation": "ここは〈学科〉（専攻する分野）の意味。専攻するのは学科で、学校は専攻の対象にならないので合わない。"}, {"text": "学校が、先生の質問に手を挙げて答えた。", "explanation": "ここは〈生徒〉の意味。手を挙げて答えるのは生徒で、学校は主語にならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc1fa91a-7aca-4910-94dc-199f440e31bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35160, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "学校", "is_correct": true, "explanation": "「終わってから」の主語になり、練習の前の時間を示す。正解。"}, {"text": "名前", "is_correct": false, "explanation": "「名前が終わってから」は成り立たず、文が不自然になる。"}, {"text": "写真", "is_correct": false, "explanation": "「写真が終わってから」は成り立たず、文が不自然になる。"}, {"text": "地図", "is_correct": false, "explanation": "「地図が終わってから」は成り立たず、文が不自然になる。"}], "explanations": {"学校": "「終わってから」の主語になり、練習の前の時間を示す。正解。", "名前": "「名前が終わってから」は成り立たず、文が不自然になる。", "写真": "「写真が終わってから」は成り立たず、文が不自然になる。", "地図": "「地図が終わってから」は成り立たず、文が不自然になる。"}, "sentence_index": 6, "correct_answer": "学校"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "学校が、新しい自動車を発売した。", "explanation": "ここは〈会社〉の意味。自動車を売り出すのは会社で、学校は子どもが勉強する場所なので合わない。"}, {"text": "学校が、残業して深夜まで働いた。", "explanation": "ここは〈社員〉の意味。残業して働くのは人で、学校は主語にできない。"}, {"text": "学校が、患者に手術の説明をした。", "explanation": "ここは〈医者〉の意味。患者に手術の説明をするのは医者で、学校は合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc1fa91a-7aca-4910-94dc-199f440e31bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35160, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "祖父は毎朝、学校を歩いて通っていた。", "corrected_sentence": "祖父は毎朝、学校へ歩いて通っていた。", "error_description": "誤りは助詞「を」。「通う」の行き先は「へ」で示すため、「学校へ」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc1fa91a-7aca-4910-94dc-199f440e31bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35160, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この町には学校が三軒ある。", "corrected_sentence": "この町には学校が三校ある。", "error_description": "誤りは助数詞。学校は「校」で数えるため、「軒」は誤り。正しくは「三校」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc1fa91a-7aca-4910-94dc-199f440e31bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35162, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「話が」の主語を示す格助詞で、「広まって」の主語として入る。正解。"}, {"text": "を", "is_correct": false, "explanation": "目的語を示すが、「話を広まって」は自動詞の文として成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "場所や相手を示すが、「話に広まって」は文として通じない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示すが、「話へ広まって」は不自然で文が成り立たない。"}], "correct_answer": "が", "explanations": {"が": "「話が」の主語を示す格助詞で、「広まって」の主語として入る。正解。", "を": "目的語を示すが、「話を広まって」は自動詞の文として成り立たない。", "に": "場所や相手を示すが、「話に広まって」は文として通じない。", "へ": "方向を示すが、「話へ広まって」は不自然で文が成り立たない。"}, "error_tags": {"を": "対象", "に": "位置・相手", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc1fa91a-7aca-4910-94dc-199f440e31bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35162, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「クラスに」の到達先を示す格助詞で、「広まった」の前に入る。正解。"}, {"text": "と", "is_correct": false, "explanation": "引用や並列を示すが、「クラスと広まった」は成り立たない。"}, {"text": "より", "is_correct": false, "explanation": "比較を示すが、「クラスより広まった」は文として不自然。"}, {"text": "が", "is_correct": false, "explanation": "主語を示すが、「話が、クラスが広まった」は意味が通じない。"}], "correct_answer": "に", "explanations": {"に": "「クラスに」の到達先を示す格助詞で、「広まった」の前に入る。正解。", "と": "引用や並列を示すが、「クラスと広まった」は成り立たない。", "より": "比較を示すが、「クラスより広まった」は文として不自然。", "が": "主語を示すが、「話が、クラスが広まった」は意味が通じない。"}, "error_tags": {"と": "引用・並列", "より": "比較", "が": "主語"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc1fa91a-7aca-4910-94dc-199f440e31bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35162, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "たくさんの人に知られるようになること。", "primary_collocate": null, "pronunciation": "ひろまる", "ipa": "hiɾomaɾɯ", "syllable_count": 4, "sentences": [{"text": "彼が優勝したといううわさは、すぐに学校中に広まった。", "target_word": "広まった", "complexity_tier": "T3", "furigana": "彼[かれ]が優勝[ゆうしょう]したといううわさは、すぐに学校中[がっこうじゅう]に広[ひろ]まった。", "sentence_source": "generated"}, {"text": "変な話が広まって、彼女は困っている。", "target_word": "広まって", "complexity_tier": "T3", "furigana": "変[へん]な話[はなし]が広[ひろ]まって、彼女[かのじょ]は困[こま]っている。", "sentence_source": "generated"}, {"text": "良い知らせは、あっという間に町の人に広まった。", "target_word": "広まった", "complexity_tier": "T3", "furigana": "良[よ]い知[し]らせは、あっという間[ま]に町[まち]の人[ひと]に広[ひろ]まった。", "sentence_source": "generated"}, {"text": "この歌は、ネットを通じて若い人たちの間に広まった。", "target_word": "広まった", "complexity_tier": "T3", "furigana": "この歌[うた]は、ネットを通[つう]じて若[わか]い人[ひと]たちの間[あいだ]に広[ひろ]まった。", "sentence_source": "generated"}, {"text": "秘密のはずが、いつの間にか広まっていた。", "target_word": "広まって", "complexity_tier": "T3", "furigana": "秘密[ひみつ]のはずが、いつの間[ま]にか広[ひろ]まっていた。", "sentence_source": "generated"}, {"text": "悪いうわさが広まらないうちに、本当のことを話そう。", "target_word": "広まらない", "complexity_tier": "T3", "furigana": "悪[わる]いうわさが広[ひろ]まらないうちに、本当[ほんとう]のことを話[はな]そう。", "sentence_source": "generated"}, {"text": "彼女の名前が広まったのは、あのテレビ番組のあとだ。", "target_word": "広まった", "complexity_tier": "T3", "furigana": "彼女[かのじょ]の名前[なまえ]が広[ひろ]まったのは、あのテレビ番組[ばんぐみ]のあとだ。", "sentence_source": "generated"}, {"text": "先生が結婚するという話が、クラスに広まった。", "target_word": "広まった", "complexity_tier": "T3", "furigana": "先生[せんせい]が結婚[けっこん]するという話[はなし]が、クラスに広[ひろ]まった。", "sentence_source": "generated"}, {"text": "その店のおいしさは口コミで広まり、いつも行列ができている。", "target_word": "広まり", "complexity_tier": "T3", "furigana": "その店[みせ]のおいしさは口[くち]コミで広[ひろ]まり、いつも行列[ぎょうれつ]ができている。", "sentence_source": "generated"}, {"text": "友だちに話したら、うわさが広まってしまった。", "target_word": "広まって", "complexity_tier": "T3", "furigana": "友[とも]だちに話[はな]したら、うわさが広[ひろ]まってしまった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "広まる", "label": "終止形"}, {"form": "広まらない", "label": "否定形"}, {"form": "広まり", "label": "連用形"}, {"form": "広まって", "label": "テ形"}, {"form": "広まった", "label": "タ形"}, {"form": "広まれば", "label": "仮定形"}], "register": "neutral", "sense_fingerprint": "うわさ・話・知らせなどが多くの人に知られるようになる", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '82bc3f5f-a777-4e8f-a68b-12799a2d2b95') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35162, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "広まった", "is_correct": true, "explanation": "過去の形で、うわさが学校中に知られたという出来事を表す。正解。"}, {"text": "広まれ", "is_correct": false, "explanation": "命令形は事実を述べる文に続かず、「すぐに学校中に広まれ。」は成り立たない。"}, {"text": "広まって", "is_correct": false, "explanation": "テ形は文を終えられず、「すぐに学校中に広まって。」は不完全になる。"}, {"text": "広まり", "is_correct": false, "explanation": "連用形は文を終えられず、文が成立しない。"}], "explanations": {"広まった": "過去の形で、うわさが学校中に知られたという出来事を表す。正解。", "広まれ": "命令形は事実を述べる文に続かず、「すぐに学校中に広まれ。」は成り立たない。", "広まって": "テ形は文を終えられず、「すぐに学校中に広まって。」は不完全になる。", "広まり": "連用形は文を終えられず、文が成立しない。"}, "sentence_index": 0, "correct_answer": "広まった"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "町の人口が一気に広まった。", "explanation": "ここは〈増える〉の意味。人口は増えるもので、広まるは知識・流行・うわさなどが知られることに使う。"}, {"text": "風船が一気に大きく広まった。", "explanation": "ここは〈ふくらむ〉の意味。風船が大きくなることはふくらむで表し、広まるは知識や流行など目に見えないものに使うため合わない。"}, {"text": "川の水が上流から下流へ広まった。", "explanation": "ここは〈流れる〉の意味。水は流れるものであり、広まるは情報や流行に使うため合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc1fa91a-7aca-4910-94dc-199f440e31bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35162, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "広まった", "is_correct": true, "explanation": "過去の形で、名前が広がったという出来事を「のは」の文に続ける。正解。"}, {"text": "広めて", "is_correct": false, "explanation": "テ形は「のは」に続かず、文が成立しない。"}, {"text": "広まれ", "is_correct": false, "explanation": "命令形は「のは」の文に続かず、文が成立しない。"}, {"text": "広めさせた", "is_correct": false, "explanation": "「名前を広めさせた」の形で目的語が必要になり、主語の「名前が」と合わない。"}], "explanations": {"広まった": "過去の形で、名前が広がったという出来事を「のは」の文に続ける。正解。", "広めて": "テ形は「のは」に続かず、文が成立しない。", "広まれ": "命令形は「のは」の文に続かず、文が成立しない。", "広めさせた": "「名前を広めさせた」の形で目的語が必要になり、主語の「名前が」と合わない。"}, "sentence_index": 6, "correct_answer": "広まった"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "お茶がすっかり冷えて、広まった。", "explanation": "ここは〈冷える〉の意味。温度が下がることは冷えるで表し、広まるは知られることに使う。"}, {"text": "コップが床に落ちて、広まった。", "explanation": "ここは〈割れる〉の意味。物が壊れることは割れるで表し、広まるは人や話題に使う。"}, {"text": "洗ったタオルが、部屋の隅で広まった。", "explanation": "ここは〈乾く〉の意味。水分がなくなることは乾くで表し、広まるは人や話題が知られることに使うため合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc1fa91a-7aca-4910-94dc-199f440e31bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35162, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "その噂はすぐに町中を広まった。", "corrected_sentence": "その噂はすぐに町中に広まった。", "error_description": "誤りは助詞「を」。「広まる」は広がる先を「に」で示すため、「町中に」が正しい。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "広まって", "is_correct": true, "explanation": "テ形で、後ろの「彼女は困っている」へ原因として続く。正解。"}, {"text": "広めて", "is_correct": false, "explanation": "他動詞で、「話が広めて、」は主語と合わず文が成立しない。"}, {"text": "広まる", "is_correct": false, "explanation": "終止形では原因として後ろに続けられず、文が切れてしまう。"}, {"text": "広まれ", "is_correct": false, "explanation": "命令形は文の途中に続かず、「広まれ、」は成り立たない。"}], "correct_form": "広まって", "base_form": "広まる", "form_label": "テ形", "sentence_index": 1, "explanations": {"広まって": "テ形で、後ろの「彼女は困っている」へ原因として続く。正解。", "広めて": "他動詞で、「話が広めて、」は主語と合わず文が成立しない。", "広まる": "終止形では原因として後ろに続けられず、文が切れてしまう。", "広まれ": "命令形は文の途中に続かず、「広まれ、」は成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc1fa91a-7aca-4910-94dc-199f440e31bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35162, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "その話は、もう町中に広まってあった。", "corrected_sentence": "その話は、もう町中に広まっていた。", "error_description": "誤りは「てあった」。「広まる」は自動詞なので「ていた」を使い、「てある」は他動詞の結果状態に使うため誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "広まった", "is_correct": true, "explanation": "過去形で、先生の結婚の話がクラスに広がった出来事を表す。正解。"}, {"text": "広まらない", "is_correct": false, "explanation": "否定形だと、話が広まらなかったという逆の内容になる。"}, {"text": "広まり", "is_correct": false, "explanation": "連用形は文を終えられず、「クラスに広まり。」は成り立たない。"}, {"text": "広まって", "is_correct": false, "explanation": "テ形は文を終えられず、「クラスに広まって。」は成り立たない。"}], "correct_form": "広まった", "base_form": "広まる", "form_label": "タ形", "sentence_index": 7, "explanations": {"広まった": "過去形で、先生の結婚の話がクラスに広がった出来事を表す。正解。", "広まらない": "否定形だと、話が広まらなかったという逆の内容になる。", "広まり": "連用形は文を終えられず、「クラスに広まり。」は成り立たない。", "広まって": "テ形は文を終えられず、「クラスに広まって。」は成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc1fa91a-7aca-4910-94dc-199f440e31bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35163, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "へ", "options": [{"text": "へ", "is_correct": true, "explanation": "「全国へ」の到達先を示す格助詞で、「広まった」の前に入る。正解。"}, {"text": "を", "is_correct": false, "explanation": "目的語を示すが、「全国を広まった」は自動詞の文として成り立たない。"}, {"text": "の", "is_correct": false, "explanation": "名詞を修飾するが、「全国の広まった」は主語や述語として成り立たない。"}, {"text": "より", "is_correct": false, "explanation": "比較を示すが、「全国より広まった」は文として通じない。"}], "correct_answer": "へ", "explanations": {"へ": "「全国へ」の到達先を示す格助詞で、「広まった」の前に入る。正解。", "を": "目的語を示すが、「全国を広まった」は自動詞の文として成り立たない。", "の": "名詞を修飾するが、「全国の広まった」は主語や述語として成り立たない。", "より": "比較を示すが、「全国より広まった」は文として通じない。"}, "error_tags": {"を": "対象", "の": "連体修飾", "より": "比較"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc1fa91a-7aca-4910-94dc-199f440e31bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35163, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "と", "options": [{"text": "と", "is_correct": true, "explanation": "「広まったと言われている」の引用を示す助詞。正解。"}, {"text": "が", "is_correct": false, "explanation": "主語を示すが、「広まったが言われている」は接続が通じない。"}, {"text": "に", "is_correct": false, "explanation": "場所や相手を示すが、「広まったに言われている」は成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "場所や手段を示すが、「広まったで言われている」は成り立たない。"}], "correct_answer": "と", "explanations": {"と": "「広まったと言われている」の引用を示す助詞。正解。", "が": "主語を示すが、「広まったが言われている」は接続が通じない。", "に": "場所や相手を示すが、「広まったに言われている」は成り立たない。", "で": "場所や手段を示すが、「広まったで言われている」は成り立たない。"}, "error_tags": {"が": "主語・接続", "に": "位置・相手", "で": "場所・手段"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc1fa91a-7aca-4910-94dc-199f440e31bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35163, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "ある事柄や物が、多くの人や場所に広く知られるようになる。", "primary_collocate": null, "pronunciation": "ひろまる", "ipa": "hiɾomaɾɯ", "syllable_count": 4, "sentences": [{"text": "新しい遊びが、子どもたちの間に広まっている。", "target_word": "広まって", "complexity_tier": "T3", "furigana": "新[あたら]しい遊[あそ]びが、子[こ]どもたちの間[あいだ]に広[ひろ]まっている。", "sentence_source": "generated"}, {"text": "この料理は、江戸時代に全国へ広まったそうだ。", "target_word": "広まった", "complexity_tier": "T3", "furigana": "この料理[りょうり]は、江戸時代[えどじだい]に全国[ぜんこく]へ広[ひろ]まったそうだ。", "sentence_source": "generated"}, {"text": "スマートフォンが広まって、生活が大きく変わった。", "target_word": "広まって", "complexity_tier": "T3", "furigana": "スマートフォンが広[ひろ]まって、生活[せいかつ]が大[おお]きく変[か]わった。", "sentence_source": "generated"}, {"text": "この新しい決まりは、まだ会社の外には広まっていない。", "target_word": "広まって", "complexity_tier": "T3", "furigana": "この新[あたら]しい決[き]まりは、まだ会社[かいしゃ]の外[そと]には広[ひろ]まっていない。", "sentence_source": "generated"}, {"text": "健康にいい食べ方が、世界中に広まった。", "target_word": "広まった", "complexity_tier": "T3", "furigana": "健康[けんこう]にいい食[た]べ方[かた]が、世界中[せかいじゅう]に広[ひろ]まった。", "sentence_source": "generated"}, {"text": "その考え方は、若い人の間で広まりつつある。", "target_word": "広まり", "complexity_tier": "T3", "furigana": "その考[かんが]え方[かた]は、若[わか]い人[ひと]の間[あいだ]で広[ひろ]まりつつある。", "sentence_source": "generated"}, {"text": "手作りの石けんの作り方が、インターネットで広まった。", "target_word": "広まった", "complexity_tier": "T3", "furigana": "手作[てづく]りの石[せっ]けんの作[つく]り方[かた]が、インターネットで広[ひろ]まった。", "sentence_source": "generated"}, {"text": "茶の文化は、中国から日本へ広まったと言われている。", "target_word": "広まった", "complexity_tier": "T3", "furigana": "茶[ちゃ]の文化[ぶんか]は、中国[ちゅうごく]から日本[にほん]へ広[ひろ]まったと言[い]われている。", "sentence_source": "generated"}, {"text": "この服の流行は、都会から地方へと広まっていった。", "target_word": "広まって", "complexity_tier": "T3", "furigana": "この服[ふく]の流行[りゅうこう]は、都会[とかい]から地方[ちほう]へと広[ひろ]まっていった。", "sentence_source": "generated"}, {"text": "安い商品はすぐに広まるが、品質が悪いと長続きしない。", "target_word": "広まる", "complexity_tier": "T3", "furigana": "安[やす]い商品[しょうひん]はすぐに広[ひろ]まるが、品質[ひんしつ]が悪[わる]いと長続[ながつづ]きしない。", "sentence_source": "generated"}], "morphological_forms": [{"form": "広まる", "label": "終止形"}, {"form": "広まらない", "label": "否定形"}, {"form": "広まり", "label": "連用形"}, {"form": "広まって", "label": "テ形"}, {"form": "広まった", "label": "タ形"}, {"form": "広まれば", "label": "仮定形"}], "register": "neutral", "sense_fingerprint": "流行・習慣・製品・文化・考えなどが多くの人や場所に行き渡る", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '82bc3f5f-a777-4e8f-a68b-12799a2d2b95') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35163, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "広まって", "is_correct": true, "explanation": "テ形で「広まっている」の一部になり、遊びが広がっている状態を表す。正解。"}, {"text": "広めて", "is_correct": false, "explanation": "他動詞で主語の「遊び」と合わず、「広めている」は文の意味が通じない。"}, {"text": "広まり", "is_correct": false, "explanation": "連用形は「いる」に続かず、「広まりいる」は成り立たない。"}, {"text": "広まれば", "is_correct": false, "explanation": "仮定形は「いる」に続かず、「広まればいる」は成り立たない。"}], "explanations": {"広まって": "テ形で「広まっている」の一部になり、遊びが広がっている状態を表す。正解。", "広めて": "他動詞で主語の「遊び」と合わず、「広めている」は文の意味が通じない。", "広まり": "連用形は「いる」に続かず、「広まりいる」は成り立たない。", "広まれば": "仮定形は「いる」に続かず、「広まればいる」は成り立たない。"}, "sentence_index": 0, "correct_answer": "広まって"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "店の客が、一気に広まった。", "explanation": "ここは〈増える〉の意味。客の数は増えるもので、広まるは知識・流行・考えなど目に見えないものに使う。"}, {"text": "お湯がすっかり冷めて、広まった。", "explanation": "ここは〈冷める〉の意味。温度が下がることは冷めるで表し、広まるは広く行き渡ることに使う。"}, {"text": "パン生地が発酵して、広まった。", "explanation": "ここは〈ふくらむ〉の意味。生地がふくらむのはふくらむで表し、広まるは広く行き渡ることに使う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc1fa91a-7aca-4910-94dc-199f440e31bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35163, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "広まった", "is_correct": true, "explanation": "過去形で、作り方がインターネットで広がったという出来事を表す。正解。"}, {"text": "広まれ", "is_correct": false, "explanation": "命令形は文の終わりに続かず、文が成立しない。"}, {"text": "広めさせた", "is_correct": false, "explanation": "使役の形で、主語の「作り方が」と合わず、文の意味が通じない。"}, {"text": "広まろう", "is_correct": false, "explanation": "意志形は過去の出来事を述べる文に合わず、文が成立しない。"}], "explanations": {"広まった": "過去形で、作り方がインターネットで広がったという出来事を表す。正解。", "広まれ": "命令形は文の終わりに続かず、文が成立しない。", "広めさせた": "使役の形で、主語の「作り方が」と合わず、文の意味が通じない。", "広まろう": "意志形は過去の出来事を述べる文に合わず、文が成立しない。"}, "sentence_index": 6, "correct_answer": "広まった"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "砂糖がコーヒーにすっかり広まった。", "explanation": "ここは〈混ざる〉の意味。溶けて混ざるのは混ざるで表し、広まるは人々に知られることに使う。"}, {"text": "机の上にほこりが広まった。", "explanation": "ここは〈積もる〉の意味。ほこりが積もるのは積もるで表し、広まるは人や流行に使う。"}, {"text": "おもちゃが床に広まった。", "explanation": "ここは〈散らばる〉の意味。物が散らかることは散らばるで表し、広まるは人や考えに使う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc1fa91a-7aca-4910-94dc-199f440e31bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35163, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "新しい健康法が、テレビを通じて全国を広まった。", "corrected_sentence": "新しい健康法が、テレビを通じて全国に広まった。", "error_description": "誤りは助詞「を」。「広まる」は広がる先を「に」で示すため、「全国に」が正しい。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "広まった", "is_correct": true, "explanation": "過去形で、「〜そうだ」の伝聞と合い、江戸時代の出来事として自然。正解。"}, {"text": "広まって", "is_correct": false, "explanation": "テ形は文を終えられず、「〜そうだ」と続かない。"}, {"text": "広まろう", "is_correct": false, "explanation": "意志形は伝聞の「そうだ」に続かず、文が成立しない。"}, {"text": "広まれば", "is_correct": false, "explanation": "仮定形は「〜そうだ」に続かず、文が成立しない。"}], "correct_form": "広まった", "base_form": "広まる", "form_label": "タ形", "sentence_index": 1, "explanations": {"広まった": "過去形で、「〜そうだ」の伝聞と合い、江戸時代の出来事として自然。正解。", "広まって": "テ形は文を終えられず、「〜そうだ」と続かない。", "広まろう": "意志形は伝聞の「そうだ」に続かず、文が成立しない。", "広まれば": "仮定形は「〜そうだ」に続かず、文が成立しない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc1fa91a-7aca-4910-94dc-199f440e31bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35163, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "そのニュースはもう国中に広まってある。", "corrected_sentence": "そのニュースはもう国中に広まっている。", "error_description": "誤りは「てある」。「広まる」は自動詞なので「ている」を使い、「てある」は他動詞の結果状態に使うため誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "広まった", "is_correct": true, "explanation": "過去形で、「と言われている」の伝聞の内容として合う。正解。"}, {"text": "広まらない", "is_correct": false, "explanation": "否定形だと、茶の文化が広まらなかったという逆の内容になる。"}, {"text": "広まり", "is_correct": false, "explanation": "連用形は文を終えられず、「と言われている」に続かない。"}, {"text": "広まれ", "is_correct": false, "explanation": "命令形は「と言われている」に続かず、文が成立しない。"}], "correct_form": "広まった", "base_form": "広まる", "form_label": "タ形", "sentence_index": 7, "explanations": {"広まった": "過去形で、「と言われている」の伝聞の内容として合う。正解。", "広まらない": "否定形だと、茶の文化が広まらなかったという逆の内容になる。", "広まり": "連用形は文を終えられず、「と言われている」に続かない。", "広まれ": "命令形は「と言われている」に続かず、文が成立しない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc1fa91a-7aca-4910-94dc-199f440e31bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
