INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35164, 3, 'prompt1_core', '{"pos": "代名詞", "semantic_class": "function", "definition": "行為をする人自身を指すときに使う再帰代名詞。", "primary_collocate": null, "pronunciation": "じぶん", "ipa": "dʑibɯɴ", "syllable_count": 3, "sentences": [{"text": "宿題は自分でやらなければ意味がありません。", "target_word": "自分", "complexity_tier": "T3", "furigana": "宿題[しゅくだい]は自分[じぶん]でやらなければ意味[いみ]がありません。", "sentence_source": "generated"}, {"text": "彼は自分のミスを素直に認めた。", "target_word": "自分", "complexity_tier": "T3", "furigana": "彼[かれ]は自分[じぶん]のミスを素直[すなお]に認[みと]めた。", "sentence_source": "generated"}, {"text": "人のせいにしないで、自分の行動を振り返ってください。", "target_word": "自分", "complexity_tier": "T4", "furigana": "人[ひと]のせいにしないで、自分[じぶん]の行動[こうどう]を振[ふ]り返[かえ]ってください。", "sentence_source": "generated"}, {"text": "自分の荷物は自分で持ってください。", "target_word": "自分", "complexity_tier": "T2", "furigana": "自分[じぶん]の荷物[にもつ]は自分[じぶん]で持[も]ってください。", "sentence_source": "generated"}, {"text": "鏡を見て、自分の顔が疲れているのに気づいた。", "target_word": "自分", "complexity_tier": "T3", "furigana": "鏡[かがみ]を見[み]て、自分[じぶん]の顔[かお]が疲[つか]れているのに気[き]づいた。", "sentence_source": "generated"}, {"text": "妹は自分の意見をはっきり言える子です。", "target_word": "自分", "complexity_tier": "T3", "furigana": "妹[いもうと]は自分[じぶん]の意見[いけん]をはっきり言[い]える子[こ]です。", "sentence_source": "generated"}, {"text": "自分に自信がなくて、発表の前に緊張した。", "target_word": "自分", "complexity_tier": "T3", "furigana": "自分[じぶん]に自信[じしん]がなくて、発表[はっぴょう]の前[まえ]に緊張[きんちょう]した。", "sentence_source": "generated"}, {"text": "失敗しても自分を責めすぎないほうがいいです。", "target_word": "自分", "complexity_tier": "T3", "furigana": "失敗[しっぱい]しても自分[じぶん]を責[せ]めすぎないほうがいいです。", "sentence_source": "generated"}, {"text": "母は自分のことより家族のことをいつも先に考える。", "target_word": "自分", "complexity_tier": "T3", "furigana": "母[はは]は自分[じぶん]のことより家族[かぞく]のことをいつも先[さき]に考[かんが]える。", "sentence_source": "generated"}, {"text": "自分が好きなことを仕事にするのは簡単ではない。", "target_word": "自分", "complexity_tier": "T4", "furigana": "自分[じぶん]が好[す]きなことを仕事[しごと]にするのは簡単[かんたん]ではない。", "sentence_source": "generated"}], "morphological_forms": [{"form": "自分", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "文の主語や話し手自身を指す再帰的な代名詞。自分自身を表す。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4c3b1d77-b0ef-4bb3-862f-9f84b278ab5c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35164, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "自分", "is_correct": true, "explanation": "「自分でやらなければ」の形で、宿題をやる主語自身を指す再帰代名詞。空所に入るのはこれだけ。"}, {"text": "嘘", "is_correct": false, "explanation": "「嘘でやらなければ」は意味が通らず、空所に入らない。"}, {"text": "誰", "is_correct": false, "explanation": "疑問語。平叙文の「宿題は誰でやらなければ」は文として成り立たない。"}, {"text": "夢", "is_correct": false, "explanation": "「夢でやらなければ」は意味が通らず、空所に入らない。"}], "explanations": {"自分": "「自分でやらなければ」の形で、宿題をやる主語自身を指す再帰代名詞。空所に入るのはこれだけ。", "嘘": "「嘘でやらなければ」は意味が通らず、空所に入らない。", "誰": "疑問語。平叙文の「宿題は誰でやらなければ」は文として成り立たない。", "夢": "「夢でやらなければ」は意味が通らず、空所に入らない。"}, "sentence_index": 0, "correct_answer": "自分"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この鍋は自分で沸いた。", "explanation": "〈ひとりでに〉の意味。「自分」は人自身を指す語で、鍋が自分で沸くという物の動きには使えない。"}, {"text": "交渉の自分は態度を変えなかった。", "explanation": "〈我が方〉の意味。「自分」は一人の行為者自身を指すので、交渉の味方側をまとめて指すことはできない。"}, {"text": "まず自分紹介をしてください。", "explanation": "〈自己〉の意味の熟語。「自己紹介」の「自己」は「自分」に置き換えられず、「自分紹介」とは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e33d01b3-97f1-4e39-a664-d3e16060402b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35164, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "自分", "is_correct": true, "explanation": "「自分に自信がない」で、主語自身の自信の欠如を表す。空所に入るのはこれだけ。"}, {"text": "何", "is_correct": false, "explanation": "疑問語。「何に自信がなくて」は平叙文として成り立たず、主語の自信を表せない。"}, {"text": "机", "is_correct": false, "explanation": "物。「机に自信がなくて」は人の心の状態として成り立たない。"}, {"text": "雨", "is_correct": false, "explanation": "自然現象。「雨に自信がなくて」は人の心の状態として成り立たない。"}], "explanations": {"自分": "「自分に自信がない」で、主語自身の自信の欠如を表す。空所に入るのはこれだけ。", "何": "疑問語。「何に自信がなくて」は平叙文として成り立たず、主語の自信を表せない。", "机": "物。「机に自信がなくて」は人の心の状態として成り立たない。", "雨": "自然現象。「雨に自信がなくて」は人の心の状態として成り立たない。"}, "sentence_index": 6, "correct_answer": "自分"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は自分が高く、人に頭を下げられない。", "explanation": "〈自尊心〉の意味。「自分」は自己そのものを指す語で、「自分が高い」では自尊心の高さを表せない。"}, {"text": "夜は自分に帰った。", "explanation": "〈自宅〉の意味。「自分」は人を指す語で、帰る場所は表せない。"}, {"text": "この畑の自分は豊作だった。", "explanation": "〈畑〉の意味。「自分」は人自身を指す語で、畑という場所や作物を指すことはできない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e33d01b3-97f1-4e39-a664-d3e16060402b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35164, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼は自分を失敗を素直に認めた。", "corrected_sentence": "彼は自分の失敗を素直に認めた。", "error_description": "「自分」に続く助詞が「を」になっている。所有を表す「の」が正しい（自分の失敗）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e33d01b3-97f1-4e39-a664-d3e16060402b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35164, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼女は自分を厳しい人です。", "corrected_sentence": "彼女は自分に厳しい人です。", "error_description": "「厳しい」の対象を示す助詞が「を」になっている。「自分に厳しい」の「に」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e33d01b3-97f1-4e39-a664-d3e16060402b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35166, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "正解。読む対象のひらがなを示す「を」で、「ひらがなを読む」になる。"}, {"text": "に", "is_correct": false, "explanation": "「読む」の対象には「を」を使うので、「ひらがなに読む」は不自然。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すので、「ひらがなへ読む」は読む対象を表せず不自然。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並列や共同を示すので、読む対象には合わない。"}], "correct_answer": "を", "explanations": {"を": "正解。読む対象のひらがなを示す「を」で、「ひらがなを読む」になる。", "に": "「読む」の対象には「を」を使うので、「ひらがなに読む」は不自然。", "へ": "「へ」は方向を示すので、「ひらがなへ読む」は読む対象を表せず不自然。", "と": "「と」は並列や共同を示すので、読む対象には合わない。"}, "error_tags": {"に": "目的語の誤用", "と": "並列・共同の誤用", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '401b40f5-d031-4d88-9d8d-edaa3348f3cf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35166, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "正解。読む対象の字を示す「を」で、「小さな字を読む」になる。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すので、「字へ読む」は読む対象を表せず不自然。"}, {"text": "に", "is_correct": false, "explanation": "「に」は場所や相手を示すので、「字に読むのが」は読む対象を表せず不自然。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較を示すので、読む対象は表せず合わない。"}], "correct_answer": "を", "explanations": {"を": "正解。読む対象の字を示す「を」で、「小さな字を読む」になる。", "へ": "「へ」は方向を示すので、「字へ読む」は読む対象を表せず不自然。", "に": "「に」は場所や相手を示すので、「字に読むのが」は読む対象を表せず不自然。", "より": "「より」は比較を示すので、読む対象は表せず合わない。"}, "error_tags": {"へ": "方向", "より": "比較", "に": "対象の誤用"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '401b40f5-d031-4d88-9d8d-edaa3348f3cf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35166, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "目で字を見て、その意味がわかること。", "primary_collocate": null, "pronunciation": "よむ", "ipa": "jomɯ", "syllable_count": 2, "sentences": [{"text": "古い地図の字がかすれて、読めませんでした。", "target_word": "読めませんでした", "complexity_tier": "T4", "furigana": "古[ふる]い地図[ちず]の字[じ]がかすれて、読[よ]めませんでした。", "sentence_source": "generated"}, {"text": "私は五歳のとき、もうひらがなを読むことができました。", "target_word": "読む", "complexity_tier": "T4", "furigana": "私[わたし]は五歳[ごさい]のとき、もうひらがなを読[よ]むことができました。", "sentence_source": "generated"}, {"text": "看板の字が小さすぎて、ここからは読めません。", "target_word": "読めません", "complexity_tier": "T3", "furigana": "看板[かんばん]の字[じ]が小[ちい]さすぎて、ここからは読[よ]めません。", "sentence_source": "generated"}, {"text": "字がきれいなので、だれでも簡単に読めます。", "target_word": "読めます", "complexity_tier": "T3", "furigana": "字[じ]がきれいなので、だれでも簡単[かんたん]に読[よ]めます。", "sentence_source": "generated"}, {"text": "弟はまだ小さいので、漢字が読めません。", "target_word": "読めません", "complexity_tier": "T3", "furigana": "弟[おとうと]はまだ小[ちい]さいので、漢字[かんじ]が読[よ]めません。", "sentence_source": "generated"}, {"text": "外国の文字は、習わないと読めません。", "target_word": "読めません", "complexity_tier": "T3", "furigana": "外国[がいこく]の文字[もじ]は、習[なら]わないと読[よ]めません。", "sentence_source": "generated"}, {"text": "日本に来て、やっと駅の案内を読めるようになりました。", "target_word": "読める", "complexity_tier": "T4", "furigana": "日本[にほん]に来[き]て、やっと駅[えき]の案内[あんない]を読[よ]めるようになりました。", "sentence_source": "generated"}, {"text": "暗い部屋では、本の小さな字を読むのが大変です。", "target_word": "読む", "complexity_tier": "T4", "furigana": "暗[くら]い部屋[へや]では、本[ほん]の小[ちい]さな字[じ]を読[よ]むのが大変[たいへん]です。", "sentence_source": "generated"}, {"text": "祖母は目が悪くなって、新聞の字を読むのがつらいと言います。", "target_word": "読む", "complexity_tier": "T4", "furigana": "祖母[そぼ]は目[め]が悪[わる]くなって、新聞[しんぶん]の字[じ]を読[よ]むのがつらいと言[い]います。", "sentence_source": "generated"}, {"text": "この看板はローマ字で書いてあるので、外国人も読めます。", "target_word": "読めます", "complexity_tier": "T4", "furigana": "この看板[かんばん]はローマ字[じ]で書[か]いてあるので、外国人[がいこくじん]も読[よ]めます。", "sentence_source": "generated"}], "morphological_forms": [{"form": "読む", "label": "辞書形"}, {"form": "読み", "label": "連用形"}, {"form": "読んで", "label": "て形"}, {"form": "読んだ", "label": "た形"}, {"form": "読まない", "label": "ない形"}, {"form": "読めば", "label": "仮定形"}, {"form": "読もう", "label": "意志形"}, {"form": "読める", "label": "可能形"}], "register": "polite", "sense_fingerprint": "字を見てその意味がわかる(文字・漢字・看板の字が読める/読めない)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c32a7421-5115-45dc-a774-604346542668') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35166, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "読めませんでした", "is_correct": true, "explanation": "正解。字が見分けられなかったことを表す可能形の否定過去で、かすれた字の文脈に合う。"}, {"text": "読めました", "is_correct": false, "explanation": "肯定になり、字がかすれて読めなかったという文脈と矛盾する。"}, {"text": "読まされました", "is_correct": false, "explanation": "使役受身で、無理に読まされた意味になり、字がかすれて読めなかった状況とは合わない。"}, {"text": "読ませました", "is_correct": false, "explanation": "使役形で、誰かに読ませたという意味になり、字の状態の話とは合わない。"}], "explanations": {"読めませんでした": "正解。字が見分けられなかったことを表す可能形の否定過去で、かすれた字の文脈に合う。", "読めました": "肯定になり、字がかすれて読めなかったという文脈と矛盾する。", "読まされました": "使役受身で、無理に読まされた意味になり、字がかすれて読めなかった状況とは合わない。", "読ませました": "使役形で、誰かに読ませたという意味になり、字の状態の話とは合わない。"}, "sentence_index": 0, "correct_answer": "読めませんでした"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は空気が読めるので、会議でよく発言します。", "explanation": "ここは〈空気を読む〉（場の雰囲気を察する）の意味。字を見て意味がわかるという意味では合わない。"}, {"text": "この音楽は静かなので、外国人も読めます。", "explanation": "音を耳で理解する内容に〈読める〉を使っており、字を見て理解する意味とは合わない。"}, {"text": "この山は高いので、頂上の形が読めます。", "explanation": "〈形を読む〉は形から判断する意味で、文字を見て内容がわかるという意味とは違う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '401b40f5-d031-4d88-9d8d-edaa3348f3cf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35166, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "読める", "is_correct": true, "explanation": "正解。「〜ようになる」の前に可能形を置き、読めるようになったという能力の変化を表す。"}, {"text": "読み", "is_correct": false, "explanation": "連用形では「ようになる」に続かず、不自然になる。"}, {"text": "読もう", "is_correct": false, "explanation": "意志形は「ようになる」と合わず、能力の変化を表せない。"}, {"text": "読んだ", "is_correct": false, "explanation": "「読んだようになった」は読んだように見えるという意味で、能力の獲得を表さない。"}], "explanations": {"読める": "正解。「〜ようになる」の前に可能形を置き、読めるようになったという能力の変化を表す。", "読み": "連用形では「ようになる」に続かず、不自然になる。", "読もう": "意志形は「ようになる」と合わず、能力の変化を表せない。", "読んだ": "「読んだようになった」は読んだように見えるという意味で、能力の獲得を表さない。"}, "sentence_index": 6, "correct_answer": "読める"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この番組の結末は、途中から読めました。", "explanation": "ここは〈先を予想する〉の意味。字を見て内容がわかるという意味では合わない。"}, {"text": "この料理は、外国人も読めます。", "explanation": "ここは〈作り方がわかる〉の意味。字を見て意味がわかるという〈読む〉とは別の内容なので合わない。"}, {"text": "先生の早口も、耳で読めました。", "explanation": "ここは〈聞き取る〉の意味。読むは字を目で見て内容を理解する動詞なので、耳で聞いて分かる内容には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '401b40f5-d031-4d88-9d8d-edaa3348f3cf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35166, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妹はまだ小さいので、ひらがなが読むできません。", "corrected_sentence": "妹はまだ小さいので、ひらがなが読めません。", "error_description": "可能の形は「読め」＋「ません」。「読むできません」は「読む」と「できる」を重ねた誤りで、正しくは「読めません」。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "読む", "is_correct": true, "explanation": "正解。辞書形で「ことができる」の前に置き、能力を表す文になる。"}, {"text": "読み", "is_correct": false, "explanation": "連用形は「ことができる」に続かず、文法的に成立しない。"}, {"text": "読んで", "is_correct": false, "explanation": "て形は「ことができました」に直接つながらない。"}, {"text": "読もう", "is_correct": false, "explanation": "意志形は「ことができる」と合わず、能力の文にならない。"}], "correct_form": "読む", "base_form": "読む", "form_label": "辞書形（基本形）", "sentence_index": 1, "explanations": {"読む": "正解。辞書形で「ことができる」の前に置き、能力を表す文になる。", "読み": "連用形は「ことができる」に続かず、文法的に成立しない。", "読んで": "て形は「ことができました」に直接つながらない。", "読もう": "意志形は「ことができる」と合わず、能力の文にならない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '401b40f5-d031-4d88-9d8d-edaa3348f3cf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35166, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "祖母は細かい字が読めなないと言います。", "corrected_sentence": "祖母は細かい字が読めないと言います。", "error_description": "否定の形は「読めない」。「読めなない」は否定の活用の誤りで、正しくは「読めない」。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "読む", "is_correct": true, "explanation": "正解。辞書形で「のが」の前に置き、名詞句として文を作る。"}, {"text": "読めば", "is_correct": false, "explanation": "仮定形は「のが」に続けられず、名詞句の形にならない。"}, {"text": "読まれ", "is_correct": false, "explanation": "受身の語幹で、「のが」に続けられず、名詞句の形にならない。"}, {"text": "読ませ", "is_correct": false, "explanation": "使役の語幹で、「のが」に続けられず、名詞句の形にならない。"}], "correct_form": "読む", "base_form": "読む", "form_label": "辞書形（基本形）", "sentence_index": 7, "explanations": {"読む": "正解。辞書形で「のが」の前に置き、名詞句として文を作る。", "読めば": "仮定形は「のが」に続けられず、名詞句の形にならない。", "読まれ": "受身の語幹で、「のが」に続けられず、名詞句の形にならない。", "読ませ": "使役の語幹で、「のが」に続けられず、名詞句の形にならない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '401b40f5-d031-4d88-9d8d-edaa3348f3cf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35167, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "正解。読む対象の新聞を示す「を」で、「新聞を読みます」になる。"}, {"text": "に", "is_correct": false, "explanation": "「読む」の対象には「を」を使うので、「新聞に読みます」は不自然。"}, {"text": "が", "is_correct": false, "explanation": "「が」は主語を示すので、読む対象には使えない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並列や共同を示すので、読む対象の表示には合わない。"}], "correct_answer": "を", "explanations": {"を": "正解。読む対象の新聞を示す「を」で、「新聞を読みます」になる。", "に": "「読む」の対象には「を」を使うので、「新聞に読みます」は不自然。", "が": "「が」は主語を示すので、読む対象には使えない。", "と": "「と」は並列や共同を示すので、読む対象の表示には合わない。"}, "error_tags": {"に": "目的語の誤用", "が": "主語の誤用", "と": "並列・共同の誤用"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '401b40f5-d031-4d88-9d8d-edaa3348f3cf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35167, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "正解。読む対象のメールを示す「を」で、「メールを読んだ」になる。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すので、「メールへ読んだ」は読む対象を表せず不自然。"}, {"text": "の", "is_correct": false, "explanation": "「の」は名詞をつなぐ助詞なので、「メールの読んだ」では動詞の対象にならない。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較を示すので、「メールより読んだ」は読む対象を表せず合わない。"}], "correct_answer": "を", "explanations": {"を": "正解。読む対象のメールを示す「を」で、「メールを読んだ」になる。", "へ": "「へ」は方向を示すので、「メールへ読んだ」は読む対象を表せず不自然。", "の": "「の」は名詞をつなぐ助詞なので、「メールの読んだ」では動詞の対象にならない。", "より": "「より」は比較を示すので、「メールより読んだ」は読む対象を表せず合わない。"}, "error_tags": {"へ": "方向", "の": "連体修飾", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '401b40f5-d031-4d88-9d8d-edaa3348f3cf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35167, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "文字や文章を、目で追いながら内容を理解する。", "primary_collocate": null, "pronunciation": "よむ", "ipa": "jomɯ", "syllable_count": 2, "sentences": [{"text": "寝る前に詩集を読みます。", "target_word": "読みます", "complexity_tier": "T3", "furigana": "寝[ね]る前[まえ]に詩集[ししゅう]を読[よ]みます。", "sentence_source": "generated"}, {"text": "電車の中で毎朝新聞を読みます。", "target_word": "読みます", "complexity_tier": "T3", "furigana": "電車[でんしゃ]の中[なか]で毎朝[まいあさ]新聞[しんぶん]を読[よ]みます。", "sentence_source": "generated"}, {"text": "説明書をよく読んでから、機械を使ってください。", "target_word": "読んで", "complexity_tier": "T4", "furigana": "説明書[せつめいしょ]をよく読[よ]んでから、機械[きかい]を使[つか]ってください。", "sentence_source": "generated"}, {"text": "この小説は長いので、最後まで読むのに三日かかりました。", "target_word": "読む", "complexity_tier": "T4", "furigana": "この小説[しょうせつ]は長[なが]いので、最後[さいご]まで読[よ]むのに三日[みっか]かかりました。", "sentence_source": "generated"}, {"text": "友達が書いた手紙を、ゆっくり読みました。", "target_word": "読みました", "complexity_tier": "T3", "furigana": "友達[ともだち]が書[か]いた手紙[てがみ]を、ゆっくり読[よ]みました。", "sentence_source": "generated"}, {"text": "難しい本ですが、辞書を引きながら読みます。", "target_word": "読みます", "complexity_tier": "T3", "furigana": "難[むずか]しい本[ほん]ですが、辞書[じしょ]を引[ひ]きながら読[よ]みます。", "sentence_source": "generated"}, {"text": "先生に勧められた本を、週末に読みました。", "target_word": "読みました", "complexity_tier": "T3", "furigana": "先生[せんせい]に勧[すす]められた本[ほん]を、週末[しゅうまつ]に読[よ]みました。", "sentence_source": "generated"}, {"text": "メールを読んだあとで、すぐに返事を書きました。", "target_word": "読んだ", "complexity_tier": "T3", "furigana": "メールを読[よ]んだあとで、すぐに返事[へんじ]を書[か]きました。", "sentence_source": "generated"}, {"text": "問題文をていねいに読まないと、間違えてしまいます。", "target_word": "読まない", "complexity_tier": "T4", "furigana": "問題文[もんだいぶん]をていねいに読[よ]まないと、間違[まちが]えてしまいます。", "sentence_source": "generated"}, {"text": "図書館で借りた歴史の本を、毎晩少しずつ読んでいます。", "target_word": "読んで", "complexity_tier": "T4", "furigana": "図書館[としょかん]で借[か]りた歴史[れきし]の本[ほん]を、毎晩[まいばん]少[すこ]しずつ読[よ]んでいます。", "sentence_source": "generated"}], "morphological_forms": [{"form": "読む", "label": "辞書形"}, {"form": "読み", "label": "連用形"}, {"form": "読んで", "label": "て形"}, {"form": "読んだ", "label": "た形"}, {"form": "読まない", "label": "ない形"}, {"form": "読めば", "label": "仮定形"}, {"form": "読もう", "label": "意志形"}, {"form": "読める", "label": "可能形"}], "register": "polite", "sense_fingerprint": "目で文章を追って内容を理解する(本・手紙・説明書などを読む)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c32a7421-5115-45dc-a774-604346542668') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35167, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "読みます", "is_correct": true, "explanation": "正解。詩を目で追って理解する意味の「読む」の丁寧形で、ここに入る。"}, {"text": "食べます", "is_correct": false, "explanation": "詩を食べるという文にならず、文字を目で追う意味とは合わない。"}, {"text": "飲みます", "is_correct": false, "explanation": "詩を飲むという文にならず、文字の内容を理解する意味とは合わない。"}, {"text": "洗います", "is_correct": false, "explanation": "詩を洗うという文にならず、文字を目で追う意味とは合わない。"}], "explanations": {"読みます": "正解。詩を目で追って理解する意味の「読む」の丁寧形で、ここに入る。", "食べます": "詩を食べるという文にならず、文字を目で追う意味とは合わない。", "飲みます": "詩を飲むという文にならず、文字の内容を理解する意味とは合わない。", "洗います": "詩を洗うという文にならず、文字を目で追う意味とは合わない。"}, "sentence_index": 0, "correct_answer": "読みます"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この小説は長いので、最後まで空気を読むのに三日かかりました。", "explanation": "ここは〈空気を読む〉（場の雰囲気を察する）の意味。文字を目で追って内容を理解する意味では合わない。"}, {"text": "この小説は長いので、最後まで作者の心を読むのに三日かかりました。", "explanation": "ここは〈心を読む〉（相手の考えを推し量る）の意味。文字を目で追って内容を理解する意味とは違うので合わない。"}, {"text": "この小説は長いので、最後までお経を読むのに三日かかりました。", "explanation": "〈お経を読む〉は声に出して唱える意味で、小説を目で追って理解する意味とは違う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '401b40f5-d031-4d88-9d8d-edaa3348f3cf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35167, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "読みました", "is_correct": true, "explanation": "正解。本を目で追って内容を理解する意味の過去形で、ここに入る。"}, {"text": "食べました", "is_correct": false, "explanation": "本を食べるという文にならず、文字を読む意味とは合わない。"}, {"text": "洗いました", "is_correct": false, "explanation": "本を洗うという文にならず、内容を理解する意味とは合わない。"}, {"text": "飲みました", "is_correct": false, "explanation": "本を飲むという文にならず、文字を追う意味とは合わない。"}], "explanations": {"読みました": "正解。本を目で追って内容を理解する意味の過去形で、ここに入る。", "食べました": "本を食べるという文にならず、文字を読む意味とは合わない。", "洗いました": "本を洗うという文にならず、内容を理解する意味とは合わない。", "飲みました": "本を飲むという文にならず、文字を追う意味とは合わない。"}, "sentence_index": 6, "correct_answer": "読みました"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "毎晩、株価の流れを少しずつ読んでいます。", "explanation": "ここは〈流れを読む〉（先行きを予測する）の意味。文字を目で追って内容を理解する意味とは違うので合わない。"}, {"text": "彼は敵の動きを読んで、次の作戦を立てました。", "explanation": "ここは〈動きを読む〉（先を予測する）の意味。文字を目で追って内容を理解する意味とは違うので合わない。"}, {"text": "彼は相手の手を読んで、将棋の次の一手を考えました。", "explanation": "ここは〈手を読む〉（次の動きを予測する）の意味。文字を目で追って内容を理解するという意味とは違うので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '401b40f5-d031-4d88-9d8d-edaa3348f3cf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35167, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "祖父は毎晩、新聞に読みます。", "corrected_sentence": "祖父は毎晩、新聞を読みます。", "error_description": "「読む」の対象は「を」で示す。「に」は誤りで、正しくは「を」。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "読みます", "is_correct": true, "explanation": "正解。毎朝の習慣を述べる肯定の丁寧形で、この文に合う。"}, {"text": "読みません", "is_correct": false, "explanation": "否定形なので、毎朝新聞を読むという肯定の文と合わない。"}, {"text": "読みました", "is_correct": false, "explanation": "過去形なので、毎朝の習慣を表す現在の文には合わない。"}, {"text": "読んで", "is_correct": false, "explanation": "て形は文を言い切れず、ここでは文末に使えない。"}], "correct_form": "読みます", "base_form": "読む", "form_label": "ます形（丁寧形）", "sentence_index": 1, "explanations": {"読みます": "正解。毎朝の習慣を述べる肯定の丁寧形で、この文に合う。", "読みません": "否定形なので、毎朝新聞を読むという肯定の文と合わない。", "読みました": "過去形なので、毎朝の習慣を表す現在の文には合わない。", "読んで": "て形は文を言い切れず、ここでは文末に使えない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '401b40f5-d031-4d88-9d8d-edaa3348f3cf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35167, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "先生は毎晩、歴史の本を読むます。", "corrected_sentence": "先生は毎晩、歴史の本を読みます。", "error_description": "丁寧形は語幹の「読み」に「ます」をつける。「読むます」は活用の誤りで、正しくは「読みます」。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "読んだ", "is_correct": true, "explanation": "正解。すでに終えた動作を表すた形で、「あとで」の前に合う。"}, {"text": "読み", "is_correct": false, "explanation": "連用形のままでは「あとで」に続かず、文として成立しない。"}, {"text": "読もう", "is_correct": false, "explanation": "意志形は、すでに終えた動作の後に続けると不自然になる。"}, {"text": "読める", "is_correct": false, "explanation": "可能形になり、読み終えた行為を表す文にならない。"}], "correct_form": "読んだ", "base_form": "読む", "form_label": "た形（過去・完了）", "sentence_index": 7, "explanations": {"読んだ": "正解。すでに終えた動作を表すた形で、「あとで」の前に合う。", "読み": "連用形のままでは「あとで」に続かず、文として成立しない。", "読もう": "意志形は、すでに終えた動作の後に続けると不自然になる。", "読める": "可能形になり、読み終えた行為を表す文にならない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '401b40f5-d031-4d88-9d8d-edaa3348f3cf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
