INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35168, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「さを学べます」の対象を示す格助詞で、ここに入る正しい助詞。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す助詞。「大切さへ学べます」は学ぶ対象を表せない。"}, {"text": "と", "is_correct": false, "explanation": "共同や引用を示す助詞。「大切さと学べます」は目的語にならず、意味が通らない。"}, {"text": "の", "is_correct": false, "explanation": "所属や修飾を示す助詞。「大切さの学べます」は述語の目的語を作れない。"}], "correct_answer": "を", "explanations": {"を": "「さを学べます」の対象を示す格助詞で、ここに入る正しい助詞。", "へ": "方向を示す助詞。「大切さへ学べます」は学ぶ対象を表せない。", "と": "共同や引用を示す助詞。「大切さと学べます」は目的語にならず、意味が通らない。", "の": "所属や修飾を示す助詞。「大切さの学べます」は述語の目的語を作れない。"}, "error_tags": {"へ": "方向", "と": "共同・引用", "の": "所属・修飾"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e33d01b3-97f1-4e39-a664-d3e16060402b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35168, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "新しいことを知ったり、できるようになったりすること。", "primary_collocate": null, "pronunciation": "まなぶ", "ipa": "manabɯ", "syllable_count": 3, "sentences": [{"text": "子どもは遊びの中で多くのことを学ぶ。", "target_word": "学ぶ", "complexity_tier": "T3", "furigana": "子[こ]どもは遊[あそ]びの中[なか]で多[おお]くのことを学[まな]ぶ。", "sentence_source": "generated"}, {"text": "失敗から学んだことを、次の仕事に生かしたい。", "target_word": "学んだ", "complexity_tier": "T4", "furigana": "失敗[しっぱい]から学[まな]んだことを、次[つぎ]の仕事[しごと]に生[い]かしたい。", "sentence_source": "generated"}, {"text": "旅行をして、その国の歴史を学びました。", "target_word": "学びました", "complexity_tier": "T3", "furigana": "旅行[りょこう]をして、その国[くに]の歴史[れきし]を学[まな]びました。", "sentence_source": "generated"}, {"text": "祖父の話から、昔の暮らしを学んだ。", "target_word": "学んだ", "complexity_tier": "T3", "furigana": "祖父[そふ]の話[はなし]から、昔[むかし]の暮[く]らしを学[まな]んだ。", "sentence_source": "generated"}, {"text": "姉は毎日、新しい料理の作り方を学んでいる。", "target_word": "学んでいる", "complexity_tier": "T3", "furigana": "姉[あね]は毎日[まいにち]、新[あたら]しい料理[りょうり]の作[つく]り方[かた]を学[まな]んでいる。", "sentence_source": "generated"}, {"text": "人の意見を聞くと、学ぶことが多い。", "target_word": "学ぶ", "complexity_tier": "T3", "furigana": "人[ひと]の意見[いけん]を聞[き]くと、学[まな]ぶことが多[おお]い。", "sentence_source": "generated"}, {"text": "初めて自転車に乗って、バランスの取り方を学んだ。", "target_word": "学んだ", "complexity_tier": "T3", "furigana": "初[はじ]めて自転車[じてんしゃ]に乗[の]って、バランスの取[と]り方[かた]を学[まな]んだ。", "sentence_source": "generated"}, {"text": "この絵本から、やさしさの大切さを学べます。", "target_word": "学べます", "complexity_tier": "T3", "furigana": "この絵本[えほん]から、やさしさの大切[たいせつ]さを学[まな]べます。", "sentence_source": "generated"}, {"text": "失敗しても、そこから学ばない人は成長できない。", "target_word": "学ばない", "complexity_tier": "T4", "furigana": "失敗[しっぱい]しても、そこから学[まな]ばない人[ひと]は成長[せいちょう]できない。", "sentence_source": "generated"}, {"text": "経験から学べば、同じ間違いは減るはずだ。", "target_word": "学べば", "complexity_tier": "T4", "furigana": "経験[けいけん]から学[まな]べば、同[おな]じ間違[まちが]いは減[へ]るはずだ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "学ぶ", "label": "終止形"}, {"form": "学び", "label": "連用形"}, {"form": "学んだ", "label": "過去形"}, {"form": "学んで", "label": "て形"}, {"form": "学ばない", "label": "否定形"}, {"form": "学べば", "label": "仮定形"}, {"form": "学べる", "label": "可能形"}], "register": "neutral", "sense_fingerprint": "経験や人の話、身近な出来事から新しいことを知り、できるようになる。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4c3b1d77-b0ef-4bb3-862f-9f84b278ab5c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35168, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "学ぶ", "is_correct": true, "explanation": "「多くのことを学ぶ」で、経験を通して新しいことを身につける意味に合う。"}, {"text": "眠る", "is_correct": false, "explanation": "「多くのことを眠る」は成り立たず、空所に入らない。"}, {"text": "走る", "is_correct": false, "explanation": "「多くのことを走る」は意味が通らず、空所に入らない。"}, {"text": "泣く", "is_correct": false, "explanation": "「多くのことを泣く」は意味が通らず、空所に入らない。"}], "explanations": {"学ぶ": "「多くのことを学ぶ」で、経験を通して新しいことを身につける意味に合う。", "眠る": "「多くのことを眠る」は成り立たず、空所に入らない。", "走る": "「多くのことを走る」は意味が通らず、空所に入らない。", "泣く": "「多くのことを泣く」は意味が通らず、空所に入らない。"}, "sentence_index": 0, "correct_answer": "学ぶ"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "忘れていた約束を学んだ。", "explanation": "〈思い出す〉の意味。「学ぶ」は新しく身につけることで、忘れていたことを思い出す場合には使わない。"}, {"text": "大事な財布を学んだ。", "explanation": "〈落とす〉の意味。「学ぶ」は知識や経験を得ることで、物をなくす意味にはならない。"}, {"text": "大事な花瓶を学んだ。", "explanation": "〈割る〉の意味。「学ぶ」は知識や技能を得る動詞で、物を壊す意味にはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e33d01b3-97f1-4e39-a664-d3e16060402b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35168, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "学んだ", "is_correct": true, "explanation": "過去形。「バランスの取り方を学んだ」で、練習を通して身につけた意味に合う。"}, {"text": "乗った", "is_correct": false, "explanation": "「取り方を乗った」は成り立たず、空所に入らない。"}, {"text": "投げた", "is_correct": false, "explanation": "「取り方を投げた」は意味が通らず、空所に入らない。"}, {"text": "割った", "is_correct": false, "explanation": "「取り方を割った」は意味が通らず、空所に入らない。"}], "explanations": {"学んだ": "過去形。「バランスの取り方を学んだ」で、練習を通して身につけた意味に合う。", "乗った": "「取り方を乗った」は成り立たず、空所に入らない。", "投げた": "「取り方を投げた」は意味が通らず、空所に入らない。", "割った": "「取り方を割った」は意味が通らず、空所に入らない。"}, "sentence_index": 6, "correct_answer": "学んだ"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "川で魚を学んだ。", "explanation": "〈釣る〉の意味。「学ぶ」は知識や技能を身につける動詞で、魚を捕まえる意味にはならない。"}, {"text": "大事な時計を学んだ。", "explanation": "〈失う〉の意味。「学ぶ」は知識や技能を得る動詞で、物を失う意味にはならない。"}, {"text": "友達の宿題を学んだ。", "explanation": "〈写す〉の意味。「学ぶ」は自分が身につける動詞で、他人の宿題を写す意味にはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e33d01b3-97f1-4e39-a664-d3e16060402b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35168, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼は毎日、英語の単語を学ぶでいる。", "corrected_sentence": "彼は毎日、英語の単語を学んでいる。", "error_description": "「学ぶ」の活用が誤っている。「学んでいる」の「て形」は「学んで」で、「学ぶで」は誤り。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "学んだ", "is_correct": true, "explanation": "過去形。「学んだこと」で、過去に得た経験を表し、文脈に合う。"}, {"text": "学ぶ", "is_correct": false, "explanation": "終止形。「学ぶこと」では過去の経験を指せず、時制が合わない。"}, {"text": "学んで", "is_correct": false, "explanation": "て形。「～ことを」の修飾に続く形にならず、文の構造が合わない。"}, {"text": "学ばない", "is_correct": false, "explanation": "否定形。学ばなかった経験を表すことになり、意味が逆になる。"}], "correct_form": "学んだ", "base_form": "学ぶ", "form_label": "過去形", "sentence_index": 1, "explanations": {"学んだ": "過去形。「学んだこと」で、過去に得た経験を表し、文脈に合う。", "学ぶ": "終止形。「学ぶこと」では過去の経験を指せず、時制が合わない。", "学んで": "て形。「～ことを」の修飾に続く形にならず、文の構造が合わない。", "学ばない": "否定形。学ばなかった経験を表すことになり、意味が逆になる。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e33d01b3-97f1-4e39-a664-d3e16060402b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35168, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼は留学して英語を学ばたい。", "corrected_sentence": "彼は留学して英語を学びたい。", "error_description": "「学ぶ」の連用形は「学び」で、「学ばたい」は誤った活用。「学びたい」が正しい。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "学べます", "is_correct": true, "explanation": "可能形の丁寧体。「学ぶことができます」の意味で、文末の丁寧さとも合う。"}, {"text": "学べて", "is_correct": false, "explanation": "て形。文末の述語にはならず、「学べて。」では文が終わらない。"}, {"text": "学べば", "is_correct": false, "explanation": "仮定形。条件節を作るので、「～ます」で終わる文の述語にならない。"}, {"text": "学びたい", "is_correct": false, "explanation": "願望形。「～たい」は願望を表し、可能の意味にならない。"}], "correct_form": "学べます", "base_form": "学ぶ", "form_label": "可能形（丁寧体）", "sentence_index": 7, "explanations": {"学べます": "可能形の丁寧体。「学ぶことができます」の意味で、文末の丁寧さとも合う。", "学べて": "て形。文末の述語にはならず、「学べて。」では文が終わらない。", "学べば": "仮定形。条件節を作るので、「～ます」で終わる文の述語にならない。", "学びたい": "願望形。「～たい」は願望を表し、可能の意味にならない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e33d01b3-97f1-4e39-a664-d3e16060402b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35169, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「技術を学んだ」の対象を示す格助詞で、ここに入る正しい助詞。"}, {"text": "が", "is_correct": false, "explanation": "主語を示す助詞。「料理の技術が学んだ」では技術が学ぶ主体になり、意味が通らない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す助詞。「技術へ学んだ」は学ぶ対象を表せない。"}, {"text": "の", "is_correct": false, "explanation": "所属や修飾を示す助詞。「料理の技術の学んだ」は述語の目的語にならない。"}], "correct_answer": "を", "explanations": {"を": "「技術を学んだ」の対象を示す格助詞で、ここに入る正しい助詞。", "が": "主語を示す助詞。「料理の技術が学んだ」では技術が学ぶ主体になり、意味が通らない。", "へ": "方向を示す助詞。「技術へ学んだ」は学ぶ対象を表せない。", "の": "所属や修飾を示す助詞。「料理の技術の学んだ」は述語の目的語にならない。"}, "error_tags": {"が": "主語", "へ": "方向", "の": "所属・修飾"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e33d01b3-97f1-4e39-a664-d3e16060402b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35169, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「プログラミングを学ぶ」の対象を示す格助詞で、ここに入る正しい助詞。"}, {"text": "と", "is_correct": false, "explanation": "共同や引用を示す助詞。「プログラミングと学ぶ学生」は目的語を作れない。"}, {"text": "より", "is_correct": false, "explanation": "比較を示す助詞。「プログラミングより学ぶ学生」は学ぶ対象を表せず、文脈に合わない。"}, {"text": "や", "is_correct": false, "explanation": "列挙の「や」。並べる相手がなく、「プログラミングや学ぶ学生」は成り立たない。"}], "correct_answer": "を", "explanations": {"を": "「プログラミングを学ぶ」の対象を示す格助詞で、ここに入る正しい助詞。", "と": "共同や引用を示す助詞。「プログラミングと学ぶ学生」は目的語を作れない。", "より": "比較を示す助詞。「プログラミングより学ぶ学生」は学ぶ対象を表せず、文脈に合わない。", "や": "列挙の「や」。並べる相手がなく、「プログラミングや学ぶ学生」は成り立たない。"}, "error_tags": {"と": "共同・引用", "より": "比較", "や": "列挙"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e33d01b3-97f1-4e39-a664-d3e16060402b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35169, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "勉強や経験を通して、知識や技術を身につけること。", "primary_collocate": null, "pronunciation": "まなぶ", "ipa": "manabɯ", "syllable_count": 3, "sentences": [{"text": "大学で経済を学ぶつもりです。", "target_word": "学ぶ", "complexity_tier": "T3", "furigana": "大学[だいがく]で経済[けいざい]を学[まな]ぶつもりです。", "sentence_source": "generated"}, {"text": "兄はフランスで料理の技術を学んだ。", "target_word": "学んだ", "complexity_tier": "T3", "furigana": "兄[あに]はフランスで料理[りょうり]の技術[ぎじゅつ]を学[まな]んだ。", "sentence_source": "generated"}, {"text": "英語を学ぶために、毎晩オンライン授業を受けています。", "target_word": "学ぶ", "complexity_tier": "T3", "furigana": "英語[えいご]を学[まな]ぶために、毎晩[まいばん]オンライン授業[じゅぎょう]を受[う]けています。", "sentence_source": "generated"}, {"text": "職人のもとで、木を削る技術を学んでいる。", "target_word": "学んでいる", "complexity_tier": "T4", "furigana": "職人[しょくにん]のもとで、木[き]を削[けず]る技術[ぎじゅつ]を学[まな]んでいる。", "sentence_source": "generated"}, {"text": "留学して、海外の教育制度を学びたいです。", "target_word": "学びたい", "complexity_tier": "T4", "furigana": "留学[りゅうがく]して、海外[かいがい]の教育[きょういく]制度[せいど]を学[まな]びたいです。", "sentence_source": "generated"}, {"text": "彼女は夜間学校で看護を学び、資格を取った。", "target_word": "学び", "complexity_tier": "T4", "furigana": "彼女[かのじょ]は夜間[やかん]学校[がっこう]で看護[かんご]を学[まな]び、資格[しかく]を取[と]った。", "sentence_source": "generated"}, {"text": "仕事を通して、お客様への話し方を学びました。", "target_word": "学びました", "complexity_tier": "T3", "furigana": "仕事[しごと]を通[とお]して、お客様[きゃくさま]への話[はな]し方[かた]を学[まな]びました。", "sentence_source": "generated"}, {"text": "将来のために、プログラミングを学ぶ学生が増えている。", "target_word": "学ぶ", "complexity_tier": "T4", "furigana": "将来[しょうらい]のために、プログラミングを学[まな]ぶ学生[がくせい]が増[ふ]えている。", "sentence_source": "generated"}, {"text": "医学を学ぶには、長い時間がかかります。", "target_word": "学ぶ", "complexity_tier": "T3", "furigana": "医学[いがく]を学[まな]ぶには、長[なが]い時間[じかん]がかかります。", "sentence_source": "generated"}, {"text": "基礎を学んでから、応用に進むほうがいい。", "target_word": "学んで", "complexity_tier": "T4", "furigana": "基礎[きそ]を学[まな]んでから、応用[おうよう]に進[すす]むほうがいい。", "sentence_source": "generated"}], "morphological_forms": [{"form": "学ぶ", "label": "終止形"}, {"form": "学び", "label": "連用形"}, {"form": "学んだ", "label": "過去形"}, {"form": "学んで", "label": "て形"}, {"form": "学ばない", "label": "否定形"}, {"form": "学びたい", "label": "願望形"}, {"form": "学べる", "label": "可能形"}], "register": "neutral", "sense_fingerprint": "学校・師匠・仕事などで、学問や技術といった体系的な知識を身につける。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4c3b1d77-b0ef-4bb3-862f-9f84b278ab5c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35169, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "学ぶ", "is_correct": true, "explanation": "「経済を学ぶつもり」で、大学で専門知識を身につける意味に合う。"}, {"text": "運ぶ", "is_correct": false, "explanation": "「経済を運ぶつもり」は意味が通らず、空所に入らない。"}, {"text": "叫ぶ", "is_correct": false, "explanation": "「経済を叫ぶつもり」は意味が通らず、空所に入らない。"}, {"text": "遊ぶ", "is_correct": false, "explanation": "「経済を遊ぶつもり」は意味が通らず、空所に入らない。"}], "explanations": {"学ぶ": "「経済を学ぶつもり」で、大学で専門知識を身につける意味に合う。", "運ぶ": "「経済を運ぶつもり」は意味が通らず、空所に入らない。", "叫ぶ": "「経済を叫ぶつもり」は意味が通らず、空所に入らない。", "遊ぶ": "「経済を遊ぶつもり」は意味が通らず、空所に入らない。"}, "sentence_index": 0, "correct_answer": "学ぶ"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "先生が生徒に英語を学ぶ。", "explanation": "〈教える〉の意味。「学ぶ」は教わる側の行為で、教える側の先生を主語にはできない。"}, {"text": "店で野菜を学ぶ。", "explanation": "〈売る〉の意味。「学ぶ」は知識や技能を身につける行為で、商品を売ることには使わない。"}, {"text": "母は毎朝パンを学ぶ。", "explanation": "〈作る〉の意味。「学ぶ」は身につける行為で、パンを生み出す意味にはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e33d01b3-97f1-4e39-a664-d3e16060402b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35169, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "学びました", "is_correct": true, "explanation": "丁寧な過去形。「話し方を学びました」で、仕事を通して身につけた意味に合う。"}, {"text": "飛びました", "is_correct": false, "explanation": "「話し方を飛びました」は意味が通らず、空所に入らない。"}, {"text": "眺めました", "is_correct": false, "explanation": "「話し方を眺めました」は意味が通らず、空所に入らない。"}, {"text": "喜びました", "is_correct": false, "explanation": "「話し方を喜びました」は意味が通らず、空所に入らない。"}], "explanations": {"学びました": "丁寧な過去形。「話し方を学びました」で、仕事を通して身につけた意味に合う。", "飛びました": "「話し方を飛びました」は意味が通らず、空所に入らない。", "眺めました": "「話し方を眺めました」は意味が通らず、空所に入らない。", "喜びました": "「話し方を喜びました」は意味が通らず、空所に入らない。"}, "sentence_index": 6, "correct_answer": "学びました"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "窓の外を学んだ。", "explanation": "〈眺める〉の意味。「学ぶ」は知識や技能を身につける動詞で、景色を眺める意味にはならない。"}, {"text": "新しいカバンを学んだ。", "explanation": "〈買う〉の意味。「学ぶ」は身につける行為で、物を購入する意味にはならない。"}, {"text": "古い皿を学んだ。", "explanation": "〈割る〉の意味。「学ぶ」は知識や技能を得る動詞で、皿を壊す意味にはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e33d01b3-97f1-4e39-a664-d3e16060402b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35169, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妹は大学で数学が学んでいる。", "corrected_sentence": "妹は大学で数学を学んでいる。", "error_description": "「学ぶ」の対象を示す助詞が「が」になっている。目的語を示す「を」が正しい（数学を学ぶ）。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "学んだ", "is_correct": true, "explanation": "過去形。「技術を学んだ」で、フランスでの過去の出来事に合う。"}, {"text": "学ぶ", "is_correct": false, "explanation": "終止形。過去の出来事を述べる文では時制が合わない。"}, {"text": "学んで", "is_correct": false, "explanation": "て形。文末の述語にはならず、「学んで」で文が終わらない。"}, {"text": "学ばない", "is_correct": false, "explanation": "否定形。学ばなかったことを表し、意味が逆になる。"}], "correct_form": "学んだ", "base_form": "学ぶ", "form_label": "過去形", "sentence_index": 1, "explanations": {"学んだ": "過去形。「技術を学んだ」で、フランスでの過去の出来事に合う。", "学ぶ": "終止形。過去の出来事を述べる文では時制が合わない。", "学んで": "て形。文末の述語にはならず、「学んで」で文が終わらない。", "学ばない": "否定形。学ばなかったことを表し、意味が逆になる。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e33d01b3-97f1-4e39-a664-d3e16060402b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35169, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "私は英語を学んたい。", "corrected_sentence": "私は英語を学びたい。", "error_description": "「学ぶ」の願望形は「学びたい」。「学んたい」は活用の誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "学ぶ", "is_correct": true, "explanation": "連体形。「学ぶ学生」で後の名詞を修飾し、文脈に合う。"}, {"text": "学び", "is_correct": false, "explanation": "連用形。名詞を直接修飾できず、「学び学生」は成り立たない。"}, {"text": "学んで", "is_correct": false, "explanation": "て形。名詞を修飾できず、「学んで学生」は成り立たない。"}, {"text": "学べ", "is_correct": false, "explanation": "命令形。名詞を修飾できず、「学べ学生」は成り立たない。"}], "correct_form": "学ぶ", "base_form": "学ぶ", "form_label": "連体形", "sentence_index": 7, "explanations": {"学ぶ": "連体形。「学ぶ学生」で後の名詞を修飾し、文脈に合う。", "学び": "連用形。名詞を直接修飾できず、「学び学生」は成り立たない。", "学んで": "て形。名詞を修飾できず、「学んで学生」は成り立たない。", "学べ": "命令形。名詞を修飾できず、「学べ学生」は成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e33d01b3-97f1-4e39-a664-d3e16060402b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35170, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「習慣にしたい」の結果や変化を示す格助詞で、ここに入る正しい助詞。"}, {"text": "で", "is_correct": false, "explanation": "手段を示す助詞。「習慣でしたい」は「習慣にする」の形にならない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す助詞。「習慣へしたい」は結果を表せず、文が成り立たない。"}, {"text": "が", "is_correct": false, "explanation": "主語や対象を示す助詞。「習慣がしたい」は「習慣にする」の形にならない。"}], "correct_answer": "に", "explanations": {"に": "「習慣にしたい」の結果や変化を示す格助詞で、ここに入る正しい助詞。", "で": "手段を示す助詞。「習慣でしたい」は「習慣にする」の形にならない。", "へ": "方向を示す助詞。「習慣へしたい」は結果を表せず、文が成り立たない。", "が": "主語や対象を示す助詞。「習慣がしたい」は「習慣にする」の形にならない。"}, "error_tags": {"で": "手段", "へ": "方向", "が": "主語・対象"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e33d01b3-97f1-4e39-a664-d3e16060402b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
