INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35170, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "何度も同じことをするようになること。", "primary_collocate": null, "pronunciation": "しゅうかん", "ipa": "ʃɯːkaɴ", "syllable_count": 4, "sentences": [{"text": "毎朝走っているうちに、早起きが習慣になった。", "target_word": "習慣", "complexity_tier": "T3", "furigana": "毎朝[まいあさ]走[はし]っているうちに、早起[はやお]きが習慣[しゅうかん]になった。", "sentence_source": "generated"}, {"text": "日記を書くことを習慣にしたいです。", "target_word": "習慣", "complexity_tier": "T3", "furigana": "日記[にっき]を書[か]くことを習慣[しゅうかん]にしたいです。", "sentence_source": "generated"}, {"text": "最初は大変でも、続ければ習慣がつく。", "target_word": "習慣", "complexity_tier": "T3", "furigana": "最初[さいしょ]は大変[たいへん]でも、続[つづ]ければ習慣[しゅうかん]がつく。", "sentence_source": "generated"}, {"text": "運動を習慣にすると、体が軽くなります。", "target_word": "習慣", "complexity_tier": "T3", "furigana": "運動[うんどう]を習慣[しゅうかん]にすると、体[からだ]が軽[かる]くなります。", "sentence_source": "generated"}, {"text": "夜にスマホを見るのが習慣になって、なかなか眠れない。", "target_word": "習慣", "complexity_tier": "T4", "furigana": "夜[よる]にスマホを見[み]るのが習慣[しゅうかん]になって、なかなか眠[ねむ]れない。", "sentence_source": "generated"}, {"text": "毎日少しずつ勉強する習慣を身につけたい。", "target_word": "習慣", "complexity_tier": "T3", "furigana": "毎日[まいにち]少[すこ]しずつ勉強[べんきょう]する習慣[しゅうかん]を身[み]につけたい。", "sentence_source": "generated"}, {"text": "三週間続けると、新しいことも習慣になると言われる。", "target_word": "習慣", "complexity_tier": "T4", "furigana": "三週間[さんしゅうかん]続[つづ]けると、新[あたら]しいことも習慣[しゅうかん]になると言[い]われる。", "sentence_source": "generated"}, {"text": "食後に歯をみがくのが習慣になっているので、忘れません。", "target_word": "習慣", "complexity_tier": "T4", "furigana": "食後[しょくご]に歯[は]をみがくのが習慣[しゅうかん]になっているので、忘[わす]れません。", "sentence_source": "generated"}, {"text": "習慣になるまでは、毎日自分に声をかけて続けた。", "target_word": "習慣", "complexity_tier": "T4", "furigana": "習慣[しゅうかん]になるまでは、毎日[まいにち]自分[じぶん]に声[こえ]をかけて続[つづ]けた。", "sentence_source": "generated"}, {"text": "早寝を習慣にしたら、朝が楽になった。", "target_word": "習慣", "complexity_tier": "T3", "furigana": "早寝[はやね]を習慣[しゅうかん]にしたら、朝[あさ]が楽[らく]になった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "習慣", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "同じ行動を繰り返して、それが当たり前になること。習慣になる・習慣にするという形成の面。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 7 above tier T3: contains vocabulary far above tier T3: みがく (Zipf 1.93)']::text[], '4c3b1d77-b0ef-4bb3-862f-9f84b278ab5c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35170, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "習慣", "is_correct": true, "explanation": "「早起きが習慣になった」で、繰り返しによって当たり前になった意味に合う。"}, {"text": "天気", "is_correct": false, "explanation": "「早起きが天気になった」は意味が通らず、空所に入らない。"}, {"text": "季節", "is_correct": false, "explanation": "「早起きが季節になった」は意味が通らず、空所に入らない。"}, {"text": "料理", "is_correct": false, "explanation": "「早起きが料理になった」は意味が通らず、空所に入らない。"}], "explanations": {"習慣": "「早起きが習慣になった」で、繰り返しによって当たり前になった意味に合う。", "天気": "「早起きが天気になった」は意味が通らず、空所に入らない。", "季節": "「早起きが季節になった」は意味が通らず、空所に入らない。", "料理": "「早起きが料理になった」は意味が通らず、空所に入らない。"}, "sentence_index": 0, "correct_answer": "習慣"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "昨日の習慣は大雨だった。", "explanation": "〈天気〉の意味。「習慣」は繰り返す行動を指し、天候は表せない。"}, {"text": "習慣の再会に驚いた。", "explanation": "〈偶然〉の意味。「習慣」は偶然の出来事を表さず、再会には使わない。"}, {"text": "習慣を防いだ。", "explanation": "〈事故〉の意味。「習慣」は起こるものではなく、防ぐ対象にはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e33d01b3-97f1-4e39-a664-d3e16060402b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35170, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "習慣", "is_correct": true, "explanation": "「新しいことも習慣になる」で、繰り返しによって定着するという意味に合う。"}, {"text": "機械", "is_correct": false, "explanation": "「新しいことも機械になる」は意味が通らず、空所に入らない。"}, {"text": "天井", "is_correct": false, "explanation": "「新しいことも天井になる」は意味が通らず、空所に入らない。"}, {"text": "窓", "is_correct": false, "explanation": "「新しいことも窓になる」は意味が通らず、空所に入らない。"}], "explanations": {"習慣": "「新しいことも習慣になる」で、繰り返しによって定着するという意味に合う。", "機械": "「新しいことも機械になる」は意味が通らず、空所に入らない。", "天井": "「新しいことも天井になる」は意味が通らず、空所に入らない。", "窓": "「新しいことも窓になる」は意味が通らず、空所に入らない。"}, "sentence_index": 6, "correct_answer": "習慣"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "貴重な習慣をした。", "explanation": "〈経験〉の意味。「習慣」は繰り返す行動を指し、一度きりの経験には使わない。"}, {"text": "この習慣は駅の近くだ。", "explanation": "〈場所〉の意味。「習慣」は繰り返す行動を指し、場所は表せない。"}, {"text": "私は習慣が弱い。", "explanation": "〈体質〉の意味。「習慣」に強い弱いという体質の意味はなく、この使い方はしない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e33d01b3-97f1-4e39-a664-d3e16060402b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35170, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "毎朝の散歩を習慣に付けている。", "corrected_sentence": "毎朝の散歩を習慣にしている。", "error_description": "「習慣」は「にする」の形が基本。「習慣に付ける」は誤りで、「習慣をつける」なら「を」を使う。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e33d01b3-97f1-4e39-a664-d3e16060402b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35170, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "毎晩寝る前にストレッチをするのを習慣をしている。", "corrected_sentence": "毎晩寝る前にストレッチをするのを習慣にしている。", "error_description": "「習慣」には「にする」を使う。「習慣をしている」は不自然で、助詞の「を」が誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e33d01b3-97f1-4e39-a664-d3e16060402b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35171, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "正解。「習慣」を主題として示し、「子どもの健康を守る」と述べる文の主題の「は」。"}, {"text": "を", "is_correct": false, "explanation": "「を」は目的語を示す。「守る」の目的語は健康であり、習慣を目的語にする文ではないため合わない。"}, {"text": "に", "is_correct": false, "explanation": "「に」は相手や場所を示す。「習慣に、子どもの健康を守る」では文の構造が成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並列や相手を示す。「習慣と、子どもの健康を守る」では主語と述語がつながらない。"}], "correct_answer": "は", "explanations": {"は": "正解。「習慣」を主題として示し、「子どもの健康を守る」と述べる文の主題の「は」。", "を": "「を」は目的語を示す。「守る」の目的語は健康であり、習慣を目的語にする文ではないため合わない。", "に": "「に」は相手や場所を示す。「習慣に、子どもの健康を守る」では文の構造が成り立たない。", "と": "「と」は並列や相手を示す。「習慣と、子どもの健康を守る」では主語と述語がつながらない。"}, "error_tags": {"を": "目的語", "に": "方向・相手", "と": "並列・相手"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e33d01b3-97f1-4e39-a664-d3e16060402b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35171, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "正解。「長年の習慣で」は原因・理由を示し、長年の習慣が目覚めの原因であることを表す。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示す。「習慣へ、目が覚める」では文が成り立たない。"}, {"text": "の", "is_correct": false, "explanation": "「の」は名詞をつなぐ。「習慣の、休みの日も」では述語に続かず不自然。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較を示す。「習慣より」では比べる対象がなく、目が覚める理由にならない。"}], "correct_answer": "で", "explanations": {"で": "正解。「長年の習慣で」は原因・理由を示し、長年の習慣が目覚めの原因であることを表す。", "へ": "「へ」は方向を示す。「習慣へ、目が覚める」では文が成り立たない。", "の": "「の」は名詞をつなぐ。「習慣の、休みの日も」では述語に続かず不自然。", "より": "「より」は比較を示す。「習慣より」では比べる対象がなく、目が覚める理由にならない。"}, "error_tags": {"へ": "方向", "の": "連体・所有", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e33d01b3-97f1-4e39-a664-d3e16060402b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35171, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "ある行動を繰り返し行うことで、自然と身についた行動の仕方。", "primary_collocate": null, "pronunciation": "しゅうかん", "ipa": "ʃɯːkaɴ", "syllable_count": 4, "sentences": [{"text": "私には、寝る前にお茶を飲む習慣がある。", "target_word": "習慣", "complexity_tier": "T3", "furigana": "私[わたし]には、寝[ね]る前[まえ]にお茶[ちゃ]を飲[の]む習慣[しゅうかん]がある。", "sentence_source": "generated"}, {"text": "食事の前に手を洗う習慣は、子どもの健康を守る。", "target_word": "習慣", "complexity_tier": "T4", "furigana": "食事[しょくじ]の前[まえ]に手[て]を洗[あら]う習慣[しゅうかん]は、子[こ]どもの健康[けんこう]を守[まも]る。", "sentence_source": "generated"}, {"text": "悪い習慣はなかなか直せない。", "target_word": "習慣", "complexity_tier": "T3", "furigana": "悪[わる]い習慣[しゅうかん]はなかなか直[なお]せない。", "sentence_source": "generated"}, {"text": "食べながらテレビを見る習慣をやめたい。", "target_word": "習慣", "complexity_tier": "T3", "furigana": "食[た]べながらテレビを見[み]る習慣[しゅうかん]をやめたい。", "sentence_source": "generated"}, {"text": "祖母は朝五時に起きる習慣があり、今も変わらない。", "target_word": "習慣", "complexity_tier": "T3", "furigana": "祖母[そぼ]は朝[あさ]五時[ごじ]に起[お]きる習慣[しゅうかん]があり、今[いま]も変[か]わらない。", "sentence_source": "generated"}, {"text": "食事のとき、ゆっくりかむ習慣が健康にいい。", "target_word": "習慣", "complexity_tier": "T3", "furigana": "食事[しょくじ]のとき、ゆっくりかむ習慣[しゅうかん]が健康[けんこう]にいい。", "sentence_source": "generated"}, {"text": "彼の爪をかむ習慣は、子どものころからだ。", "target_word": "習慣", "complexity_tier": "T3", "furigana": "彼[かれ]の爪[つめ]をかむ習慣[しゅうかん]は、子[こ]どものころからだ。", "sentence_source": "generated"}, {"text": "長年の習慣で、休みの日も同じ時間に目が覚める。", "target_word": "習慣", "complexity_tier": "T4", "furigana": "長年[ながねん]の習慣[しゅうかん]で、休[やす]みの日[ひ]も同[おな]じ時間[じかん]に目[め]が覚[さ]める。", "sentence_source": "generated"}, {"text": "食事の習慣を変えたら、体重が減った。", "target_word": "習慣", "complexity_tier": "T3", "furigana": "食事[しょくじ]の習慣[しゅうかん]を変[か]えたら、体重[たいじゅう]が減[へ]った。", "sentence_source": "generated"}, {"text": "友人は電車で本を読む習慣があり、いつも一冊持っている。", "target_word": "習慣", "complexity_tier": "T4", "furigana": "友人[ゆうじん]は電車[でんしゃ]で本[ほん]を読[よ]む習慣[しゅうかん]があり、いつも一冊[いっさつ]持[も]っている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "習慣", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "繰り返しによって身についた、その人の決まった行動の仕方。習慣がある・悪い習慣という定着した面。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4c3b1d77-b0ef-4bb3-862f-9f84b278ab5c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35171, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "習慣", "is_correct": true, "explanation": "正解。「寝る前にお茶を飲む」という繰り返しの行動を、身についた習慣として表す語。"}, {"text": "天気", "is_correct": false, "explanation": "天気は「お茶を飲む」の対象にならず、「お茶を飲む天気がある」は意味をなさない。"}, {"text": "銀行", "is_correct": false, "explanation": "銀行は飲む対象ではないため、「お茶を飲む銀行がある」は文として成り立たない。"}, {"text": "方言", "is_correct": false, "explanation": "方言は話し言葉のことで、「お茶を飲む方言がある」は意味が通らない。"}], "explanations": {"習慣": "正解。「寝る前にお茶を飲む」という繰り返しの行動を、身についた習慣として表す語。", "天気": "天気は「お茶を飲む」の対象にならず、「お茶を飲む天気がある」は意味をなさない。", "銀行": "銀行は飲む対象ではないため、「お茶を飲む銀行がある」は文として成り立たない。", "方言": "方言は話し言葉のことで、「お茶を飲む方言がある」は意味が通らない。"}, "sentence_index": 0, "correct_answer": "習慣"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この扇風機は、急に止まる習慣がある。", "explanation": "ここは〈癖〉の意味。機械の不具合の傾向には〈癖〉を使い、習慣は人の繰り返し行動に使う。"}, {"text": "彼はピアノの習慣が上手で、コンクールで優勝した。", "explanation": "ここは〈技術〉の意味。腕前の高さは技術で表し、習慣では表せない。"}, {"text": "昨日の火事は、一度きりの習慣として人々の記憶に残った。", "explanation": "ここは〈出来事〉の意味。一度きりの事件は習慣とは言わず、習慣は繰り返しの行動を指す。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e33d01b3-97f1-4e39-a664-d3e16060402b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35171, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "習慣", "is_correct": true, "explanation": "正解。爪をかむという繰り返しの行動が身についたことを表す語。"}, {"text": "切手", "is_correct": false, "explanation": "切手は行為の主語にならず、「爪をかむ切手は」では意味が通らない。"}, {"text": "電車", "is_correct": false, "explanation": "電車は爪をかむ行為と結びつかず、文として成り立たない。"}, {"text": "窓", "is_correct": false, "explanation": "窓は「爪をかむ」の名詞として当てはまらず、意味が通らない。"}], "explanations": {"習慣": "正解。爪をかむという繰り返しの行動が身についたことを表す語。", "切手": "切手は行為の主語にならず、「爪をかむ切手は」では意味が通らない。", "電車": "電車は爪をかむ行為と結びつかず、文として成り立たない。", "窓": "窓は「爪をかむ」の名詞として当てはまらず、意味が通らない。"}, "sentence_index": 6, "correct_answer": "習慣"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この薬は強い習慣があるので、医師の指示なしには飲めない。", "explanation": "ここは〈習慣性〉の意味。薬が依存を起こす性質は習慣性と言い、習慣では表せない。"}, {"text": "彼女は歴史の習慣が豊富で、どんな質問にも答えられる。", "explanation": "ここは〈知識〉の意味。知っている量の多さは知識と言い、習慣では言わない。"}, {"text": "彼は契約書の習慣を細かく確認した。", "explanation": "ここは〈内容〉の意味。契約書の文面や中身は内容と言い、習慣では表せない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e33d01b3-97f1-4e39-a664-d3e16060402b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35171, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "私は毎日十分ほど散歩する習慣に持っている。", "corrected_sentence": "私は毎日十分ほど散歩する習慣を持っている。", "error_description": "正しくは「習慣を持つ」。「習慣に持つ」と「に」を使うと不自然になるので、助詞は「を」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e33d01b3-97f1-4e39-a664-d3e16060402b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35171, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼は毎日ストレッチをする習慣が身につける。", "corrected_sentence": "彼は毎日ストレッチをする習慣が身についている。", "error_description": "「習慣が身につく」は自動詞で、主語は習慣になる。「身につける」は他動詞で目的語が要るため誤り。正しくは「身についている」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e33d01b3-97f1-4e39-a664-d3e16060402b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35172, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "正解。「赤ちゃんが生まれた」と出来事の主語を示す「が」。"}, {"text": "を", "is_correct": false, "explanation": "「を」は目的語を示す。「赤ちゃんを生まれた」は不自然で、出来事の主語にならない。"}, {"text": "に", "is_correct": false, "explanation": "「に」は相手や場所を示す。「赤ちゃんに生まれた」は出来事の主語として成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並列や共同を示す。「赤ちゃんと生まれた」では出来事の主語にならない。"}], "correct_answer": "が", "explanations": {"が": "正解。「赤ちゃんが生まれた」と出来事の主語を示す「が」。", "を": "「を」は目的語を示す。「赤ちゃんを生まれた」は不自然で、出来事の主語にならない。", "に": "「に」は相手や場所を示す。「赤ちゃんに生まれた」は出来事の主語として成り立たない。", "と": "「と」は並列や共同を示す。「赤ちゃんと生まれた」では出来事の主語にならない。"}, "error_tags": {"を": "目的語", "に": "相手・場所", "と": "並列・共同"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "死ぬ", "is_correct": true, "explanation": "正解。「生まれる」の対義語で、命が終わること。"}, {"text": "眠る", "is_correct": false, "explanation": "眠るは睡眠を指し、誕生の反対語ではない。"}, {"text": "歩く", "is_correct": false, "explanation": "歩くは移動の動作で、誕生と対になる語ではない。"}, {"text": "笑う", "is_correct": false, "explanation": "笑うは表情や感情の動作で、誕生の対義語ではない。"}], "correct_answer": "死ぬ", "explanations": {"死ぬ": "正解。「生まれる」の対義語で、命が終わること。", "眠る": "眠るは睡眠を指し、誕生の反対語ではない。", "歩く": "歩くは移動の動作で、誕生と対になる語ではない。", "笑う": "笑うは表情や感情の動作で、誕生の対義語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e33d01b3-97f1-4e39-a664-d3e16060402b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35172, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "正解。時期を示す「に」で、戦争のころに生まれたことを表す。"}, {"text": "が", "is_correct": false, "explanation": "「が」は主語を示す。「戦争のころが生まれ」では時期の表現として成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示す。「戦争のころへ生まれ」は不自然。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較を示す。「戦争のころより生まれ」では意味が通らない。"}], "correct_answer": "に", "explanations": {"に": "正解。時期を示す「に」で、戦争のころに生まれたことを表す。", "が": "「が」は主語を示す。「戦争のころが生まれ」では時期の表現として成り立たない。", "へ": "「へ」は方向を示す。「戦争のころへ生まれ」は不自然。", "より": "「より」は比較を示す。「戦争のころより生まれ」では意味が通らない。"}, "error_tags": {"が": "主語", "へ": "方向", "より": "比較"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "死ぬ", "is_correct": true, "explanation": "正解。「生まれる」の対義語で、命が終わること。"}, {"text": "食べる", "is_correct": false, "explanation": "食べるは飲食の動作で、誕生の反対語ではない。"}, {"text": "走る", "is_correct": false, "explanation": "走るは移動の動作で、誕生と対になる語ではない。"}, {"text": "泣く", "is_correct": false, "explanation": "泣くは感情の表出で、誕生の対義語ではない。"}], "correct_answer": "死ぬ", "explanations": {"死ぬ": "正解。「生まれる」の対義語で、命が終わること。", "食べる": "食べるは飲食の動作で、誕生の反対語ではない。", "走る": "走るは移動の動作で、誕生と対になる語ではない。", "泣く": "泣くは感情の表出で、誕生の対義語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e33d01b3-97f1-4e39-a664-d3e16060402b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35172, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "赤ちゃんがお母さんのおなかから出てくること。", "primary_collocate": null, "pronunciation": "うまれる", "ipa": "ɯmaɾeɾɯ", "syllable_count": 4, "sentences": [{"text": "弟は春に生まれました。", "target_word": "生まれました", "complexity_tier": "T2", "furigana": "弟[おとうと]は春[はる]に生[う]まれました。", "sentence_source": "generated"}, {"text": "昨日、友だちの家で赤ちゃんが生まれた。", "target_word": "生まれた", "complexity_tier": "T2", "furigana": "昨日[きのう]、友[とも]だちの家[いえ]で赤[あか]ちゃんが生[う]まれた。", "sentence_source": "generated"}, {"text": "私は大阪の病院で生まれたが、育ったのは京都だ。", "target_word": "生まれた", "complexity_tier": "T3", "furigana": "私[わたし]は大阪[おおさか]の病院[びょういん]で生[う]まれたが、育[そだ]ったのは京都[きょうと]だ。", "sentence_source": "generated"}, {"text": "来月、姉に子どもが生まれる予定です。", "target_word": "生まれる", "complexity_tier": "T3", "furigana": "来月[らいげつ]、姉[あね]に子[こ]どもが生[う]まれる予定[よてい]です。", "sentence_source": "generated"}, {"text": "双子が生まれて、家の中がにぎやかになった。", "target_word": "生まれて", "complexity_tier": "T3", "furigana": "双子[ふたご]が生[う]まれて、家[いえ]の中[なか]がにぎやかになった。", "sentence_source": "generated"}, {"text": "生まれたばかりの赤ちゃんは、一日の大半を寝て過ごす。", "target_word": "生まれた", "complexity_tier": "T3", "furigana": "生[う]まれたばかりの赤[あか]ちゃんは、一日[いちにち]の大半[たいはん]を寝[ね]て過[す]ごす。", "sentence_source": "generated"}, {"text": "予定より早く生まれたので、赤ちゃんは小さかった。", "target_word": "生まれた", "complexity_tier": "T3", "furigana": "予定[よてい]より早[はや]く生[う]まれたので、赤[あか]ちゃんは小[ちい]さかった。", "sentence_source": "generated"}, {"text": "祖母は戦争のころに生まれ、苦労して育った。", "target_word": "生まれ", "complexity_tier": "T4", "furigana": "祖母[そぼ]は戦争[せんそう]のころに生[う]まれ、苦労[くろう]して育[そだ]った。", "sentence_source": "generated"}, {"text": "娘が生まれた日のことを、今でもはっきり覚えている。", "target_word": "生まれた", "complexity_tier": "T3", "furigana": "娘[むすめ]が生[う]まれた日[ひ]のことを、今[いま]でもはっきり覚[おぼ]えている。", "sentence_source": "generated"}, {"text": "無事に生まれるよう、家族みんなが祈っていた。", "target_word": "生まれる", "complexity_tier": "T4", "furigana": "無事[ぶじ]に生[う]まれるよう、家族[かぞく]みんなが祈[いの]っていた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "生まれる", "label": "終止形"}, {"form": "生まれ", "label": "連用形"}, {"form": "生まれた", "label": "過去形"}, {"form": "生まれて", "label": "て形"}, {"form": "生まれない", "label": "否定形"}, {"form": "生まれれば", "label": "仮定形"}, {"form": "生まれよう", "label": "意志形"}], "register": "neutral", "sense_fingerprint": "赤ちゃんが母親の体から出て、この世に誕生する。出産・誕生の意味。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4c3b1d77-b0ef-4bb3-862f-9f84b278ab5c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35172, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "生まれました", "is_correct": true, "explanation": "正解。「春に生まれました」と丁寧な過去形で、誕生した事実を述べる形。"}, {"text": "生まれて", "is_correct": false, "explanation": "て形は文末に置けず、「弟は春に生まれて。」と文が終わらない。"}, {"text": "生まれれば", "is_correct": false, "explanation": "仮定形は条件節になり、文を終えられない。"}, {"text": "生まれよう", "is_correct": false, "explanation": "意向形は意志を表すため、第三者の誕生を述べる文に合わない。"}], "explanations": {"生まれました": "正解。「春に生まれました」と丁寧な過去形で、誕生した事実を述べる形。", "生まれて": "て形は文末に置けず、「弟は春に生まれて。」と文が終わらない。", "生まれれば": "仮定形は条件節になり、文を終えられない。", "生まれよう": "意向形は意志を表すため、第三者の誕生を述べる文に合わない。"}, "sentence_index": 0, "correct_answer": "生まれました"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "電車は、駅から生まれた。", "explanation": "ここは〈出発する〉の意味。電車が駅を離れることは出るで表し、生まれるは誕生を指すので使えない。"}, {"text": "庭の雑草が一晩で生まれた。", "explanation": "ここは〈生える〉の意味。草が地面から出てくることは生えるで表し、生まれるは誕生を指すので合わない。"}, {"text": "その子は三歳まで病気もせず、すくすく生まれた。", "explanation": "ここは〈成長〉の意味。すくすく育つ過程は成長・育つで表し、生まれるは誕生の瞬間を指す。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e33d01b3-97f1-4e39-a664-d3e16060402b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35172, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "生まれた", "is_correct": true, "explanation": "正解。「予定より早く生まれたので」と過去の出来事を理由として述べる形。"}, {"text": "壊れた", "is_correct": false, "explanation": "壊れるは物の故障を表し、赤ちゃんの誕生の文には合わない。"}, {"text": "歌った", "is_correct": false, "explanation": "歌う動作は赤ちゃんの小ささの理由にならず、文の意味が通らない。"}, {"text": "届いた", "is_correct": false, "explanation": "届くは品物などの到着を表し、赤ちゃんが小さい理由として不自然。"}], "explanations": {"生まれた": "正解。「予定より早く生まれたので」と過去の出来事を理由として述べる形。", "壊れた": "壊れるは物の故障を表し、赤ちゃんの誕生の文には合わない。", "歌った": "歌う動作は赤ちゃんの小ささの理由にならず、文の意味が通らない。", "届いた": "届くは品物などの到着を表し、赤ちゃんが小さい理由として不自然。"}, "sentence_index": 6, "correct_answer": "生まれた"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "事故で一度は命を失いかけたが、奇跡的に生まれた。", "explanation": "ここは〈生き返る〉の意味。一度失いかけた命が戻ることは生まれるでは表せない。"}, {"text": "赤ちゃんの歯が三本、もう生まれた。", "explanation": "ここは〈生える〉の意味。歯が出てくることは生まれるではなく生えるを使う。"}, {"text": "壊れた機械が一晩で生まれた。", "explanation": "ここは〈修理〉の意味。壊れたものを直すことは生まれるではなく修理する。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e33d01b3-97f1-4e39-a664-d3e16060402b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35172, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "先週、友だちの家で赤ちゃんが生まれる。", "corrected_sentence": "先週、友だちの家で赤ちゃんが生まれた。", "error_description": "「先週」は過去を表すので、非過去の「生まれる」は誤り。正しくは過去形の「生まれた」。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "生まれた", "is_correct": true, "explanation": "正解。「昨日」の出来事を表す過去形。"}, {"text": "生まれて", "is_correct": false, "explanation": "て形は文を終えられず、「昨日、赤ちゃんが生まれて。」では文として完結しない。"}, {"text": "生まれない", "is_correct": false, "explanation": "否定形にすると「生まれなかった」となり、誕生した事実と合わない。"}, {"text": "生まれれば", "is_correct": false, "explanation": "仮定形は条件を表すため、起きた出来事を述べる文に合わない。"}], "correct_form": "生まれた", "base_form": "生まれる", "form_label": "過去形", "sentence_index": 1, "explanations": {"生まれた": "正解。「昨日」の出来事を表す過去形。", "生まれて": "て形は文を終えられず、「昨日、赤ちゃんが生まれて。」では文として完結しない。", "生まれない": "否定形にすると「生まれなかった」となり、誕生した事実と合わない。", "生まれれば": "仮定形は条件を表すため、起きた出来事を述べる文に合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e33d01b3-97f1-4e39-a664-d3e16060402b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35172, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "祖母は戦争のころを生まれ、苦労して育ったと聞く。", "corrected_sentence": "祖母は戦争のころに生まれ、苦労して育ったと聞く。", "error_description": "時点を示すのは「に」。「を」は目的語を示すため、「戦争のころを生まれ」は誤り。正しくは「に」。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "生まれ", "is_correct": true, "explanation": "正解。文を続ける連用形で、後の「育った」へつながる。"}, {"text": "生まれます", "is_correct": false, "explanation": "丁寧形は普通体の文中で続けにくく、「生まれます、苦労して」は不自然。"}, {"text": "生まれる", "is_correct": false, "explanation": "辞書形は続けられず、「生まれる、苦労して」は不自然。"}, {"text": "生まれたい", "is_correct": false, "explanation": "願望形では「生まれたい、苦労して育った」と意味が通らない。"}], "correct_form": "生まれ", "base_form": "生まれる", "form_label": "連用形", "sentence_index": 7, "explanations": {"生まれ": "正解。文を続ける連用形で、後の「育った」へつながる。", "生まれます": "丁寧形は普通体の文中で続けにくく、「生まれます、苦労して」は不自然。", "生まれる": "辞書形は続けられず、「生まれる、苦労して」は不自然。", "生まれたい": "願望形では「生まれたい、苦労して育った」と意味が通らない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e33d01b3-97f1-4e39-a664-d3e16060402b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35173, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "正解。「東京で生まれた」と出来事の場所を示す「で」。"}, {"text": "が", "is_correct": false, "explanation": "「東京が生まれて」では場所を示せず、文として成り立たない。"}, {"text": "を", "is_correct": false, "explanation": "「東京を生まれて」は不自然で、生まれた場所を表せない。"}, {"text": "と", "is_correct": false, "explanation": "「東京と生まれて」では場所の意味にならない。"}], "correct_answer": "で", "explanations": {"で": "正解。「東京で生まれた」と出来事の場所を示す「で」。", "が": "「東京が生まれて」では場所を示せず、文として成り立たない。", "を": "「東京を生まれて」は不自然で、生まれた場所を表せない。", "と": "「東京と生まれて」では場所の意味にならない。"}, "error_tags": {"が": "主語", "を": "目的語", "と": "並列・共同"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "死ぬ", "is_correct": true, "explanation": "正解。「生まれる」の対義語で、命が終わること。"}, {"text": "眠る", "is_correct": false, "explanation": "眠るは睡眠を指し、誕生の反対語ではない。"}, {"text": "歩く", "is_correct": false, "explanation": "歩くは移動の動作で、誕生と対になる語ではない。"}, {"text": "笑う", "is_correct": false, "explanation": "笑うは表情の動作で、誕生の対義語ではない。"}], "correct_answer": "死ぬ", "explanations": {"死ぬ": "正解。「生まれる」の対義語で、命が終わること。", "眠る": "眠るは睡眠を指し、誕生の反対語ではない。", "歩く": "歩くは移動の動作で、誕生と対になる語ではない。", "笑う": "笑うは表情の動作で、誕生の対義語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e33d01b3-97f1-4e39-a664-d3e16060402b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35173, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "正解。「この村で生まれた」と出来事の場所を示す「で」。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示す。「この村へ生まれた」では場所を示せない。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較を示す。「この村より生まれた」では意味が通らない。"}, {"text": "の", "is_correct": false, "explanation": "「の」は名詞をつなぐ。「この村の生まれた」は文として完結せず不自然。"}], "correct_answer": "で", "explanations": {"で": "正解。「この村で生まれた」と出来事の場所を示す「で」。", "へ": "「へ」は方向を示す。「この村へ生まれた」では場所を示せない。", "より": "「より」は比較を示す。「この村より生まれた」では意味が通らない。", "の": "「の」は名詞をつなぐ。「この村の生まれた」は文として完結せず不自然。"}, "error_tags": {"へ": "方向", "より": "比較", "の": "連体・所有"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "死ぬ", "is_correct": true, "explanation": "正解。「生まれる」の対義語で、命が終わること。"}, {"text": "食べる", "is_correct": false, "explanation": "食べるは飲食の動作で、誕生の反対語ではない。"}, {"text": "走る", "is_correct": false, "explanation": "走るは移動の動作で、誕生と対になる語ではない。"}, {"text": "泣く", "is_correct": false, "explanation": "泣くは感情の表出で、誕生の対義語ではない。"}], "correct_answer": "死ぬ", "explanations": {"死ぬ": "正解。「生まれる」の対義語で、命が終わること。", "食べる": "食べるは飲食の動作で、誕生の反対語ではない。", "走る": "走るは移動の動作で、誕生と対になる語ではない。", "泣く": "泣くは感情の表出で、誕生の対義語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e33d01b3-97f1-4e39-a664-d3e16060402b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35173, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "命を持ったものが、この世に出てくること。", "primary_collocate": null, "pronunciation": "うまれる", "ipa": "ɯmaɾeɾɯ", "syllable_count": 4, "sentences": [{"text": "昨日、うちの猫に子どもが生まれた。", "target_word": "生まれた", "complexity_tier": "T3", "furigana": "昨日(きのう)、うちの猫(ねこ)に子(こ)どもが生(う)まれた。", "sentence_source": "generated"}, {"text": "私は東京で生まれて、大阪で育った。", "target_word": "生まれて", "complexity_tier": "T3", "furigana": "私(わたし)は東京(とうきょう)で生(う)まれて、大阪(おおさか)で育(そだ)った。", "sentence_source": "generated"}, {"text": "姉に赤ちゃんが生まれるのは来月だ。", "target_word": "生まれる", "complexity_tier": "T3", "furigana": "姉(あね)に赤(あか)ちゃんが生(う)まれるのは来月(らいげつ)だ。", "sentence_source": "generated"}, {"text": "春になると、この池でカエルの子が生まれる。", "target_word": "生まれる", "complexity_tier": "T3", "furigana": "春(はる)になると、この池(いけ)でカエルの子(こ)が生(う)まれる。", "sentence_source": "generated"}, {"text": "兄は雪の降る日に生まれたそうだ。", "target_word": "生まれた", "complexity_tier": "T3", "furigana": "兄(あに)は雪(ゆき)の降(ふ)る日(ひ)に生(う)まれたそうだ。", "sentence_source": "generated"}, {"text": "動物園でパンダの赤ちゃんが生まれ、みんな喜んでいる。", "target_word": "生まれ", "complexity_tier": "T3", "furigana": "動物園(どうぶつえん)でパンダの赤(あか)ちゃんが生(う)まれ、みんな喜(よろこ)んでいる。", "sentence_source": "generated"}, {"text": "馬は生まれてすぐに立ち上がることができる。", "target_word": "生まれて", "complexity_tier": "T3", "furigana": "馬(うま)は生(う)まれてすぐに立(た)ち上(あ)がることができる。", "sentence_source": "generated"}, {"text": "祖父は八十年前にこの村で生まれた。", "target_word": "生まれた", "complexity_tier": "T3", "furigana": "祖父(そふ)は八十年前(はちじゅうねんまえ)にこの村(むら)で生(う)まれた。", "sentence_source": "generated"}, {"text": "卵から小さなひよこが生まれた。", "target_word": "生まれた", "complexity_tier": "T3", "furigana": "卵(たまご)から小(ちい)さなひよこが生(う)まれた。", "sentence_source": "generated"}, {"text": "双子が生まれたので、家の中がにぎやかになった。", "target_word": "生まれた", "complexity_tier": "T3", "furigana": "双子(ふたご)が生(う)まれたので、家(いえ)の中(なか)がにぎやかになった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "生まれる", "label": "辞書形"}, {"form": "生まれます", "label": "丁寧形"}, {"form": "生まれない", "label": "否定形"}, {"form": "生まれた", "label": "過去形"}, {"form": "生まれて", "label": "て形"}, {"form": "生まれれば", "label": "仮定形"}, {"form": "生まれよう", "label": "意向形"}], "register": "neutral", "sense_fingerprint": "命あるものが誕生すること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4c3b1d77-b0ef-4bb3-862f-9f84b278ab5c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35173, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "生まれた", "is_correct": true, "explanation": "正解。「昨日」に合う過去形で、猫の出産という出来事を述べる。"}, {"text": "生まれれば", "is_correct": false, "explanation": "仮定形は条件を表し、昨日の出来事を述べる文にならない。"}, {"text": "生まれない", "is_correct": false, "explanation": "否定形では出来事が起きなかったことになり、文の内容に合わない。"}, {"text": "生まれよう", "is_correct": false, "explanation": "意向形は意志を表し、昨日起きた出来事には合わない。"}], "explanations": {"生まれた": "正解。「昨日」に合う過去形で、猫の出産という出来事を述べる。", "生まれれば": "仮定形は条件を表し、昨日の出来事を述べる文にならない。", "生まれない": "否定形では出来事が起きなかったことになり、文の内容に合わない。", "生まれよう": "意向形は意志を表し、昨日起きた出来事には合わない。"}, "sentence_index": 0, "correct_answer": "生まれた"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "生徒は先生の合図で一斉に生まれた。", "explanation": "ここは〈立つ〉の意味。一斉に立ち上がることは立つで表し、生まれるは命の誕生を指すので合わない。"}, {"text": "その子犬は一年で、すくすく生まれた。", "explanation": "ここは〈成長〉の意味。すくすく育つことは成長・育つで表し、生まれるは誕生の瞬間を指す。"}, {"text": "朝、彼は七時に生まれて、会社へ出かけた。", "explanation": "ここは〈出かける〉の意味。家を出て出社することは出かけるで表し、生まれるは誕生を指すので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e33d01b3-97f1-4e39-a664-d3e16060402b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35173, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "生まれて", "is_correct": true, "explanation": "正解。「生まれてすぐに」とつなぐ て形。"}, {"text": "壊れて", "is_correct": false, "explanation": "壊れるは物が使えなくなることを表し、馬の動作の文には合わない。"}, {"text": "生まれる", "is_correct": false, "explanation": "辞書形は「生まれるすぐに」と続かず、文が成り立たない。"}, {"text": "生まれず", "is_correct": false, "explanation": "否定の連用形で、「生まれずすぐに立ち上がる」は意味が通らない。"}], "explanations": {"生まれて": "正解。「生まれてすぐに」とつなぐ て形。", "壊れて": "壊れるは物が使えなくなることを表し、馬の動作の文には合わない。", "生まれる": "辞書形は「生まれるすぐに」と続かず、文が成り立たない。", "生まれず": "否定の連用形で、「生まれずすぐに立ち上がる」は意味が通らない。"}, "sentence_index": 6, "correct_answer": "生まれて"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "溺れた犬は奇跡的に生まれ、家に戻った。", "explanation": "ここは〈生き返る〉の意味。一度命を失った者が戻ることは生まれるでは表せない。"}, {"text": "子ネコの毛が、一晩で生まれた。", "explanation": "ここは〈生える〉の意味。毛が出てくることは生まれるではなく生えるを使う。"}, {"text": "新しい橋が、川の上に一晩で生まれた。", "explanation": "ここは〈完成〉の意味。橋は架けるで表し、生まれるは命の誕生に使う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e33d01b3-97f1-4e39-a664-d3e16060402b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35173, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "叔父は三十年前に生まれる。", "corrected_sentence": "叔父は三十年前に生まれた。", "error_description": "「三十年前」は過去を表すので、非過去の「生まれる」は誤り。正しくは過去形の「生まれた」。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "生まれて", "is_correct": true, "explanation": "正解。「生まれて、大阪で育った」と続ける て形。"}, {"text": "生まれよう", "is_correct": false, "explanation": "意向形は話し手の意志を表し、「東京で生まれよう、大阪で育った」は文として成り立たない。"}, {"text": "生まれたい", "is_correct": false, "explanation": "願望形では「東京で生まれたい、大阪で育った」と意味が通らず、出生の事実を述べる文に合わない。"}, {"text": "生まれます", "is_correct": false, "explanation": "丁寧形は普通体の文中に入れると不自然で、文を続けられない。"}], "correct_form": "生まれて", "base_form": "生まれる", "form_label": "て形", "sentence_index": 1, "explanations": {"生まれて": "正解。「生まれて、大阪で育った」と続ける て形。", "生まれよう": "意向形は話し手の意志を表し、「東京で生まれよう、大阪で育った」は文として成り立たない。", "生まれたい": "願望形では「東京で生まれたい、大阪で育った」と意味が通らず、出生の事実を述べる文に合わない。", "生まれます": "丁寧形は普通体の文中に入れると不自然で、文を続けられない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e33d01b3-97f1-4e39-a664-d3e16060402b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35173, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "馬は牧場を生まれて、すぐに立ち上がる。", "corrected_sentence": "馬は牧場で生まれて、すぐに立ち上がる。", "error_description": "出来事の場所を示すのは「で」。「を」は目的語を示すため誤り。正しくは「で」。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "生まれた", "is_correct": true, "explanation": "正解。「八十年前」に合う過去形。"}, {"text": "生まれて", "is_correct": false, "explanation": "て形は文末に置けず、文が終わらない。"}, {"text": "生まれる", "is_correct": false, "explanation": "辞書形は非過去で、「八十年前」の出来事と時制が合わない。"}, {"text": "生まれ", "is_correct": false, "explanation": "連用形は文を続けるだけで、文を完結させられない。"}], "correct_form": "生まれた", "base_form": "生まれる", "form_label": "過去形", "sentence_index": 7, "explanations": {"生まれた": "正解。「八十年前」に合う過去形。", "生まれて": "て形は文末に置けず、文が終わらない。", "生まれる": "辞書形は非過去で、「八十年前」の出来事と時制が合わない。", "生まれ": "連用形は文を続けるだけで、文を完結させられない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e33d01b3-97f1-4e39-a664-d3e16060402b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35176, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "正解。「気持ちを伝える」の目的語を示す「を」。"}, {"text": "に", "is_correct": false, "explanation": "「に」は相手を示す。「私の気持ちに伝えたい」では目的語にならない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は共同や引用を示す。「気持ちと伝えたい」では文の構造が成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示す。「気持ちへ伝えたい」は目的語として不自然。"}], "correct_answer": "を", "explanations": {"を": "正解。「気持ちを伝える」の目的語を示す「を」。", "に": "「に」は相手を示す。「私の気持ちに伝えたい」では目的語にならない。", "と": "「と」は共同や引用を示す。「気持ちと伝えたい」では文の構造が成り立たない。", "へ": "「へ」は方向を示す。「気持ちへ伝えたい」は目的語として不自然。"}, "error_tags": {"に": "相手", "と": "共同・引用", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e33d01b3-97f1-4e39-a664-d3e16060402b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35176, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "正解。「お礼を伝えたくて」の目的語を示す「を」。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示す。「お礼へ伝えたくて」では方向の意味にならない。"}, {"text": "の", "is_correct": false, "explanation": "「の」は名詞をつなぐ。「お礼の伝えたくて」は文として成り立たない。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較を示す。「お礼より伝えたくて」では意味が通らない。"}], "correct_answer": "を", "explanations": {"を": "正解。「お礼を伝えたくて」の目的語を示す「を」。", "へ": "「へ」は方向を示す。「お礼へ伝えたくて」では方向の意味にならない。", "の": "「の」は名詞をつなぐ。「お礼の伝えたくて」は文として成り立たない。", "より": "「より」は比較を示す。「お礼より伝えたくて」では意味が通らない。"}, "error_tags": {"へ": "方向", "の": "連体・所有", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e33d01b3-97f1-4e39-a664-d3e16060402b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35176, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "何かを人に知らせること。", "primary_collocate": null, "pronunciation": "つたえる", "ipa": "tsɯtaeɾɯ", "syllable_count": 4, "sentences": [{"text": "母に、帰りが遅くなると伝えた。", "target_word": "伝えた", "complexity_tier": "T3", "furigana": "母(はは)に、帰(かえ)りが遅(おそ)くなると伝(つた)えた。", "sentence_source": "generated"}, {"text": "先生に私の気持ちを伝えたい。", "target_word": "伝えたい", "complexity_tier": "T3", "furigana": "先生(せんせい)に私(わたし)の気持(きも)ちを伝(つた)えたい。", "sentence_source": "generated"}, {"text": "田中さんに会議の時間を伝えておいた。", "target_word": "伝えて", "complexity_tier": "T3", "furigana": "田中(たなか)さんに会議(かいぎ)の時間(じかん)を伝(つた)えておいた。", "sentence_source": "generated"}, {"text": "大事な用事だから、必ず本人に伝える。", "target_word": "伝える", "complexity_tier": "T3", "furigana": "大事(だいじ)な用事(ようじ)だから、必(かなら)ず本人(ほんにん)に伝(つた)える。", "sentence_source": "generated"}, {"text": "言葉がわからなくても、笑顔で気持ちを伝えることはできる。", "target_word": "伝える", "complexity_tier": "T3", "furigana": "言葉(ことば)がわからなくても、笑顔(えがお)で気持(きも)ちを伝(つた)えることはできる。", "sentence_source": "generated"}, {"text": "試合の結果を、すぐ家族に伝えた。", "target_word": "伝えた", "complexity_tier": "T3", "furigana": "試合(しあい)の結果(けっか)を、すぐ家族(かぞく)に伝(つた)えた。", "sentence_source": "generated"}, {"text": "駅員は電車が遅れる理由を客に伝えた。", "target_word": "伝えた", "complexity_tier": "T3", "furigana": "駅員(えきいん)は電車(でんしゃ)が遅(おく)れる理由(りゆう)を客(きゃく)に伝(つた)えた。", "sentence_source": "generated"}, {"text": "友だちにお礼を伝えたくて、手紙を書いた。", "target_word": "伝えたくて", "complexity_tier": "T3", "furigana": "友(とも)だちにお礼(れい)を伝(つた)えたくて、手紙(てがみ)を書(か)いた。", "sentence_source": "generated"}, {"text": "急な変更は、全員に伝えなければならない。", "target_word": "伝えなければ", "complexity_tier": "T3", "furigana": "急(きゅう)な変更(へんこう)は、全員(ぜんいん)に伝(つた)えなければならない。", "sentence_source": "generated"}, {"text": "医者は患者に病気のことを正しく伝えた。", "target_word": "伝えた", "complexity_tier": "T3", "furigana": "医者(いしゃ)は患者(かんじゃ)に病気(びょうき)のことを正(ただ)しく伝(つた)えた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "伝える", "label": "辞書形"}, {"form": "伝えます", "label": "丁寧形"}, {"form": "伝えない", "label": "否定形"}, {"form": "伝えた", "label": "過去形"}, {"form": "伝えて", "label": "て形"}, {"form": "伝えれば", "label": "仮定形"}, {"form": "伝えよう", "label": "意向形"}, {"form": "伝えられる", "label": "可能形"}], "register": "neutral", "sense_fingerprint": "情報や気持ちを相手に知らせること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4c3b1d77-b0ef-4bb3-862f-9f84b278ab5c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35176, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "伝えた", "is_correct": true, "explanation": "正解。過去形で、帰りが遅くなることを母に知らせた事実を述べる。"}, {"text": "伝えて", "is_correct": false, "explanation": "て形は文を終えられず、「母に伝えて。」と文が続かない。"}, {"text": "伝えれば", "is_correct": false, "explanation": "仮定形は条件節になり、文を終えられない。"}, {"text": "伝えたら", "is_correct": false, "explanation": "条件形は主節が来ないと文が完結せず、この位置では不自然。"}], "explanations": {"伝えた": "正解。過去形で、帰りが遅くなることを母に知らせた事実を述べる。", "伝えて": "て形は文を終えられず、「母に伝えて。」と文が続かない。", "伝えれば": "仮定形は条件節になり、文を終えられない。", "伝えたら": "条件形は主節が来ないと文が完結せず、この位置では不自然。"}, "sentence_index": 0, "correct_answer": "伝えた"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "大事な荷物を、必ず本人の家に伝える。", "explanation": "ここは〈届ける〉の意味。物を相手のもとへ運ぶことは伝えるではなく届けるを使う。"}, {"text": "私は古い書類を、ごみ箱に伝えた。", "explanation": "ここは〈捨てる〉の意味。不要なものを処分することは捨てるで表し、伝えるは知らせる意味なので合わない。"}, {"text": "大事な書類を、必ず本人の手に伝える。", "explanation": "ここは〈手渡す〉の意味。書類を直接渡すことは伝えるではなく手渡すを使う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e33d01b3-97f1-4e39-a664-d3e16060402b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35176, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "伝えた", "is_correct": true, "explanation": "正解。過去形で、駅員が理由を客に知らせた事実を述べる。"}, {"text": "伝えなければ", "is_correct": false, "explanation": "条件形は文を終えられず、「駅員は理由を客に伝えなければ。」で意味が完結しない。"}, {"text": "伝えず", "is_correct": false, "explanation": "連用形は文を続けるだけで、この位置では文を終えられない。"}, {"text": "伝えておいて", "is_correct": false, "explanation": "て形の「おいて」は文末で意味が通らず、文として不自然。"}], "explanations": {"伝えた": "正解。過去形で、駅員が理由を客に知らせた事実を述べる。", "伝えなければ": "条件形は文を終えられず、「駅員は理由を客に伝えなければ。」で意味が完結しない。", "伝えず": "連用形は文を続けるだけで、この位置では文を終えられない。", "伝えておいて": "て形の「おいて」は文末で意味が通らず、文として不自然。"}, "sentence_index": 6, "correct_answer": "伝えた"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "祖母は毎年、孫に手作りの服を伝えた。", "explanation": "ここは〈贈る〉の意味。物を相手に贈ることは伝えるではなく贈るを使う。"}, {"text": "私は友だちのコップに、ジュースを伝えた。", "explanation": "ここは〈注ぐ〉の意味。飲み物を器に入れることは注ぐで表し、伝えるは知らせる意味なので合わない。"}, {"text": "この家の味は、代々母から娘へ伝えてきた。", "explanation": "ここは〈受け継ぐ〉の意味。技や味を後世へ残すことで、〈知らせる〉の意味ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e33d01b3-97f1-4e39-a664-d3e16060402b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35176, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "明日、友だちに結果を伝えた。", "corrected_sentence": "明日、友だちに結果を伝える。", "error_description": "「明日」は未来を表すので、過去形の「伝えた」は誤り。正しくは非過去の「伝える」。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "伝えたい", "is_correct": true, "explanation": "正解。「伝えたい」は話し手の願望を表す形。"}, {"text": "伝えたくて", "is_correct": false, "explanation": "て形は文を終えられず、「気持ちを伝えたくて。」で文が完結しない。"}, {"text": "伝えたら", "is_correct": false, "explanation": "条件形は文を終えられず、「伝えたら。」で文が完結しない。"}, {"text": "伝えれば", "is_correct": false, "explanation": "仮定形は文を終えられず、「伝えれば。」で文が完結しない。"}], "correct_form": "伝えたい", "base_form": "伝える", "form_label": "願望形", "sentence_index": 1, "explanations": {"伝えたい": "正解。「伝えたい」は話し手の願望を表す形。", "伝えたくて": "て形は文を終えられず、「気持ちを伝えたくて。」で文が完結しない。", "伝えたら": "条件形は文を終えられず、「伝えたら。」で文が完結しない。", "伝えれば": "仮定形は文を終えられず、「伝えれば。」で文が完結しない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e33d01b3-97f1-4e39-a664-d3e16060402b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35176, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "店長は新人を新しい手順を伝えた。", "corrected_sentence": "店長は新人に新しい手順を伝えた。", "error_description": "「伝える」の相手を示すのは「に」。「を」は目的語を示すため誤り。正しくは「に」。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "伝えたくて", "is_correct": true, "explanation": "正解。願望のて形で、後の「手紙を書いた」へつながる。"}, {"text": "伝えよう", "is_correct": false, "explanation": "意向形は続けると「伝えよう、手紙を書いた」と不自然で、文脈に合わない。"}, {"text": "伝えたい", "is_correct": false, "explanation": "願望形の終止形は文を続けられず、「伝えたい、手紙を書いた」は不自然。"}, {"text": "伝えます", "is_correct": false, "explanation": "丁寧形は文中で続けられず、「伝えます、手紙を」は不自然。"}], "correct_form": "伝えたくて", "base_form": "伝える", "form_label": "願望形（て形）", "sentence_index": 7, "explanations": {"伝えたくて": "正解。願望のて形で、後の「手紙を書いた」へつながる。", "伝えよう": "意向形は続けると「伝えよう、手紙を書いた」と不自然で、文脈に合わない。", "伝えたい": "願望形の終止形は文を続けられず、「伝えたい、手紙を書いた」は不自然。", "伝えます": "丁寧形は文中で続けられず、「伝えます、手紙を」は不自然。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e33d01b3-97f1-4e39-a664-d3e16060402b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35178, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「風の力を使う」の形で、「使う」の目的語を示す「を」。"}, {"text": "が", "is_correct": false, "explanation": "「力が」は主語を示すので、「使う」の目的語には合わない。"}, {"text": "と", "is_correct": false, "explanation": "「力と使って」は並列や共同を表すが、「使う」の目的語にならない。"}, {"text": "の", "is_correct": false, "explanation": "「力の使って」は名詞修飾が続かないので、文が成り立たない。"}], "correct_answer": "を", "explanations": {"を": "「風の力を使う」の形で、「使う」の目的語を示す「を」。", "が": "「力が」は主語を示すので、「使う」の目的語には合わない。", "と": "「力と使って」は並列や共同を表すが、「使う」の目的語にならない。", "の": "「力の使って」は名詞修飾が続かないので、文が成り立たない。"}, "error_tags": {"が": "主格（主語）", "と": "並列・共同", "の": "連体（名詞修飾）"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ed848d40-3489-4681-91c1-79fe346d2be0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35178, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「足りなくて」の主語を示す「が」。「力が足りない」の形になる。"}, {"text": "へ", "is_correct": false, "explanation": "「力へ足りなくて」は方向を示さないので、文が成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "「力で足りなくて」は手段や場所にならず、「足りない」の主語にもならない。"}, {"text": "より", "is_correct": false, "explanation": "「力より足りなくて」は比較の形で、「足りない」の主語として成り立たない。"}], "correct_answer": "が", "explanations": {"が": "「足りなくて」の主語を示す「が」。「力が足りない」の形になる。", "へ": "「力へ足りなくて」は方向を示さないので、文が成り立たない。", "で": "「力で足りなくて」は手段や場所にならず、「足りない」の主語にもならない。", "より": "「力より足りなくて」は比較の形で、「足りない」の主語として成り立たない。"}, "error_tags": {"へ": "方向", "で": "手段・場所", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ed848d40-3489-4681-91c1-79fe346d2be0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35178, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "物を動かしたり、変えたりする物理的な力やエネルギー。", "primary_collocate": null, "pronunciation": "ちから", "ipa": "tɕikaɾa", "syllable_count": 3, "sentences": [{"text": "水の力で水車を回し、粉をひいている。", "target_word": "力", "complexity_tier": "T3", "furigana": "水(みず)の力(ちから)で水車(すいしゃ)を回(まわ)し、粉(こな)をひいている。", "sentence_source": "generated"}, {"text": "風の力を使って電気を作る方法が広まっている。", "target_word": "力", "complexity_tier": "T3", "furigana": "風(かぜ)の力(ちから)を使(つか)って電気(でんき)を作(つく)る方法(ほうほう)が広(ひろ)まっている。", "sentence_source": "generated"}, {"text": "重い箱を運ぶには、大きな力がいる。", "target_word": "力", "complexity_tier": "T3", "furigana": "重(おも)い箱(はこ)を運(はこ)ぶには、大(おお)きな力(ちから)がいる。", "sentence_source": "generated"}, {"text": "力を入れて引いたが、扉はびくともしなかった。", "target_word": "力", "complexity_tier": "T3", "furigana": "力(ちから)を入(い)れて引(ひ)いたが、扉(とびら)はびくともしなかった。", "sentence_source": "generated"}, {"text": "子どもたちは力を合わせて、大きな石を動かした。", "target_word": "力", "complexity_tier": "T3", "furigana": "子(こ)どもたちは力(ちから)を合(あ)わせて、大(おお)きな石(いし)を動(うご)かした。", "sentence_source": "generated"}, {"text": "蒸気の力でタービンを回し、発電する。", "target_word": "力", "complexity_tier": "T3", "furigana": "蒸気(じょうき)の力(ちから)でタービンを回(まわ)し、発電(はつでん)する。", "sentence_source": "generated"}, {"text": "彼は足の力が強く、長い坂でも楽に走れる。", "target_word": "力", "complexity_tier": "T3", "furigana": "彼(かれ)は足(あし)の力(ちから)が強(つよ)く、長(なが)い坂(さか)でも楽(らく)に走(はし)れる。", "sentence_source": "generated"}, {"text": "ロープを引く力が足りなくて、車は動かなかった。", "target_word": "力", "complexity_tier": "T3", "furigana": "ロープを引(ひ)く力(ちから)が足(た)りなくて、車(くるま)は動(うご)かなかった。", "sentence_source": "generated"}, {"text": "磁石は鉄を引きつける力を持っている。", "target_word": "力", "complexity_tier": "T3", "furigana": "磁石(じしゃく)は鉄(てつ)を引(ひ)きつける力(ちから)を持(も)っている。", "sentence_source": "generated"}, {"text": "エンジンの力が足りず、車は坂をのぼれなかった。", "target_word": "力", "complexity_tier": "T3", "furigana": "エンジンの力(ちから)が足(た)りず、車(くるま)は坂(さか)をのぼれなかった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "力", "label": "基本形"}, {"form": "力が", "label": "が格"}, {"form": "力を", "label": "を格"}], "register": "標準（普通体）", "sense_fingerprint": "力（名詞）：物を動かす・変える元になる物理的な力やエネルギー", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 9 above tier T1: contains vocabulary far above tier T1: のぼれ (Zipf 2.08)']::text[], '947d9c0d-20b2-4311-9f05-a20f8a6414f0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35178, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "力", "is_correct": true, "explanation": "物を動かす元になる物理的な力を表す。「水の力で水車を回す」の形で、この空欄に入る。"}, {"text": "色", "is_correct": false, "explanation": "「水の色で水車を回す」は動力の意味にならず、文が成り立たない。"}, {"text": "味", "is_correct": false, "explanation": "「水の味で」は動力を表せないので、水車を回す文には合わない。"}, {"text": "形", "is_correct": false, "explanation": "「水の形で水車を回す」は動力の意味にならないので合わない。"}], "explanations": {"力": "物を動かす元になる物理的な力を表す。「水の力で水車を回す」の形で、この空欄に入る。", "色": "「水の色で水車を回す」は動力の意味にならず、文が成り立たない。", "味": "「水の味で」は動力を表せないので、水車を回す文には合わない。", "形": "「水の形で水車を回す」は動力の意味にならないので合わない。"}, "sentence_index": 0, "correct_answer": "力"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "このスープは力が深く、味に奥行きがある。", "explanation": "ここは〈味の深み〉の意味。〈力〉は味の深さを表さないので、「深く」とは合わない。"}, {"text": "この部屋は力が暗く、本が読めない。", "explanation": "ここは〈明るさ〉の意味。〈力〉は光の明るさを表さないので、部屋の暗さには合わない。"}, {"text": "この箱は力が十キロある。", "explanation": "ここは〈重さ〉の意味を〈力〉に置き換えた形。物理的な力は重さ（質量）とは違うので、キログラムで表す箱の重さには合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ed848d40-3489-4681-91c1-79fe346d2be0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35178, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "力", "is_correct": true, "explanation": "物理的な力を表す。「足の力が強く」の形で、この空欄に入る。"}, {"text": "声", "is_correct": false, "explanation": "「足の声が強く」は意味が通らず、足の強さを表せない。"}, {"text": "姿", "is_correct": false, "explanation": "「足の姿が強く」は足の強さを表さないので合わない。"}, {"text": "記憶", "is_correct": false, "explanation": "「足の記憶が強く」は足の強さを表さず、文が成り立たない。"}], "explanations": {"力": "物理的な力を表す。「足の力が強く」の形で、この空欄に入る。", "声": "「足の声が強く」は意味が通らず、足の強さを表せない。", "姿": "「足の姿が強く」は足の強さを表さないので合わない。", "記憶": "「足の記憶が強く」は足の強さを表さず、文が成り立たない。"}, "sentence_index": 6, "correct_answer": "力"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この楽器は力が高く、ピアノの音が遠くまで響く。", "explanation": "ここは〈音の高さ〉の意味。〈力〉は音程を表さないので、「高く」とは合わない。"}, {"text": "彼は歴史の力が豊富で、クイズに強い。", "explanation": "ここは〈知識〉の意味を入れ替えた形。物理的な力は知識の量とは結びつかないので、「豊富」とは合わない。"}, {"text": "母の力が深く、子どもを支えた。", "explanation": "ここは〈愛情〉の意味を入れ替えた形。〈力〉は「深い」と形容できないので、感情の深さは表せない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ed848d40-3489-4681-91c1-79fe346d2be0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35178, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "小さな子どもでも、力が合わせれば重い箱を動かせる。", "corrected_sentence": "小さな子どもでも、力を合わせれば重い箱を動かせる。", "error_description": "「合わせる」の目的語は「力を」。「が」は主語を示すので、他動詞「合わせる」の目的語には合わない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ed848d40-3489-4681-91c1-79fe346d2be0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35178, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼は腕の力に強く、重い箱も軽く持ち上げられる。", "corrected_sentence": "彼は腕の力が強く、重い箱も軽く持ち上げられる。", "error_description": "「強い」の主語には「が」が入る。「に」は場所や対象を示すので、「力」の形容には合わない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ed848d40-3489-4681-91c1-79fe346d2be0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
