INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35179, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「力があるので」の主語を示す「が」。「力がある」の形になる。"}, {"text": "と", "is_correct": false, "explanation": "「力とあるので」は並列を表すが、「ある」の主語にはならない。"}, {"text": "より", "is_correct": false, "explanation": "「力よりあるので」は比較の形で、存在の文として意味が通らない。"}, {"text": "から", "is_correct": false, "explanation": "「力からあるので」は起点を示すが、「ある」の主語にはならず、文が成り立たない。"}], "correct_answer": "が", "explanations": {"が": "「力があるので」の主語を示す「が」。「力がある」の形になる。", "と": "「力とあるので」は並列を表すが、「ある」の主語にはならない。", "より": "「力よりあるので」は比較の形で、存在の文として意味が通らない。", "から": "「力からあるので」は起点を示すが、「ある」の主語にはならず、文が成り立たない。"}, "error_tags": {"と": "並列・共同", "より": "比較", "から": "起点"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ed848d40-3489-4681-91c1-79fe346d2be0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35179, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "物事を動かしたり、変化させたりする能力や影響力。", "primary_collocate": null, "pronunciation": "ちから", "ipa": "tɕikaɾa", "syllable_count": 3, "sentences": [{"text": "言葉には、人の気持ちを変える力がある。", "target_word": "力", "complexity_tier": "T3", "furigana": "言葉(ことば)には、人(ひと)の気持(きも)ちを変(か)える力(ちから)がある。", "sentence_source": "generated"}, {"text": "彼女の力で、会社は大きく変わった。", "target_word": "力", "complexity_tier": "T3", "furigana": "彼女(かのじょ)の力(ちから)で、会社(かいしゃ)は大(おお)きく変(か)わった。", "sentence_source": "generated"}, {"text": "音楽の力で、町に元気が戻った。", "target_word": "力", "complexity_tier": "T3", "furigana": "音楽(おんがく)の力(ちから)で、町(まち)に元気(げんき)が戻(もど)った。", "sentence_source": "generated"}, {"text": "この国は世界を動かす力を持っている。", "target_word": "力", "complexity_tier": "T3", "furigana": "この国(くに)は世界(せかい)を動(うご)かす力(ちから)を持(も)っている。", "sentence_source": "generated"}, {"text": "彼は先生に力を認められて、代表に選ばれた。", "target_word": "力", "complexity_tier": "T3", "furigana": "彼(かれ)は先生(せんせい)に力(ちから)を認(みと)められて、代表(だいひょう)に選(えら)ばれた。", "sentence_source": "generated"}, {"text": "新聞の力は大きく、一つの記事が世論を動かすこともある。", "target_word": "力", "complexity_tier": "T3", "furigana": "新聞(しんぶん)の力(ちから)は大(おお)きく、一(ひと)つの記事(きじ)が世論(よろん)を動(うご)かすこともある。", "sentence_source": "generated"}, {"text": "試験で自分の力を十分に出すことができた。", "target_word": "力", "complexity_tier": "T3", "furigana": "試験(しけん)で自分(じぶん)の力(ちから)を十分(じゅうぶん)に出(だ)すことができた。", "sentence_source": "generated"}, {"text": "彼は人を引きつける力があるので、みんながついていく。", "target_word": "力", "complexity_tier": "T3", "furigana": "彼(かれ)は人(ひと)を引(ひ)きつける力(ちから)があるので、みんながついていく。", "sentence_source": "generated"}, {"text": "市長には力があるので、計画を進めることができた。", "target_word": "力", "complexity_tier": "T3", "furigana": "市長(しちょう)には力(ちから)があるので、計画(けいかく)を進(すす)めることができた。", "sentence_source": "generated"}, {"text": "小さな会社だが、新しい技術の力で成長している。", "target_word": "力", "complexity_tier": "T3", "furigana": "小(ちい)さな会社(かいしゃ)だが、新(あたら)しい技術(ぎじゅつ)の力(ちから)で成長(せいちょう)している。", "sentence_source": "generated"}], "morphological_forms": [{"form": "力", "label": "基本形"}, {"form": "力が", "label": "が格"}, {"form": "力を", "label": "を格"}], "register": "標準（普通体）", "sense_fingerprint": "力（名詞）：物事や人を動かし変える能力・影響力", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '947d9c0d-20b2-4311-9f05-a20f8a6414f0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35179, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "力", "is_correct": true, "explanation": "物事や人を動かし変える能力・影響力を表す。「人の気持ちを変える力がある」の形で、この空欄に入る。"}, {"text": "色", "is_correct": false, "explanation": "「人の気持ちを変える色」は意味が通らず、影響の意味にならない。"}, {"text": "形", "is_correct": false, "explanation": "「人の気持ちを変える形」は意味が通らないので合わない。"}, {"text": "匂い", "is_correct": false, "explanation": "「匂い」は香りを表すので、人の気持ちを変える影響の意味にはならず、文として不自然。"}], "explanations": {"力": "物事や人を動かし変える能力・影響力を表す。「人の気持ちを変える力がある」の形で、この空欄に入る。", "色": "「人の気持ちを変える色」は意味が通らず、影響の意味にならない。", "形": "「人の気持ちを変える形」は意味が通らないので合わない。", "匂い": "「匂い」は香りを表すので、人の気持ちを変える影響の意味にはならず、文として不自然。"}, "sentence_index": 0, "correct_answer": "力"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この店の商品は力が高く、誰も買えない。", "explanation": "ここは〈価格〉の意味。〈力〉は値段の高さを表さないので、「高く」とは合わない。"}, {"text": "楽しい力が心に残る。", "explanation": "ここは〈思い出〉の意味を入れ替えた形。〈力〉は「楽しい」という感情の内容を持たないので、思い出の感じ方は表せない。"}, {"text": "力が豊富で、難しい言葉もすぐわかる。", "explanation": "ここは〈語彙〉の意味を入れ替えた形。〈力〉は言葉の数を指さないので、「豊富」とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ed848d40-3489-4681-91c1-79fe346d2be0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35179, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "力", "is_correct": true, "explanation": "能力を表す。「自分の力を十分に出す」の形で、この空欄に入る。"}, {"text": "影", "is_correct": false, "explanation": "「自分の影を十分に出す」は能力の発揮の意味にならないので合わない。"}, {"text": "煙", "is_correct": false, "explanation": "「自分の煙を出す」は比喩でも能力を表さず、文が成り立たない。"}, {"text": "跡", "is_correct": false, "explanation": "「自分の跡を出す」は能力の発揮の意味にならないので合わない。"}], "explanations": {"力": "能力を表す。「自分の力を十分に出す」の形で、この空欄に入る。", "影": "「自分の影を十分に出す」は能力の発揮の意味にならないので合わない。", "煙": "「自分の煙を出す」は比喩でも能力を表さず、文が成り立たない。", "跡": "「自分の跡を出す」は能力の発揮の意味にならないので合わない。"}, "sentence_index": 6, "correct_answer": "力"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この鍋は力が熱く、すぐに焦げる。", "explanation": "ここは〈温度〉の意味。〈力〉は熱さを表さないので、鍋の温度には合わない。"}, {"text": "力が鮮やかで、絵が目立つ。", "explanation": "ここは〈色彩〉の意味を入れ替えた形。〈力〉は色の鮮やかさを表さないので、この文は成り立たない。"}, {"text": "この料理は力が濃い。", "explanation": "ここは〈味〉の意味を入れ替えた形。〈力〉は味の濃さを表さないので、「濃い」とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ed848d40-3489-4681-91c1-79fe346d2be0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35179, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この映画は人の心を動かす力が持っている。", "corrected_sentence": "この映画は人の心を動かす力を持っている。", "error_description": "「持つ」の目的語は「力を」。「が」は主語を示すので、「持っている」の目的語には合わない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ed848d40-3489-4681-91c1-79fe346d2be0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35179, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼は仲間を引っ張る力を、チームを勝たせた。", "corrected_sentence": "彼は仲間を引っ張る力で、チームを勝たせた。", "error_description": "「力で」は手段を示す形。「力を」は目的語になるが、チームを勝たせた原因には「で」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ed848d40-3489-4681-91c1-79fe346d2be0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35180, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "格助詞。「持つ」の目的語「友だちを三人」を示す。"}, {"text": "に", "is_correct": false, "explanation": "「に」は相手や帰着点を表し、「友だちに三人持つ」とは言えないので合わない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は場所や手段を表し、「友だちで三人持つ」は不自然で合わない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を表し、「友だちへ持つ」とは言わない。"}], "correct_answer": "を", "explanations": {"を": "格助詞。「持つ」の目的語「友だちを三人」を示す。", "に": "「に」は相手や帰着点を表し、「友だちに三人持つ」とは言えないので合わない。", "で": "「で」は場所や手段を表し、「友だちで三人持つ」は不自然で合わない。", "へ": "「へ」は方向を表し、「友だちへ持つ」とは言わない。"}, "error_tags": {"に": "相手・帰着点", "で": "場所・手段", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e33d01b3-97f1-4e39-a664-d3e16060402b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35180, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "格助詞。「持つ」の目的語「自分の店を」を示す。"}, {"text": "と", "is_correct": false, "explanation": "「と」は相手や並列を表し、「店と持った兄」では意味が通らない。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較を表し、「店より持った」とは続かず合わない。"}, {"text": "から", "is_correct": false, "explanation": "「から」は起点を表し、「店から持った兄」とは言えないので合わない。"}], "correct_answer": "を", "explanations": {"を": "格助詞。「持つ」の目的語「自分の店を」を示す。", "と": "「と」は相手や並列を表し、「店と持った兄」では意味が通らない。", "より": "「より」は比較を表し、「店より持った」とは続かず合わない。", "から": "「から」は起点を表し、「店から持った兄」とは言えないので合わない。"}, "error_tags": {"と": "相手・並列", "より": "比較", "から": "起点"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e33d01b3-97f1-4e39-a664-d3e16060402b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35180, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "何かを手に入れていること。", "primary_collocate": null, "pronunciation": "もつ", "ipa": "mot͡sɯ", "syllable_count": 2, "sentences": [{"text": "兄は新しい自転車を持っている。", "target_word": "持って", "complexity_tier": "T3", "furigana": "兄(あに)は新(あたら)しい自転車(じてんしゃ)を持(も)っている。", "sentence_source": "generated"}, {"text": "私は日本の友だちを三人持っている。", "target_word": "持って", "complexity_tier": "T3", "furigana": "私(わたし)は日本(にほん)の友(とも)だちを三人(さんにん)持(も)っている。", "sentence_source": "generated"}, {"text": "この店のカードを持っていれば、安くなる。", "target_word": "持って", "complexity_tier": "T3", "furigana": "この店(みせ)のカードを持(も)っていれば、安(やす)くなる。", "sentence_source": "generated"}, {"text": "彼女は車の免許を持っていないので、電車で行く。", "target_word": "持って", "complexity_tier": "T3", "furigana": "彼女(かのじょ)は車(くるま)の免許(めんきょ)を持(も)っていないので、電車(でんしゃ)で行(い)く。", "sentence_source": "generated"}, {"text": "田中さんは大きな家を持つのが夢だ。", "target_word": "持つ", "complexity_tier": "T3", "furigana": "田中(たなか)さんは大(おお)きな家(いえ)を持(も)つのが夢(ゆめ)だ。", "sentence_source": "generated"}, {"text": "祖母は古い時計を持っていて、大切にしている。", "target_word": "持って", "complexity_tier": "T3", "furigana": "祖母(そぼ)は古(ふる)い時計(とけい)を持(も)っていて、大切(たいせつ)にしている。", "sentence_source": "generated"}, {"text": "パスポートを持たずに空港へ行って、困った。", "target_word": "持たず", "complexity_tier": "T3", "furigana": "パスポートを持(も)たずに空港(くうこう)へ行(い)って、困(こま)った。", "sentence_source": "generated"}, {"text": "自分の店を持った兄は、毎日忙しそうだ。", "target_word": "持った", "complexity_tier": "T3", "furigana": "自分(じぶん)の店(みせ)を持(も)った兄(あに)は、毎日(まいにち)忙(いそが)しそうだ。", "sentence_source": "generated"}, {"text": "弟は漫画を千冊も持っている。", "target_word": "持って", "complexity_tier": "T3", "furigana": "弟(おとうと)は漫画(まんが)を千冊(せんさつ)も持(も)っている。", "sentence_source": "generated"}, {"text": "彼は夢を持って、日本へ留学しに来た。", "target_word": "持って", "complexity_tier": "T3", "furigana": "彼(かれ)は夢(ゆめ)を持(も)って、日本(にほん)へ留学(りゅうがく)しに来(き)た。", "sentence_source": "generated"}], "morphological_forms": [{"form": "持つ", "label": "辞書形"}, {"form": "持ちます", "label": "丁寧形"}, {"form": "持たない", "label": "否定形"}, {"form": "持った", "label": "過去形"}, {"form": "持って", "label": "て形"}, {"form": "持てば", "label": "仮定形"}, {"form": "持とう", "label": "意向形"}, {"form": "持てる", "label": "可能形"}], "register": "neutral", "sense_fingerprint": "物や人や夢などを自分のものとして持っていること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4c3b1d77-b0ef-4bb3-862f-9f84b278ab5c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35180, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "持って", "is_correct": true, "explanation": "て形。「〜ている」につながる形で、「兄は新しい自転車を持っている」の空欄にそのまま入る。"}, {"text": "持とう", "is_correct": false, "explanation": "意向形。「持とういる」とは続かず、「持つつもりだ」の意味になるので空欄に合わない。"}, {"text": "持たず", "is_correct": false, "explanation": "否定の連用形。「持たず」は「持たないで」の意味で、「〜いる」の前には置けない。"}, {"text": "持てば", "is_correct": false, "explanation": "仮定形。「持てば」は「持つなら」の意味で、「いる」とは続かないので空欄に合わない。"}], "explanations": {"持って": "て形。「〜ている」につながる形で、「兄は新しい自転車を持っている」の空欄にそのまま入る。", "持とう": "意向形。「持とういる」とは続かず、「持つつもりだ」の意味になるので空欄に合わない。", "持たず": "否定の連用形。「持たず」は「持たないで」の意味で、「〜いる」の前には置けない。", "持てば": "仮定形。「持てば」は「持つなら」の意味で、「いる」とは続かないので空欄に合わない。"}, "sentence_index": 0, "correct_answer": "持って"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "会社は今年、売上を持つことができた。", "explanation": "ここは〈維持〉の意味。〈持つ〉は売上の数字を一定に保つ意味では使わないので、〈売上を維持する〉と言う。"}, {"text": "室温を一定に持つために、エアコンをつける。", "explanation": "ここは〈保つ〉の意味。〈持つ〉は状態を一定に保つ意味を持たないので、〈室温を一定に〉とは合わない。"}, {"text": "明日の会議のために、席を持っておいた。", "explanation": "ここは〈取る〉の意味。〈持つ〉は席を確保する意味ではないので、〈席を持つ〉では予約の意味にならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e33d01b3-97f1-4e39-a664-d3e16060402b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35180, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "持たず", "is_correct": true, "explanation": "否定の連用形。「持たずに」の意味で、「パスポートを持たずに空港へ行って」の空欄に入る。"}, {"text": "持て", "is_correct": false, "explanation": "命令形。「持て」は強い指示になり、この文の流れには続かない。"}, {"text": "持ちたい", "is_correct": false, "explanation": "願望の形。「持ちたい空港」は文として続かず、「パスポートを持って」の意味にもならない。"}, {"text": "持とう", "is_correct": false, "explanation": "意向形。「持とう」は「空港へ」と続かず、文の流れに合わないので空欄に入らない。"}], "explanations": {"持たず": "否定の連用形。「持たずに」の意味で、「パスポートを持たずに空港へ行って」の空欄に入る。", "持て": "命令形。「持て」は強い指示になり、この文の流れには続かない。", "持ちたい": "願望の形。「持ちたい空港」は文として続かず、「パスポートを持って」の意味にもならない。", "持とう": "意向形。「持とう」は「空港へ」と続かず、文の流れに合わないので空欄に入らない。"}, "sentence_index": 6, "correct_answer": "持たず"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "先生は、宿題を忘れた生徒に罰を持った。", "explanation": "ここは〈与える〉の意味。〈持つ〉は罰を相手に加える意味では使わないので、〈罰を与える〉と言う。"}, {"text": "隣の人と、朝に挨拶を持った。", "explanation": "ここは〈交わす〉の意味。〈持つ〉は挨拶を相手と行う意味では使わないので、〈挨拶を交わす〉と言う。"}, {"text": "彼は、ため息を持って、窓の外を見た。", "explanation": "ここは〈つく〉の意味。〈持つ〉はため息を出す動作には使わないので、〈ため息をつく〉と言う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e33d01b3-97f1-4e39-a664-d3e16060402b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35180, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "祖父は古い万年筆に持っている。", "corrected_sentence": "祖父は古い万年筆を持っている。", "error_description": "「持つ」は目的語に「を」をとる。ここは「に」が誤りで、正しくは「古い万年筆を」。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "持って", "is_correct": true, "explanation": "て形。「〜ている」の前に来る形で、この文の「持っている」の「持って」にあたる。"}, {"text": "持った", "is_correct": false, "explanation": "過去形。「持った」は過去や完了の形で、現在の状態を表す「持っている」の前には使わない。"}, {"text": "持たず", "is_correct": false, "explanation": "否定の連用形。「持たず」は「持たないで」の意味で、「三人持っている」の形にはならない。"}, {"text": "持ちます", "is_correct": false, "explanation": "丁寧形。「持ちます」は丁寧な言い方で、「持っている」の普通の形ではない。"}], "correct_form": "持って", "base_form": "持つ", "form_label": "て形", "sentence_index": 1, "explanations": {"持って": "て形。「〜ている」の前に来る形で、この文の「持っている」の「持って」にあたる。", "持った": "過去形。「持った」は過去や完了の形で、現在の状態を表す「持っている」の前には使わない。", "持たず": "否定の連用形。「持たず」は「持たないで」の意味で、「三人持っている」の形にはならない。", "持ちます": "丁寧形。「持ちます」は丁寧な言い方で、「持っている」の普通の形ではない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e33d01b3-97f1-4e39-a664-d3e16060402b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35180, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "姉は大きな夢を持うて、海外へ行った。", "corrected_sentence": "姉は大きな夢を持って、海外へ行った。", "error_description": "「持つ」のて形は「持って」。「持うて」は誤った活用形で、正しくは「持って」。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "持った", "is_correct": true, "explanation": "過去形。「持った」は過去や完了を表し、「自分の店を持った兄」の形として正しい。"}, {"text": "持って", "is_correct": false, "explanation": "て形。「持って」は連続や理由の形で、名詞を修飾する「持った兄」の形にはならない。"}, {"text": "持たず", "is_correct": false, "explanation": "否定の連用形。「持たず」は否定の意味になり、店を持っている事実とは合わない。"}, {"text": "持とう", "is_correct": false, "explanation": "意向形。「持とう」は「持つつもりだ」の意味で、過去の事実を表す「持った」とは違う。"}], "correct_form": "持った", "base_form": "持つ", "form_label": "過去形", "sentence_index": 7, "explanations": {"持った": "過去形。「持った」は過去や完了を表し、「自分の店を持った兄」の形として正しい。", "持って": "て形。「持って」は連続や理由の形で、名詞を修飾する「持った兄」の形にはならない。", "持たず": "否定の連用形。「持たず」は否定の意味になり、店を持っている事実とは合わない。", "持とう": "意向形。「持とう」は「持つつもりだ」の意味で、過去の事実を表す「持った」とは違う。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e33d01b3-97f1-4e39-a664-d3e16060402b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35182, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "連体修飾の格助詞。「試験の結果」の「の」で、試験が結果を修飾している。"}, {"text": "を", "is_correct": false, "explanation": "目的語を表す格助詞。「試験を結果は」では文が成り立たないので合わない。"}, {"text": "に", "is_correct": false, "explanation": "時点や場所を表す格助詞。「試験に結果は」は意味が通らないので合わない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表す格助詞。「試験へ結果は」は不自然で、この位置には入らない。"}], "correct_answer": "の", "explanations": {"の": "連体修飾の格助詞。「試験の結果」の「の」で、試験が結果を修飾している。", "を": "目的語を表す格助詞。「試験を結果は」では文が成り立たないので合わない。", "に": "時点や場所を表す格助詞。「試験に結果は」は意味が通らないので合わない。", "へ": "方向を表す格助詞。「試験へ結果は」は不自然で、この位置には入らない。"}, "error_tags": {"を": "目的語", "に": "時点・場所", "へ": "方向"}, "sentence_index": 0}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e33d01b3-97f1-4e39-a664-d3e16060402b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35182, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "連体修飾の格助詞。「実験の結果」の「の」で、実験が結果を修飾している。"}, {"text": "を", "is_correct": false, "explanation": "目的語を表す「を」。「実験を結果は」は対象が立たず、文として成り立たない。"}, {"text": "から", "is_correct": false, "explanation": "起点を表す格助詞。「実験から結果は」は意味が通らず、この位置には入らない。"}, {"text": "より", "is_correct": false, "explanation": "比較を表す格助詞。「実験より結果は」は比べる意味にならず、文が合わない。"}], "correct_answer": "の", "explanations": {"の": "連体修飾の格助詞。「実験の結果」の「の」で、実験が結果を修飾している。", "を": "目的語を表す「を」。「実験を結果は」は対象が立たず、文として成り立たない。", "から": "起点を表す格助詞。「実験から結果は」は意味が通らず、この位置には入らない。", "より": "比較を表す格助詞。「実験より結果は」は比べる意味にならず、文が合わない。"}, "error_tags": {"を": "目的語", "から": "起点", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e33d01b3-97f1-4e39-a664-d3e16060402b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35182, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "何かをした後に、その結果として出てくる成り行きや成果。", "primary_collocate": null, "pronunciation": "けっか", "ipa": "kekːa", "syllable_count": 3, "sentences": [{"text": "試験の結果は、来週の月曜日に出る。", "target_word": "結果", "complexity_tier": "T3", "furigana": "試験(しけん)の結果(けっか)は、来週(らいしゅう)の月曜日(げつようび)に出(で)る。", "sentence_source": "generated"}, {"text": "毎日練習した結果、泳げるようになった。", "target_word": "結果", "complexity_tier": "T3", "furigana": "毎日(まいにち)練習(れんしゅう)した結果(けっか)、泳(およ)げるようになった。", "sentence_source": "generated"}, {"text": "努力したのに、結果はよくなかった。", "target_word": "結果", "complexity_tier": "T3", "furigana": "努力(どりょく)したのに、結果(けっか)はよくなかった。", "sentence_source": "generated"}, {"text": "検査の結果を、医者が説明してくれた。", "target_word": "結果", "complexity_tier": "T3", "furigana": "検査(けんさ)の結果(けっか)を、医者(いしゃ)が説明(せつめい)してくれた。", "sentence_source": "generated"}, {"text": "結果が出るまで、静かに待つしかない。", "target_word": "結果", "complexity_tier": "T3", "furigana": "結果(けっか)が出(で)るまで、静(しず)かに待(ま)つしかない。", "sentence_source": "generated"}, {"text": "夜ふかしを続けた結果、風邪をひいてしまった。", "target_word": "結果", "complexity_tier": "T3", "furigana": "夜(よる)ふかしを続(つづ)けた結果(けっか)、風邪(かぜ)をひいてしまった。", "sentence_source": "generated"}, {"text": "試合の結果を聞いて、みんな喜んだ。", "target_word": "結果", "complexity_tier": "T3", "furigana": "試合(しあい)の結果(けっか)を聞(き)いて、みんな喜(よろこ)んだ。", "sentence_source": "generated"}, {"text": "実験の結果は、予想とはまったく違っていた。", "target_word": "結果", "complexity_tier": "T3", "furigana": "実験(じっけん)の結果(けっか)は、予想(よそう)とはまったく違(ちが)っていた。", "sentence_source": "generated"}, {"text": "結果より、どう頑張ったかが大切だと先生は言う。", "target_word": "結果", "complexity_tier": "T3", "furigana": "結果(けっか)より、どう頑張(がんば)ったかが大切(たいせつ)だと先生(せんせい)は言(い)う。", "sentence_source": "generated"}, {"text": "調査の結果、この町の人口は増えていることがわかった。", "target_word": "結果", "complexity_tier": "T3", "furigana": "調査(ちょうさ)の結果(けっか)、この町(まち)の人口(じんこう)は増(ふ)えていることがわかった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "結果", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "ある行動や原因のあとに出る成り行きや成果", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4c3b1d77-b0ef-4bb3-862f-9f84b278ab5c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35182, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "結果", "is_correct": true, "explanation": "名詞。「試験の結果」は試験の合否や成績の知らせを指し、「来週の月曜日に出る」と合う。"}, {"text": "会場", "is_correct": false, "explanation": "場所を表す名詞。「試験の会場は来週の月曜日に出る」は、会場が出るという意味になり合わない。"}, {"text": "試験官", "is_correct": false, "explanation": "人を表す名詞。「試験官が来週の月曜日に出る」は文の内容として合わない。"}, {"text": "時刻", "is_correct": false, "explanation": "時間を表す名詞。「試験の時刻は来週の月曜日に出る」は、時刻が出るという意味で不自然。"}], "explanations": {"結果": "名詞。「試験の結果」は試験の合否や成績の知らせを指し、「来週の月曜日に出る」と合う。", "会場": "場所を表す名詞。「試験の会場は来週の月曜日に出る」は、会場が出るという意味になり合わない。", "試験官": "人を表す名詞。「試験官が来週の月曜日に出る」は文の内容として合わない。", "時刻": "時間を表す名詞。「試験の時刻は来週の月曜日に出る」は、時刻が出るという意味で不自然。"}, "sentence_index": 0, "correct_answer": "結果"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この薬は、咳に対して大きな結果を発揮する。", "explanation": "ここは〈効果〉の意味。〈結果〉は行動のあとの成り行きを指すので、薬の働きを〈発揮する〉とは言わない。"}, {"text": "先生は、答案に低い結果をつけた。", "explanation": "ここは〈評価〉の意味。〈結果〉は人がつけるものではなく、〈評価をつける〉と言うのが正しい。"}, {"text": "営業チームは、今月の結果を達成した。", "explanation": "ここは〈目標〉の意味。〈結果〉は達成するものではないので、〈達成する〉と合うのは〈目標〉である。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e33d01b3-97f1-4e39-a664-d3e16060402b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35182, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "結果", "is_correct": true, "explanation": "名詞。「試合の結果」は試合の勝敗や得点の知らせを指し、「聞いて喜んだ」と合う。"}, {"text": "観客", "is_correct": false, "explanation": "人を表す名詞。「試合の観客を聞いて」は人を聞くという意味になり不自然で合わない。"}, {"text": "審判", "is_correct": false, "explanation": "人を表す名詞。「試合の審判を聞いて」は審判を聞くという意味になり文が合わない。"}, {"text": "見出し", "is_correct": false, "explanation": "記事の題を表す名詞。「試合の見出しを聞いて」は見出しを聞くという意味で不自然。"}], "explanations": {"結果": "名詞。「試合の結果」は試合の勝敗や得点の知らせを指し、「聞いて喜んだ」と合う。", "観客": "人を表す名詞。「試合の観客を聞いて」は人を聞くという意味になり不自然で合わない。", "審判": "人を表す名詞。「試合の審判を聞いて」は審判を聞くという意味になり文が合わない。", "見出し": "記事の題を表す名詞。「試合の見出しを聞いて」は見出しを聞くという意味で不自然。"}, "sentence_index": 6, "correct_answer": "結果"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "あの店の結果が広がって、お客さんが増えた。", "explanation": "ここは〈評判〉の意味。〈結果〉は行動のあとの成り行きを指すので、店の噂や評判が広がるとは言わない。"}, {"text": "審判は、選手の反則に結果を下した。", "explanation": "ここは〈判定〉の意味。〈下す〉は判定や判断に使うので、〈結果〉は下すものではなく、〈判定を下す〉と言う。"}, {"text": "一度の失敗で、会社は結果を失った。", "explanation": "ここは〈信用〉の意味。〈結果〉は失うものではないので、〈信用を失う〉と言うのが正しい。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e33d01b3-97f1-4e39-a664-d3e16060402b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35182, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "健康診断の結果が、先生が教えてくれた。", "corrected_sentence": "健康診断の結果を、先生が教えてくれた。", "error_description": "「教える」の対象は「結果を」。「結果が」は主語になってしまうので誤り。正しくは「結果を」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e33d01b3-97f1-4e39-a664-d3e16060402b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35182, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "調査の結果が、はっきり立った。", "corrected_sentence": "調査の結果が、はっきり出た。", "error_description": "「結果」に続く動詞は「出る」。「立つ」は誤りで、正しくは「出た」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e33d01b3-97f1-4e39-a664-d3e16060402b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
