INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35184, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「教育を受けた」の「を」。受ける対象の目的語を示し、教育に直接つく助詞。"}, {"text": "が", "is_correct": false, "explanation": "「教育が受けた」は成り立たない。「受ける」の対象は「を」で示す。"}, {"text": "に", "is_correct": false, "explanation": "「教育に受けた」は不自然。「に」は方向や相手を示すので、受ける対象には合わない。"}, {"text": "と", "is_correct": false, "explanation": "「教育と受けた」は文が成り立たない。「と」は並列や相手を示すので合わない。"}], "correct_answer": "を", "explanations": {"を": "「教育を受けた」の「を」。受ける対象の目的語を示し、教育に直接つく助詞。", "が": "「教育が受けた」は成り立たない。「受ける」の対象は「を」で示す。", "に": "「教育に受けた」は不自然。「に」は方向や相手を示すので、受ける対象には合わない。", "と": "「教育と受けた」は文が成り立たない。「と」は並列や相手を示すので合わない。"}, "error_tags": {"が": "subject marker, does not fit transitive 受けた", "に": "direction or target, not the object", "と": "pairing or companion, not the object"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8ba898d-26ba-45b0-8878-cd9248f53336') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35184, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "学校で勉強したり、先生から教えてもらったりすることです。", "primary_collocate": null, "pronunciation": "きょういく", "ipa": "kʲoːikɯ", "syllable_count": 4, "sentences": [{"text": "私は小さいころから、良い教育を受けて育った。", "target_word": "教育", "complexity_tier": "T3", "furigana": "私[わたし]は小[ちい]さいころから、良[よ]い教育[きょういく]を受[う]けて育[そだ]った。", "sentence_source": "generated"}, {"text": "この国では、小学校の教育は無料だ。", "target_word": "教育", "complexity_tier": "T3", "furigana": "この国[くに]では、小学校[しょうがっこう]の教育[きょういく]は無料[むりょう]だ。", "sentence_source": "generated"}, {"text": "姉は、子どもが教育を受けられる環境を作りたいと考え、大学で学んだ。", "target_word": "教育", "complexity_tier": "T3", "furigana": "姉は、子どもが教育[きょういく]を受けられる環境を作りたいと考え、大学で学んだ。", "sentence_source": "generated"}, {"text": "教育が大切だと、先生はいつも言っている。", "target_word": "教育", "complexity_tier": "T3", "furigana": "教育[きょういく]が大切[たいせつ]だと、先生[せんせい]はいつも言[い]っている。", "sentence_source": "generated"}, {"text": "父は教育に熱心で、毎日宿題を見てくれた。", "target_word": "教育", "complexity_tier": "T3", "furigana": "父[ちち]は教育[きょういく]に熱心[ねっしん]で、毎日[まいにち]宿題[しゅくだい]を見[み]てくれた。", "sentence_source": "generated"}, {"text": "山の村にも学校ができて、子どもたちが教育を受けられるようになった。", "target_word": "教育", "complexity_tier": "T3", "furigana": "山[やま]の村[むら]にも学校[がっこう]ができて、子[こ]どもたちが教育[きょういく]を受[う]けられるようになった。", "sentence_source": "generated"}, {"text": "親の仕事が忙しくても、子どもは教育を受ける権利がある。", "target_word": "教育", "complexity_tier": "T3", "furigana": "親[おや]の仕事[しごと]が忙[いそが]しくても、子[こ]どもは教育[きょういく]を受[う]ける権利[けんり]がある。", "sentence_source": "generated"}, {"text": "外国で教育を受けたので、彼は三つの言葉を話せる。", "target_word": "教育", "complexity_tier": "T3", "furigana": "外国[がいこく]で教育[きょういく]を受[う]けたので、彼[かれ]は三[みっ]つの言葉[ことば]を話[はな]せる。", "sentence_source": "generated"}, {"text": "教育のおかげで、私は読み書きができるようになった。", "target_word": "教育", "complexity_tier": "T3", "furigana": "教育[きょういく]のおかげで、私[わたし]は読[よ]み書[か]きができるようになった。", "sentence_source": "generated"}, {"text": "学校の教育が終わってから、塾に通っている。", "target_word": "教育", "complexity_tier": "T3", "furigana": "学校[がっこう]の教育[きょういく]が終[お]わってから、塾[じゅく]に通[かよ]っている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "教育", "label": "基本形"}, {"form": "教育する", "label": "動詞形"}, {"form": "教育を受ける", "label": "よく使う形"}], "register": "標準", "sense_fingerprint": "学校で先生に教わり、勉強すること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd6bd5b2a-24c0-4711-bcdb-72baf5213c95') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35184, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "教育", "is_correct": true, "explanation": "「良い教育を受けて育った」の「教育」。学校で教わる経験を指し、空所に入る。"}, {"text": "料理", "is_correct": false, "explanation": "「良い料理を受けて育った」は不自然。「受ける」は料理には合わない。"}, {"text": "天気", "is_correct": false, "explanation": "「良い天気を受けて育った」は意味をなさない。空所には教わる経験を表す語が入る。"}, {"text": "睡眠", "is_correct": false, "explanation": "「良い睡眠を受けて育った」とは言わない。「受ける」と睡眠は結びつかない。"}], "explanations": {"教育": "「良い教育を受けて育った」の「教育」。学校で教わる経験を指し、空所に入る。", "料理": "「良い料理を受けて育った」は不自然。「受ける」は料理には合わない。", "天気": "「良い天気を受けて育った」は意味をなさない。空所には教わる経験を表す語が入る。", "睡眠": "「良い睡眠を受けて育った」とは言わない。「受ける」と睡眠は結びつかない。"}, "sentence_index": 0, "correct_answer": "教育"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妹は教育に就くため、夜遅くまで勉強している。", "explanation": "ここは〈教職〉（教師という職業）の意味。教育は職業ではないので、「教育に就く」とは言わない。"}, {"text": "この時計は教育が正確で、一度も遅れたことがない。", "explanation": "ここは〈性能〉（機械の精度）の意味。教育は人に教えることなので、時計の正確さには使わない。"}, {"text": "うちの庭では、花を教育して毎年咲かせている。", "explanation": "ここは〈育てる〉（植物を育てる）の意味。教育は人に教えることなので、花には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8ba898d-26ba-45b0-8878-cd9248f53336') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35184, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "教育", "is_correct": true, "explanation": "「教育を受ける権利」の「教育」。子どもが受けるべき学びを指し、空所に入る。"}, {"text": "天候", "is_correct": false, "explanation": "「天候を受ける」とは言わない。権利の対象として天候は合わない。"}, {"text": "洗濯", "is_correct": false, "explanation": "「洗濯を受ける権利」は意味をなさない。受ける対象として洗濯は合わない。"}, {"text": "地震", "is_correct": false, "explanation": "「地震を受ける権利」は不自然。権利の文脈に地震は合わない。"}], "explanations": {"教育": "「教育を受ける権利」の「教育」。子どもが受けるべき学びを指し、空所に入る。", "天候": "「天候を受ける」とは言わない。権利の対象として天候は合わない。", "洗濯": "「洗濯を受ける権利」は意味をなさない。受ける対象として洗濯は合わない。", "地震": "「地震を受ける権利」は不自然。権利の文脈に地震は合わない。"}, "sentence_index": 6, "correct_answer": "教育"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この病院では、腰の教育を専門にしている医師がいる。", "explanation": "ここは〈治療〉の意味。教育は人に教えることを指し、腰の治療には使わない。"}, {"text": "この工場では、靴の教育を一日千足行っている。", "explanation": "ここは〈製造〉の意味。教育は知識や技能を教える営みで、靴を作る意味はない。"}, {"text": "この店では、肉の教育に時間をかけて、柔らかく仕上げる。", "explanation": "ここは〈下ごしらえ〉の意味。教育は人への指導を指すので、肉の加工には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8ba898d-26ba-45b0-8878-cd9248f53336') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35184, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "私の町には、夜間に教育に受けられる施設もある。", "corrected_sentence": "私の町には、夜間に教育を受けられる施設もある。", "error_description": "「教育を受けられる」の「を」が「に」になっている。「受ける」の対象は教育なので、目的語を示す「を」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8ba898d-26ba-45b0-8878-cd9248f53336') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35184, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "祖母は、戦争のせいで十分な教育を受けらなかったと話していた。", "corrected_sentence": "祖母は、戦争のせいで十分な教育を受けられなかったと話していた。", "error_description": "可能形は「受けられる」なので、過去否定は「受けられなかった」。「受けらなかった」は「れ」が抜けた誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8ba898d-26ba-45b0-8878-cd9248f53336') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35185, 3, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8ba898d-26ba-45b0-8878-cd9248f53336') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35185, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「教育を受ける」の「を」。受ける対象の目的語を示し、教育に直接つく助詞。"}, {"text": "が", "is_correct": false, "explanation": "「教育が受ける」は成り立たない。「受ける」の対象は目的語の「を」で示す。"}, {"text": "に", "is_correct": false, "explanation": "「教育に受ける」は不自然。「に」は方向や相手を示すので、受ける対象には合わない。"}, {"text": "で", "is_correct": false, "explanation": "「教育で受ける」は文が成り立たない。「で」は場所や手段を示すので、ここでは合わない。"}], "correct_answer": "を", "explanations": {"を": "「教育を受ける」の「を」。受ける対象の目的語を示し、教育に直接つく助詞。", "が": "「教育が受ける」は成り立たない。「受ける」の対象は目的語の「を」で示す。", "に": "「教育に受ける」は不自然。「に」は方向や相手を示すので、受ける対象には合わない。", "で": "「教育で受ける」は文が成り立たない。「で」は場所や手段を示すので、ここでは合わない。"}, "error_tags": {"が": "subject marker, does not fit transitive 受ける", "に": "direction or target, not the object", "で": "place or means, not the object"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8ba898d-26ba-45b0-8878-cd9248f53336') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35185, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "人に知識や技能を教え、育てること。また、その内容や制度。", "primary_collocate": null, "pronunciation": "きょういく", "ipa": "kʲoːikɯ", "syllable_count": 4, "sentences": [{"text": "現代の高等教育において、画一的な知識伝達モデルはもはやその有効性を維持し得ない。", "target_word": "教育", "complexity_tier": "T3", "furigana": "現代[げんだい]の高等教育[こうとうきょういく]において、画一的[かくいつてき]な知識[ちしき]伝達[でんたつ]モデルはもはやその有効性[ゆうこうせい]を維持[いじ]し得[え]ない。", "sentence_source": "mined"}, {"text": "教育の現場では、タブレットを使った授業が広がっている。", "target_word": "教育", "complexity_tier": "T3", "furigana": "教育[きょういく]の現場[げんば]では、タブレットを使[つか]った授業[じゅぎょう]が広[ひろ]がっている。", "sentence_source": "generated"}, {"text": "大学教育の現場において、教授陣が個々の学修到達度を最大化するためにこのシステムを如何に設計し、運用するかが問われているのである。", "target_word": "教育", "complexity_tier": "T3", "furigana": "大学教育[だいがくきょういく]の現場[げんば]において、教授陣[きょうじゅじん]が個々[ここ]の学修[がくしゅう]到達度[とうたつど]を最大化[さいだいか]するためにこのシステムを如何[いか]に設計[せっけい]し、運用[うんよう]するかが問[と]われているのである。", "sentence_source": "mined"}, {"text": "すなわち、技術的革新は単なる効率化の道具にとどまらず、教育の公平性と個別最適化を両立させる新たな認識論的枠組みを構築し得るという点に、その本質的な教育的示唆が存すると言えよう。", "target_word": "教育", "complexity_tier": "T3", "furigana": "すなわち、技術的[ぎじゅつてき]革新[かくしん]は単[たん]なる効率化[こうりつか]の道具[どうぐ]にとどまらず、教育[きょういく]の公平性[こうへいせい]と個別[こべつ]最適化[さいてきか]を両立[りょうりつ]させる新[あら]たな認識論的[にんしきろんてき]枠組[わくぐ]みを構築[こうちく]し得[う]るという点[てん]に、その本質的[ほんしつてき]な教育的[きょういくてき]示唆[しさ]が存[そん]すると言[い]えよう。", "sentence_source": "mined"}, {"text": "教育の在り方を見直す議論が国会で続いている。", "target_word": "教育", "complexity_tier": "T3", "furigana": "教育[きょういく]の在り方[ありかた]を見直す議論が国会で続いている。", "sentence_source": "generated"}, {"text": "教育にかかる費用が高いため、進学をあきらめる家庭もある。", "target_word": "教育", "complexity_tier": "T3", "furigana": "教育[きょういく]にかかる費用[ひよう]が高[たか]いため、進学[しんがく]をあきらめる家庭[かてい]もある。", "sentence_source": "generated"}, {"text": "彼女は論文で、教育の成果を測る新たな指標を示した。", "target_word": "教育", "complexity_tier": "T3", "furigana": "彼女は論文で、教育[きょういく]の成果[せいか]を測る新たな指標を示した。", "sentence_source": "generated"}, {"text": "政府は、地方の子どもが教育を受ける機会を広げる予算を組んだ。", "target_word": "教育", "complexity_tier": "T3", "furigana": "政府は、地方の子どもが教育[きょういく]を受ける機会を広げる予算を組んだ。", "sentence_source": "generated"}, {"text": "家庭での教育と学校の教育が、子どもの成長を支えている。", "target_word": "教育", "complexity_tier": "T3", "furigana": "家庭[かてい]での教育[きょういく]と学校[がっこう]の教育[きょういく]が、子[こ]どもの成長[せいちょう]を支[ささ]えている。", "sentence_source": "generated"}, {"text": "職場での教育が不十分だと、新人はすぐに仕事をやめてしまう。", "target_word": "教育", "complexity_tier": "T3", "furigana": "職場[しょくば]での教育[きょういく]が不十分[ふじゅうぶん]だと、新人[しんじん]はすぐに仕事[しごと]をやめてしまう。", "sentence_source": "generated"}], "morphological_forms": [{"form": "教育", "label": "基本形"}, {"form": "教育する", "label": "動詞形"}, {"form": "教育的", "label": "形容動詞形"}], "register": "書き言葉", "sense_fingerprint": "知識や技能を教え育てる営みと、その内容・制度", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 2 above tier T1: 3 words above tier T1 (max 2): 個々 (Zipf 3.92), 学修 (Zipf 2.76), 如何 (Zipf 3.96)','sentence 3 above tier T1: 6 words above tier T1 (max 2): 革新 (Zipf 3.98), とどまら (Zipf 3.23), 両立 (Zipf 3.76), 枠組み (Zipf 3.64), 示唆 (Zipf 3.85), 存する (Zipf 2.52)']::text[], 'd6bd5b2a-24c0-4711-bcdb-72baf5213c95') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35185, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "教育", "is_correct": true, "explanation": "「高等教育」の「教育」。大学などの高等な教育制度を指し、空所に入る。"}, {"text": "運動", "is_correct": false, "explanation": "「高等運動」とは言わない。文脈は高等教育を論じているので、運動は合わない。"}, {"text": "料理", "is_correct": false, "explanation": "「高等料理」は言わない。大学の教育の話をしている文脈に料理は合わない。"}, {"text": "天気", "is_correct": false, "explanation": "「高等天気」は意味をなさない。文脈は高等教育の知識伝達モデルを論じているので、天気は合わない。"}], "explanations": {"教育": "「高等教育」の「教育」。大学などの高等な教育制度を指し、空所に入る。", "運動": "「高等運動」とは言わない。文脈は高等教育を論じているので、運動は合わない。", "料理": "「高等料理」は言わない。大学の教育の話をしている文脈に料理は合わない。", "天気": "「高等天気」は意味をなさない。文脈は高等教育の知識伝達モデルを論じているので、天気は合わない。"}, "sentence_index": 0, "correct_answer": "教育"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は教育に就くため、大学で資格の勉強をしている。", "explanation": "ここは〈教職〉（教師という職業）の意味。教育は職業ではなく行為や制度を指すので、「教育に就く」とは言わない。"}, {"text": "この船は教育がよく、嵐の海を無事に進んだ。", "explanation": "ここは〈性能〉（機械や船の働き）の意味。教育は人に知識や技能を教えることなので、船の性能には使わない。"}, {"text": "この畑では、野菜を教育して大きく育てている。", "explanation": "ここは〈栽培〉（作物を作り育てること）の意味。教育は人に知識や技能を教えることなので、野菜の栽培には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8ba898d-26ba-45b0-8878-cd9248f53336') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35185, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "教育", "is_correct": true, "explanation": "「論文で、教育の成果を測る」の「教育」。教育の効果を指し、空所に入る。"}, {"text": "地震", "is_correct": false, "explanation": "「地震の成果」は意味をなさない。教育の効果を測る文脈に地震は合わない。"}, {"text": "天候", "is_correct": false, "explanation": "「天候の成果」とは言わない。成果を測る対象として天候は合わない。"}, {"text": "寝坊", "is_correct": false, "explanation": "「寝坊の成果」は不自然で、論文の指標の文脈には合わない。"}], "explanations": {"教育": "「論文で、教育の成果を測る」の「教育」。教育の効果を指し、空所に入る。", "地震": "「地震の成果」は意味をなさない。教育の効果を測る文脈に地震は合わない。", "天候": "「天候の成果」とは言わない。成果を測る対象として天候は合わない。", "寝坊": "「寝坊の成果」は不自然で、論文の指標の文脈には合わない。"}, "sentence_index": 6, "correct_answer": "教育"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "傷の教育が悪化したので、病院へ行った。", "explanation": "ここは〈治療〉の意味。教育は人に教えることを指し、傷の手当てには使わない。"}, {"text": "この工場では、部品の教育を一日千個行っている。", "explanation": "ここは〈製造〉の意味。教育は知識や技能を教える営みで、部品を作る意味はない。"}, {"text": "この料理は、塩の教育が絶妙だ。", "explanation": "ここは〈味付け〉の意味。教育は人への指導を指すので、塩の加減には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8ba898d-26ba-45b0-8878-cd9248f53336') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35185, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼女は地方の子どもに教育に受けさせる取り組みを進めている。", "corrected_sentence": "彼女は地方の子どもに教育を受けさせる取り組みを進めている。", "error_description": "「教育を受けさせる」の「を」が「に」になっている。「受けさせる」の対象は教育なので、目的語を示す「を」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8ba898d-26ba-45b0-8878-cd9248f53336') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35185, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この大学では、留学生にも質の高い教育に提供している。", "corrected_sentence": "この大学では、留学生にも質の高い教育を提供している。", "error_description": "「教育を提供する」の「を」が「に」になっている。「提供する」は目的語に「を」を取るので、「を」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8ba898d-26ba-45b0-8878-cd9248f53336') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35187, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「文化を知るために」で、「知る」の目的語なので「を」。"}, {"text": "が", "is_correct": false, "explanation": "「文化が知る」では文化が知る主体になってしまい、ここでは成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "「文化に知る」は成り立たず、「知る」の対象を示すには「を」が必要。"}, {"text": "へ", "is_correct": false, "explanation": "方向の「へ」は「文化へ知る」と続かず、「知る」の文脈に合わない。"}], "correct_answer": "を", "explanations": {"を": "「文化を知るために」で、「知る」の目的語なので「を」。", "が": "「文化が知る」では文化が知る主体になってしまい、ここでは成り立たない。", "に": "「文化に知る」は成り立たず、「知る」の対象を示すには「を」が必要。", "へ": "方向の「へ」は「文化へ知る」と続かず、「知る」の文脈に合わない。"}, "error_tags": {"が": "主語", "に": "相手", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d6d98c9-41ee-45f3-a318-58e42f1f84d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35187, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d6d98c9-41ee-45f3-a318-58e42f1f84d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35187, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "人間の社会や歴史の中で、人々が作り出してきた知識、芸術、習慣、価値観などの総体。", "primary_collocate": null, "pronunciation": "ぶんか", "ipa": "bɯŋka", "syllable_count": 3, "sentences": [{"text": "単なるエネルギー源に過ぎなかった穀物が、生命の維持と豊かな食体験を同時に叶える食文化へと昇華される。", "target_word": "文化", "complexity_tier": "T3", "furigana": "単[たん]なるエネルギー源[げん]に過[す]ぎなかった穀物[こくもつ]が、生命[せいめい]の維持[いじ]と豊[ゆた]かな食体験[しょくたいけん]を同時[どうじ]に叶[かな]える食文化[しょくぶんか]へと昇華[しょうか]される。", "sentence_source": "mined"}, {"text": "旅行先では、その土地の文化を知るために、まず市場を歩いてみる。", "target_word": "文化", "complexity_tier": "T3", "furigana": "旅行先[りょこうさき]では、その土地[とち]の文化[ぶんか]を知[し]るために、まず市場[いちば]を歩[ある]いてみる。", "sentence_source": "generated"}, {"text": "言葉が違えば、ものの考え方や文化も違うことが多い。", "target_word": "文化", "complexity_tier": "T3", "furigana": "言葉[ことば]が違[ちが]えば、ものの考[かんが]え方[かた]や文化[ぶんか]も違[ちが]うことが多[おお]い。", "sentence_source": "generated"}, {"text": "留学生は、日本の文化に興味があって、茶道を習い始めた。", "target_word": "文化", "complexity_tier": "T3", "furigana": "留学生[りゅうがくせい]は、日本[にほん]の文化[ぶんか]に興味[きょうみ]があって、茶道[さどう]を習[なら]い始[はじ]めた。", "sentence_source": "generated"}, {"text": "異なる文化を持つ人と働くときは、相手の習慣を尊重することが大切だ。", "target_word": "文化", "complexity_tier": "T3", "furigana": "異[こと]なる文化[ぶんか]を持[も]つ人[ひと]と働[はたら]くときは、相手[あいて]の習慣[しゅうかん]を尊重[そんちょう]することが大切[たいせつ]だ。", "sentence_source": "generated"}, {"text": "古い寺や祭りは、地域の文化を次の世代に伝える役目を果たしている。", "target_word": "文化", "complexity_tier": "T3", "furigana": "古[ふる]い寺[てら]や祭[まつ]りは、地域[ちいき]の文化[ぶんか]を次[つぎ]の世代[せだい]に伝[つた]える役目[やくめ]を果[は]たしている。", "sentence_source": "generated"}, {"text": "握手であいさつする文化の国もあれば、おじぎをする国もある。", "target_word": "文化", "complexity_tier": "T3", "furigana": "握手[あくしゅ]であいさつする文化[ぶんか]の国[くに]もあれば、おじぎをする国[くに]もある。", "sentence_source": "generated"}, {"text": "麺をすする音は、日本では失礼ではないが、文化が違う国では嫌がられることがある。", "target_word": "文化", "complexity_tier": "T3", "furigana": "麺[めん]をすする音[おと]は、日本[にほん]では失礼[しつれい]ではないが、文化[ぶんか]が違[ちが]う国[くに]では嫌[いや]がられることがある。", "sentence_source": "generated"}, {"text": "博物館には、千年前の人々の暮らしと文化を伝える品々が並んでいる。", "target_word": "文化", "complexity_tier": "T3", "furigana": "博物館[はくぶつかん]には、千年前[せんねんまえ]の人々[ひとびと]の暮[く]らしと文化[ぶんか]を伝[つた]える品々[しなじな]が並[なら]んでいる。", "sentence_source": "generated"}, {"text": "若者の間で生まれた新しい文化が、やがて社会全体に広がっていった。", "target_word": "文化", "complexity_tier": "T3", "furigana": "若者[わかもの]の間[あいだ]で生[う]まれた新[あたら]しい文化[ぶんか]が、やがて社会全体[しゃかいぜんたい]に広[ひろ]がっていった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "文化", "label": "基本形"}], "register": "中立", "sense_fingerprint": "ある社会の人々が築いてきた知識・芸術・習慣・価値観の全体", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T1: 3 words above tier T1 (max 2): 穀物 (Zipf 3.52), 叶える (Zipf 3.54), 昇華 (Zipf 3.35)','sentence 3 above tier T1: 3 words above tier T1 (max 2): 留学生 (Zipf 3.87), 茶道 (Zipf 3.28), 習い (Zipf 3.43)']::text[], '95d3b987-f670-4e84-a902-8e7233637a42') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35187, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "文化", "is_correct": true, "explanation": "「食文化」で、人々が築いてきた食に関する知識・習慣・価値観の総体を指す。"}, {"text": "経済", "is_correct": false, "explanation": "「食経済」は成り立たず、人々が築いてきた知識や習慣という文脈に合わない。"}, {"text": "教育", "is_correct": false, "explanation": "「食教育」は食を教える意味になり、社会が築いてきた習慣・価値観の総体とは合わない。"}, {"text": "言語", "is_correct": false, "explanation": "「食言語」は成り立たず、食と結びつく習慣や価値観を指す語が必要な位置に合わない。"}], "explanations": {"文化": "「食文化」で、人々が築いてきた食に関する知識・習慣・価値観の総体を指す。", "経済": "「食経済」は成り立たず、人々が築いてきた知識や習慣という文脈に合わない。", "教育": "「食教育」は食を教える意味になり、社会が築いてきた習慣・価値観の総体とは合わない。", "言語": "「食言語」は成り立たず、食と結びつく習慣や価値観を指す語が必要な位置に合わない。"}, "sentence_index": 0, "correct_answer": "文化"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この地域には、多くの文化が昔から暮らしている。", "explanation": "ここは〈民族〉の意味。文化は人々ではなく、知識や習慣のまとまりなので、暮らすものとしては合わない。"}, {"text": "彼は去年から文化が十キロも増えた。", "explanation": "ここは〈体重〉の意味。文化は重さを量るものではないので、体重の増減には使えない。"}, {"text": "この文化には、町の道路と駅がくわしく描かれている。", "explanation": "ここは〈地図〉の意味。文化は道路や駅を描いた図ではないので、描かれるものとしては合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d6d98c9-41ee-45f3-a318-58e42f1f84d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35187, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "文化", "is_correct": true, "explanation": "「握手であいさつする文化の国」で、あいさつの習慣や価値観をもつ社会を指す。"}, {"text": "通貨", "is_correct": false, "explanation": "通貨はお金の制度で、握手であいさつする習慣の違いを表さないので合わない。"}, {"text": "時刻", "is_correct": false, "explanation": "時刻は時の点を表す語で、あいさつの仕方によって国を区別する文脈に合わない。"}, {"text": "天気", "is_correct": false, "explanation": "天気は空模様を表す語で、あいさつの習慣をもつ国を指す文脈には合わない。"}], "explanations": {"文化": "「握手であいさつする文化の国」で、あいさつの習慣や価値観をもつ社会を指す。", "通貨": "通貨はお金の制度で、握手であいさつする習慣の違いを表さないので合わない。", "時刻": "時刻は時の点を表す語で、あいさつの仕方によって国を区別する文脈に合わない。", "天気": "天気は空模様を表す語で、あいさつの習慣をもつ国を指す文脈には合わない。"}, "sentence_index": 6, "correct_answer": "文化"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この薬は、若者の間で広がった文化を治すために開発された。", "explanation": "ここは〈病気〉の意味。文化は治療の対象ではないので、治すという文脈には合わない。"}, {"text": "明日の文化は三十度まで上がるでしょう。", "explanation": "ここは〈気温〉の意味。文化は温度を表すものではないので、上がる対象としては合わない。"}, {"text": "この文化は、正確な時間を刻む。", "explanation": "ここは〈時計〉の意味。文化は時間を刻む道具ではないので、正確に時を刻むものとしては合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d6d98c9-41ee-45f3-a318-58e42f1f84d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35187, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "日本の文化を詳しい友人が、茶道を教えてくれた。", "corrected_sentence": "日本の文化に詳しい友人が、茶道を教えてくれた。", "error_description": "「詳しい」は「〜に詳しい」の形をとり、「文化」には「に」が付く。「を」は誤り（正しい形：日本の文化に詳しい友人が、茶道を教えてくれた）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d6d98c9-41ee-45f3-a318-58e42f1f84d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35187, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この町には、昔ながらの文化を今も色濃く残っている。", "corrected_sentence": "この町には、昔ながらの文化が今も色濃く残っている。", "error_description": "「残る」は自動詞なので主語に「が」を取る。「文化を」は誤りで、正しくは「文化が」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d6d98c9-41ee-45f3-a318-58e42f1f84d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35188, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "原因を表す「で」。「科学の発展で」は「科学の発展によって」の意味で、生活が便利になった原因を示す。"}, {"text": "を", "is_correct": false, "explanation": "目的語を表す「を」。「発展を」は動作の対象になるが、ここは原因を述べる文なので合わない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表す「へ」。「発展へ、私たちの生活は」は原因の意味にならず不自然。"}, {"text": "と", "is_correct": false, "explanation": "並列や相手を表す「と」。「発展と、私たちの生活は」では原因の意味が出ず合わない。"}], "correct_answer": "で", "explanations": {"で": "原因を表す「で」。「科学の発展で」は「科学の発展によって」の意味で、生活が便利になった原因を示す。", "を": "目的語を表す「を」。「発展を」は動作の対象になるが、ここは原因を述べる文なので合わない。", "へ": "方向を表す「へ」。「発展へ、私たちの生活は」は原因の意味にならず不自然。", "と": "並列や相手を表す「と」。「発展と、私たちの生活は」では原因の意味が出ず合わない。"}, "error_tags": {"を": "目的語", "へ": "方向", "と": "並列・相手"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "衰退", "is_correct": true, "explanation": "物事の勢いが衰えて悪くなること。「発展」が良くなる意味なので、対義語になる。"}, {"text": "拡大", "is_correct": false, "explanation": "範囲や規模を広げること。発展と関係は深いが、良くなる・悪くなるの対立ではないので対義語ではない。"}, {"text": "開発", "is_correct": false, "explanation": "新しく作り出したり土地などを整えたりすること。発展に近い意味で、対義語ではない。"}, {"text": "誕生", "is_correct": false, "explanation": "生まれること。発展の反対語ではなく、新しく始まる意味なので対義語にはならない。"}], "correct_answer": "衰退", "explanations": {"衰退": "物事の勢いが衰えて悪くなること。「発展」が良くなる意味なので、対義語になる。", "拡大": "範囲や規模を広げること。発展と関係は深いが、良くなる・悪くなるの対立ではないので対義語ではない。", "開発": "新しく作り出したり土地などを整えたりすること。発展に近い意味で、対義語ではない。", "誕生": "生まれること。発展の反対語ではなく、新しく始まる意味なので対義語にはならない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e33d01b3-97f1-4e39-a664-d3e16060402b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35188, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "原因や手段を表す「により」の「に」。「医学の発展により」は、医学の進歩を理由として示す。"}, {"text": "より", "is_correct": false, "explanation": "比較を表す「より」。「医学の発展より」は比べる意味になり、原因を示さないので合わない。"}, {"text": "を", "is_correct": false, "explanation": "目的語を表す「を」。「医学の発展を、多くの病気が治る」は文の対象が立たず、成り立たない。"}, {"text": "の", "is_correct": false, "explanation": "連体修飾の「の」。「医学の発展の」の後に文が続かず、この位置には入らない。"}], "correct_answer": "に", "explanations": {"に": "原因や手段を表す「により」の「に」。「医学の発展により」は、医学の進歩を理由として示す。", "より": "比較を表す「より」。「医学の発展より」は比べる意味になり、原因を示さないので合わない。", "を": "目的語を表す「を」。「医学の発展を、多くの病気が治る」は文の対象が立たず、成り立たない。", "の": "連体修飾の「の」。「医学の発展の」の後に文が続かず、この位置には入らない。"}, "error_tags": {"より": "比較", "を": "目的語", "の": "連体修飾"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "衰退", "is_correct": true, "explanation": "物事の勢いが衰えて悪くなること。「発展」が良くなる意味なので、対義語になる。"}, {"text": "普及", "is_correct": false, "explanation": "広く行き渡ること。発展と近い話題だが、良くなる・悪くなるの対立ではなく対義語ではない。"}, {"text": "継承", "is_correct": false, "explanation": "前の人から受け継ぐこと。発展とは意味がつながらず、対義語ではない。"}, {"text": "進出", "is_correct": false, "explanation": "新しい場所へ入り込むこと。発展と関係するが、対義語ではない。"}], "correct_answer": "衰退", "explanations": {"衰退": "物事の勢いが衰えて悪くなること。「発展」が良くなる意味なので、対義語になる。", "普及": "広く行き渡ること。発展と近い話題だが、良くなる・悪くなるの対立ではなく対義語ではない。", "継承": "前の人から受け継ぐこと。発展とは意味がつながらず、対義語ではない。", "進出": "新しい場所へ入り込むこと。発展と関係するが、対義語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e33d01b3-97f1-4e39-a664-d3e16060402b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35188, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "ものがもっとよくなったり、新しいものが出てきたりすること。", "primary_collocate": null, "pronunciation": "はってん", "ipa": "hatːeɴ", "syllable_count": 4, "sentences": [{"text": "この町は、鉄道ができてから大きく発展した。", "target_word": "発展した", "complexity_tier": "T3", "furigana": "この町(まち)は、鉄道(てつどう)ができてから大(おお)きく発展(はってん)した。", "sentence_source": "generated"}, {"text": "科学の発展で、私たちの生活は便利になった。", "target_word": "発展", "complexity_tier": "T3", "furigana": "科学(かがく)の発展(はってん)で、私(わたし)たちの生活(せいかつ)は便利(べんり)になった。", "sentence_source": "generated"}, {"text": "国の発展には、教育がとても大切だ。", "target_word": "発展", "complexity_tier": "T3", "furigana": "国(くに)の発展(はってん)には、教育(きょういく)がとても大切(たいせつ)だ。", "sentence_source": "generated"}, {"text": "小さな店が発展して、今では全国に支店がある。", "target_word": "発展して", "complexity_tier": "T3", "furigana": "小(ちい)さな店(みせ)が発展(はってん)して、今(いま)では全国(ぜんこく)に支店(してん)がある。", "sentence_source": "generated"}, {"text": "技術が発展するにつれて、仕事のやり方も変わる。", "target_word": "発展する", "complexity_tier": "T3", "furigana": "技術(ぎじゅつ)が発展(はってん)するにつれて、仕事(しごと)のやり方(かた)も変(か)わる。", "sentence_source": "generated"}, {"text": "二つの国の友好関係が、さらに発展することを願う。", "target_word": "発展する", "complexity_tier": "T3", "furigana": "二(ふた)つの国(くに)の友好関係(ゆうこうかんけい)が、さらに発展(はってん)することを願(ねが)う。", "sentence_source": "generated"}, {"text": "港のおかげで、この地域は商業が発展した。", "target_word": "発展した", "complexity_tier": "T3", "furigana": "港(みなと)のおかげで、この地域(ちいき)は商業(しょうぎょう)が発展(はってん)した。", "sentence_source": "generated"}, {"text": "医学の発展により、多くの病気が治るようになった。", "target_word": "発展", "complexity_tier": "T3", "furigana": "医学(いがく)の発展(はってん)により、多(おお)くの病気(びょうき)が治(なお)るようになった。", "sentence_source": "generated"}, {"text": "祖父は、会社が発展していく様子を見守ってきた。", "target_word": "発展して", "complexity_tier": "T3", "furigana": "祖父(そふ)は、会社(かいしゃ)が発展(はってん)していく様子(ようす)を見守(みまも)ってきた。", "sentence_source": "generated"}, {"text": "都市が発展すると、自然が減ることもある。", "target_word": "発展する", "complexity_tier": "T3", "furigana": "都市(とし)が発展(はってん)すると、自然(しぜん)が減(へ)ることもある。", "sentence_source": "generated"}], "morphological_forms": [{"form": "発展", "label": "基本形"}, {"form": "発展する", "label": "辞書形"}, {"form": "発展しない", "label": "否定形"}, {"form": "発展した", "label": "過去形"}, {"form": "発展して", "label": "て形"}, {"form": "発展すれば", "label": "仮定形"}, {"form": "発展しよう", "label": "意向形"}, {"form": "発展させる", "label": "使役形"}], "register": "neutral", "sense_fingerprint": "物事や社会が進んで大きく良くなっていくこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4c3b1d77-b0ef-4bb3-862f-9f84b278ab5c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35188, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "発展した", "is_correct": true, "explanation": "過去形。「大きく発展した」で文が終わり、鉄道ができてからの変化を表す。"}, {"text": "発展させた", "is_correct": false, "explanation": "使役の過去形。「町は大きく発展させた」は、町を主語にすると他動詞の形が合わず文が成り立たない。"}, {"text": "発展しよう", "is_correct": false, "explanation": "意向形。「大きく発展しよう」は勧誘の言い方になり、過去の変化を述べる文には合わない。"}, {"text": "発展すれば", "is_correct": false, "explanation": "仮定形。「発展すれば」で文が止まり、文として完結しないので空欄に合わない。"}], "explanations": {"発展した": "過去形。「大きく発展した」で文が終わり、鉄道ができてからの変化を表す。", "発展させた": "使役の過去形。「町は大きく発展させた」は、町を主語にすると他動詞の形が合わず文が成り立たない。", "発展しよう": "意向形。「大きく発展しよう」は勧誘の言い方になり、過去の変化を述べる文には合わない。", "発展すれば": "仮定形。「発展すれば」で文が止まり、文として完結しないので空欄に合わない。"}, "sentence_index": 0, "correct_answer": "発展した"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "子どもの脳は、十歳ごろまで大きく発展する。", "explanation": "ここは〈発達〉の意味。〈発展〉は物事が大きく良くなる意味で、人の能力や体の成長には〈発達〉を使う。"}, {"text": "この苗木は、一年で大きく発展した。", "explanation": "ここは〈成長〉の意味。〈発展〉は社会や物事の変化に使うので、植物が育つ様子には〈成長〉を使う。"}, {"text": "この学校の生徒の数は、去年から大きく発展した。", "explanation": "ここは〈増加〉の意味。〈発展〉は人数の増え方には使わないので、〈生徒の数が増加した〉と言う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e33d01b3-97f1-4e39-a664-d3e16060402b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35188, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "発展した", "is_correct": true, "explanation": "過去形。「商業が発展した」で文が終わり、港のおかげで変化したことを表す。"}, {"text": "発展しなければ", "is_correct": false, "explanation": "否定の仮定形。「発展しなければ」で文が止まり、完結しない。"}, {"text": "発展させよう", "is_correct": false, "explanation": "使役の意向形。「商業が発展させよう」では主語と目的語が合わず、過去の変化を表す文にならない。"}, {"text": "発展すると", "is_correct": false, "explanation": "条件の形。「発展すると」で文が止まり、完結しないので空欄に合わない。"}], "explanations": {"発展した": "過去形。「商業が発展した」で文が終わり、港のおかげで変化したことを表す。", "発展しなければ": "否定の仮定形。「発展しなければ」で文が止まり、完結しない。", "発展させよう": "使役の意向形。「商業が発展させよう」では主語と目的語が合わず、過去の変化を表す文にならない。", "発展すると": "条件の形。「発展すると」で文が止まり、完結しないので空欄に合わない。"}, "sentence_index": 6, "correct_answer": "発展した"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "昨日の大雨で、川の水位が発展した。", "explanation": "ここは〈上昇〉の意味。〈発展〉は水位のような数値の変化には使わないので、〈水位が上昇した〉と言う。"}, {"text": "弟の身長が発展して、もう私より高くなった。", "explanation": "ここは〈伸びる〉の意味。〈発展〉は身長の変化には使わないので、〈身長が伸びて〉と言う。"}, {"text": "夕方になって、風が発展してきた。", "explanation": "ここは〈強まる〉の意味。〈発展〉は風の強さの変化には使わないので、〈風が強まってきた〉と言う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e33d01b3-97f1-4e39-a664-d3e16060402b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35188, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "新しい道路ができてから、この村は大きく発展させた。", "corrected_sentence": "新しい道路ができてから、この村は大きく発展した。", "error_description": "「発展させた」は他動詞で、目的語（村を）が必要。主語「村は」のままでは目的語がなく成り立たないので誤り。正しくは「発展した」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e33d01b3-97f1-4e39-a664-d3e16060402b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35188, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "海外との取引が増えて、この会社は大きく発展しった。", "corrected_sentence": "海外との取引が増えて、この会社は大きく発展した。", "error_description": "「発展」は「する」を付けた動詞で、過去形は「発展した」。「発展しった」は「する」の活用として成り立たない誤った形で、「発展した」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e33d01b3-97f1-4e39-a664-d3e16060402b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35192, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "原因を表す「で」。「友だちの影響で」は、友だちの働きかけが理由であることを示す。"}, {"text": "を", "is_correct": false, "explanation": "目的語を表す「を」。「影響を」は動作の対象を示すが、ここは原因を述べる文なので合わない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表す「へ」。「影響へ」は原因の意味にならず、文が合わない。"}, {"text": "と", "is_correct": false, "explanation": "並列や相手を表す「と」。「影響と」では原因の意味が出ず合わない。"}], "correct_answer": "で", "explanations": {"で": "原因を表す「で」。「友だちの影響で」は、友だちの働きかけが理由であることを示す。", "を": "目的語を表す「を」。「影響を」は動作の対象を示すが、ここは原因を述べる文なので合わない。", "へ": "方向を表す「へ」。「影響へ」は原因の意味にならず、文が合わない。", "と": "並列や相手を表す「と」。「影響と」では原因の意味が出ず合わない。"}, "error_tags": {"を": "目的語", "へ": "方向", "と": "並列・相手"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e33d01b3-97f1-4e39-a664-d3e16060402b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35192, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "対象を表す「に」。「将来に影響した」で、先生の言葉が私の将来に及ぼした働きを示す。"}, {"text": "で", "is_correct": false, "explanation": "手段や場所を表す「で」。「将来で影響した」は意味が通らず合わない。"}, {"text": "より", "is_correct": false, "explanation": "比較を表す「より」。「将来より影響した」は比べる意味にならず、文が合わない。"}, {"text": "の", "is_correct": false, "explanation": "連体修飾の「の」。「将来の影響した」は文として続かず、空欄に入らない。"}], "correct_answer": "に", "explanations": {"に": "対象を表す「に」。「将来に影響した」で、先生の言葉が私の将来に及ぼした働きを示す。", "で": "手段や場所を表す「で」。「将来で影響した」は意味が通らず合わない。", "より": "比較を表す「より」。「将来より影響した」は比べる意味にならず、文が合わない。", "の": "連体修飾の「の」。「将来の影響した」は文として続かず、空欄に入らない。"}, "error_tags": {"で": "場所・手段", "より": "比較", "の": "連体修飾"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e33d01b3-97f1-4e39-a664-d3e16060402b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35192, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "何かが、ほかのものに、はたらきかけること。", "primary_collocate": null, "pronunciation": "えいきょう", "ipa": "eːkʲoː", "syllable_count": 4, "sentences": [{"text": "天気は気分に大きな影響を与える。", "target_word": "影響", "complexity_tier": "T3", "furigana": "天気(てんき)は気分(きぶん)に大(おお)きな影響(えいきょう)を与(あた)える。", "sentence_source": "generated"}, {"text": "友だちの影響で、私も走り始めた。", "target_word": "影響", "complexity_tier": "T3", "furigana": "友(とも)だちの影響(えいきょう)で、私(わたし)も走(はし)り始(はじ)めた。", "sentence_source": "generated"}, {"text": "台風の影響で、電車が止まった。", "target_word": "影響", "complexity_tier": "T3", "furigana": "台風(たいふう)の影響(えいきょう)で、電車(でんしゃ)が止(と)まった。", "sentence_source": "generated"}, {"text": "親の考え方は、子どもに影響する。", "target_word": "影響する", "complexity_tier": "T3", "furigana": "親(おや)の考(かんが)え方(かた)は、子(こ)どもに影響(えいきょう)する。", "sentence_source": "generated"}, {"text": "睡眠が足りないと、仕事に悪い影響が出る。", "target_word": "影響", "complexity_tier": "T3", "furigana": "睡眠(すいみん)が足(た)りないと、仕事(しごと)に悪(わる)い影響(えいきょう)が出(で)る。", "sentence_source": "generated"}, {"text": "この本は、多くの若者に影響を与えた。", "target_word": "影響", "complexity_tier": "T3", "furigana": "この本(ほん)は、多(おお)くの若者(わかもの)に影響(えいきょう)を与(あた)えた。", "sentence_source": "generated"}, {"text": "暑さの影響を受けて、野菜の値段が上がった。", "target_word": "影響", "complexity_tier": "T3", "furigana": "暑(あつ)さの影響(えいきょう)を受(う)けて、野菜(やさい)の値段(ねだん)が上(あ)がった。", "sentence_source": "generated"}, {"text": "先生の言葉は、私の将来に影響した。", "target_word": "影響した", "complexity_tier": "T3", "furigana": "先生(せんせい)の言葉(ことば)は、私(わたし)の将来(しょうらい)に影響(えいきょう)した。", "sentence_source": "generated"}, {"text": "雨はあまり影響しないから、予定は変えない。", "target_word": "影響しない", "complexity_tier": "T3", "furigana": "雨(あめ)はあまり影響(えいきょう)しないから、予定(よてい)は変(か)えない。", "sentence_source": "generated"}, {"text": "薬の影響で、一日中眠かった。", "target_word": "影響", "complexity_tier": "T3", "furigana": "薬(くすり)の影響(えいきょう)で、一日中(いちにちじゅう)眠(ねむ)かった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "影響", "label": "基本形"}, {"form": "影響する", "label": "辞書形"}, {"form": "影響しない", "label": "否定形"}, {"form": "影響した", "label": "過去形"}, {"form": "影響して", "label": "て形"}, {"form": "影響すれば", "label": "仮定形"}, {"form": "影響される", "label": "受身形"}], "register": "neutral", "sense_fingerprint": "あるものが他のものに作用して変化をもたらすこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 9 above tier T1: contains vocabulary far above tier T1: 眠かっ (Zipf 2.26)']::text[], '4c3b1d77-b0ef-4bb3-862f-9f84b278ab5c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35192, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "影響", "is_correct": true, "explanation": "名詞。「大きな影響を与える」は、天気が気分にはたらきかけることを表し、文に合う。"}, {"text": "天気", "is_correct": false, "explanation": "名詞だが、「大きな天気を与える」は意味が通らず、文の空欄に入らない。"}, {"text": "反省", "is_correct": false, "explanation": "名詞だが、「大きな反省を与える」は不自然で、与えるものとしては合わない。"}, {"text": "感想", "is_correct": false, "explanation": "名詞だが、「大きな感想を与える」は意味が合わず、空欄に入らない。"}], "explanations": {"影響": "名詞。「大きな影響を与える」は、天気が気分にはたらきかけることを表し、文に合う。", "天気": "名詞だが、「大きな天気を与える」は意味が通らず、文の空欄に入らない。", "反省": "名詞だが、「大きな反省を与える」は不自然で、与えるものとしては合わない。", "感想": "名詞だが、「大きな感想を与える」は意味が合わず、空欄に入らない。"}, "sentence_index": 0, "correct_answer": "影響"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この薬は、咳を止める影響がある。", "explanation": "ここは〈効果〉の意味。〈影響〉は周りに及ぼすはたらきを指し、目的どおりの効き目には〈効果〉を使う。"}, {"text": "この件で、社長は事故の影響を取った。", "explanation": "ここは〈責任〉の意味。〈影響〉は責任を負うものではないので、〈事故の責任を取る〉の形にはならない。"}, {"text": "運転中は、周りの車に影響を払うことが大切だ。", "explanation": "ここは〈注意〉の意味。〈影響〉は注意を向けるものではないので、〈注意を払う〉の形にはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e33d01b3-97f1-4e39-a664-d3e16060402b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35192, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "影響", "is_correct": true, "explanation": "名詞。「暑さの影響を受けて」は暑さが野菜の値段に与えた作用を表し、文に合う。"}, {"text": "対策", "is_correct": false, "explanation": "名詞だが、「暑さの対策を受けて」は受け身の意味が合わず、空欄に入らない。"}, {"text": "原因", "is_correct": false, "explanation": "名詞だが、「暑さの原因を受けて」は原因を受けるという意味で不自然。"}, {"text": "対象", "is_correct": false, "explanation": "名詞だが、「暑さの対象を受けて」は意味が通らず、空欄に入らない。"}], "explanations": {"影響": "名詞。「暑さの影響を受けて」は暑さが野菜の値段に与えた作用を表し、文に合う。", "対策": "名詞だが、「暑さの対策を受けて」は受け身の意味が合わず、空欄に入らない。", "原因": "名詞だが、「暑さの原因を受けて」は原因を受けるという意味で不自然。", "対象": "名詞だが、「暑さの対象を受けて」は意味が通らず、空欄に入らない。"}, "sentence_index": 6, "correct_answer": "影響"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "新しい機械で、作業の影響を省けた。", "explanation": "ここは〈手間〉の意味。〈影響〉は省くものではないので、〈手間を省く〉と言う。"}, {"text": "先生は作品に、高い影響を下した。", "explanation": "ここは〈評価〉の意味。〈影響〉は下すものではなく、〈評価を下す〉と言うのが正しい。"}, {"text": "新しい発表は、世間の影響を集めた。", "explanation": "ここは〈注目〉の意味。〈影響〉は人の関心を集めるものではなく、〈注目を集める〉と言うのが正しい。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e33d01b3-97f1-4e39-a664-d3e16060402b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35192, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この店の雰囲気は、お客さんの気分に大きな影響に与える。", "corrected_sentence": "この店の雰囲気は、お客さんの気分に大きな影響を与える。", "error_description": "「与える」の目的語は「影響を」。「影響に」は誤りで、正しくは「影響を与える」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e33d01b3-97f1-4e39-a664-d3e16060402b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35192, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "寒さの影響を取って、花の開花が遅れた。", "corrected_sentence": "寒さの影響を受けて、花の開花が遅れた。", "error_description": "「影響」には「受ける」が続く。「取る」は誤りで、正しくは「受けて」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e33d01b3-97f1-4e39-a664-d3e16060402b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35194, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "与えるの目的語「餌」を示す格助詞で、直前の名詞に付く正しい助詞。"}, {"text": "が", "is_correct": false, "explanation": "「餌が与える」では餌が主語になり、与える主体がなくなって合わない。"}, {"text": "に", "is_correct": false, "explanation": "「犬に餌に与える」と「に」が二重になり、文法的に成立しない。"}, {"text": "の", "is_correct": false, "explanation": "「餌の与える」は連体修飾の形が崩れ、動詞が文の述語として機能しない。"}], "correct_answer": "を", "explanations": {"を": "与えるの目的語「餌」を示す格助詞で、直前の名詞に付く正しい助詞。", "が": "「餌が与える」では餌が主語になり、与える主体がなくなって合わない。", "に": "「犬に餌に与える」と「に」が二重になり、文法的に成立しない。", "の": "「餌の与える」は連体修飾の形が崩れ、動詞が文の述語として機能しない。"}, "error_tags": {"が": "主語の格を誤る", "に": "二重の格助詞", "の": "連体修飾の助詞を誤る"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "受ける", "is_correct": true, "explanation": "与える（相手に渡す）の対義語で、相手から受け取る意味。辞書で対義語として挙がる。"}, {"text": "防ぐ", "is_correct": false, "explanation": "害が起きないよう止める意味で、与えることの対義にはならない。"}, {"text": "残す", "is_correct": false, "explanation": "そのまま留めておく意味で、渡すことの反対語ではない。"}, {"text": "増やす", "is_correct": false, "explanation": "数量を多くする意味で、与える行為の対義語ではない。"}], "correct_answer": "受ける", "explanations": {"受ける": "与える（相手に渡す）の対義語で、相手から受け取る意味。辞書で対義語として挙がる。", "防ぐ": "害が起きないよう止める意味で、与えることの対義にはならない。", "残す": "そのまま留めておく意味で、渡すことの反対語ではない。", "増やす": "数量を多くする意味で、与える行為の対義語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c07d00d1-8048-4ad4-beac-311160b5c24e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35194, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "与えるの目的語「チャンス」を示す格助詞で、直前に置く正しい助詞。"}, {"text": "と", "is_correct": false, "explanation": "「チャンスと与える」は共同の意味になり、目的語を示せない。"}, {"text": "へ", "is_correct": false, "explanation": "「チャンスへ与える」は方向の意味になり、与える対象の目的語としては合わない。"}, {"text": "から", "is_correct": false, "explanation": "「チャンスから与える」は起点の意味になり、目的語を示す働きがない。"}], "correct_answer": "を", "explanations": {"を": "与えるの目的語「チャンス」を示す格助詞で、直前に置く正しい助詞。", "と": "「チャンスと与える」は共同の意味になり、目的語を示せない。", "へ": "「チャンスへ与える」は方向の意味になり、与える対象の目的語としては合わない。", "から": "「チャンスから与える」は起点の意味になり、目的語を示す働きがない。"}, "error_tags": {"と": "共同の格を誤る", "へ": "方向の格を誤る", "から": "起点の格を誤る"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "受ける", "is_correct": true, "explanation": "与える（相手に渡す）の対義語で、相手から受け取る意味。辞書で対義語として挙がる。"}, {"text": "守る", "is_correct": false, "explanation": "大切に保つ意味で、渡すことの反対語ではない。"}, {"text": "壊す", "is_correct": false, "explanation": "形をなくす意味で、与える行為の対義語ではない。"}, {"text": "集める", "is_correct": false, "explanation": "一か所に寄せる意味で、与える行為の対義語ではない。"}], "correct_answer": "受ける", "explanations": {"受ける": "与える（相手に渡す）の対義語で、相手から受け取る意味。辞書で対義語として挙がる。", "守る": "大切に保つ意味で、渡すことの反対語ではない。", "壊す": "形をなくす意味で、与える行為の対義語ではない。", "集める": "一か所に寄せる意味で、与える行為の対義語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c07d00d1-8048-4ad4-beac-311160b5c24e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35194, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "何かを誰かに渡すこと。", "primary_collocate": null, "pronunciation": "あたえる", "ipa": "a.ta.e.ɾɯ", "syllable_count": 4, "sentences": [{"text": "先生は生徒たちに宿題を与えた。", "target_word": "与えた", "complexity_tier": "T3", "furigana": "先生[せんせい]は生徒[せいと]たちに宿題[しゅくだい]を与[あた]えた。", "sentence_source": "generated"}, {"text": "毎朝、犬に餌を与えるのが私の仕事だ。", "target_word": "与える", "complexity_tier": "T3", "furigana": "毎朝[まいあさ]、犬[いぬ]に餌[えさ]を与[あた]えるのが私[わたし]の仕事[しごと]だ。", "sentence_source": "generated"}, {"text": "会社は新人に大きな仕事を与えて、成長を期待した。", "target_word": "与えて", "complexity_tier": "T3", "furigana": "会社[かいしゃ]は新人[しんじん]に大[おお]きな仕事[しごと]を与[あた]えて、成長[せいちょう]を期待[きたい]した。", "sentence_source": "generated"}, {"text": "子どもに十分な睡眠を与えないと、体に悪い影響が出る。", "target_word": "与えない", "complexity_tier": "T3", "furigana": "子[こ]どもに十分[じゅうぶん]な睡眠[すいみん]を与[あた]えないと、体[からだ]に悪[わる]い影響[えいきょう]が出[で]る。", "sentence_source": "generated"}, {"text": "彼の言葉は、私に勇気を与えてくれた。", "target_word": "与えて", "complexity_tier": "T3", "furigana": "彼[かれ]の言葉[ことば]は、私[わたし]に勇気[ゆうき]を与[あた]えてくれた。", "sentence_source": "generated"}, {"text": "審査員は最も優れた作品に金賞を与えた。", "target_word": "与えた", "complexity_tier": "T3", "furigana": "審査員[しんさいん]は最[もっと]も優[すぐ]れた作品[さくひん]に金賞[きんしょう]を与[あた]えた。", "sentence_source": "generated"}, {"text": "会社は社員に大きな裁量を与えている。", "target_word": "与えている", "complexity_tier": "T3", "furigana": "会社[かいしゃ]は社員[しゃいん]に大[おお]きな裁量[さいりょう]を与[あた]えている。", "sentence_source": "generated"}, {"text": "失敗した人にも、もう一度チャンスを与えるべきだ。", "target_word": "与える", "complexity_tier": "T3", "furigana": "失敗[しっぱい]した人[ひと]にも、もう一度[いちど]チャンスを与[あた]えるべきだ。", "sentence_source": "generated"}, {"text": "彼女の笑顔は周りの人に安心感を与える。", "target_word": "与える", "complexity_tier": "T3", "furigana": "彼女[かのじょ]の笑顔[えがお]は周[まわ]りの人[ひと]に安心感[あんしんかん]を与[あた]える。", "sentence_source": "generated"}, {"text": "親は子どもに愛情を与えながら育てる。", "target_word": "与えながら", "complexity_tier": "T3", "furigana": "親[おや]は子[こ]どもに愛情[あいじょう]を与[あた]えながら育[そだ]てる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "与える", "label": "辞書形"}, {"form": "与えない", "label": "否定形"}, {"form": "与えます", "label": "丁寧形"}, {"form": "与えた", "label": "過去形"}, {"form": "与えて", "label": "て形"}, {"form": "与えれば", "label": "仮定形"}, {"form": "与えよう", "label": "意向形"}, {"form": "与えられる", "label": "受身形"}], "register": "neutral", "sense_fingerprint": "人や動物に物・機会・影響などを渡す、授ける", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fd5ffa41-1131-4a11-8fcb-1ef942369fab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35194, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "与えた", "is_correct": true, "explanation": "過去形の終止形で、「宿題を与えた。」と文を正しく締めくくる。"}, {"text": "与えて", "is_correct": false, "explanation": "て形は文末に置けず、「宿題を与えて。」は文として途切れる。"}, {"text": "与えれば", "is_correct": false, "explanation": "仮定形は条件節を作るので、この位置では文が完結しない。"}, {"text": "与えず", "is_correct": false, "explanation": "打ち消しの連用形で、文末に置くと意味が途切れて文にならない。"}], "explanations": {"与えた": "過去形の終止形で、「宿題を与えた。」と文を正しく締めくくる。", "与えて": "て形は文末に置けず、「宿題を与えて。」は文として途切れる。", "与えれば": "仮定形は条件節を作るので、この位置では文が完結しない。", "与えず": "打ち消しの連用形で、文末に置くと意味が途切れて文にならない。"}, "sentence_index": 0, "correct_answer": "与えた"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "友人に自転車を一週間与えた。", "explanation": "ここは〈貸す〉の意味。与えるは物を相手のものにする意味なので、期限付きの貸し借りには合わない。"}, {"text": "彼は机の上にコップを与えた。", "explanation": "ここは〈置く〉の意味。与えるは受け手に渡す意味なので、物を場所に置くだけの動作には使わない。"}, {"text": "配達員は小包を家に与えた。", "explanation": "ここは〈届ける〉の意味。与えるは受け手が人や動物で、場所を受け手にはしないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c07d00d1-8048-4ad4-beac-311160b5c24e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35194, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "与えている", "is_correct": true, "explanation": "継続の形で、「裁量を与えている」と現在の状態を正しく述べる。"}, {"text": "与えよう", "is_correct": false, "explanation": "意向形は「会社は…与えよう。」と文末に置くと、意志を述べる文になり状態と合わない。"}, {"text": "与えれば", "is_correct": false, "explanation": "仮定形は条件節を作るので、文末に置くと文が完結しない。"}, {"text": "与え", "is_correct": false, "explanation": "連用形のままでは文末に置けず、文として途切れる。"}], "explanations": {"与えている": "継続の形で、「裁量を与えている」と現在の状態を正しく述べる。", "与えよう": "意向形は「会社は…与えよう。」と文末に置くと、意志を述べる文になり状態と合わない。", "与えれば": "仮定形は条件節を作るので、文末に置くと文が完結しない。", "与え": "連用形のままでは文末に置けず、文として途切れる。"}, "sentence_index": 6, "correct_answer": "与えている"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "親は子どもを祖母に与えながら、仕事に出た。", "explanation": "ここは〈預ける〉の意味。与えるは人を一時的に預ける意味では使わないので合わない。"}, {"text": "親は子どもの努力を与えながら育てる。", "explanation": "ここは〈認める〉の意味。与えるは努力を評価する意味では使わないので不自然になる。"}, {"text": "親は子どもに雨を与えながら育てる。", "explanation": "ここは〈降らせる〉の意味。与えるは物や感情を相手に渡す意味で、天候を人に向けては使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c07d00d1-8048-4ad4-beac-311160b5c24e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35194, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "母は弟に小遣いが与えた。", "corrected_sentence": "母は弟に小遣いを与えた。", "error_description": "与えるの目的語（小遣い）には「を」を付ける。「が」は誤りで、正しくは「を」。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "与える", "is_correct": true, "explanation": "辞書形で、「のが私の仕事だ」の前に名詞として続く正しい形。"}, {"text": "与えて", "is_correct": false, "explanation": "て形は「のが」の前に続かず、名詞句として成立しない。"}, {"text": "与えれば", "is_correct": false, "explanation": "仮定形は「のが」に続けられず、文の骨組みが崩れる。"}, {"text": "与えよう", "is_correct": false, "explanation": "意向形は「のが」に続かず、意志の表現が文の主語句に合わない。"}], "correct_form": "与える", "base_form": "与える", "form_label": "辞書形", "sentence_index": 1, "explanations": {"与える": "辞書形で、「のが私の仕事だ」の前に名詞として続く正しい形。", "与えて": "て形は「のが」の前に続かず、名詞句として成立しない。", "与えれば": "仮定形は「のが」に続けられず、文の骨組みが崩れる。", "与えよう": "意向形は「のが」に続かず、意志の表現が文の主語句に合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c07d00d1-8048-4ad4-beac-311160b5c24e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35194, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "父は娘に新しい自転車を与えらた。", "corrected_sentence": "父は娘に新しい自転車を与えた。", "error_description": "与えるの過去形は「与えた」。「与えらた」は語形が誤り（「ら」が余分）。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "与える", "is_correct": true, "explanation": "辞書形で、「チャンスを与えるべきだ」と助動詞に続く正しい形。"}, {"text": "与えた", "is_correct": false, "explanation": "過去形は「べきだ」に続けられず、文法的に成立しない。"}, {"text": "与えます", "is_correct": false, "explanation": "丁寧形は「べきだ」に続けられず、文体も普通体と合わない。"}, {"text": "与えられる", "is_correct": false, "explanation": "受身・可能の形は「チャンスを」の「を」と合わず、文の構造が崩れる。"}], "correct_form": "与える", "base_form": "与える", "form_label": "辞書形", "sentence_index": 7, "explanations": {"与える": "辞書形で、「チャンスを与えるべきだ」と助動詞に続く正しい形。", "与えた": "過去形は「べきだ」に続けられず、文法的に成立しない。", "与えます": "丁寧形は「べきだ」に続けられず、文体も普通体と合わない。", "与えられる": "受身・可能の形は「チャンスを」の「を」と合わず、文の構造が崩れる。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c07d00d1-8048-4ad4-beac-311160b5c24e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35198, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「人類の歴史」と名詞をつなぐ連体修飾の「の」。"}, {"text": "が", "is_correct": false, "explanation": "「人類が歴史は」と主語にしても文が成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "「人類に歴史は」と相手を示す形では文の意味が通らない。"}, {"text": "へ", "is_correct": false, "explanation": "「人類へ歴史は」と方向を示す形では文の意味が通らない。"}], "correct_answer": "の", "explanations": {"の": "「人類の歴史」と名詞をつなぐ連体修飾の「の」。", "が": "「人類が歴史は」と主語にしても文が成り立たない。", "に": "「人類に歴史は」と相手を示す形では文の意味が通らない。", "へ": "「人類へ歴史は」と方向を示す形では文の意味が通らない。"}, "error_tags": {"が": "主語", "に": "相手", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ed848d40-3489-4681-91c1-79fe346d2be0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35198, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「人類の進化」と名詞をつなぐ連体修飾の「の」。"}, {"text": "で", "is_correct": false, "explanation": "「人類で進化について学べる」は手段の意味になり、文が通らない。"}, {"text": "と", "is_correct": false, "explanation": "「人類と進化について学べる」は一緒に学ぶ相手の意味になり、内容が合わない。"}, {"text": "へ", "is_correct": false, "explanation": "「人類へ進化について学べる」は方向の意味になり、学ぶ相手として成り立たない。"}], "correct_answer": "の", "explanations": {"の": "「人類の進化」と名詞をつなぐ連体修飾の「の」。", "で": "「人類で進化について学べる」は手段の意味になり、文が通らない。", "と": "「人類と進化について学べる」は一緒に学ぶ相手の意味になり、内容が合わない。", "へ": "「人類へ進化について学べる」は方向の意味になり、学ぶ相手として成り立たない。"}, "error_tags": {"で": "手段", "と": "共同の相手", "へ": "方向"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ed848d40-3489-4681-91c1-79fe346d2be0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35198, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "世界中のすべての人のことです。", "primary_collocate": null, "pronunciation": "じんるい", "ipa": "dʑiɴɾɯi", "syllable_count": 4, "sentences": [{"text": "人類は長い間、火を使って暮らしてきた。", "target_word": "人類", "complexity_tier": "T3", "furigana": "人類(じんるい)は長(なが)い間(あいだ)、火(ひ)を使(つか)って暮(く)らしてきた。", "sentence_source": "generated"}, {"text": "人類の歴史は、数百万年前に始まったと言われる。", "target_word": "人類", "complexity_tier": "T3", "furigana": "人類(じんるい)の歴史(れきし)は、数百万年前(すうひゃくまんねんまえ)に始(はじ)まったと言(い)われる。", "sentence_source": "generated"}, {"text": "地球の環境を守ることは、人類全体の課題だ。", "target_word": "人類", "complexity_tier": "T3", "furigana": "地球(ちきゅう)の環境(かんきょう)を守(まも)ることは、人類(じんるい)全体(ぜんたい)の課題(かだい)だ。", "sentence_source": "generated"}, {"text": "人類が初めて月に降りたのは、五十年以上前だ。", "target_word": "人類", "complexity_tier": "T3", "furigana": "人類(じんるい)が初(はじ)めて月(つき)に降(お)りたのは、五十年以上前(ごじゅうねんいじょうまえ)だ。", "sentence_source": "generated"}, {"text": "医学の進歩は、人類の寿命を大きく延ばした。", "target_word": "人類", "complexity_tier": "T3", "furigana": "医学(いがく)の進歩(しんぽ)は、人類(じんるい)の寿命(じゅみょう)を大(おお)きく延(の)ばした。", "sentence_source": "generated"}, {"text": "新しい病気は、人類にとって大きな脅威になる。", "target_word": "人類", "complexity_tier": "T3", "furigana": "新(あたら)しい病気(びょうき)は、人類(じんるい)にとって大(おお)きな脅威(きょうい)になる。", "sentence_source": "generated"}, {"text": "人類は言葉を使って、知識を次の世代に伝えてきた。", "target_word": "人類", "complexity_tier": "T3", "furigana": "人類(じんるい)は言葉(ことば)を使(つか)って、知識(ちしき)を次(つぎ)の世代(せだい)に伝(つた)えてきた。", "sentence_source": "generated"}, {"text": "この博物館では、人類の進化について学べる。", "target_word": "人類", "complexity_tier": "T3", "furigana": "この博物館(はくぶつかん)では、人類(じんるい)の進化(しんか)について学(まな)べる。", "sentence_source": "generated"}, {"text": "戦争のない世界は、人類の長年の願いだ。", "target_word": "人類", "complexity_tier": "T3", "furigana": "戦争(せんそう)のない世界(せかい)は、人類(じんるい)の長年(ながねん)の願(ねが)いだ。", "sentence_source": "generated"}, {"text": "宇宙へ行く技術は、人類の夢をかなえつつある。", "target_word": "人類", "complexity_tier": "T3", "furigana": "宇宙(うちゅう)へ行(い)く技術(ぎじゅつ)は、人類(じんるい)の夢(ゆめ)をかなえつつある。", "sentence_source": "generated"}], "morphological_forms": [{"form": "人類", "label": "基本形"}, {"form": "人類の", "label": "の格"}, {"form": "人類は", "label": "主題"}], "register": "標準（普通体）", "sense_fingerprint": "人類（名詞）：地球上の人間全体を一つの集団として指す語", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '947d9c0d-20b2-4311-9f05-a20f8a6414f0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35198, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "人類", "is_correct": true, "explanation": "世界中の人間全体を指す主語で、火を使って暮らしてきた集団として合う。"}, {"text": "電車", "is_correct": false, "explanation": "乗り物の名前で、火を使って暮らしてきた主語にはならないので合わない。"}, {"text": "天気", "is_correct": false, "explanation": "気象の状態を表し、暮らしてきた主体にはならないので合わない。"}, {"text": "机", "is_correct": false, "explanation": "家具で、火を使って暮らすことはできないので合わない。"}], "explanations": {"人類": "世界中の人間全体を指す主語で、火を使って暮らしてきた集団として合う。", "電車": "乗り物の名前で、火を使って暮らしてきた主語にはならないので合わない。", "天気": "気象の状態を表し、暮らしてきた主体にはならないので合わない。", "机": "家具で、火を使って暮らすことはできないので合わない。"}, "sentence_index": 0, "correct_answer": "人類"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "教室には人類が三十人いる。", "explanation": "ここは〈人間〉（個々の人）の意味。人類は地球上の人間全体を一つの集団として指す語なので、人数を数える文には合わない。"}, {"text": "アフリカに住む人類と、北欧に住む人類では、肌の色が違う。", "explanation": "ここは〈人種〉の意味。人類は全人間を指し、地域や肌の色で分けた集団は指せないので合わない。"}, {"text": "この町の人類は、十万人を超えている。", "explanation": "ここは〈人口〉の意味。人類は地球全体の人間を指すので、町の人数を表すには使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ed848d40-3489-4681-91c1-79fe346d2be0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35198, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "人類", "is_correct": true, "explanation": "言葉を使って知識を次の世代に伝えてきた主語として合う。"}, {"text": "冷蔵庫", "is_correct": false, "explanation": "家電で、言葉を使って知識を伝えてきた主体にはならないので合わない。"}, {"text": "靴下", "is_correct": false, "explanation": "衣類で、知識を伝えてきた主語にはならないので合わない。"}, {"text": "窓", "is_correct": false, "explanation": "建具で、言葉を使って知識を伝えることはできないので合わない。"}], "explanations": {"人類": "言葉を使って知識を次の世代に伝えてきた主語として合う。", "冷蔵庫": "家電で、言葉を使って知識を伝えてきた主体にはならないので合わない。", "靴下": "衣類で、知識を伝えてきた主語にはならないので合わない。", "窓": "建具で、言葉を使って知識を伝えることはできないので合わない。"}, "sentence_index": 6, "correct_answer": "人類"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "ペンギンの人類は、南極の氷の上で群れを作って暮らしている。", "explanation": "ここは〈動物の種〉の意味。人類は人間だけを指す語なので、ペンギンには使わない。"}, {"text": "町の人類が、祭りのために広場に集まった。", "explanation": "ここは〈住民〉の意味。人類は地球上の全人間を指すので、一つの町の人々には使わない。"}, {"text": "あの人類は、いつも一番に会議室に来ている。", "explanation": "ここは〈個人〉を指す「人」の意味。人類は集団全体を指すので、一人の人には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ed848d40-3489-4681-91c1-79fe346d2be0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35198, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "その発見は、人類を新しい希望を与えた。", "corrected_sentence": "その発見は、人類に新しい希望を与えた。", "error_description": "「を」が二つ続いていて文が成り立たない。「与える」の相手は「に」で示すので、「人類に」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ed848d40-3489-4681-91c1-79fe346d2be0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35198, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "人類を、地球の気候の変化に直面している。", "corrected_sentence": "人類は、地球の気候の変化に直面している。", "error_description": "「直面している」の主語は「は」で示す。「を」にすると主語が示されず、文が成り立たない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ed848d40-3489-4681-91c1-79fe346d2be0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35200, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "齎すの目的語「被害」を示す格助詞で、直前に置く正しい助詞。"}, {"text": "に", "is_correct": false, "explanation": "「被害に齎した」は目的語の格を誤り、「に」は与える相手を示すので合わない。"}, {"text": "で", "is_correct": false, "explanation": "「被害で齎した」は手段の意味になり、目的語を示せない。"}, {"text": "へ", "is_correct": false, "explanation": "「被害へ齎した」は方向の意味になり、結果を生むという意味と合わない。"}], "correct_answer": "を", "explanations": {"を": "齎すの目的語「被害」を示す格助詞で、直前に置く正しい助詞。", "に": "「被害に齎した」は目的語の格を誤り、「に」は与える相手を示すので合わない。", "で": "「被害で齎した」は手段の意味になり、目的語を示せない。", "へ": "「被害へ齎した」は方向の意味になり、結果を生むという意味と合わない。"}, "error_tags": {"に": "目的語の格を誤る", "で": "手段の格を誤る", "へ": "方向の格を誤る"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c07d00d1-8048-4ad4-beac-311160b5c24e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35200, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "齎すの目的語「便利さ」を示す格助詞で、直前に置く正しい助詞。"}, {"text": "が", "is_correct": false, "explanation": "「便利さが齎した」は便利さを主語にしてしまい、もたらす主体がなくなって合わない。"}, {"text": "の", "is_correct": false, "explanation": "「便利さの齎した」は連体修飾の形が崩れ、動詞が述語として機能しない。"}, {"text": "から", "is_correct": false, "explanation": "「便利さから齎した」は起点の意味になり、目的語を示せない。"}], "correct_answer": "を", "explanations": {"を": "齎すの目的語「便利さ」を示す格助詞で、直前に置く正しい助詞。", "が": "「便利さが齎した」は便利さを主語にしてしまい、もたらす主体がなくなって合わない。", "の": "「便利さの齎した」は連体修飾の形が崩れ、動詞が述語として機能しない。", "から": "「便利さから齎した」は起点の意味になり、目的語を示せない。"}, "error_tags": {"が": "主語の格を誤る", "の": "連体修飾の助詞を誤る", "から": "起点の格を誤る"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c07d00d1-8048-4ad4-beac-311160b5c24e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35200, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "何かを持って来て、与えること。", "primary_collocate": null, "pronunciation": "もたらす", "ipa": "mo.ta.ɾa.sɯ", "syllable_count": 4, "sentences": [{"text": "新しい技術は、私たちの生活に大きな変化を齎した。", "target_word": "齎した", "complexity_tier": "T3", "furigana": "新[あたら]しい技術[ぎじゅつ]は、私[わたし]たちの生活[せいかつ]に大[おお]きな変化[へんか]を齎[もたら]した。", "sentence_source": "generated"}, {"text": "長く続いた雨は、農家に深刻な被害を齎した。", "target_word": "齎した", "complexity_tier": "T3", "furigana": "長[なが]く続[つづ]いた雨[あめ]は、農家[のうか]に深刻[しんこく]な被害[ひがい]を齎[もたら]した。", "sentence_source": "generated"}, {"text": "この薬の発見は、多くの患者に希望を齎した。", "target_word": "齎した", "complexity_tier": "T3", "furigana": "この薬[くすり]の発見[はっけん]は、多[おお]くの患者[かんじゃ]に希望[きぼう]を齎[もたら]した。", "sentence_source": "generated"}, {"text": "春の訪れは、町に明るい空気を齎す。", "target_word": "齎す", "complexity_tier": "T3", "furigana": "春[はる]の訪[おとず]れは、町[まち]に明[あか]るい空気[くうき]を齎[もたら]す。", "sentence_source": "generated"}, {"text": "景気の回復が、会社に大きな利益を齎した。", "target_word": "齎した", "complexity_tier": "T3", "furigana": "景気[けいき]の回復[かいふく]が、会社[かいしゃ]に大[おお]きな利益[りえき]を齎[もたら]した。", "sentence_source": "generated"}, {"text": "戦争は人々に悲しみしか齎さない。", "target_word": "齎さない", "complexity_tier": "T3", "furigana": "戦争[せんそう]は人々[ひとびと]に悲[かな]しみしか齎[もたら]さない。", "sentence_source": "generated"}, {"text": "彼の一言が、会議に思わぬ転機を齎した。", "target_word": "齎した", "complexity_tier": "T3", "furigana": "彼[かれ]の一言[ひとこと]が、会議[かいぎ]に思[おも]わぬ転機[てんき]を齎[もたら]した。", "sentence_source": "generated"}, {"text": "インターネットは私たちに便利さを齎した。", "target_word": "齎した", "complexity_tier": "T3", "furigana": "インターネットは私[わたし]たちに便利[べんり]さを齎[もたら]した。", "sentence_source": "generated"}, {"text": "台風は大雨だけでなく、強い風も齎す。", "target_word": "齎す", "complexity_tier": "T3", "furigana": "台風[たいふう]は大雨[おおあめ]だけでなく、強[つよ]い風[かぜ]も齎[もたら]す。", "sentence_source": "generated"}, {"text": "川の洪水は、畑に豊かな土を齎すこともある。", "target_word": "齎す", "complexity_tier": "T3", "furigana": "川[かわ]の洪水[こうずい]は、畑[はたけ]に豊[ゆた]かな土[つち]を齎[もたら]すこともある。", "sentence_source": "generated"}], "morphological_forms": [{"form": "齎す", "label": "辞書形"}, {"form": "齎さない", "label": "否定形"}, {"form": "齎します", "label": "丁寧形"}, {"form": "齎した", "label": "過去形"}, {"form": "齎して", "label": "て形"}, {"form": "齎せば", "label": "仮定形"}, {"form": "齎そう", "label": "意向形"}, {"form": "齎される", "label": "受身形"}], "register": "formal", "sense_fingerprint": "結果として変化・利益・被害などを持ち込み、引き起こす", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fd5ffa41-1131-4a11-8fcb-1ef942369fab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35200, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "齎した", "is_correct": true, "explanation": "過去形の終止形で、「大きな変化を齎した。」と文を締める正しい形。"}, {"text": "齎して", "is_correct": false, "explanation": "て形は文末に置けず、「変化を齎して。」は文として途切れる。"}, {"text": "齎せば", "is_correct": false, "explanation": "仮定形は条件節を作るので、この位置では文が完結しない。"}, {"text": "齎さず", "is_correct": false, "explanation": "打ち消しの連用形で、文末に置くと意味が途切れて文にならない。"}], "explanations": {"齎した": "過去形の終止形で、「大きな変化を齎した。」と文を締める正しい形。", "齎して": "て形は文末に置けず、「変化を齎して。」は文として途切れる。", "齎せば": "仮定形は条件節を作るので、この位置では文が完結しない。", "齎さず": "打ち消しの連用形で、文末に置くと意味が途切れて文にならない。"}, "sentence_index": 0, "correct_answer": "齎した"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "強盗は店から現金を齎して逃げた。", "explanation": "ここは〈奪う〉の意味。齎すは持って来て与える、または結果を生む意味なので、人から物を取る意味では使わない。"}, {"text": "私は店で新しい服を齎した。", "explanation": "ここは〈手に入れる〉の意味。齎すは結果を生む意味で、物を手に入れる意味では使わない。"}, {"text": "彼女は夕方の空を齎した。", "explanation": "ここは〈見上げる〉の意味。齎すは物を持って来る・結果を生む意味で、景色を見る動作には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c07d00d1-8048-4ad4-beac-311160b5c24e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35200, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "齎した", "is_correct": true, "explanation": "過去形の終止形で、「転機を齎した。」と文を正しく締める。"}, {"text": "齎せ", "is_correct": false, "explanation": "命令形は「転機を齎せ。」と命令の文になり、過去の出来事を述べる文と合わない。"}, {"text": "齎そう", "is_correct": false, "explanation": "意向の形は意志を表し、過去の出来事を述べる文には合わない。"}, {"text": "齎される", "is_correct": false, "explanation": "受身形は「転機を」の目的語と合わず、文が成立しない。"}], "explanations": {"齎した": "過去形の終止形で、「転機を齎した。」と文を正しく締める。", "齎せ": "命令形は「転機を齎せ。」と命令の文になり、過去の出来事を述べる文と合わない。", "齎そう": "意向の形は意志を表し、過去の出来事を述べる文には合わない。", "齎される": "受身形は「転機を」の目的語と合わず、文が成立しない。"}, "sentence_index": 6, "correct_answer": "齎した"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は会議で大切な意見を齎して、すぐに消した。", "explanation": "ここは〈消す〉の意味。齎すは結果を生む意味で、言葉を取り消す意味では使わない。"}, {"text": "彼女は大事な鍵を齎して、どこかに置き忘れた。", "explanation": "ここは〈なくす〉の意味。齎すは持って来て与える、または結果を生む意味で、物を失う意味では使わない。"}, {"text": "母は夕食の材料を齎して、冷蔵庫の奥に隠した。", "explanation": "ここは〈隠す〉の意味。齎すは持って来て与える、または結果を生む意味で、人目から物を隠す意味では使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c07d00d1-8048-4ad4-beac-311160b5c24e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35200, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "大雨は農地に深刻な被害に齎した。", "corrected_sentence": "大雨は農地に深刻な被害を齎した。", "error_description": "齎すの目的語（被害）には「を」を付ける。「に」は誤りで、正しくは「を」。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "齎した", "is_correct": true, "explanation": "過去形で、雨が被害を生んだという過去の出来事を正しく表す。"}, {"text": "齎して", "is_correct": false, "explanation": "て形は文末に置けず、「被害を齎して。」は文として途切れる。"}, {"text": "齎せば", "is_correct": false, "explanation": "仮定形は条件節を作るので、過去の出来事を述べる文には合わない。"}, {"text": "齎される", "is_correct": false, "explanation": "受身形は「被害を」の目的語と合わず、主語が被害を受ける形になって文が崩れる。"}], "correct_form": "齎した", "base_form": "齎す", "form_label": "過去形", "sentence_index": 1, "explanations": {"齎した": "過去形で、雨が被害を生んだという過去の出来事を正しく表す。", "齎して": "て形は文末に置けず、「被害を齎して。」は文として途切れる。", "齎せば": "仮定形は条件節を作るので、過去の出来事を述べる文には合わない。", "齎される": "受身形は「被害を」の目的語と合わず、主語が被害を受ける形になって文が崩れる。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c07d00d1-8048-4ad4-beac-311160b5c24e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35200, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "大雨は川の水位を上げ、洪水を齎しした。", "corrected_sentence": "大雨は川の水位を上げ、洪水を齎した。", "error_description": "齎すの過去形は「齎した」。「齎しした」は連用形に「した」が続く語形の誤り（「し」が余分）。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "齎した", "is_correct": true, "explanation": "過去形で、インターネットが便利さをもたらしたという過去の出来事を正しく表す。"}, {"text": "齎そう", "is_correct": false, "explanation": "意向形は意志を表し、過去の出来事を述べる文には合わない。"}, {"text": "齎します", "is_correct": false, "explanation": "丁寧形は普通体の文に合わず、文体が合わない。"}, {"text": "齎さない", "is_correct": false, "explanation": "否定の現在形で、もたらさなかったという過去の出来事とは時制も意味も合わない。"}], "correct_form": "齎した", "base_form": "齎す", "form_label": "過去形", "sentence_index": 7, "explanations": {"齎した": "過去形で、インターネットが便利さをもたらしたという過去の出来事を正しく表す。", "齎そう": "意向形は意志を表し、過去の出来事を述べる文には合わない。", "齎します": "丁寧形は普通体の文に合わず、文体が合わない。", "齎さない": "否定の現在形で、もたらさなかったという過去の出来事とは時制も意味も合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c07d00d1-8048-4ad4-beac-311160b5c24e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35202, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「人生の変革を決意し」は、変革が「決意する」の目的語になる正しい助詞。"}, {"text": "に", "is_correct": false, "explanation": "「人生の変革に決意し」は、決意の対象を示す助詞として不自然。"}, {"text": "で", "is_correct": false, "explanation": "「人生の変革で決意し」は手段の意味になり、決意の対象を示せない。"}, {"text": "が", "is_correct": false, "explanation": "「人生の変革が決意し」は変革を主語にしてしまい、文が成り立たない。"}], "correct_answer": "を", "explanations": {"を": "「人生の変革を決意し」は、変革が「決意する」の目的語になる正しい助詞。", "に": "「人生の変革に決意し」は、決意の対象を示す助詞として不自然。", "で": "「人生の変革で決意し」は手段の意味になり、決意の対象を示せない。", "が": "「人生の変革が決意し」は変革を主語にしてしまい、文が成り立たない。"}, "error_tags": {"に": "相手", "で": "手段", "が": "主語"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '871fac38-b929-4ac1-b557-568e2dd37cac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35202, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「静かな変革をもたらした」は、変革が「もたらす」の目的語になる正しい助詞。"}, {"text": "の", "is_correct": false, "explanation": "「静かな変革の、もたらした」は連体の「の」になり、動詞の目的語を示せず文が成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「変革へもたらした」は方向を表し、もたらす対象として不自然。"}, {"text": "と", "is_correct": false, "explanation": "「変革ともたらした」は並列にならず、文が不自然。"}], "correct_answer": "を", "explanations": {"を": "「静かな変革をもたらした」は、変革が「もたらす」の目的語になる正しい助詞。", "の": "「静かな変革の、もたらした」は連体の「の」になり、動詞の目的語を示せず文が成り立たない。", "へ": "「変革へもたらした」は方向を表し、もたらす対象として不自然。", "と": "「変革ともたらした」は並列にならず、文が不自然。"}, "error_tags": {"の": "連体", "へ": "方向", "と": "並列"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '871fac38-b929-4ac1-b557-568e2dd37cac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35202, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "何かを、前とはまったくちがうものに変えること。", "primary_collocate": null, "pronunciation": "へんかく", "ipa": "heŋkaku", "syllable_count": 4, "sentences": [{"text": "町の暮らしは、鉄道の開通によって大きな変革を迎えた。", "target_word": "変革", "complexity_tier": "T3", "furigana": "町[まち]の暮[く]らしは、鉄道[てつどう]の開通[かいつう]によって大[おお]きな変革[へんかく]を迎[むか]えた。", "sentence_source": "generated"}, {"text": "彼は人生の変革を決意し、会社を辞めて農業を始めた。", "target_word": "変革", "complexity_tier": "T3", "furigana": "彼[かれ]は人生[じんせい]の変革[へんかく]を決意[けつい]し、会社[かいしゃ]を辞[や]めて農業[のうぎょう]を始[はじ]めた。", "sentence_source": "generated"}, {"text": "店の変革が成功して、客の数が二倍になった。", "target_word": "変革", "complexity_tier": "T3", "furigana": "店[みせ]の変革[へんかく]が成功[せいこう]して、客[きゃく]の数[かず]が二倍[にばい]になった。", "sentence_source": "generated"}, {"text": "古い建物を図書館にする変革は、町の人に歓迎された。", "target_word": "変革", "complexity_tier": "T3", "furigana": "古[ふる]い建物[たてもの]を図書館[としょかん]にする変革[へんかく]は、町[まち]の人[ひと]に歓迎[かんげい]された。", "sentence_source": "generated"}, {"text": "この国は、百年前に大きな変革を経験した。", "target_word": "変革", "complexity_tier": "T3", "furigana": "この国[くに]は、百年前[ひゃくねんまえ]に大[おお]きな変革[へんかく]を経験[けいけん]した。", "sentence_source": "generated"}, {"text": "変革のためには、まず今のやり方を知る必要がある。", "target_word": "変革", "complexity_tier": "T3", "furigana": "変革[へんかく]のためには、まず今[いま]のやり方[かた]を知[し]る必要[ひつよう]がある。", "sentence_source": "generated"}, {"text": "時代の変革についていけず、その工場は閉鎖された。", "target_word": "変革", "complexity_tier": "T3", "furigana": "時代[じだい]の変革[へんかく]についていけず、その工場[こうじょう]は閉鎖[へいさ]された。", "sentence_source": "generated"}, {"text": "彼女の発明は、台所仕事に静かな変革をもたらした。", "target_word": "変革", "complexity_tier": "T3", "furigana": "彼女[かのじょ]の発明[はつめい]は、台所[だいどころ]仕事[しごと]に静[しず]かな変革[へんかく]をもたらした。", "sentence_source": "generated"}, {"text": "小さな村にも、技術の変革の波は押し寄せている。", "target_word": "変革", "complexity_tier": "T3", "furigana": "小[ちい]さな村[むら]にも、技術[ぎじゅつ]の変革[へんかく]の波[なみ]は押[お]し寄[よ]せている。", "sentence_source": "generated"}, {"text": "彼の考え方には、留学をきっかけに大きな変革が起きた。", "target_word": "変革", "complexity_tier": "T3", "furigana": "彼[かれ]の考[かんが]え方[かた]には、留学[りゅうがく]をきっかけに大[おお]きな変革[へんかく]が起[お]きた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "変革", "label": "基本形（名詞）"}, {"form": "変革する", "label": "終止形"}, {"form": "変革した", "label": "過去形"}, {"form": "変革される", "label": "受身形"}], "register": "plain", "sense_fingerprint": "変革：何かを以前とはまったく違うものに変えること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '55b18bfd-21ad-4c83-b5d6-f22248d6b44f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35202, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "変革", "is_correct": true, "explanation": "「大きな変革を迎えた」は、鉄道の開通で暮らしが大きく変わったという意味に合う。"}, {"text": "解雇", "is_correct": false, "explanation": "「大きな解雇を迎えた」は意味が通らず、暮らしの変化の話と合わない。"}, {"text": "採寸", "is_correct": false, "explanation": "「大きな採寸を迎えた」は成り立たず、文脈に合わない。"}, {"text": "配膳", "is_correct": false, "explanation": "「大きな配膳を迎えた」は文の意味が通らない。"}], "explanations": {"変革": "「大きな変革を迎えた」は、鉄道の開通で暮らしが大きく変わったという意味に合う。", "解雇": "「大きな解雇を迎えた」は意味が通らず、暮らしの変化の話と合わない。", "採寸": "「大きな採寸を迎えた」は成り立たず、文脈に合わない。", "配膳": "「大きな配膳を迎えた」は文の意味が通らない。"}, "sentence_index": 0, "correct_answer": "変革"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "「来る」は変格活用の動詞だ。", "explanation": "ここは〈変格〉の意味。文法で不規則な活用を指す語で、何かを前とまったく違うものに変える〈変革〉とは違う。"}, {"text": "壊れた橋を変革した。", "explanation": "ここは〈修復〉の意味。壊れたものを元の状態に戻す語で、前とはまったく違うものに変える〈変革〉とは合わない。"}, {"text": "粘土の形が変革した。", "explanation": "ここは〈変形〉の意味。力を受けて形が崩れる場面に使う語で、何かを前とは違うものに変える〈変革〉とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '871fac38-b929-4ac1-b557-568e2dd37cac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35202, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "変革", "is_correct": true, "explanation": "「時代の変革についていけず」は、根本的な変化についていけないという意味に合う。"}, {"text": "発熱", "is_correct": false, "explanation": "「時代の発熱についていけず」は意味が通らず、文脈に合わない。"}, {"text": "散歩", "is_correct": false, "explanation": "「時代の散歩についていけず」は不自然で、工場の閉鎖と結びつかない。"}, {"text": "釣り", "is_correct": false, "explanation": "「時代の釣りについていけず」は文脈に合わず、意味をなさない。"}], "explanations": {"変革": "「時代の変革についていけず」は、根本的な変化についていけないという意味に合う。", "発熱": "「時代の発熱についていけず」は意味が通らず、文脈に合わない。", "散歩": "「時代の散歩についていけず」は不自然で、工場の閉鎖と結びつかない。", "釣り": "「時代の釣りについていけず」は文脈に合わず、意味をなさない。"}, "sentence_index": 6, "correct_answer": "変革"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "お金を電子マネーのポイントに変革する。", "explanation": "ここは〈換算〉の意味。単位を別の単位に置き換える語で、何かを根本から変える〈変革〉とは違う。"}, {"text": "壊れた時計を変革した。", "explanation": "ここは〈修理〉の意味。壊れた部品を直す語で、前とはまったく違うものに変える〈変革〉とは合わない。"}, {"text": "体温を変革した。", "explanation": "ここは〈測定〉の意味。体温は測って知るもので、前と違うものに変える〈変革〉とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '871fac38-b929-4ac1-b557-568e2dd37cac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35202, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼女は生活を変革を望んで、故郷を離れた。", "corrected_sentence": "彼女は生活の変革を望んで、故郷を離れた。", "error_description": "「生活の変革」と連体修飾の「の」を使うのが正しい。「を」を入れると二重になり誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '871fac38-b929-4ac1-b557-568e2dd37cac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35202, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "その国は、戦争を機に大きな変革を見失った。", "corrected_sentence": "その国は、戦争を機に大きな変革を遂げた。", "error_description": "「変革を遂げる」が正しい。「見失う」は変革と結びつかず、不自然な組み合わせ。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '871fac38-b929-4ac1-b557-568e2dd37cac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35203, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「大きな変革をもたらした」は、変革が「もたらす」の目的語になる正しい助詞。"}, {"text": "に", "is_correct": false, "explanation": "「大きな変革にもたらした」は目的語の形にならず、不自然。"}, {"text": "で", "is_correct": false, "explanation": "「大きな変革でもたらした」は手段の意味になり、文が不自然。"}, {"text": "から", "is_correct": false, "explanation": "「大きな変革からもたらした」は起点の意味になり、文が成り立たない。"}], "correct_answer": "を", "explanations": {"を": "「大きな変革をもたらした」は、変革が「もたらす」の目的語になる正しい助詞。", "に": "「大きな変革にもたらした」は目的語の形にならず、不自然。", "で": "「大きな変革でもたらした」は手段の意味になり、文が不自然。", "から": "「大きな変革からもたらした」は起点の意味になり、文が成り立たない。"}, "error_tags": {"に": "相手", "で": "手段", "から": "起点"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '871fac38-b929-4ac1-b557-568e2dd37cac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35203, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「政治の変革」は、政治を対象とする変革を表す連体修飾の正しい助詞。"}, {"text": "を", "is_correct": false, "explanation": "「政治を変革を求めて」は助詞「を」が二つ重なり、誤り。"}, {"text": "へ", "is_correct": false, "explanation": "「政治へ変革を求めて」は方向を表し、変革の対象を示せず不自然。"}, {"text": "と", "is_correct": false, "explanation": "「政治と変革を求めて」は並列になり、目的がぼやけて文が不自然。"}], "correct_answer": "の", "explanations": {"の": "「政治の変革」は、政治を対象とする変革を表す連体修飾の正しい助詞。", "を": "「政治を変革を求めて」は助詞「を」が二つ重なり、誤り。", "へ": "「政治へ変革を求めて」は方向を表し、変革の対象を示せず不自然。", "と": "「政治と変革を求めて」は並列になり、目的がぼやけて文が不自然。"}, "error_tags": {"を": "目的語の重複", "へ": "方向", "と": "並列"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '871fac38-b929-4ac1-b557-568e2dd37cac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35203, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "社会や制度、物事のあり方を根本的に変えること。改革。", "primary_collocate": null, "pronunciation": "へんかく", "ipa": "heŋkaku", "syllable_count": 4, "sentences": [{"text": "資金のみならず、経営の知見や人的ネットワークが注入されることで、個々の企業の成長が触発され、結果として社会実装を加速させ、ひいては経済構造の変革を促す強力な原動力となるのだ。", "target_word": "変革", "complexity_tier": "T4", "furigana": "資金[しきん]のみならず、経営[けいえい]の知見[ちけん]や人的[じんてき]ネットワークが注入[ちゅうにゅう]されることで、個々[ここ]の企業[きぎょう]の成長[せいちょう]が触発[しょくはつ]され、結果[けっか]として社会[しゃかい]実装[じっそう]を加速[かそく]させ、ひいては経済[けいざい]構造[こうぞう]の変革[へんかく]を促[うなが]す強力[きょうりょく]な原動力[げんどうりょく]となるのだ。", "sentence_source": "mined"}, {"text": "産業革命は、人々の働き方と暮らしに大きな変革をもたらした。", "target_word": "変革", "complexity_tier": "T3", "furigana": "産業[さんぎょう]革命[かくめい]は、人々[ひとびと]の働[はたら]き方[かた]と暮[く]らしに大[おお]きな変革[へんかく]をもたらした。", "sentence_source": "generated"}, {"text": "会社は古い仕組みを見直し、組織の変革に取り組んでいる。", "target_word": "変革", "complexity_tier": "T3", "furigana": "会社[かいしゃ]は古[ふる]い仕組[しく]みを見直[みなお]し、組織[そしき]の変革[へんかく]に取[と]り組[く]んでいる。", "sentence_source": "generated"}, {"text": "新しい法律は、社会の仕組みを大きく変革する力をもつ。", "target_word": "変革", "complexity_tier": "T3", "furigana": "新[あたら]しい法律[ほうりつ]は、社会[しゃかい]の仕組[しく]みを大[おお]きく変革[へんかく]する力[ちから]をもつ。", "sentence_source": "generated"}, {"text": "市長は、教育制度の変革を公約に掲げて当選した。", "target_word": "変革", "complexity_tier": "T3", "furigana": "市長[しちょう]は、教育[きょういく]制度[せいど]の変革[へんかく]を公約[こうやく]に掲[かか]げて当選[とうせん]した。", "sentence_source": "generated"}, {"text": "インターネットの普及は、社会に急速な変革を起こした。", "target_word": "変革", "complexity_tier": "T3", "furigana": "インターネットの普及[ふきゅう]は、社会[しゃかい]に急速[きゅうそく]な変革[へんかく]を起[お]こした。", "sentence_source": "generated"}, {"text": "変革を恐れていては、企業は長く生き残れない。", "target_word": "変革", "complexity_tier": "T3", "furigana": "変革[へんかく]を恐[おそ]れていては、企業[きぎょう]は長[なが]く生[い]き残[のこ]れない。", "sentence_source": "generated"}, {"text": "彼らは政治の変革を求めて、町で署名を集めた。", "target_word": "変革", "complexity_tier": "T3", "furigana": "彼[かれ]らは政治[せいじ]の変革[へんかく]を求[もと]めて、町[まち]で署名[しょめい]を集[あつ]めた。", "sentence_source": "generated"}, {"text": "国全体の変革には、時間と多くの人の協力が必要だ。", "target_word": "変革", "complexity_tier": "T3", "furigana": "国[くに]全体[ぜんたい]の変革[へんかく]には、時間[じかん]と多[おお]くの人[ひと]の協力[きょうりょく]が必要[ひつよう]だ。", "sentence_source": "generated"}, {"text": "経営陣は思い切った変革を決断し、古い部署をすべて作り直した。", "target_word": "変革", "complexity_tier": "T3", "furigana": "経営陣[けいえいじん]は思[おも]い切[き]った変革[へんかく]を決断[けつだん]し、古[ふる]い部署[ぶしょ]をすべて作[つく]り直[なお]した。", "sentence_source": "generated"}], "morphological_forms": [{"form": "変革", "label": "基本形（名詞）"}, {"form": "変革する", "label": "終止形"}, {"form": "変革した", "label": "過去形"}, {"form": "変革される", "label": "受身形"}], "register": "formal", "sense_fingerprint": "変革：社会や制度などのあり方を根本から変えること（改革）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '55b18bfd-21ad-4c83-b5d6-f22248d6b44f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35203, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "変革", "is_correct": true, "explanation": "「経済構造の変革を促す」は、制度や仕組みを根本から変えることを促す意味に合う。"}, {"text": "包装", "is_correct": false, "explanation": "「経済構造の包装を促す」は意味が通らず、文脈に合わない。"}, {"text": "採掘", "is_correct": false, "explanation": "「経済構造の採掘を促す」は成り立たず、文の意味が通らない。"}, {"text": "翻訳", "is_correct": false, "explanation": "「経済構造の翻訳を促す」は文脈に合わず、意味をなさない。"}], "explanations": {"変革": "「経済構造の変革を促す」は、制度や仕組みを根本から変えることを促す意味に合う。", "包装": "「経済構造の包装を促す」は意味が通らず、文脈に合わない。", "採掘": "「経済構造の採掘を促す」は成り立たず、文の意味が通らない。", "翻訳": "「経済構造の翻訳を促す」は文脈に合わず、意味をなさない。"}, "sentence_index": 0, "correct_answer": "変革"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "「来る」は変格活用の動詞だ。", "explanation": "ここは〈変格〉の意味。文法で不規則な活用を指す語で、社会や制度を根本から変える〈変革〉とは違う。"}, {"text": "古い橋を変革する工事が始まった。", "explanation": "ここは〈改修〉の意味。部分的に直す工事を指す語で、制度を根本から変える〈変革〉とは合わない。"}, {"text": "来週の会議の日程を変革した。", "explanation": "ここは〈変更〉の意味。小さな調整で足りる場面に使い、社会や制度を根本から変えることは表さない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '871fac38-b929-4ac1-b557-568e2dd37cac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35203, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "変革", "is_correct": true, "explanation": "「変革を恐れていては」は、根本的な変化を恐れていては、という意味に合う。"}, {"text": "遠征", "is_correct": false, "explanation": "「遠征を恐れていては」は文脈に合わず、企業の存続の話と結びつかない。"}, {"text": "照明", "is_correct": false, "explanation": "「照明を恐れていては」は意味が通らず、文の流れに合わない。"}, {"text": "解答", "is_correct": false, "explanation": "「解答を恐れていては」は不自然で、企業の話として成り立たない。"}], "explanations": {"変革": "「変革を恐れていては」は、根本的な変化を恐れていては、という意味に合う。", "遠征": "「遠征を恐れていては」は文脈に合わず、企業の存続の話と結びつかない。", "照明": "「照明を恐れていては」は意味が通らず、文の流れに合わない。", "解答": "「解答を恐れていては」は不自然で、企業の話として成り立たない。"}, "sentence_index": 6, "correct_answer": "変革"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この機能は音声を文字に変革する。", "explanation": "ここは〈変換〉の意味。形式を別のものに移し替える語で、社会や制度を根本から変える〈変革〉とは違う。"}, {"text": "文章の誤りを変革した。", "explanation": "ここは〈修正〉の意味。誤りを直す場面に使う語で、根本的な変化を表す〈変革〉とは合わない。"}, {"text": "壊れた屋根を変革した。", "explanation": "ここは〈補修〉の意味。壊れた部分を直す場面に使う語で、前とは違うものに変える〈変革〉とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '871fac38-b929-4ac1-b557-568e2dd37cac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35203, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "町の交通制度を変革を求める声が高まった。", "corrected_sentence": "町の交通制度の変革を求める声が高まった。", "error_description": "「制度の変革」と連体修飾の「の」を使うのが正しい。「を」を入れると二重になり誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '871fac38-b929-4ac1-b557-568e2dd37cac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35203, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "新しい技術が、社会に大きな変革を落とした。", "corrected_sentence": "新しい技術が、社会に大きな変革を起こした。", "error_description": "「変革を起こす」が正しい。「落とす」は変革と結びつかず、不自然な組み合わせ。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '871fac38-b929-4ac1-b557-568e2dd37cac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35204, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「記録をつける」で、記録が「つける」の目的語になる。"}, {"text": "が", "is_correct": false, "explanation": "「つけます」は他動詞なので、目的語に「が」は使えない。"}, {"text": "と", "is_correct": false, "explanation": "「記録とつけます」では文として成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を表し、目的語には使えない。"}], "correct_answer": "を", "explanations": {"を": "「記録をつける」で、記録が「つける」の目的語になる。", "が": "「つけます」は他動詞なので、目的語に「が」は使えない。", "と": "「記録とつけます」では文として成り立たない。", "へ": "「へ」は方向を表し、目的語には使えない。"}, "error_tags": {"が": "subject_object_confusion", "と": "wrong_relation", "へ": "direction"}, "sentence_index": 2}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5a30e95-140b-4f0b-af5e-4d35b664424c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35204, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「結果を記録する」で、結果が記録の対象になる。"}, {"text": "が", "is_correct": false, "explanation": "「記録した」の目的語に「が」は使えず、文が成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「結果へ記録した」では対象を表せない。"}, {"text": "と", "is_correct": false, "explanation": "「結果と細かく記録した」では対象を表せず、文が成り立たない。"}], "correct_answer": "を", "explanations": {"を": "「結果を記録する」で、結果が記録の対象になる。", "が": "「記録した」の目的語に「が」は使えず、文が成り立たない。", "へ": "「結果へ記録した」では対象を表せない。", "と": "「結果と細かく記録した」では対象を表せず、文が成り立たない。"}, "error_tags": {"が": "subject_object_confusion", "へ": "direction", "と": "wrong_relation"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5a30e95-140b-4f0b-af5e-4d35b664424c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35204, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "何かを書いたり、覚えたりするために、紙などにのこすこと。", "primary_collocate": null, "pronunciation": "きろく", "ipa": "kiɾokɯ", "syllable_count": 3, "sentences": [{"text": "記録を書く。", "target_word": "記録", "complexity_tier": "T1", "furigana": "記録[きろく]を書[か]く。", "sentence_source": "generated"}, {"text": "紙に記録する。", "target_word": "記録する", "complexity_tier": "T1", "furigana": "紙[かみ]に記録[きろく]する。", "sentence_source": "generated"}, {"text": "毎日の記録をつけます。", "target_word": "記録", "complexity_tier": "T2", "furigana": "毎日[まいにち]の記録[きろく]をつけます。", "sentence_source": "generated"}, {"text": "犬の体重を記録します。", "target_word": "記録します", "complexity_tier": "T2", "furigana": "犬[いぬ]の体重[たいじゅう]を記録[きろく]します。", "sentence_source": "generated"}, {"text": "見たことをノートに記録しておく。", "target_word": "記録し", "complexity_tier": "T3", "furigana": "見[み]たことをノートに記録[きろく]しておく。", "sentence_source": "generated"}, {"text": "忘れないように記録を残した。", "target_word": "記録", "complexity_tier": "T3", "furigana": "忘[わす]れないように記録[きろく]を残[のこ]した。", "sentence_source": "generated"}, {"text": "雨が降った日を記録すると、天気の流れがわかる。", "target_word": "記録する", "complexity_tier": "T4", "furigana": "雨[あめ]が降[ふ]った日[ひ]を記録[きろく]すると、天気[てんき]の流[なが]れがわかる。", "sentence_source": "generated"}, {"text": "先生に言われて、実験の結果を細かく記録した。", "target_word": "記録した", "complexity_tier": "T4", "furigana": "先生[せんせい]に言[い]われて、実験[じっけん]の結果[けっか]を細[こま]かく記録[きろく]した。", "sentence_source": "generated"}, {"text": "記録を見返すことで、自分の成長に気づくことができた。", "target_word": "記録", "complexity_tier": "T4", "furigana": "記録[きろく]を見返[みかえ]すことで、自分[じぶん]の成長[せいちょう]に気[き]づくことができた。", "sentence_source": "generated"}, {"text": "この記録は去年のものです。", "target_word": "記録", "complexity_tier": "T2", "furigana": "この記録[きろく]は去年[きょねん]のものです。", "sentence_source": "generated"}], "morphological_forms": [{"form": "記録する", "label": "活用"}, {"form": "記録した", "label": "活用"}, {"form": "記録される", "label": "活用"}, {"form": "記録簿", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 書いたり覚えたりして紙に残すこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '91f81af3-0e78-4da0-b675-62ce9dc0b7db') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35204, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "記録", "is_correct": true, "explanation": "見出し語そのものの「きろく」です。"}, {"text": "記憶", "is_correct": false, "explanation": "「きおく」は「ろ」が「お」に変わる一拍違いの別の語です。"}, {"text": "気楽", "is_correct": false, "explanation": "「きらく」は「ろ」が「ら」に変わる一拍違いの別の語です。"}, {"text": "帰宅", "is_correct": false, "explanation": "「きたく」は「ろ」が「た」に変わる一拍違いの別の語です。"}, {"text": "企画", "is_correct": false, "explanation": "「きかく」は「ろ」が「か」に変わる一拍違いの別の語です。"}], "explanations": {"記録": "見出し語そのものの「きろく」です。", "記憶": "「きおく」は「ろ」が「お」に変わる一拍違いの別の語です。", "気楽": "「きらく」は「ろ」が「ら」に変わる一拍違いの別の語です。", "帰宅": "「きたく」は「ろ」が「た」に変わる一拍違いの別の語です。", "企画": "「きかく」は「ろ」が「か」に変わる一拍違いの別の語です。"}, "sentence_index": null, "correct_answer": "記録"}, "level_3": {"options": [{"text": "記録", "is_correct": true, "explanation": "書いて残すものなので「書く」の目的語として意味が合います。"}, {"text": "眠気", "is_correct": false, "explanation": "形は合うが、眠気は書くものではないので意味が合わない。"}, {"text": "疲れ", "is_correct": false, "explanation": "形は合うが、疲れを書くとは言わず意味が合わない。"}, {"text": "空腹", "is_correct": false, "explanation": "形は合うが、空腹は書く対象ではなく意味が合わない。"}], "explanations": {"記録": "書いて残すものなので「書く」の目的語として意味が合います。", "眠気": "形は合うが、眠気は書くものではないので意味が合わない。", "疲れ": "形は合うが、疲れを書くとは言わず意味が合わない。", "空腹": "形は合うが、空腹は書く対象ではなく意味が合わない。"}, "sentence_index": 0, "correct_answer": "記録"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "朝ごはんに記録を食べました。", "explanation": "記録は紙などに残す行為や物で、食べ物ではないので「食べる」と合わない。"}, {"text": "窓を記録して部屋を涼しくした。", "explanation": "記録は書き残すことで、窓を開ける動作の意味では使えない。"}, {"text": "彼は記録が大きくて、友達に笑われた。", "explanation": "記録は書き残したものやその行為で、体の大きさのような性質を表す語ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5a30e95-140b-4f0b-af5e-4d35b664424c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
