INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35205, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "と", "options": [{"text": "と", "is_correct": true, "explanation": "「記録として」で資格や役割を表します。"}, {"text": "を", "is_correct": false, "explanation": "「記録をして」では「保存されている」と合わず不自然です。"}, {"text": "へ", "is_correct": false, "explanation": "「記録へして」は文として成り立ちません。"}, {"text": "の", "is_correct": false, "explanation": "「記録のして」は文として成り立ちません。"}], "correct_answer": "と", "explanations": {"と": "「記録として」で資格や役割を表します。", "を": "「記録をして」では「保存されている」と合わず不自然です。", "へ": "「記録へして」は文として成り立ちません。", "の": "「記録のして」は文として成り立ちません。"}, "error_tags": {"を": "object_marker", "へ": "direction", "の": "noun_link"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5a30e95-140b-4f0b-af5e-4d35b664424c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35205, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "過去の出来事や情報を、文字や画像などを使って後で見られるように残すこと。また、その残されたもの。", "primary_collocate": null, "pronunciation": "きろく", "ipa": "kiɾokɯ", "syllable_count": 3, "sentences": [{"text": "記録的な暑さが続く夏の午後、公園の入り方で一人の少年が手作りのレモネードを販売していた。", "target_word": "記録", "complexity_tier": "T6", "furigana": "記録的[きろくてき]な暑[あつ]さが続[つづ]く夏[なつ]の午後[ごご]、公園[こうえん]の入[い]り方[かた]で一人[ひとり]の少年[しょうねん]が手作[てづく]りのレモネードを販売[はんばい]していた。", "sentence_source": "mined"}, {"text": "記録を取る。", "target_word": "記録", "complexity_tier": "T1", "furigana": "記録[きろく]を取[と]る。", "sentence_source": "generated"}, {"text": "会議の記録を読みます。", "target_word": "記録", "complexity_tier": "T2", "furigana": "会議[かいぎ]の記録[きろく]を読[よ]みます。", "sentence_source": "generated"}, {"text": "日記は毎日の記録です。", "target_word": "記録", "complexity_tier": "T2", "furigana": "日記[にっき]は毎日[まいにち]の記録[きろく]です。", "sentence_source": "generated"}, {"text": "先生が授業の様子を記録している。", "target_word": "記録し", "complexity_tier": "T3", "furigana": "先生[せんせい]が授業[じゅぎょう]の様子[ようす]を記録[きろく]している。", "sentence_source": "generated"}, {"text": "古い記録が図書館で見つかった。", "target_word": "記録", "complexity_tier": "T3", "furigana": "古[ふる]い記録[きろく]が図書館[としょかん]で見[み]つかった。", "sentence_source": "generated"}, {"text": "事故の記録を残すために、写真を何枚も撮った。", "target_word": "記録", "complexity_tier": "T4", "furigana": "事故[じこ]の記録[きろく]を残[のこ]すために、写真[しゃしん]を何枚[なんまい]も撮[と]った。", "sentence_source": "generated"}, {"text": "この映像は、当時の様子を伝える貴重な記録として保存されている。", "target_word": "記録", "complexity_tier": "T5", "furigana": "この映像[えいぞう]は、当時[とうじ]の様子[ようす]を伝[つた]える貴重[きちょう]な記録[きろく]として保存[ほぞん]されている。", "sentence_source": "generated"}, {"text": "記録がなければ、何が起きたのか分からなかっただろう。", "target_word": "記録", "complexity_tier": "T4", "furigana": "記録[きろく]がなければ、何[なに]が起[お]きたのか分[わ]からなかっただろう。", "sentence_source": "generated"}, {"text": "気温や降水量などのデータを毎日記録して、一年間の変化をまとめた。", "target_word": "記録し", "complexity_tier": "T5", "furigana": "気温[きおん]や降水量[こうすいりょう]などのデータを毎日[まいにち]記録[きろく]して、一年間[いちねんかん]の変化[へんか]をまとめた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "記録する", "label": "活用"}, {"form": "記録した", "label": "活用"}, {"form": "記録される", "label": "活用"}, {"form": "記録簿", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 出来事や情報を残すこと、その物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '91f81af3-0e78-4da0-b675-62ce9dc0b7db') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35205, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "記録", "is_correct": true, "explanation": "見出し語「きろく」そのものです。"}, {"text": "記憶", "is_correct": false, "explanation": "「きおく」で、二番目の音が違います。"}, {"text": "規則", "is_correct": false, "explanation": "「きそく」で、二番目の音が違います。"}, {"text": "企画", "is_correct": false, "explanation": "「きかく」で、二番目の音が違います。"}, {"text": "帰国", "is_correct": false, "explanation": "「きこく」で、二番目の音が違います。"}], "explanations": {"記録": "見出し語「きろく」そのものです。", "記憶": "「きおく」で、二番目の音が違います。", "規則": "「きそく」で、二番目の音が違います。", "企画": "「きかく」で、二番目の音が違います。", "帰国": "「きこく」で、二番目の音が違います。"}, "sentence_index": null, "correct_answer": "記録"}, "level_3": {"options": [{"text": "記録", "is_correct": true, "explanation": "「記録的な暑さ」で、記録に残るほどの暑さという意味です。"}, {"text": "国際", "is_correct": false, "explanation": "形は合うが、暑さを「国際的」とは言わないので意味が合わない。"}, {"text": "具体", "is_correct": false, "explanation": "形は合うが、暑さを「具体的」とは言わないので意味が合わない。"}, {"text": "個人", "is_correct": false, "explanation": "形は合うが、暑さを「個人的」とは言わないので意味が合わない。"}], "explanations": {"記録": "「記録的な暑さ」で、記録に残るほどの暑さという意味です。", "国際": "形は合うが、暑さを「国際的」とは言わないので意味が合わない。", "具体": "形は合うが、暑さを「具体的」とは言わないので意味が合わない。", "個人": "形は合うが、暑さを「個人的」とは言わないので意味が合わない。"}, "sentence_index": 0, "correct_answer": "記録"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "昨日、私は記録を飲んで元気になった。", "explanation": "「記録」は残された情報なので、飲むことはできません。"}, {"text": "この記録は五階建てで、エレベーターもある。", "explanation": "「記録」を建物の意味で使っていて、誤りです。"}, {"text": "雨が降ったので、記録をさして出かけた。", "explanation": "「記録」を傘のように使っていて、誤りです。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5a30e95-140b-4f0b-af5e-4d35b664424c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35205, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "記録", "is_correct": true, "explanation": "見出し語「きろく」そのものです。"}, {"text": "基軸", "is_correct": false, "explanation": "「きじく」で、二番目の音が違います。"}, {"text": "帰宅", "is_correct": false, "explanation": "「きたく」で、二番目の音が違います。"}, {"text": "危篤", "is_correct": false, "explanation": "「きとく」で、二番目の音が違います。"}, {"text": "弥勒", "is_correct": false, "explanation": "「みろく」で、最初の音が違います。"}], "explanations": {"記録": "見出し語「きろく」そのものです。", "基軸": "「きじく」で、二番目の音が違います。", "帰宅": "「きたく」で、二番目の音が違います。", "危篤": "「きとく」で、二番目の音が違います。", "弥勒": "「みろく」で、最初の音が違います。"}, "sentence_index": null, "correct_answer": "記録"}, "level_3": {"options": [{"text": "記録", "is_correct": true, "explanation": "事故の様子を残すものとして意味が合います。"}, {"text": "洗濯", "is_correct": false, "explanation": "形は合うが、事故の洗濯を残すとは言わないので意味が合わない。"}, {"text": "季節", "is_correct": false, "explanation": "形は合うが、写真を撮って残すものとして意味が合わない。"}, {"text": "機械", "is_correct": false, "explanation": "形は合うが、事故の機械を残すとは言えず意味が合わない。"}], "explanations": {"記録": "事故の様子を残すものとして意味が合います。", "洗濯": "形は合うが、事故の洗濯を残すとは言わないので意味が合わない。", "季節": "形は合うが、写真を撮って残すものとして意味が合わない。", "機械": "形は合うが、事故の機械を残すとは言えず意味が合わない。"}, "sentence_index": 6, "correct_answer": "記録"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "雨の日は傘を記録して、外へ出た。", "explanation": "「記録する」を「持つ」の意味で使っていて、誤りです。"}, {"text": "犬が庭を記録して、とても元気に遊んでいる。", "explanation": "「記録する」を「走る」の意味で使っていて、誤りです。"}, {"text": "私はおいしい料理を記録して、おなかがいっぱいになった。", "explanation": "「記録する」を「食べる」の意味で使っていて、誤りです。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5a30e95-140b-4f0b-af5e-4d35b664424c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors,