INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35206, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「親に伝達した」で伝える相手を示します。"}, {"text": "を", "is_correct": false, "explanation": "「話を」と重なり、目的語が二つになって不自然。"}, {"text": "の", "is_correct": false, "explanation": "「親の伝達した」では動詞につながらない。"}, {"text": "で", "is_correct": false, "explanation": "「親で伝達した」は相手を示せず不自然。"}], "correct_answer": "に", "explanations": {"に": "「親に伝達した」で伝える相手を示します。", "を": "「話を」と重なり、目的語が二つになって不自然。", "の": "「親の伝達した」では動詞につながらない。", "で": "「親で伝達した」は相手を示せず不自然。"}, "error_tags": {"を": "double_object", "の": "possessive_misuse", "で": "means_misuse"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9dc1648a-3cf1-4824-8fa7-eef6835fe76e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35206, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「思いを伝達する」で伝える対象を示します。"}, {"text": "の", "is_correct": false, "explanation": "「思いの伝達する」は動詞につながらない。"}, {"text": "と", "is_correct": false, "explanation": "「思いと伝達する」は意味をなさない。"}, {"text": "へ", "is_correct": false, "explanation": "「思いへ伝達する」は対象を示せず不自然。"}], "correct_answer": "を", "explanations": {"を": "「思いを伝達する」で伝える対象を示します。", "の": "「思いの伝達する」は動詞につながらない。", "と": "「思いと伝達する」は意味をなさない。", "へ": "「思いへ伝達する」は対象を示せず不自然。"}, "error_tags": {"の": "possessive_misuse", "と": "comitative_misuse", "へ": "direction_misuse"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9dc1648a-3cf1-4824-8fa7-eef6835fe76e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35206, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "人や物の間で、情報や気持ちを送ったり受け取ったりすること。", "primary_collocate": null, "pronunciation": "でんたつ", "ipa": "dentatsɯ", "syllable_count": 4, "sentences": [{"text": "伝達は大切だ。", "target_word": "伝達", "complexity_tier": "T1", "furigana": "伝達[でんたつ]は大切[たいせつ]だ。", "sentence_source": "generated"}, {"text": "情報を伝達する。", "target_word": "伝達する", "complexity_tier": "T1", "furigana": "情報[じょうほう]を伝達[でんたつ]する。", "sentence_source": "generated"}, {"text": "伝達がうまくいかなかった。", "target_word": "伝達", "complexity_tier": "T2", "furigana": "伝達[でんたつ]がうまくいかなかった。", "sentence_source": "generated"}, {"text": "先生の話を親に伝達した。", "target_word": "伝達した", "complexity_tier": "T2", "furigana": "先生[せんせい]の話[はなし]を親[おや]に伝達[でんたつ]した。", "sentence_source": "generated"}, {"text": "気持ちの伝達は難しい。", "target_word": "伝達", "complexity_tier": "T2", "furigana": "気持[きも]ちの伝達[でんたつ]は難[むずか]しい。", "sentence_source": "generated"}, {"text": "蜂は踊りで場所を伝達する。", "target_word": "伝達する", "complexity_tier": "T3", "furigana": "蜂[はち]は踊[おど]りで場所[ばしょ]を伝達[でんたつ]する。", "sentence_source": "generated"}, {"text": "伝達された内容を確認した。", "target_word": "伝達された", "complexity_tier": "T3", "furigana": "伝達[でんたつ]された内容[ないよう]を確認[かくにん]した。", "sentence_source": "generated"}, {"text": "手紙は思いを伝達する手段だ。", "target_word": "伝達する", "complexity_tier": "T3", "furigana": "手紙[てがみ]は思[おも]いを伝達[でんたつ]する手段[しゅだん]だ。", "sentence_source": "generated"}, {"text": "伝達に誤りがあったようだ。", "target_word": "伝達", "complexity_tier": "T3", "furigana": "伝達[でんたつ]に誤[あやま]りがあったようだ。", "sentence_source": "generated"}, {"text": "町の放送で、注意が伝達された。", "target_word": "伝達された", "complexity_tier": "T4", "furigana": "町[まち]の放送[ほうそう]で、注意[ちゅうい]が伝達[でんたつ]された。", "sentence_source": "generated"}], "morphological_forms": [{"form": "伝達する", "label": "活用"}, {"form": "伝達される", "label": "活用"}, {"form": "伝達力", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | 人や物の間で情報や気持ちをやり取りすること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d87f72e-2602-405c-b8a8-61acb30acc84') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35206, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "伝達", "is_correct": true, "explanation": "「情報のやり取りは大切だ」という意味に合います。"}, {"text": "混雑", "is_correct": false, "explanation": "形は合うが、「大切だ」と評価できる意味に合わない。"}, {"text": "解雇", "is_correct": false, "explanation": "形は合うが、「大切だ」と結びつく意味が合わない。"}, {"text": "渋滞", "is_correct": false, "explanation": "形は合うが、「大切だ」という評価に意味が合わない。"}], "explanations": {"伝達": "「情報のやり取りは大切だ」という意味に合います。", "混雑": "形は合うが、「大切だ」と評価できる意味に合わない。", "解雇": "形は合うが、「大切だ」と結びつく意味が合わない。", "渋滞": "形は合うが、「大切だ」という評価に意味が合わない。"}, "sentence_index": 0, "correct_answer": "伝達"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "祖母は庭の花に水を伝達した。", "explanation": "「伝達する」は情報を伝える意味で、水をやる意味ではない。"}, {"text": "私は昨日、新しい服を伝達した。", "explanation": "「伝達する」に買う・着る意味はなく、服を対象にできない。"}, {"text": "弟は犬を伝達して散歩に行った。", "explanation": "「伝達する」は連れて行く意味ではなく、犬を対象にできない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9dc1648a-3cf1-4824-8fa7-eef6835fe76e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35206, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "伝達された", "is_correct": true, "explanation": "「伝えられた内容」という意味に合います。"}, {"text": "混雑された", "is_correct": false, "explanation": "形は合うが、内容を確認する文脈で意味が合わない。"}, {"text": "大破された", "is_correct": false, "explanation": "形は合うが、内容を確認する文脈で意味が合わない。"}, {"text": "混乱された", "is_correct": false, "explanation": "形は合うが、内容を確認する文脈で意味が合わない。"}], "explanations": {"伝達された": "「伝えられた内容」という意味に合います。", "混雑された": "形は合うが、内容を確認する文脈で意味が合わない。", "大破された": "形は合うが、内容を確認する文脈で意味が合わない。", "混乱された": "形は合うが、内容を確認する文脈で意味が合わない。"}, "sentence_index": 6, "correct_answer": "伝達された"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "窓ガラスが強い風で伝達された。", "explanation": "「伝達される」は情報が伝わる意味で、物が壊れる意味ではない。"}, {"text": "大きな木が台風で伝達された。", "explanation": "「伝達される」は木が倒れる意味にはならない。"}, {"text": "ケーキがオーブンで伝達された。", "explanation": "「伝達される」は焼かれる意味ではなく、ケーキに使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9dc1648a-3cf1-4824-8fa7-eef6835fe76e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35206, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "情報を伝達を急いだ。", "corrected_sentence": "情報の伝達を急いだ。", "error_description": "名詞「伝達」の前で内容を示すには「の」を使う。「を」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9dc1648a-3cf1-4824-8fa7-eef6835fe76e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35206, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "社内を伝達は午後に行われた。", "corrected_sentence": "社内の伝達は午後に行われた。", "error_description": "「社内」は範囲・場所を示すので「の」を使う。「を」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9dc1648a-3cf1-4824-8fa7-eef6835fe76e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35207, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「情報の伝達」で伝達する内容を示します。"}, {"text": "を", "is_correct": false, "explanation": "「情報を伝達が」では助詞が衝突して不自然。"}, {"text": "に", "is_correct": false, "explanation": "「情報に伝達が」では意味がつながらない。"}, {"text": "へ", "is_correct": false, "explanation": "「情報へ伝達が」では意味がつながらない。"}], "correct_answer": "の", "explanations": {"の": "「情報の伝達」で伝達する内容を示します。", "を": "「情報を伝達が」では助詞が衝突して不自然。", "に": "「情報に伝達が」では意味がつながらない。", "へ": "「情報へ伝達が」では意味がつながらない。"}, "error_tags": {"を": "object_misuse", "に": "target_misuse", "へ": "direction_misuse"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9dc1648a-3cf1-4824-8fa7-eef6835fe76e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
