INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35207, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "情報や考え、気持ちなどを、他の人や場所に送り届けること。また、それを伝える手段や仕組み。", "primary_collocate": null, "pronunciation": "でんたつ", "ipa": "dentatsɯ", "syllable_count": 4, "sentences": [{"text": "現代の高等教育では、教師から学生への一方向の伝達だけでは学びは成り立たない。", "target_word": "伝達", "complexity_tier": "T6", "furigana": "現代[げんだい]の高等[こうとう]教育[きょういく]では、教師[きょうし]から学生[がくせい]への一方向[いっぽうこう]の伝達[でんたつ]だけでは学[まな]びは成[な]り立[た]たない。", "sentence_source": "generated"}, {"text": "情報の伝達が遅れた。", "target_word": "伝達", "complexity_tier": "T2", "furigana": "情報[じょうほう]の伝達[でんたつ]が遅[おく]れた。", "sentence_source": "generated"}, {"text": "上司に正確に伝達した。", "target_word": "伝達した", "complexity_tier": "T2", "furigana": "上司[じょうし]に正確[せいかく]に伝達[でんたつ]した。", "sentence_source": "generated"}, {"text": "気持ちの伝達は、言葉だけではない。", "target_word": "伝達", "complexity_tier": "T3", "furigana": "気持[きも]ちの伝達[でんたつ]は、言葉[ことば]だけではない。", "sentence_source": "generated"}, {"text": "犬は声で仲間に危険を伝達する。", "target_word": "伝達する", "complexity_tier": "T3", "furigana": "犬[いぬ]は声[こえ]で仲間[なかま]に危険[きけん]を伝達[でんたつ]する。", "sentence_source": "generated"}, {"text": "伝達の方法を工夫する必要がある。", "target_word": "伝達", "complexity_tier": "T3", "furigana": "伝達[でんたつ]の方法[ほうほう]を工夫[くふう]する必要[ひつよう]がある。", "sentence_source": "generated"}, {"text": "連絡が正しく伝達されなかった。", "target_word": "伝達されなかった", "complexity_tier": "T4", "furigana": "連絡[れんらく]が正[ただ]しく伝達[でんたつ]されなかった。", "sentence_source": "generated"}, {"text": "脳は神経を通して信号を伝達している。", "target_word": "伝達している", "complexity_tier": "T3", "furigana": "脳[のう]は神経[しんけい]を通[とお]して信号[しんごう]を伝達[でんたつ]している。", "sentence_source": "generated"}, {"text": "伝達を早くするため、メールを使う。", "target_word": "伝達", "complexity_tier": "T3", "furigana": "伝達[でんたつ]を早[はや]くするため、メールを使[つか]う。", "sentence_source": "generated"}, {"text": "命令の伝達に時間がかかりすぎた。", "target_word": "伝達", "complexity_tier": "T3", "furigana": "命令[めいれい]の伝達[でんたつ]に時間[じかん]がかかりすぎた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "伝達する", "label": "活用"}, {"form": "伝達される", "label": "活用"}, {"form": "伝達力", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | 情報や気持ちを他へ送り届けること、その手段", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d87f72e-2602-405c-b8a8-61acb30acc84') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35207, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "伝達", "is_correct": true, "explanation": "「一方向の伝達だけでは学びは成り立たない」の「伝達」。"}, {"text": "混雑", "is_correct": false, "explanation": "「一方向の混雑」は文として成立せず、学びに合わない。"}, {"text": "解雇", "is_correct": false, "explanation": "「一方向の解雇」は意味をなさず、文脈に合わない。"}, {"text": "包装", "is_correct": false, "explanation": "「一方向の包装」は意味をなさず、文脈に合わない。"}], "explanations": {"伝達": "「一方向の伝達だけでは学びは成り立たない」の「伝達」。", "混雑": "「一方向の混雑」は文として成立せず、学びに合わない。", "解雇": "「一方向の解雇」は意味をなさず、文脈に合わない。", "包装": "「一方向の包装」は意味をなさず、文脈に合わない。"}, "sentence_index": 0, "correct_answer": "伝達"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "重い荷物を二階まで伝達した。", "explanation": "「伝達」は情報や気持ちを伝える意味で、物を運ぶ意味ではない。"}, {"text": "夕食のあと、皿を伝達してきれいにした。", "explanation": "「伝達する」に洗う意味はなく、皿を対象にできない。"}, {"text": "彼は毎朝、公園を伝達してから会社へ行く。", "explanation": "「伝達する」は歩く・走る意味ではなく、公園を対象にできない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9dc1648a-3cf1-4824-8fa7-eef6835fe76e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35207, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "伝達されなかった", "is_correct": true, "explanation": "「連絡が正しく届かなかった」という意味に合います。"}, {"text": "解雇されなかった", "is_correct": false, "explanation": "形は合うが、連絡を解雇するという意味にならない。"}, {"text": "栽培されなかった", "is_correct": false, "explanation": "形は合うが、連絡を育てるという意味が合わない。"}, {"text": "建設されなかった", "is_correct": false, "explanation": "形は合うが、連絡を建てるという意味が合わない。"}], "explanations": {"伝達されなかった": "「連絡が正しく届かなかった」という意味に合います。", "解雇されなかった": "形は合うが、連絡を解雇するという意味にならない。", "栽培されなかった": "形は合うが、連絡を育てるという意味が合わない。", "建設されなかった": "形は合うが、連絡を建てるという意味が合わない。"}, "sentence_index": 6, "correct_answer": "伝達されなかった"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "昨日の伝達は、とても丸かった。", "explanation": "「伝達」は形状を表す語ではなく、丸いという意味にならない。"}, {"text": "新しい靴の伝達が足に合わない。", "explanation": "「伝達」は靴の大きさを表さない。靴のサイズの意味で使うのは誤り。"}, {"text": "この料理は伝達が強くて、とても辛い。", "explanation": "「伝達」に味の意味はなく、料理の辛さの説明に使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9dc1648a-3cf1-4824-8fa7-eef6835fe76e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35207, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "連絡の伝達を遅れた。", "corrected_sentence": "連絡の伝達が遅れた。", "error_description": "「遅れる」の主語には「が」を使う。「を」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9dc1648a-3cf1-4824-8fa7-eef6835fe76e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35207, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "大切な話を友達を伝達した。", "corrected_sentence": "大切な話を友達に伝達した。", "error_description": "伝える相手は「に」で示す。「を」を重ねるのは誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9dc1648a-3cf1-4824-8fa7-eef6835fe76e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35208, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「話す」は他動詞で、目的語「歴史」に「を」が付く。"}, {"text": "が", "is_correct": false, "explanation": "「歴史が話す」と主語にすると、「話してくれました」の目的語が欠けて文が成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "「歴史に話す」の「に」は話す相手を示すので、話す内容である目的語にはならない。"}, {"text": "へ", "is_correct": false, "explanation": "「歴史へ話す」の「へ」は方向を表し、話す内容にはならない。"}], "correct_answer": "を", "explanations": {"を": "「話す」は他動詞で、目的語「歴史」に「を」が付く。", "が": "「歴史が話す」と主語にすると、「話してくれました」の目的語が欠けて文が成り立たない。", "に": "「歴史に話す」の「に」は話す相手を示すので、話す内容である目的語にはならない。", "へ": "「歴史へ話す」の「へ」は方向を表し、話す内容にはならない。"}, "error_tags": {"が": "主格（主語）", "に": "相手", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d6d98c9-41ee-45f3-a318-58e42f1f84d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35208, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「歴史のテスト」の「の」は、名詞「テスト」を「歴史の」と修飾する。"}, {"text": "を", "is_correct": false, "explanation": "「歴史をテスト」の「を」は、名詞同士をつなぐ役割を果たせない。"}, {"text": "で", "is_correct": false, "explanation": "「歴史でテスト」の「で」は手段・場所を表し、名詞の修飾にならない。"}, {"text": "から", "is_correct": false, "explanation": "「歴史からテスト」の「から」は起点を表し、テストの内容を示せない。"}], "correct_answer": "の", "explanations": {"の": "「歴史のテスト」の「の」は、名詞「テスト」を「歴史の」と修飾する。", "を": "「歴史をテスト」の「を」は、名詞同士をつなぐ役割を果たせない。", "で": "「歴史でテスト」の「で」は手段・場所を表し、名詞の修飾にならない。", "から": "「歴史からテスト」の「から」は起点を表し、テストの内容を示せない。"}, "error_tags": {"を": "目的語", "で": "手段・場所", "から": "起点"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d6d98c9-41ee-45f3-a318-58e42f1f84d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35208, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "人が昔にしたことや、起こったことをまとめたお話です。", "primary_collocate": null, "pronunciation": "れきし", "ipa": "ɾekʲiɕi", "syllable_count": 3, "sentences": [{"text": "昔の人のくらしを知るために、歴史の本を読みます。", "target_word": "歴史", "complexity_tier": "T3", "furigana": "昔[むかし]の人[ひと]のくらしを知[し]るために、歴史[れきし]の本[ほん]を読[よ]みます。", "sentence_source": "generated"}, {"text": "先生が、この町の歴史をやさしく話してくれました。", "target_word": "歴史", "complexity_tier": "T3", "furigana": "先生[せんせい]が、この町[まち]の歴史[れきし]をやさしく話[はな]してくれました。", "sentence_source": "generated"}, {"text": "わたしは歴史の授業で、昔の戦いについて習いました。", "target_word": "歴史", "complexity_tier": "T3", "furigana": "わたしは歴史[れきし]の授業[じゅぎょう]で、昔[むかし]の戦[たたか]いについて習[なら]いました。", "sentence_source": "generated"}, {"text": "歴史の物語を読むと、昔の人の気持ちがよく分かります。", "target_word": "歴史", "complexity_tier": "T3", "furigana": "歴史[れきし]の物語[ものがたり]を読[よ]むと、昔[むかし]の人[ひと]の気持[きも]ちがよく分[わ]かります。", "sentence_source": "generated"}, {"text": "博物館で、町の歴史が分かる絵を見ました。", "target_word": "歴史", "complexity_tier": "T3", "furigana": "博物館[はくぶつかん]で、町[まち]の歴史[れきし]が分[わ]かる絵[え]を見[み]ました。", "sentence_source": "generated"}, {"text": "弟は歴史が好きで、昔の王様の話をよくします。", "target_word": "歴史", "complexity_tier": "T3", "furigana": "弟[おとうと]は歴史[れきし]が好[す]きで、昔[むかし]の王様[おうさま]の話[はなし]をよくします。", "sentence_source": "generated"}, {"text": "この神社には、五百年の歴史があると聞きました。", "target_word": "歴史", "complexity_tier": "T3", "furigana": "この神社[じんじゃ]には、五百年[ごひゃくねん]の歴史[れきし]があると聞[き]きました。", "sentence_source": "generated"}, {"text": "歴史のテストがあるので、年表をおぼえています。", "target_word": "歴史", "complexity_tier": "T3", "furigana": "歴史[れきし]のテストがあるので、年表[ねんぴょう]をおぼえています。", "sentence_source": "generated"}, {"text": "おじいさんは、村の歴史を子どもたちに話しました。", "target_word": "歴史", "complexity_tier": "T3", "furigana": "おじいさんは、村[むら]の歴史[れきし]を子[こ]どもたちに話[はな]しました。", "sentence_source": "generated"}, {"text": "図書館で歴史の本を三冊借りました。", "target_word": "歴史", "complexity_tier": "T3", "furigana": "図書館[としょかん]で歴史[れきし]の本[ほん]を三冊[さんさつ]借[か]りました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "歴史", "label": "基本形"}], "register": "丁寧（です・ます体）", "sense_fingerprint": "昔の人のしたことや出来事をまとめた、学校や本で学ぶお話としての歴史", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '95d3b987-f670-4e84-a902-8e7233637a42') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35208, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "歴史", "is_correct": true, "explanation": "昔の人がしたことや起こったことをまとめたお話で、「昔の人のくらしを知る本」にふさわしい。"}, {"text": "算数", "is_correct": false, "explanation": "計算を学ぶ教科で、昔の人のくらしを知る本の内容には合わない。"}, {"text": "体育", "is_correct": false, "explanation": "運動を学ぶ教科で、昔の人のくらしを知る本の内容には合わない。"}, {"text": "図工", "is_correct": false, "explanation": "工作や絵をつくる教科で、昔の人のくらしを知る本の内容には合わない。"}], "explanations": {"歴史": "昔の人がしたことや起こったことをまとめたお話で、「昔の人のくらしを知る本」にふさわしい。", "算数": "計算を学ぶ教科で、昔の人のくらしを知る本の内容には合わない。", "体育": "運動を学ぶ教科で、昔の人のくらしを知る本の内容には合わない。", "図工": "工作や絵をつくる教科で、昔の人のくらしを知る本の内容には合わない。"}, "sentence_index": 0, "correct_answer": "歴史"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "体温を計ったら、歴史が三十八度あった。", "explanation": "ここは〈体温〉の意味。体温は三十八度あるというように言い、〈歴史〉は過去の出来事の記録やお話を指すので合わない。"}, {"text": "歴史の実験で、水が沸騰する温度をはかりました。", "explanation": "ここは〈科学〉の意味。水の温度は科学の実験で扱うもので、昔の出来事のお話である〈歴史〉とは合わない。"}, {"text": "この店の料理は、私の歴史にぴったり合う。", "explanation": "ここは〈好み〉の意味。料理の味は好みに合うと言い、〈歴史〉は過去の出来事の記録やお話を指すので、味の好みには合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d6d98c9-41ee-45f3-a318-58e42f1f84d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35208, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "歴史", "is_correct": true, "explanation": "過去から今までの出来事の積み重ねを指し、「五百年の」と年数で表せる。"}, {"text": "天気", "is_correct": false, "explanation": "天気は空模様を表す語で、五百年という年数の積み重ねとは結びつかないので合わない。"}, {"text": "年齢", "is_correct": false, "explanation": "人や生き物の生きてきた年数を指し、神社の出来事の積み重ねを表さない。"}, {"text": "誕生日", "is_correct": false, "explanation": "生まれた日を指し、「五百年の誕生日」は成り立たない。"}], "explanations": {"歴史": "過去から今までの出来事の積み重ねを指し、「五百年の」と年数で表せる。", "天気": "天気は空模様を表す語で、五百年という年数の積み重ねとは結びつかないので合わない。", "年齢": "人や生き物の生きてきた年数を指し、神社の出来事の積み重ねを表さない。", "誕生日": "生まれた日を指し、「五百年の誕生日」は成り立たない。"}, "sentence_index": 6, "correct_answer": "歴史"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "駅までの歴史は、歩いて十分ほどだ。", "explanation": "ここは〈距離〉の意味。道のりは距離で表し、〈歴史〉は過去の出来事の記録を指すので、道のりには合わない。"}, {"text": "この靴の歴史は、二千円だ。", "explanation": "ここは〈値段〉の意味。靴の値段は二千円のように表し、〈歴史〉は過去の出来事の記録を指すので、値段には合わない。"}, {"text": "今日は歴史が悪い。", "explanation": "ここは〈天気〉の意味。天気は良い・悪いで表し、〈歴史〉は過去の出来事の記録を指すので、天候には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d6d98c9-41ee-45f3-a318-58e42f1f84d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35208, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "先生は歴史を宿題で、町の古い地図を出した。", "corrected_sentence": "先生は歴史の宿題で、町の古い地図を出した。", "error_description": "名詞と名詞をつなぐ「の」が正しい。「歴史を宿題」の「を」は誤りで、正しくは「歴史の宿題」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d6d98c9-41ee-45f3-a318-58e42f1f84d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35208, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "祖父は、昔の戦争の歴史家を孫たちに話してくれました。", "corrected_sentence": "祖父は、昔の戦争の歴史を孫たちに話してくれました。", "error_description": "「歴史家」は歴史を研究する人を指し、話す対象となる出来事の記録ではない。出来事の記録を指す「歴史」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d6d98c9-41ee-45f3-a318-58e42f1f84d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35209, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「調べる」は他動詞で、目的語「歴史」に「を」が付く。"}, {"text": "が", "is_correct": false, "explanation": "「歴史が調べると」では他動詞「調べる」の目的語が欠け、文が成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "「歴史に調べると」の「に」は調べる対象を示せない。"}, {"text": "へ", "is_correct": false, "explanation": "「歴史へ調べると」の「へ」は方向を表し、調べる対象にはならない。"}], "correct_answer": "を", "explanations": {"を": "「調べる」は他動詞で、目的語「歴史」に「を」が付く。", "が": "「歴史が調べると」では他動詞「調べる」の目的語が欠け、文が成り立たない。", "に": "「歴史に調べると」の「に」は調べる対象を示せない。", "へ": "「歴史へ調べると」の「へ」は方向を表し、調べる対象にはならない。"}, "error_tags": {"が": "主格（他動詞の目的語と合わない）", "に": "方向・相手", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d6d98c9-41ee-45f3-a318-58e42f1f84d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35209, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「歴史が長い」の主語を示す「が」で、形容詞「長い」の主語になる。"}, {"text": "と", "is_correct": false, "explanation": "「歴史と長い店」は並列の「と」で、「長い」の主語にはならない。"}, {"text": "で", "is_correct": false, "explanation": "「歴史で長い店」は手段・場所の「で」で、形容詞の主語にならない。"}, {"text": "から", "is_correct": false, "explanation": "「歴史から長い店」は起点の「から」で、主語を表せない。"}], "correct_answer": "が", "explanations": {"が": "「歴史が長い」の主語を示す「が」で、形容詞「長い」の主語になる。", "と": "「歴史と長い店」は並列の「と」で、「長い」の主語にはならない。", "で": "「歴史で長い店」は手段・場所の「で」で、形容詞の主語にならない。", "から": "「歴史から長い店」は起点の「から」で、主語を表せない。"}, "error_tags": {"と": "並列・共同", "で": "手段・場所", "から": "起点"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d6d98c9-41ee-45f3-a318-58e42f1f84d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35209, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "過去の出来事や人々の活動の記録。また、時間の流れの中で変化してきた事柄の筋道。", "primary_collocate": null, "pronunciation": "れきし", "ipa": "ɾekʲiɕi", "syllable_count": 3, "sentences": [{"text": "オートクチュールの歴史は、単なる服飾の変遷を超え、人類の美的探究と技術革新の軌跡そのものである。", "target_word": "歴史", "complexity_tier": "T5", "furigana": "オートクチュールの歴史[れきし]は、単[たん]なる服飾[ふくしょく]の変遷[へんせん]を超[こ]え、人類[じんるい]の美的[びてき]探究[たんきゅう]と技術[ぎじゅつ]革新[かくしん]の軌跡[きせき]そのものである。", "sentence_source": "mined"}, {"text": "この城の歴史を調べると、持ち主が何度も変わったことが分かる。", "target_word": "歴史", "complexity_tier": "T3", "furigana": "この城[しろ]の歴史[れきし]を調[しら]べると、持[も]ち主[ぬし]が何度[なんど]も変[か]わったことが分[わ]かる。", "sentence_source": "generated"}, {"text": "日本の鉄道の歴史は、明治時代の新橋と横浜の間から始まった。", "target_word": "歴史", "complexity_tier": "T3", "furigana": "日本[にほん]の鉄道[てつどう]の歴史[れきし]は、明治[めいじ]時代[じだい]の新橋[しんばし]と横浜[よこはま]の間[あいだ]から始[はじ]まった。", "sentence_source": "generated"}, {"text": "歴史を学ぶと、現在の社会がなぜこうなったのかが見えてくる。", "target_word": "歴史", "complexity_tier": "T3", "furigana": "歴史[れきし]を学[まな]ぶと、現在[げんざい]の社会[しゃかい]がなぜこうなったのかが見[み]えてくる。", "sentence_source": "generated"}, {"text": "この大学は百年を超える歴史があり、多くの研究者を育ててきた。", "target_word": "歴史", "complexity_tier": "T3", "furigana": "この大学[だいがく]は百年[ひゃくねん]を超[こ]える歴史[れきし]があり、多[おお]くの研究者[けんきゅうしゃ]を育[そだ]ててきた。", "sentence_source": "generated"}, {"text": "漢字の歴史をたどると、形も意味も時代とともに変化してきたことが分かる。", "target_word": "歴史", "complexity_tier": "T4", "furigana": "漢字[かんじ]の歴史[れきし]をたどると、形[かたち]も意味[いみ]も時代[じだい]とともに変化[へんか]してきたことが分[わ]かる。", "sentence_source": "generated"}, {"text": "彼は印刷技術の歴史について、一冊の本にまとめた。", "target_word": "歴史", "complexity_tier": "T3", "furigana": "彼[かれ]は印刷[いんさつ]技術[ぎじゅつ]の歴史[れきし]について、一冊[いっさつ]の本[ほん]にまとめた。", "sentence_source": "generated"}, {"text": "歴史が長い店ほど、客の信頼を守る工夫を続けている。", "target_word": "歴史", "complexity_tier": "T3", "furigana": "歴史[れきし]が長[なが]い店[みせ]ほど、客[きゃく]の信頼[しんらい]を守[まも]る工夫[くふう]を続[つづ]けている。", "sentence_source": "generated"}, {"text": "医学の歴史には、偶然の発見が大きな進歩を生んだ例が多い。", "target_word": "歴史", "complexity_tier": "T4", "furigana": "医学[いがく]の歴史[れきし]には、偶然[ぐうぜん]の発見[はっけん]が大[おお]きな進歩[しんぽ]を生[う]んだ例[れい]が多[おお]い。", "sentence_source": "generated"}, {"text": "その国の歴史を知らないまま、政治だけを論じても意味がない。", "target_word": "歴史", "complexity_tier": "T4", "furigana": "その国[くに]の歴史[れきし]を知[し]らないまま、政治[せいじ]だけを論[ろん]じても意味[いみ]がない。", "sentence_source": "generated"}], "morphological_forms": [{"form": "歴史", "label": "基本形"}], "register": "中立（書き言葉・常体）", "sense_fingerprint": "過去の記録や、物事が時代とともに変化してきた筋道としての歴史", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T1: contains vocabulary far above tier T1: オートクチュール (Zipf 2.47)']::text[], '95d3b987-f670-4e84-a902-8e7233637a42') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35209, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "歴史", "is_correct": true, "explanation": "時間の流れの中で変化してきた事柄の筋道としての〈歴史〉で、「人類の美的探究と技術革新の軌跡」と言い換えられる。"}, {"text": "型紙", "is_correct": false, "explanation": "服を裁断するための型のことで、「軌跡そのものである」と言える時間の流れの記録ではない。"}, {"text": "生地", "is_correct": false, "explanation": "布地のことで、「単なる服飾の変遷を超えた軌跡」という時間の流れの記録とは意味が合わない。"}, {"text": "天気", "is_correct": false, "explanation": "天気は空模様を表す語で、時間の流れの軌跡とは結びつかないので合わない。"}], "explanations": {"歴史": "時間の流れの中で変化してきた事柄の筋道としての〈歴史〉で、「人類の美的探究と技術革新の軌跡」と言い換えられる。", "型紙": "服を裁断するための型のことで、「軌跡そのものである」と言える時間の流れの記録ではない。", "生地": "布地のことで、「単なる服飾の変遷を超えた軌跡」という時間の流れの記録とは意味が合わない。", "天気": "天気は空模様を表す語で、時間の流れの軌跡とは結びつかないので合わない。"}, "sentence_index": 0, "correct_answer": "歴史"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は見た目が歴史の割に若く見える。", "explanation": "ここは〈年齢〉の意味。『年齢の割に若く見える』の年齢を歴史に置き換えたもので、〈歴史〉は過去の出来事の記録を指すため、人の年の数え方には合わない。"}, {"text": "この果物は歴史が短くて、三日でいたんでしまう。", "explanation": "ここは〈寿命〉の意味。果物の保存期間は寿命と言い、過去の出来事の記録を指す〈歴史〉とは合わない。"}, {"text": "先月の海外旅行で、私はたくさんの歴史を積んだ。", "explanation": "ここは〈経験〉の意味。経験は積むものだが、〈歴史〉は過去の出来事の記録で、積むものではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d6d98c9-41ee-45f3-a318-58e42f1f84d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35209, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "歴史", "is_correct": true, "explanation": "技術の移り変わりを時間の流れに沿ってまとめた〈歴史〉を指し、「一冊の本にまとめた」の対象になる。"}, {"text": "天気", "is_correct": false, "explanation": "天気は空模様を表す語で、印刷技術について一冊の本にまとめる対象にはならない。"}, {"text": "時刻", "is_correct": false, "explanation": "時刻は時の点を表す語で、印刷技術の移り変わりをまとめる対象にはならない。"}, {"text": "体重", "is_correct": false, "explanation": "体重は人や動物の重さを表す語で、印刷技術をまとめる対象にはならない。"}], "explanations": {"歴史": "技術の移り変わりを時間の流れに沿ってまとめた〈歴史〉を指し、「一冊の本にまとめた」の対象になる。", "天気": "天気は空模様を表す語で、印刷技術について一冊の本にまとめる対象にはならない。", "時刻": "時刻は時の点を表す語で、印刷技術の移り変わりをまとめる対象にはならない。", "体重": "体重は人や動物の重さを表す語で、印刷技術をまとめる対象にはならない。"}, "sentence_index": 6, "correct_answer": "歴史"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼女は外資系で十年の歴史を積んできた。", "explanation": "ここは〈経歴〉の意味。経歴は積むものだが、〈歴史〉は時間の流れの記録で、人の職歴を指す語ではない。"}, {"text": "この事故から、私たちは大切な歴史を得た。", "explanation": "ここは〈教訓〉の意味。教訓は得るものだが、〈歴史〉は過去の出来事の記録で、得るものではない。"}, {"text": "彼は長年の練習で、ピアノの歴史を磨いてきた。", "explanation": "ここは〈技術〉の意味。技術は磨くものだが、〈歴史〉は過去の記録で、磨く対象ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d6d98c9-41ee-45f3-a318-58e42f1f84d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35209, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "祖母は町の歴史に調べて、本にまとめた。", "corrected_sentence": "祖母は町の歴史を調べて、本にまとめた。", "error_description": "「調べる」は他動詞なので目的語に「を」を取る。「歴史に」の「に」が誤りで、正しくは「歴史を」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d6d98c9-41ee-45f3-a318-58e42f1f84d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35209, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この神社の歴史な文書が残っている。", "corrected_sentence": "この神社の歴史的な文書が残っている。", "error_description": "「歴史的な文書」の「的」が抜けている。「歴史な」は形容動詞として成り立たないので誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d6d98c9-41ee-45f3-a318-58e42f1f84d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
