INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35210, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "function", "definition": "「於く」は、ある場所や時を表すことばです。", "primary_collocate": null, "pronunciation": "おく", "ipa": "o.kɯ", "syllable_count": 2, "sentences": [{"text": "会議は本社の大会議室に於いて行われる。", "target_word": "於いて", "complexity_tier": "T3", "furigana": "会議[かいぎ]は本社[ほんしゃ]の大会議室[だいかいぎしつ]に於[お]いて行[おこな]われる。", "sentence_source": "generated"}, {"text": "卒業式は体育館に於いて開かれた。", "target_word": "於いて", "complexity_tier": "T3", "furigana": "卒業式[そつぎょうしき]は体育館[たいいくかん]に於[お]いて開[ひら]かれた。", "sentence_source": "generated"}, {"text": "江戸時代に於いて、米は富の中心だった。", "target_word": "於いて", "complexity_tier": "T3", "furigana": "江戸時代[えどじだい]に於[お]いて、米[こめ]は富[とみ]の中心[ちゅうしん]だった。", "sentence_source": "generated"}, {"text": "日本に於ける少子化は、大きな問題だ。", "target_word": "於ける", "complexity_tier": "T3", "furigana": "日本[にほん]に於[お]ける少子化[しょうしか]は、大[おお]きな問題[もんだい]だ。", "sentence_source": "generated"}, {"text": "試合は東京ドームに於いて行われた。", "target_word": "於いて", "complexity_tier": "T3", "furigana": "試合[しあい]は東京[とうきょう]ドームに於[お]いて行[おこな]われた。", "sentence_source": "generated"}, {"text": "昨年に於いては、売り上げが最高を記録した。", "target_word": "於いては", "complexity_tier": "T3", "furigana": "昨年[さくねん]に於[お]いては、売[う]り上[あ]げが最高[さいこう]を記録[きろく]した。", "sentence_source": "generated"}, {"text": "教育に於ける家庭の役割は大きい。", "target_word": "於ける", "complexity_tier": "T3", "furigana": "教育[きょういく]に於[お]ける家庭[かてい]の役割[やくわり]は大[おお]きい。", "sentence_source": "generated"}, {"text": "この点に於いて、二人の意見は一致している。", "target_word": "於いて", "complexity_tier": "T3", "furigana": "この点[てん]に於[お]いて、二人[ふたり]の意見[いけん]は一致[いっち]している。", "sentence_source": "generated"}, {"text": "開会式は午前九時に、市民ホールに於いて始まります。", "target_word": "於いて", "complexity_tier": "T3", "furigana": "開会式[かいかいしき]は午前[ごぜん]九時[くじ]に、市民[しみん]ホールに於[お]いて始[はじ]まります。", "sentence_source": "generated"}, {"text": "国際大会に於ける彼女の活躍は素晴らしかった。", "target_word": "於ける", "complexity_tier": "T3", "furigana": "国際[こくさい]大会[たいかい]に於[お]ける彼女[かのじょ]の活躍[かつやく]は素晴[すば]らしかった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "於く", "label": "辞書形"}, {"form": "於いて", "label": "て形"}, {"form": "於いては", "label": "て形+は"}, {"form": "於ける", "label": "連体形"}], "register": "formal", "sense_fingerprint": "「〜に於いて」「〜に於ける」の形で、場所・時・場面を示す", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fd5ffa41-1131-4a11-8fcb-1ef942369fab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35210, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "於いて", "is_correct": true, "explanation": "「大会議室に於いて行われる」と、場所を示す正しい連語の形になる。"}, {"text": "於ける", "is_correct": false, "explanation": "連体形は後ろに名詞が必要で、「行われる」に直接続くと文法的に成立しない。"}, {"text": "於く", "is_correct": false, "explanation": "辞書形は「大会議室に於く行われる」と場所の連語にならず、文が崩れる。"}, {"text": "於いた", "is_correct": false, "explanation": "過去形は「大会議室に於いた行われる」と連なって文が崩れ、場所を示す連語にならない。"}], "explanations": {"於いて": "「大会議室に於いて行われる」と、場所を示す正しい連語の形になる。", "於ける": "連体形は後ろに名詞が必要で、「行われる」に直接続くと文法的に成立しない。", "於く": "辞書形は「大会議室に於く行われる」と場所の連語にならず、文が崩れる。", "於いた": "過去形は「大会議室に於いた行われる」と連なって文が崩れ、場所を示す連語にならない。"}, "sentence_index": 0, "correct_answer": "於いて"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼はペンに於いて手紙を書いた。", "explanation": "ここは〈で〉（手段）の意味。於いては場所・場面を示すので、道具を使う手段の意味では使わない。"}, {"text": "私は先生に於いて感謝している。", "explanation": "ここは〈に対して〉の意味。於いては場所・場面を示すので、感情の対象には使わない。"}, {"text": "彼は友人に於いて出かけた。", "explanation": "ここは〈と〉（相手）の意味。於いては場所・場面を示すので、一緒に行く相手を表す用法には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c07d00d1-8048-4ad4-beac-311160b5c24e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35210, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "於ける", "is_correct": true, "explanation": "連体形で「教育に於ける家庭の役割」と後ろの名詞を修飾し、正しい形になる。"}, {"text": "於いても", "is_correct": false, "explanation": "「も」が付いて話題を広げる意味になり、名詞を修飾する連体形の役割を果たさない。"}, {"text": "於いてこそ", "is_correct": false, "explanation": "強調の形で文の意味が変わり、名詞を修飾する連体形の役割を果たさない。"}, {"text": "於いてさえ", "is_correct": false, "explanation": "極端な例を示す形で、名詞を修飾する連体形の役割を果たさない。"}], "explanations": {"於ける": "連体形で「教育に於ける家庭の役割」と後ろの名詞を修飾し、正しい形になる。", "於いても": "「も」が付いて話題を広げる意味になり、名詞を修飾する連体形の役割を果たさない。", "於いてこそ": "強調の形で文の意味が変わり、名詞を修飾する連体形の役割を果たさない。", "於いてさえ": "極端な例を示す形で、名詞を修飾する連体形の役割を果たさない。"}, "sentence_index": 6, "correct_answer": "於ける"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は東京に於いて来た。", "explanation": "ここは〈から〉の意味。於いては場所・場面を示すので、出発点を表す「から」の意味にはならない。"}, {"text": "彼女は花に於いて美しい。", "explanation": "ここは〈のように〉の意味。於いては比喩の対象を示せず、たとえの表現には使わない。"}, {"text": "今日は昨日に於いて暑い。", "explanation": "ここは〈より〉の意味。於いては比較の基準を示せず、比べる表現には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c07d00d1-8048-4ad4-beac-311160b5c24e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35210, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "式典は市役所の大ホールに於ける行われた。", "corrected_sentence": "式典は市役所の大ホールに於いて行われた。", "error_description": "「於いて」は連用形で動詞に続く。「於ける」は連体形で後ろに名詞が必要なので、「行われた」の前では誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c07d00d1-8048-4ad4-beac-311160b5c24e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35210, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "会議で於いて、新しい案が出された。", "corrected_sentence": "会議において、新しい案が出された。", "error_description": "「於いて」には直前に「に」を伴う。ここで「で」を使うのは誤りで、正しくは「に」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c07d00d1-8048-4ad4-beac-311160b5c24e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
