INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35212, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "property", "definition": "ほかのものとくらべて、とてもすごいこと。", "primary_collocate": null, "pronunciation": "ひるい", "ipa": "çi.ɾɯ.i", "syllable_count": 3, "sentences": [{"text": "彼の記憶力は比類のないものだ。", "target_word": "比類", "complexity_tier": "T3", "furigana": "彼[かれ]の記憶力[きおくりょく]は比類[ひるい]のないものだ。", "sentence_source": "generated"}, {"text": "この山の景色は、比類のない美しさで知られている。", "target_word": "比類", "complexity_tier": "T3", "furigana": "この山[やま]の景色[けしき]は、比類[ひるい]のない美[うつく]しさで知[し]られている。", "sentence_source": "generated"}, {"text": "彼女は比類のない才能を持つピアニストだ。", "target_word": "比類", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は比類[ひるい]のない才能[さいのう]を持[も]つピアニストだ。", "sentence_source": "generated"}, {"text": "その城は、比類のない大きさを誇っている。", "target_word": "比類", "complexity_tier": "T3", "furigana": "その城[しろ]は、比類[ひるい]のない大[おお]きさを誇[ほこ]っている。", "sentence_source": "generated"}, {"text": "比類のない速さで走る選手が、世界記録を更新した。", "target_word": "比類", "complexity_tier": "T3", "furigana": "比類[ひるい]のない速[はや]さで走[はし]る選手[せんしゅ]が、世界[せかい]記録[きろく]を更新[こうしん]した。", "sentence_source": "generated"}, {"text": "彼の集中力は比類がなく、誰も真似できない。", "target_word": "比類", "complexity_tier": "T3", "furigana": "彼[かれ]の集中力[しゅうちゅうりょく]は比類[ひるい]がなく、誰[だれ]も真似[まね]できない。", "sentence_source": "generated"}, {"text": "比類なき強さを見せて、チームは五連覇を果たした。", "target_word": "比類", "complexity_tier": "T3", "furigana": "比類[ひるい]なき強[つよ]さを見[み]せて、チームは五連覇[ごれんぱ]を果[は]たした。", "sentence_source": "generated"}, {"text": "この絵の色づかいは比類のないもので、見る人を驚かせる。", "target_word": "比類", "complexity_tier": "T3", "furigana": "この絵[え]の色[いろ]づかいは比類[ひるい]のないもので、見[み]る人[ひと]を驚[おどろ]かせる。", "sentence_source": "generated"}, {"text": "祖母の料理は比類のない味で、家族みんなが大好きだ。", "target_word": "比類", "complexity_tier": "T3", "furigana": "祖母[そぼ]の料理[りょうり]は比類[ひるい]のない味[あじ]で、家族[かぞく]みんなが大好[だいす]きだ。", "sentence_source": "generated"}, {"text": "彼の勇気は比類のないもので、町中の人が称えた。", "target_word": "比類", "complexity_tier": "T3", "furigana": "彼[かれ]の勇気[ゆうき]は比類[ひるい]のないもので、町中[まちじゅう]の人[ひと]が称[たた]えた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "比類", "label": "基本形"}, {"form": "比類のない", "label": "連体修飾形"}, {"form": "比類なき", "label": "文語連体形"}, {"form": "比類がない", "label": "述語形"}], "register": "formal", "sense_fingerprint": "「比類のない」の形で、ほかと比べものにならないほどすごい", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fd5ffa41-1131-4a11-8fcb-1ef942369fab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35212, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "比類", "is_correct": true, "explanation": "「比類のないものだ」の一部として、ほかに並ぶものがない意味の名詞になる。"}, {"text": "平凡", "is_correct": false, "explanation": "ありふれている意味で、「のない」と続けても「とてもすごい」の意味にならない。"}, {"text": "無縁", "is_correct": false, "explanation": "関係がない意味で、記憶力をほめる文の意味と合わない。"}, {"text": "比喩", "is_correct": false, "explanation": "たとえの意味で、「のないもの」と続けても記憶力の評価として成立しない。"}], "explanations": {"比類": "「比類のないものだ」の一部として、ほかに並ぶものがない意味の名詞になる。", "平凡": "ありふれている意味で、「のない」と続けても「とてもすごい」の意味にならない。", "無縁": "関係がない意味で、記憶力をほめる文の意味と合わない。", "比喩": "たとえの意味で、「のないもの」と続けても記憶力の評価として成立しない。"}, "sentence_index": 0, "correct_answer": "比類"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "双子の兄弟は、比類のないほど似ている。", "explanation": "ここは〈そっくり〉の意味。比類は他に並ぶものがないほどすぐれている意味で、似ていることには使わない。"}, {"text": "この店のパンは比類のないほど普通の味だ。", "explanation": "ここは〈平凡〉の意味。比類は他を圧倒するすぐれた意味なので、ありふれた評価とは合わない。"}, {"text": "彼は比類のない平均点を取った。", "explanation": "ここは〈平均的〉の意味。比類は並外れてすぐれているという意味で、ありふれた点数には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c07d00d1-8048-4ad4-beac-311160b5c24e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35212, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "比類", "is_correct": true, "explanation": "「比類なき強さ」の一部として、ほかに並ぶものがない意味の名詞になる。"}, {"text": "格別", "is_correct": false, "explanation": "特に違う意味で、「なき強さ」と続けても、比べものにならない強さの意味にはならない。"}, {"text": "劣る", "is_correct": false, "explanation": "動詞の終止形で、「なき」に続かず、強さを修飾できない。"}, {"text": "比べる", "is_correct": false, "explanation": "動詞の終止形で、「なき」に続かず、強さを修飾できない。"}], "explanations": {"比類": "「比類なき強さ」の一部として、ほかに並ぶものがない意味の名詞になる。", "格別": "特に違う意味で、「なき強さ」と続けても、比べものにならない強さの意味にはならない。", "劣る": "動詞の終止形で、「なき」に続かず、強さを修飾できない。", "比べる": "動詞の終止形で、「なき」に続かず、強さを修飾できない。"}, "sentence_index": 6, "correct_answer": "比類"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は比類のない勝手さで、会議を途中で抜け出した。", "explanation": "ここは〈身勝手〉の意味。比類は並外れてすぐれているという意味で、わがままな振る舞いの程度には使わない。"}, {"text": "市場に比類のない商品が並んでいるが、どれも同じ品だ。", "explanation": "ここは〈同じ〉の意味。比類は他に並ぶもののない意味なので、同じものが並ぶことには使わない。"}, {"text": "その電車は比類のないほど遅れた。", "explanation": "ここは〈大幅に〉の意味。比類は程度がすぐれているという意味で、遅れの程度には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c07d00d1-8048-4ad4-beac-311160b5c24e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35212, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼女の歌声は比類をない美しさだ。", "corrected_sentence": "彼女の歌声は比類のない美しさだ。", "error_description": "「比類」の後は「の」で続けて「のない」とする。「を」は誤りで、正しくは「の」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c07d00d1-8048-4ad4-beac-311160b5c24e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35212, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼は比類のないの記録を達成した。", "corrected_sentence": "彼は比類のない記録を達成した。", "error_description": "「比類のない」の後に「の」を重ねるのは誤り。「のない記録」と続けるのが正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c07d00d1-8048-4ad4-beac-311160b5c24e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
