INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35213, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "property", "definition": "他に同じくらいのものがないほど、すぐれていること。", "primary_collocate": null, "pronunciation": "ひるい", "ipa": "çi.ɾɯ.i", "syllable_count": 3, "sentences": [{"text": "この職人の技は、世界でも比類のないものだ。", "target_word": "比類のない", "complexity_tier": "T3", "furigana": "この職人の技は、世界でも比類[ひるい]のないものだ。", "sentence_source": "generated"}, {"text": "彼の功績は歴史上、比類のないものとして語り継がれている。", "target_word": "比類", "complexity_tier": "T3", "furigana": "彼[かれ]の功績[こうせき]は歴史上[れきしじょう]、比類[ひるい]のないものとして語[かた]り継[つ]がれている。", "sentence_source": "generated"}, {"text": "比類なき名作として、この小説は今も読まれている。", "target_word": "比類", "complexity_tier": "T3", "furigana": "比類[ひるい]なき名作[めいさく]として、この小説[しょうせつ]は今[いま]も読[よ]まれている。", "sentence_source": "generated"}, {"text": "その医師は、比類のない腕前で多くの命を救った。", "target_word": "比類", "complexity_tier": "T3", "furigana": "その医師[いし]は、比類[ひるい]のない腕前[うでまえ]で多[おお]くの命[いのち]を救[すく]った。", "sentence_source": "generated"}, {"text": "この宝石の輝きは比類がなく、博物館の宝になっている。", "target_word": "比類", "complexity_tier": "T3", "furigana": "この宝石[ほうせき]の輝[かがや]きは比類[ひるい]がなく、博物館[はくぶつかん]の宝[たから]になっている。", "sentence_source": "generated"}, {"text": "彼女の演技は比類のない完成度で、審査員全員を感動させた。", "target_word": "比類", "complexity_tier": "T3", "furigana": "彼女[かのじょ]の演技[えんぎ]は比類[ひるい]のない完成度[かんせいど]で、審査員[しんさいん]全員[ぜんいん]を感動[かんどう]させた。", "sentence_source": "generated"}, {"text": "この国の自然は比類のない価値を持ち、守るべきだ。", "target_word": "比類", "complexity_tier": "T3", "furigana": "この国[くに]の自然[しぜん]は比類[ひるい]のない価値[かち]を持[も]ち、守[まも]るべきだ。", "sentence_source": "generated"}, {"text": "比類のない発明のおかげで、会社は世界一になった。", "target_word": "比類", "complexity_tier": "T3", "furigana": "比類[ひるい]のない発明[はつめい]のおかげで、会社[かいしゃ]は世界一[せかいいち]になった。", "sentence_source": "generated"}, {"text": "彼は比類なき学者として、今も尊敬されている。", "target_word": "比類", "complexity_tier": "T3", "furigana": "彼[かれ]は比類[ひるい]なき学者[がくしゃ]として、今[いま]も尊敬[そんけい]されている。", "sentence_source": "generated"}, {"text": "彼の演奏は比類のない深みがあり、聴衆を黙らせた。", "target_word": "比類", "complexity_tier": "T3", "furigana": "彼[かれ]の演奏[えんそう]は比類[ひるい]のない深[ふか]みがあり、聴衆[ちょうしゅう]を黙[だま]らせた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "比類", "label": "基本形"}, {"form": "比類のない", "label": "連体修飾形"}, {"form": "比類なき", "label": "文語連体形"}, {"form": "比類がない", "label": "述語形"}], "register": "formal", "sense_fingerprint": "「比類のない」の形で、並ぶものがないほど優れている", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fd5ffa41-1131-4a11-8fcb-1ef942369fab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35213, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "比類のない", "is_correct": true, "explanation": "「並ぶものがないほど優れている」の意味で、「世界でも〜ものだ」の「もの」を修飾するので合う。"}, {"text": "比喩的な", "is_correct": false, "explanation": "比喩に関する形容で、優れていることを表さないので、世界一の技という文脈に合わない。"}, {"text": "比例的な", "is_correct": false, "explanation": "割合が釣り合うことを表す語で、技の優秀さを表さないので合わない。"}, {"text": "比較的な", "is_correct": false, "explanation": "他と比べた上での程度を表す語で、「世界でも並ぶものがない」という意味にならないので合わない。"}], "explanations": {"比類のない": "「並ぶものがないほど優れている」の意味で、「世界でも〜ものだ」の「もの」を修飾するので合う。", "比喩的な": "比喩に関する形容で、優れていることを表さないので、世界一の技という文脈に合わない。", "比例的な": "割合が釣り合うことを表す語で、技の優秀さを表さないので合わない。", "比較的な": "他と比べた上での程度を表す語で、「世界でも並ぶものがない」という意味にならないので合わない。"}, "sentence_index": 0, "correct_answer": "比類のない"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この薬は、水と成分を一対二の比類で混ぜて使う。", "explanation": "比類に割合の意味はなく、一対二の比率を表す文では使えない。"}, {"text": "新しい機種と古い機種の比類を、表にまとめた。", "explanation": "比類に比較の意味はなく、機種の差を表にまとめる文では使えない。"}, {"text": "二つの製品は、見た目の比類が高いので、同じ会社のものだと分かる。", "explanation": "比類は似ていることを表さず、同じ会社だと分かる文には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c07d00d1-8048-4ad4-beac-311160b5c24e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35213, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "比類", "is_correct": true, "explanation": "「並ぶものがないほど優れていること」の意味で、「比類のない価値」に合う。"}, {"text": "比色", "is_correct": false, "explanation": "色を比べる測定の用語で、「比類のない価値」の文脈に合わない。"}, {"text": "比翼", "is_correct": false, "explanation": "二つの翼が並ぶことを表す語で、自然の価値を表さないので合わない。"}, {"text": "比丘", "is_correct": false, "explanation": "出家した僧を指す語で、「自然は〜のない価値を持つ」の文脈に合わない。"}], "explanations": {"比類": "「並ぶものがないほど優れていること」の意味で、「比類のない価値」に合う。", "比色": "色を比べる測定の用語で、「比類のない価値」の文脈に合わない。", "比翼": "二つの翼が並ぶことを表す語で、自然の価値を表さないので合わない。", "比丘": "出家した僧を指す語で、「自然は〜のない価値を持つ」の文脈に合わない。"}, "sentence_index": 6, "correct_answer": "比類"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この国は輸出の比類が大きく、経済を支えている。", "explanation": "比類に比重の意味はなく、輸出が経済を支える重みを表す文では使えない。"}, {"text": "この詩は比類が豊かで、読むと情景が浮かぶ。", "explanation": "比類に比喩の意味はなく、詩の表現技法を表す文では使えない。"}, {"text": "二つの製品の比類は、ほぼ同じだ。", "explanation": "比類は優劣を比べる語ではなく、製品の差を表す文には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c07d00d1-8048-4ad4-beac-311160b5c24e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35213, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この作家の文章は比類を魅力があり、多くの読者を引きつける。", "corrected_sentence": "この作家の文章は比類のない魅力があり、多くの読者を引きつける。", "error_description": "「比類」は「比類のない＋名詞」の形で名詞を修飾する。「比類を」は誤りで、正しくは「比類のない魅力」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c07d00d1-8048-4ad4-beac-311160b5c24e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35213, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この作家の描写は比類で豊かで、読者の心に残る。", "corrected_sentence": "この作家の描写は比類なく豊かで、読者の心に残る。", "error_description": "「比類」は「比類なく＋用言」の形で用いる。「比類で」は誤りで、正しくは「比類なく豊かで」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c07d00d1-8048-4ad4-beac-311160b5c24e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35218, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "正解。「ヨーロッパの地図」の「の」は、ヨーロッパに関する地図という所属を表す。"}, {"text": "が", "is_correct": false, "explanation": "「ヨーロッパが地図を見ると」となり、地域が見る主語になって不自然。"}, {"text": "に", "is_correct": false, "explanation": "「ヨーロッパに地図を見ると」では、地図を見る対象や場所として「に」が合わない。"}, {"text": "へ", "is_correct": false, "explanation": "「ヨーロッパへ地図を見ると」は方向を示す形になり、地図を見る文として意味が通らない。"}], "correct_answer": "の", "explanations": {"の": "正解。「ヨーロッパの地図」の「の」は、ヨーロッパに関する地図という所属を表す。", "が": "「ヨーロッパが地図を見ると」となり、地域が見る主語になって不自然。", "に": "「ヨーロッパに地図を見ると」では、地図を見る対象や場所として「に」が合わない。", "へ": "「ヨーロッパへ地図を見ると」は方向を示す形になり、地図を見る文として意味が通らない。"}, "error_tags": {"が": "主語の誤用", "に": "対象の誤用", "へ": "方向の誤用"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cb121d0f-78e4-45de-917e-3033e99aa380') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35218, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "正解。「ヨーロッパの国々」の「の」は、ヨーロッパに属する国々という所属を表す。"}, {"text": "を", "is_correct": false, "explanation": "「ヨーロッパを国々では」となり、目的を示す「を」が主題の場所を示せず不自然。"}, {"text": "より", "is_correct": false, "explanation": "「ヨーロッパより国々では」は比較の形になり、サッカーが人気だという文脈に合わない。"}, {"text": "から", "is_correct": false, "explanation": "「ヨーロッパから国々では」は起点を示す形になり、人気の場所を示す文として合わない。"}], "correct_answer": "の", "explanations": {"の": "正解。「ヨーロッパの国々」の「の」は、ヨーロッパに属する国々という所属を表す。", "を": "「ヨーロッパを国々では」となり、目的を示す「を」が主題の場所を示せず不自然。", "より": "「ヨーロッパより国々では」は比較の形になり、サッカーが人気だという文脈に合わない。", "から": "「ヨーロッパから国々では」は起点を示す形になり、人気の場所を示す文として合わない。"}, "error_tags": {"を": "目的語の誤用", "より": "比較の誤用", "から": "起点の誤用"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cb121d0f-78e4-45de-917e-3033e99aa380') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35218, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "たくさんの国がある広いちいきのことです。", "primary_collocate": null, "pronunciation": "よーろっぱ", "ipa": "joːɾoppa", "syllable_count": 5, "sentences": [{"text": "兄は来年、仕事でヨーロッパに引っ越す。", "target_word": "ヨーロッパ", "complexity_tier": "T3", "furigana": "兄[あに]は来年[らいねん]、仕事[しごと]でヨーロッパに引[ひ]っ越[こ]す。", "sentence_source": "generated"}, {"text": "ヨーロッパの地図を見ると、小さな国がたくさんある。", "target_word": "ヨーロッパ", "complexity_tier": "T3", "furigana": "ヨーロッパの地図[ちず]を見[み]ると、小[ちい]さな国[くに]がたくさんある。", "sentence_source": "generated"}, {"text": "ヨーロッパには、夏でもすずしい国が多い。", "target_word": "ヨーロッパ", "complexity_tier": "T3", "furigana": "ヨーロッパには、夏[なつ]でもすずしい国[くに]が多[おお]い。", "sentence_source": "generated"}, {"text": "私はいつかヨーロッパのお城を見に行きたい。", "target_word": "ヨーロッパ", "complexity_tier": "T3", "furigana": "私[わたし]はいつかヨーロッパのお城[しろ]を見[み]に行[い]きたい。", "sentence_source": "generated"}, {"text": "ヨーロッパから来た友だちが、日本の食べ物を気に入った。", "target_word": "ヨーロッパ", "complexity_tier": "T3", "furigana": "ヨーロッパから来[き]た友[とも]だちが、日本[にほん]の食[た]べ物[もの]を気[き]に入[い]った。", "sentence_source": "generated"}, {"text": "ヨーロッパへ行くとき、先生に町の写真を見せてもらった。", "target_word": "ヨーロッパ", "complexity_tier": "T3", "furigana": "ヨーロッパへ行[い]くとき、先生[せんせい]に町[まち]の写真[しゃしん]を見[み]せてもらった。", "sentence_source": "generated"}, {"text": "この店はヨーロッパのチョコレートだけを売っている。", "target_word": "ヨーロッパ", "complexity_tier": "T3", "furigana": "この店[みせ]はヨーロッパのチョコレートだけを売[う]っている。", "sentence_source": "generated"}, {"text": "ヨーロッパの国々では、サッカーがとても人気だ。", "target_word": "ヨーロッパ", "complexity_tier": "T3", "furigana": "ヨーロッパの国々[くにぐに]では、サッカーがとても人気[にんき]だ。", "sentence_source": "generated"}, {"text": "ヨーロッパを旅行した祖父は、いろいろな言葉を聞いたと話した。", "target_word": "ヨーロッパ", "complexity_tier": "T3", "furigana": "ヨーロッパを旅行[りょこう]した祖父[そふ]は、いろいろな言葉[ことば]を聞[き]いたと話[はな]した。", "sentence_source": "generated"}, {"text": "ヨーロッパの都市には、古い駅が多く残っている。", "target_word": "ヨーロッパ", "complexity_tier": "T3", "furigana": "ヨーロッパの都市[とし]には、古[ふる]い駅[えき]が多[おお]く残[のこ]っている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "ヨーロッパ", "label": "基本形"}], "register": "標準的な書き言葉", "sense_fingerprint": "たくさんの国がある広い地域としてのヨーロッパ（やさしい説明の意味）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 2 above tier T2: contains vocabulary far above tier T2: すずしい (Zipf 2.04)']::text[], '21e4fc6d-cea0-417b-8165-be5b5a112aa0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35218, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "ヨーロッパ", "is_correct": true, "explanation": "正解。「ヨーロッパに引っ越す」の地域名として、引っ越し先を示す。"}, {"text": "階段", "is_correct": false, "explanation": "「階段に引っ越す」は成り立たず、引っ越し先として合わない。"}, {"text": "冷蔵庫", "is_correct": false, "explanation": "冷蔵庫は引っ越しの行き先にならず、「仕事で冷蔵庫に引っ越す」は不自然。"}, {"text": "洗濯機", "is_correct": false, "explanation": "洗濯機は住む場所ではないので、引っ越し先として意味が通らない。"}], "explanations": {"ヨーロッパ": "正解。「ヨーロッパに引っ越す」の地域名として、引っ越し先を示す。", "階段": "「階段に引っ越す」は成り立たず、引っ越し先として合わない。", "冷蔵庫": "冷蔵庫は引っ越しの行き先にならず、「仕事で冷蔵庫に引っ越す」は不自然。", "洗濯機": "洗濯機は住む場所ではないので、引っ越し先として意味が通らない。"}, "sentence_index": 0, "correct_answer": "ヨーロッパ"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "ヨーロッパは、首都パリにたくさんの美術館がある。", "explanation": "ここは「フランス」のような首都を持つ一国の話。ヨーロッパは地域名で首都を持たないので合わない。"}, {"text": "ヨーロッパは、毎週日曜に私と映画を見に行く。", "explanation": "ここは「友だち」（人）の意味。ヨーロッパは地域名なので、人のように映画を見に行くとは言わない。"}, {"text": "ヨーロッパは、春に赤い花を咲かせる。", "explanation": "ここは「バラ」（植物）の意味。ヨーロッパは地域名なので、花を咲かせるものではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cb121d0f-78e4-45de-917e-3033e99aa380') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35218, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "ヨーロッパ", "is_correct": true, "explanation": "正解。「ヨーロッパのチョコレート」の地域名として、産地を示す。"}, {"text": "台風", "is_correct": false, "explanation": "「台風のチョコレート」は成り立たず、産地としても合わない。"}, {"text": "石鹸", "is_correct": false, "explanation": "石鹸はチョコレートの産地にならず、「石鹸のチョコレート」は不自然。"}, {"text": "電柱", "is_correct": false, "explanation": "電柱はチョコレートの産地にならず、この文の意味に合わない。"}], "explanations": {"ヨーロッパ": "正解。「ヨーロッパのチョコレート」の地域名として、産地を示す。", "台風": "「台風のチョコレート」は成り立たず、産地としても合わない。", "石鹸": "石鹸はチョコレートの産地にならず、「石鹸のチョコレート」は不自然。", "電柱": "電柱はチョコレートの産地にならず、この文の意味に合わない。"}, "sentence_index": 6, "correct_answer": "ヨーロッパ"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "ヨーロッパは、野菜と肉をよく煮込んで作る料理だ。", "explanation": "ここは「カレー」（料理）の意味。ヨーロッパは地域名で、料理の名前ではない。"}, {"text": "ヨーロッパは九十分間続き、最後にどちらかが勝つ。", "explanation": "ここは「試合」（出来事）の意味。ヨーロッパは地域名で、九十分で決着がつく出来事ではない。"}, {"text": "ヨーロッパは、冷たい空気の中で白く降る。", "explanation": "ここは「雪」（天気）の意味。ヨーロッパは地域名なので、空から降るものではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cb121d0f-78e4-45de-917e-3033e99aa380') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35218, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "祖母は、ヨーロッパを生まれました。", "corrected_sentence": "祖母は、ヨーロッパで生まれました。", "error_description": "「生まれる」は生まれた場所を「で」で示す。「を」は誤りで、正しくは「ヨーロッパで生まれました」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cb121d0f-78e4-45de-917e-3033e99aa380') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35218, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "来月、ヨーロッパを留学する予定です。", "corrected_sentence": "来月、ヨーロッパへ留学する予定です。", "error_description": "「留学する」は行き先を「へ」で示す。「を」は誤りで、正しくは「ヨーロッパへ留学する予定です」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cb121d0f-78e4-45de-917e-3033e99aa380') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35219, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "正解。「ヨーロッパの国々」は、ヨーロッパに属する国々という所属を表す。"}, {"text": "を", "is_correct": false, "explanation": "「ヨーロッパを国々を電車で旅行する」となり、目的語が二つ並んで文が成り立たない。"}, {"text": "が", "is_correct": false, "explanation": "「ヨーロッパが国々を旅行する」となり、地域が旅行する主語になって不自然。"}, {"text": "に", "is_correct": false, "explanation": "「ヨーロッパに国々を電車で旅行する」では、地域に向かって国々を運ぶ形になり意味が通らない。"}], "correct_answer": "の", "explanations": {"の": "正解。「ヨーロッパの国々」は、ヨーロッパに属する国々という所属を表す。", "を": "「ヨーロッパを国々を電車で旅行する」となり、目的語が二つ並んで文が成り立たない。", "が": "「ヨーロッパが国々を旅行する」となり、地域が旅行する主語になって不自然。", "に": "「ヨーロッパに国々を電車で旅行する」では、地域に向かって国々を運ぶ形になり意味が通らない。"}, "error_tags": {"を": "目的語の重複", "が": "主語の誤用", "に": "方向・対象の誤用"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cb121d0f-78e4-45de-917e-3033e99aa380') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35219, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "正解。「ヨーロッパの古い町」の「の」は、ヨーロッパに属する町という所属を表す。"}, {"text": "へ", "is_correct": false, "explanation": "「ヨーロッパへ古い町には」となり、方向の「へ」が町の所属を示せず不自然。"}, {"text": "より", "is_correct": false, "explanation": "「ヨーロッパより古い町には」は比較の形になり、どの町かという文脈に合わない。"}, {"text": "で", "is_correct": false, "explanation": "「ヨーロッパで古い町には、石の道が残っている」は、動作の場所を示す「で」になり、存在の場所を示す「に」と合わない。"}], "correct_answer": "の", "explanations": {"の": "正解。「ヨーロッパの古い町」の「の」は、ヨーロッパに属する町という所属を表す。", "へ": "「ヨーロッパへ古い町には」となり、方向の「へ」が町の所属を示せず不自然。", "より": "「ヨーロッパより古い町には」は比較の形になり、どの町かという文脈に合わない。", "で": "「ヨーロッパで古い町には、石の道が残っている」は、動作の場所を示す「で」になり、存在の場所を示す「に」と合わない。"}, "error_tags": {"へ": "方向の誤用", "より": "比較の誤用", "で": "場所・存在の誤用"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cb121d0f-78e4-45de-917e-3033e99aa380') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35219, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "ヨーロッパとは、ユーラシア大陸の西側にある地域で、多くの国々が集まっています。", "primary_collocate": null, "pronunciation": "よーろっぱ", "ipa": "joːɾoppa", "syllable_count": 5, "sentences": [{"text": "中世ヨーロッパで発展したゴシック様式の大聖堂は、その圧倒的な高さと美しさで人々を魅了しました。", "target_word": "ヨーロッパ", "complexity_tier": "T3", "furigana": "中世[ちゅうせい]ヨーロッパで発展[はってん]したゴシック様式[ようしき]の大聖堂[だいせいどう]は、その圧倒的[あっとうてき]な高[たか]さと美[うつく]しさで人々[ひとびと]を魅了[みりょう]しました。", "sentence_source": "mined"}, {"text": "夏休みに、ヨーロッパの国々を電車で旅行する予定です。", "target_word": "ヨーロッパ", "complexity_tier": "T3", "furigana": "夏休[なつやす]みに、ヨーロッパの国々[くにぐに]を電車[でんしゃ]で旅行[りょこう]する予定[よてい]です。", "sentence_source": "generated"}, {"text": "ヨーロッパには、小さな国がたくさん集まっています。", "target_word": "ヨーロッパ", "complexity_tier": "T3", "furigana": "ヨーロッパには、小[ちい]さな国[くに]がたくさん集[あつ]まっています。", "sentence_source": "generated"}, {"text": "ヨーロッパの北のほうでは、冬は日が短く、夕方四時に暗くなる。", "target_word": "ヨーロッパ", "complexity_tier": "T3", "furigana": "ヨーロッパの北[きた]のほうでは、冬[ふゆ]は日[ひ]が短[みじか]く、夕方[ゆうがた]四時[よじ]に暗[くら]くなる。", "sentence_source": "generated"}, {"text": "彼女は大学を出てから、ヨーロッパへ音楽の勉強に行った。", "target_word": "ヨーロッパ", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は大学[だいがく]を出[で]てから、ヨーロッパへ音楽[おんがく]の勉強[べんきょう]に行[い]った。", "sentence_source": "generated"}, {"text": "ヨーロッパでは、電車に乗って一日で別の国へ行けることもある。", "target_word": "ヨーロッパ", "complexity_tier": "T3", "furigana": "ヨーロッパでは、電車[でんしゃ]に乗[の]って一日[いちにち]で別[べつ]の国[くに]へ行[い]けることもある。", "sentence_source": "generated"}, {"text": "この料理はもともとヨーロッパの田舎で食べられていたそうです。", "target_word": "ヨーロッパ", "complexity_tier": "T3", "furigana": "この料理[りょうり]はもともとヨーロッパの田舎[いなか]で食[た]べられていたそうです。", "sentence_source": "generated"}, {"text": "ヨーロッパの古い町には、石の道が残っているところが多い。", "target_word": "ヨーロッパ", "complexity_tier": "T3", "furigana": "ヨーロッパの古[ふる]い町[まち]には、石[いし]の道[みち]が残[のこ]っているところが多[おお]い。", "sentence_source": "generated"}, {"text": "飛行機で日本からヨーロッパまで、十二時間ほどかかります。", "target_word": "ヨーロッパ", "complexity_tier": "T3", "furigana": "飛行機[ひこうき]で日本[にほん]からヨーロッパまで、十二時間[じゅうにじかん]ほどかかります。", "sentence_source": "generated"}, {"text": "ヨーロッパの言葉は国ごとに違うので、旅行の前に挨拶を覚えた。", "target_word": "ヨーロッパ", "complexity_tier": "T3", "furigana": "ヨーロッパの言葉[ことば]は国[くに]ごとに違[ちが]うので、旅行[りょこう]の前[まえ]に挨拶[あいさつ]を覚[おぼ]えた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "ヨーロッパ", "label": "基本形"}], "register": "標準的な書き言葉", "sense_fingerprint": "ユーラシア大陸西部の、多くの国が集まる地域を指す地名", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '21e4fc6d-cea0-417b-8165-be5b5a112aa0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35219, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "ヨーロッパ", "is_correct": true, "explanation": "正解。地域名として、ゴシック様式が発展した場所を示す。"}, {"text": "月面", "is_correct": false, "explanation": "中世の月面には人が住まず、大聖堂様式が発展した場所ではないので、この文に合わない。"}, {"text": "南極", "is_correct": false, "explanation": "中世の南極に大聖堂文化は存在せず、「中世南極で発展した」は成り立たない。"}, {"text": "砂漠", "is_correct": false, "explanation": "砂漠で中世に大聖堂様式が発展したという内容にはならず、ゴシック様式の文脈に合わない。"}], "explanations": {"ヨーロッパ": "正解。地域名として、ゴシック様式が発展した場所を示す。", "月面": "中世の月面には人が住まず、大聖堂様式が発展した場所ではないので、この文に合わない。", "南極": "中世の南極に大聖堂文化は存在せず、「中世南極で発展した」は成り立たない。", "砂漠": "砂漠で中世に大聖堂様式が発展したという内容にはならず、ゴシック様式の文脈に合わない。"}, "sentence_index": 0, "correct_answer": "ヨーロッパ"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "ヨーロッパは海に囲まれた島国で、国民は英語を話す。", "explanation": "ここは「イギリス」のような一国の話。ヨーロッパは多くの国が集まる地域なので、島国や一つの言語とは言えない。"}, {"text": "ヨーロッパは、アジアも含む東西に広がった大陸全体のことだ。", "explanation": "ここは「ユーラシア大陸」（大陸全体）の意味。ヨーロッパは西側の地域だけを指し、アジアを含む大陸全体は指さないので合わない。"}, {"text": "ヨーロッパは、箸と米を日々の食事に使う文化圏のことだ。", "explanation": "ここは「東洋」（アジア）の意味。ヨーロッパは西側の地域で、箸と米の食文化を持つ地域ではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cb121d0f-78e4-45de-917e-3033e99aa380') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35219, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "ヨーロッパ", "is_correct": true, "explanation": "正解。「ヨーロッパの田舎」の地域名として、料理が食べられていた場所を示す。"}, {"text": "火星", "is_correct": false, "explanation": "火星に田舎はなく、昔からこの料理が食べられていた場所としては成り立たない。"}, {"text": "海底", "is_correct": false, "explanation": "海底に「田舎」という場所はなく、料理が食べられていた場所として合わない。"}, {"text": "宇宙", "is_correct": false, "explanation": "「宇宙の田舎」という言い方は成り立たず、料理の文脈に合わない。"}], "explanations": {"ヨーロッパ": "正解。「ヨーロッパの田舎」の地域名として、料理が食べられていた場所を示す。", "火星": "火星に田舎はなく、昔からこの料理が食べられていた場所としては成り立たない。", "海底": "海底に「田舎」という場所はなく、料理が食べられていた場所として合わない。", "宇宙": "「宇宙の田舎」という言い方は成り立たず、料理の文脈に合わない。"}, "sentence_index": 6, "correct_answer": "ヨーロッパ"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "ヨーロッパは、卵と砂糖を泡立てて焼く食べ物だ。", "explanation": "ここは「ケーキ」（食べ物）の意味。ヨーロッパは地域名で、料理や食べ物を指す言葉ではない。"}, {"text": "ヨーロッパは九十分間続き、最後にどちらかのチームが勝つ。", "explanation": "ここは「試合」（出来事）の意味。ヨーロッパは地域名で、九十分で決着がつく出来事ではない。"}, {"text": "ヨーロッパは心が明るくなる感情で、人を幸せにする。", "explanation": "ここは「嬉しさ」（感情）の意味。ヨーロッパは地域名なので、感情として心を明るくするとは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cb121d0f-78e4-45de-917e-3033e99aa380') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35219, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼は若いころ、ヨーロッパを住んでいた。", "corrected_sentence": "彼は若いころ、ヨーロッパに住んでいた。", "error_description": "「住む」は場所を「に」で示す。「を」は誤りで、正しくは「ヨーロッパに住んでいた」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cb121d0f-78e4-45de-917e-3033e99aa380') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35219, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "去年はヨーロッパで行かなかった。", "corrected_sentence": "去年はヨーロッパへ行かなかった。", "error_description": "「行く」は行き先を「へ」で示す。「で」は動作が行われる場所を示すので誤りで、正しくは「ヨーロッパへ行かなかった」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cb121d0f-78e4-45de-917e-3033e99aa380') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35224, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "「複製は」と主題を示す「は」。"}, {"text": "に", "is_correct": false, "explanation": "「複製に、駅前の店で頼める」は相手を示す形になり、意味が通らない。"}, {"text": "へ", "is_correct": false, "explanation": "「複製へ、駅前の店で頼める」は方向の意味になり、頼める対象にならない。"}, {"text": "で", "is_correct": false, "explanation": "「複製で、駅前の店で頼める」は手段の意味になり、文が通らない。"}], "correct_answer": "は", "explanations": {"は": "「複製は」と主題を示す「は」。", "に": "「複製に、駅前の店で頼める」は相手を示す形になり、意味が通らない。", "へ": "「複製へ、駅前の店で頼める」は方向の意味になり、頼める対象にならない。", "で": "「複製で、駅前の店で頼める」は手段の意味になり、文が通らない。"}, "error_tags": {"に": "相手", "へ": "方向", "で": "手段"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ed848d40-3489-4681-91c1-79fe346d2be0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35224, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「複製を店に飾る」の目的語を示す「を」。"}, {"text": "と", "is_correct": false, "explanation": "「複製と店に飾っている」は並べる意味になり、飾る対象が示せない。"}, {"text": "から", "is_correct": false, "explanation": "「複製から店に飾っている」は起点の意味になり、飾る対象の説明にならない。"}, {"text": "より", "is_correct": false, "explanation": "「複製より店に飾っている」は比較の意味になり、文が通らない。"}], "correct_answer": "を", "explanations": {"を": "「複製を店に飾る」の目的語を示す「を」。", "と": "「複製と店に飾っている」は並べる意味になり、飾る対象が示せない。", "から": "「複製から店に飾っている」は起点の意味になり、飾る対象の説明にならない。", "より": "「複製より店に飾っている」は比較の意味になり、文が通らない。"}, "error_tags": {"と": "共同", "から": "起点", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ed848d40-3489-4681-91c1-79fe346d2be0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35224, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "同じものをもう一つ作ること。", "primary_collocate": null, "pronunciation": "ふくせい", "ipa": "ɸɯkɯseː", "syllable_count": 4, "sentences": [{"text": "大切な絵の複製を作って、部屋に飾った。", "target_word": "複製", "complexity_tier": "T3", "furigana": "大切(たいせつ)な絵(え)の複製(ふくせい)を作(つく)って、部屋(へや)に飾(かざ)った。", "sentence_source": "generated"}, {"text": "家の鍵の複製は、駅前の店で頼める。", "target_word": "複製", "complexity_tier": "T3", "furigana": "家(いえ)の鍵(かぎ)の複製(ふくせい)は、駅前(えきまえ)の店(みせ)で頼(たの)める。", "sentence_source": "generated"}, {"text": "このポスターは、有名な絵の複製だ。", "target_word": "複製", "complexity_tier": "T3", "furigana": "このポスターは、有名(ゆうめい)な絵(え)の複製(ふくせい)だ。", "sentence_source": "generated"}, {"text": "古い手紙が傷まないように、複製を作って保管している。", "target_word": "複製", "complexity_tier": "T3", "furigana": "古(ふる)い手紙(てがみ)が傷(いた)まないように、複製(ふくせい)を作(つく)って保管(ほかん)している。", "sentence_source": "generated"}, {"text": "博物館には、本物ではなく複製が展示されている。", "target_word": "複製", "complexity_tier": "T3", "furigana": "博物館(はくぶつかん)には、本物(ほんもの)ではなく複製(ふくせい)が展示(てんじ)されている。", "sentence_source": "generated"}, {"text": "複製は本物とよく似ているが、値段はずっと安い。", "target_word": "複製", "complexity_tier": "T3", "furigana": "複製(ふくせい)は本物(ほんもの)とよく似(に)ているが、値段(ねだん)はずっと安(やす)い。", "sentence_source": "generated"}, {"text": "先生は地図の複製を配って、全員に見せた。", "target_word": "複製", "complexity_tier": "T3", "furigana": "先生(せんせい)は地図(ちず)の複製(ふくせい)を配(くば)って、全員(ぜんいん)に見(み)せた。", "sentence_source": "generated"}, {"text": "本物は金庫にしまって、複製を店に飾っている。", "target_word": "複製", "complexity_tier": "T3", "furigana": "本物(ほんもの)は金庫(きんこ)にしまって、複製(ふくせい)を店(みせ)に飾(かざ)っている。", "sentence_source": "generated"}, {"text": "彫刻の複製を作るために、型を取った。", "target_word": "複製", "complexity_tier": "T3", "furigana": "彫刻(ちょうこく)の複製(ふくせい)を作(つく)るために、型(かた)を取(と)った。", "sentence_source": "generated"}, {"text": "この写真は複製なので、自由に持ち帰ってもいい。", "target_word": "複製", "complexity_tier": "T3", "furigana": "この写真(しゃしん)は複製(ふくせい)なので、自由(じゆう)に持(も)ち帰(かえ)ってもいい。", "sentence_source": "generated"}], "morphological_forms": [{"form": "複製", "label": "基本形"}, {"form": "複製を", "label": "を格"}, {"form": "複製する", "label": "動詞形"}], "register": "標準（普通体）", "sense_fingerprint": "複製（名詞）：絵・鍵・地図など実物と同じものをもう一つ作ること、またその品", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '947d9c0d-20b2-4311-9f05-a20f8a6414f0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35224, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "複製", "is_correct": true, "explanation": "絵と同じものをもう一つ作る意味で、作って部屋に飾るという文に合う。"}, {"text": "予定", "is_correct": false, "explanation": "計画を指す語で、絵の代わりに作って飾るものではないので合わない。"}, {"text": "返事", "is_correct": false, "explanation": "返答を指す語で、作って部屋に飾るものではないので合わない。"}, {"text": "天気", "is_correct": false, "explanation": "気象の状態で、作ることも部屋に飾ることもできないので合わない。"}], "explanations": {"複製": "絵と同じものをもう一つ作る意味で、作って部屋に飾るという文に合う。", "予定": "計画を指す語で、絵の代わりに作って飾るものではないので合わない。", "返事": "返答を指す語で、作って部屋に飾るものではないので合わない。", "天気": "気象の状態で、作ることも部屋に飾ることもできないので合わない。"}, "sentence_index": 0, "correct_answer": "複製"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は有名な画家の作風を複製して、自分の作品を作った。", "explanation": "ここは〈模倣〉の意味。作風は形のあるものではなく複製できないので、真似をする意味では模倣を使う。"}, {"text": "先生の話を複製して、ノートに書き留めた。", "explanation": "ここは〈書き留める〉の意味。複製は既にあるものと同じものをもう一つ作ることで、話を記録して残す行為は書き留めると言うので合わない。"}, {"text": "明日の天気を複製して、ニュースで伝えた。", "explanation": "ここは〈予報〉の意味。複製は同じものを作ることで、先の天気を推し量って伝えることは予報と言うので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ed848d40-3489-4681-91c1-79fe346d2be0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35224, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "複製", "is_correct": true, "explanation": "地図と同じものをもう一つ作った物を指し、配って見せるという文に合う。"}, {"text": "感想", "is_correct": false, "explanation": "意見を述べる言葉で、地図の代わりに配るものではないので合わない。"}, {"text": "印象", "is_correct": false, "explanation": "心に残る受け止め方で、物として配ることはできないので合わない。"}, {"text": "気温", "is_correct": false, "explanation": "気象の数値で、地図を配るという文の対象にならないので合わない。"}], "explanations": {"複製": "地図と同じものをもう一つ作った物を指し、配って見せるという文に合う。", "感想": "意見を述べる言葉で、地図の代わりに配るものではないので合わない。", "印象": "心に残る受け止め方で、物として配ることはできないので合わない。", "気温": "気象の数値で、地図を配るという文の対象にならないので合わない。"}, "sentence_index": 6, "correct_answer": "複製"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "長い報告書を複製して、一ページにまとめた。", "explanation": "ここは〈要約〉の意味。複製は元と同じものをもう一つ作ることで、長い内容を短くまとめる意味では使わないので、要約と言う。"}, {"text": "この会社は新しい技術を複製して、特許を取得した。", "explanation": "ここは〈開発〉の意味。複製は既にある物を同じように作ることで、新しい技術を生み出すことは開発と言うので合わない。"}, {"text": "この料理は祖母の味を複製した。", "explanation": "ここは〈再現〉の意味。味は形のあるものではなく、同じものをもう一つ作るとは言えないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ed848d40-3489-4681-91c1-79fe346d2be0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35224, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "祖父の時計の複製に店に頼んだ。", "corrected_sentence": "祖父の時計の複製を店に頼んだ。", "error_description": "「頼む」の目的語は「を」で示す。「に」にすると目的語が示せず、「店に」と重なって文が成り立たない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ed848d40-3489-4681-91c1-79fe346d2be0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35224, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "博物館では、古い地図の複製を展示されている。", "corrected_sentence": "博物館では、古い地図の複製が展示されている。", "error_description": "「展示される」は受け身なので、主語は「が」で示す。「を」にすると受け身の形が成り立たない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ed848d40-3489-4681-91c1-79fe346d2be0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35225, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「複製を作る」の目的語を示す「を」。"}, {"text": "に", "is_correct": false, "explanation": "「複製に作っておけば」は作る対象を示せず、不自然。"}, {"text": "へ", "is_correct": false, "explanation": "「複製へ作っておけば」は方向の意味になり、作る対象にならない。"}, {"text": "より", "is_correct": false, "explanation": "「複製より作っておけば」は比較の意味になり、文が通らない。"}], "correct_answer": "を", "explanations": {"を": "「複製を作る」の目的語を示す「を」。", "に": "「複製に作っておけば」は作る対象を示せず、不自然。", "へ": "「複製へ作っておけば」は方向の意味になり、作る対象にならない。", "より": "「複製より作っておけば」は比較の意味になり、文が通らない。"}, "error_tags": {"に": "相手・位置", "へ": "方向", "より": "比較"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ed848d40-3489-4681-91c1-79fe346d2be0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
