INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35225, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "既にあるものと同じものをもう一つ作り出すこと。", "primary_collocate": null, "pronunciation": "ふくせい", "ipa": "ɸɯkɯseː", "syllable_count": 4, "sentences": [{"text": "細胞が分かれる前に、DNAの複製が行われる。", "target_word": "複製", "complexity_tier": "T3", "furigana": "細胞(さいぼう)が分(わ)かれる前(まえ)に、DNAの複製(ふくせい)が行(おこな)われる。", "sentence_source": "generated"}, {"text": "データの複製を作っておけば、消えても安心だ。", "target_word": "複製", "complexity_tier": "T3", "furigana": "データの複製(ふくせい)を作(つく)っておけば、消(き)えても安心(あんしん)だ。", "sentence_source": "generated"}, {"text": "許可なく本の複製を配ることは、法律で禁じられている。", "target_word": "複製", "complexity_tier": "T3", "furigana": "許可(きょか)なく本(ほん)の複製(ふくせい)を配(くば)ることは、法律(ほうりつ)で禁(きん)じられている。", "sentence_source": "generated"}, {"text": "元のファイルと同じ内容の複製が、別のフォルダーにできていた。", "target_word": "複製", "complexity_tier": "T3", "furigana": "元(もと)のファイルと同(おな)じ内容(ないよう)の複製(ふくせい)が、別(べつ)のフォルダーにできていた。", "sentence_source": "generated"}, {"text": "この機械は、書類の複製を一分で百枚作れる。", "target_word": "複製", "complexity_tier": "T3", "furigana": "この機械(きかい)は、書類(しょるい)の複製(ふくせい)を一分(いっぷん)で百枚(ひゃくまい)作(つく)れる。", "sentence_source": "generated"}, {"text": "ウイルスは人の細胞に入って、自分の複製を増やす。", "target_word": "複製", "complexity_tier": "T3", "furigana": "ウイルスは人(ひと)の細胞(さいぼう)に入(はい)って、自分(じぶん)の複製(ふくせい)を増(ふ)やす。", "sentence_source": "generated"}, {"text": "音楽の無断の複製は、作った人の権利を傷つける。", "target_word": "複製", "complexity_tier": "T3", "furigana": "音楽(おんがく)の無断(むだん)の複製(ふくせい)は、作(つく)った人(ひと)の権利(けんり)を傷(きず)つける。", "sentence_source": "generated"}, {"text": "古い映像は、劣化する前に複製して保存する。", "target_word": "複製", "complexity_tier": "T3", "furigana": "古(ふる)い映像(えいぞう)は、劣化(れっか)する前(まえ)に複製(ふくせい)して保存(ほぞん)する。", "sentence_source": "generated"}, {"text": "複製を作るときは、元の物を傷つけないよう注意する。", "target_word": "複製", "complexity_tier": "T3", "furigana": "複製(ふくせい)を作(つく)るときは、元(もと)の物(もの)を傷(きず)つけないよう注意(ちゅうい)する。", "sentence_source": "generated"}, {"text": "この遺跡の像は、複製を置いて本物は別の部屋で守っている。", "target_word": "複製", "complexity_tier": "T3", "furigana": "この遺跡(いせき)の像(ぞう)は、複製(ふくせい)を置(お)いて本物(ほんもの)は別(べつ)の部屋(へや)で守(まも)っている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "複製", "label": "基本形"}, {"form": "複製を", "label": "を格"}, {"form": "複製して", "label": "動詞形（て形）"}], "register": "標準（普通体）", "sense_fingerprint": "複製（名詞）：データ・遺伝子・書類など既存のものと同一のものを作り出すこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '947d9c0d-20b2-4311-9f05-a20f8a6414f0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35225, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "複製", "is_correct": true, "explanation": "DNAを同じものにもう一つ作る過程を指し、行われるという文に合う。"}, {"text": "会議", "is_correct": false, "explanation": "人が集まって話し合う場で、DNAには行われないので合わない。"}, {"text": "面接", "is_correct": false, "explanation": "人を評価する場で、DNAには行われないので合わない。"}, {"text": "演奏", "is_correct": false, "explanation": "音楽を奏でる行為で、DNAには行われないので合わない。"}], "explanations": {"複製": "DNAを同じものにもう一つ作る過程を指し、行われるという文に合う。", "会議": "人が集まって話し合う場で、DNAには行われないので合わない。", "面接": "人を評価する場で、DNAには行われないので合わない。", "演奏": "音楽を奏でる行為で、DNAには行われないので合わない。"}, "sentence_index": 0, "correct_answer": "複製"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "保存したファイルを複製して、名前で探した。", "explanation": "ここは〈検索〉の意味。複製は同じものをもう一つ作ることで、名前を手がかりに探し出すことは検索と言うので合わない。"}, {"text": "この座席を複製して、来週の分も押さえた。", "explanation": "ここは〈予約〉の意味。複製は同じものを作ることで、場所を先に取っておくことは予約と言うので合わない。"}, {"text": "注文の品を複製して、玄関まで届けた。", "explanation": "ここは〈配達〉の意味。複製は同じものを作ることで、品物を相手の所へ運ぶことは配達と言うので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ed848d40-3489-4681-91c1-79fe346d2be0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35225, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "複製", "is_correct": true, "explanation": "無断で作られた同一の複製を指し、作った人の権利を傷つけるという文に合う。"}, {"text": "天気", "is_correct": false, "explanation": "気象の状態で、権利を傷つける主語にはならないので合わない。"}, {"text": "階段", "is_correct": false, "explanation": "建物の一部で、無断で作ることはできないので合わない。"}, {"text": "歯磨き", "is_correct": false, "explanation": "日常の習慣や道具で、音楽の権利を傷つける主語にはならないので合わない。"}], "explanations": {"複製": "無断で作られた同一の複製を指し、作った人の権利を傷つけるという文に合う。", "天気": "気象の状態で、権利を傷つける主語にはならないので合わない。", "階段": "建物の一部で、無断で作ることはできないので合わない。", "歯磨き": "日常の習慣や道具で、音楽の権利を傷つける主語にはならないので合わない。"}, "sentence_index": 6, "correct_answer": "複製"}, "level_6": {"correct_sentence_index": 5, "wrong_sentences": [{"text": "この景色の美しさを複製して、家でも楽しめるようにした。", "explanation": "ここは〈再現〉の意味。美しさのような目に見えない魅力は同じものを作れないので、複製ではなく再現と言う。"}, {"text": "長い論文を複製して、三行にまとめた。", "explanation": "ここは〈要約〉の意味。複製は元と同じものを作ることで、長い内容を短くまとめることは要約と言うので合わない。"}, {"text": "この小説は、英語の複製として海外で出版された。", "explanation": "ここは〈翻訳〉の意味。元の内容を別の言語に置き換える場合は翻訳版と言い、複製とは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ed848d40-3489-4681-91c1-79fe346d2be0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35225, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "このデータの複製をを、別の場所に保存した。", "corrected_sentence": "このデータの複製を、別の場所に保存した。", "error_description": "「を」が二つ続いていて文が成り立たない。「保存する」の目的語は「を」一つで示す。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ed848d40-3489-4681-91c1-79fe346d2be0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35225, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "細胞は、DNAの複製が終えてから分かれる。", "corrected_sentence": "細胞は、DNAの複製を終えてから分かれる。", "error_description": "「終える」の目的語は「を」で示す。「が」にすると複製が終える主体になり、文が成り立たない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ed848d40-3489-4681-91c1-79fe346d2be0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35226, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "も", "options": [{"text": "も", "is_correct": true, "explanation": "「プロセスも大切」の「も」。「そこに至るプロセス」も大切だと付け加える働き。"}, {"text": "を", "is_correct": false, "explanation": "「を」は目的語を示すため、「プロセスを大切です」では文が成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "「に」は相手や位置を示すため、「プロセスに大切です」では文が成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は手段や場所を示すため、「プロセスで大切です」では文が成り立たない。"}], "correct_answer": "も", "explanations": {"も": "「プロセスも大切」の「も」。「そこに至るプロセス」も大切だと付け加える働き。", "を": "「を」は目的語を示すため、「プロセスを大切です」では文が成り立たない。", "に": "「に」は相手や位置を示すため、「プロセスに大切です」では文が成り立たない。", "で": "「で」は手段や場所を示すため、「プロセスで大切です」では文が成り立たない。"}, "error_tags": {"を": "object", "に": "target", "で": "means"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4a4989a7-06d7-41dd-ba78-6cb1bfb73104') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35226, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「申し込みのプロセス」と名詞をつなぐ「の」。「申し込み」が「プロセス」を修飾している。"}, {"text": "が", "is_correct": false, "explanation": "「が」は主語を示すため、「申し込みがプロセス」では修飾関係が成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すため、「申し込みへプロセス」では名詞をつなぐ形にならない。"}, {"text": "から", "is_correct": false, "explanation": "「から」は起点を示すため、「申し込みからプロセス」では修飾関係にならない。"}], "correct_answer": "の", "explanations": {"の": "「申し込みのプロセス」と名詞をつなぐ「の」。「申し込み」が「プロセス」を修飾している。", "が": "「が」は主語を示すため、「申し込みがプロセス」では修飾関係が成り立たない。", "へ": "「へ」は方向を示すため、「申し込みへプロセス」では名詞をつなぐ形にならない。", "から": "「から」は起点を示すため、「申し込みからプロセス」では修飾関係にならない。"}, "error_tags": {"が": "subject", "へ": "direction", "から": "source"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4a4989a7-06d7-41dd-ba78-6cb1bfb73104') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35226, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "物事を進める手順ややり方のことです。", "primary_collocate": null, "pronunciation": "ぷろせす", "ipa": "pɯɾosesɯ", "syllable_count": 4, "sentences": [{"text": "完成までのプロセスを、先生が図で説明してくれました。", "target_word": "プロセス", "complexity_tier": "T3", "furigana": "完成[かんせい]までのプロセスを、先生[せんせい]が図[ず]で説明[せつめい]してくれました。", "sentence_source": "generated"}, {"text": "結果だけでなく、そこに至るプロセスも大切です。", "target_word": "プロセス", "complexity_tier": "T3", "furigana": "結果[けっか]だけでなく、そこに至[いた]るプロセスも大切[たいせつ]です。", "sentence_source": "generated"}, {"text": "このプロセスは複雑なので、手順を一つずつ確認しましょう。", "target_word": "プロセス", "complexity_tier": "T3", "furigana": "このプロセスは複雑[ふくざつ]なので、手順[てじゅん]を一[ひと]つずつ確認[かくにん]しましょう。", "sentence_source": "generated"}, {"text": "パンができるまでのプロセスを工場で見学しました。", "target_word": "プロセス", "complexity_tier": "T3", "furigana": "パンができるまでのプロセスを工場[こうじょう]で見学[けんがく]しました。", "sentence_source": "generated"}, {"text": "契約までのプロセスが長く、半年もかかりました。", "target_word": "プロセス", "complexity_tier": "T3", "furigana": "契約[けいやく]までのプロセスが長[なが]く、半年[はんとし]もかかりました。", "sentence_source": "generated"}, {"text": "新しい商品を作るプロセスで、何度も失敗しました。", "target_word": "プロセス", "complexity_tier": "T3", "furigana": "新[あたら]しい商品[しょうひん]を作[つく]るプロセスで、何度[なんど]も失敗[しっぱい]しました。", "sentence_source": "generated"}, {"text": "彼は問題を解決するプロセスを丁寧にノートに書いた。", "target_word": "プロセス", "complexity_tier": "T3", "furigana": "彼[かれ]は問題[もんだい]を解決[かいけつ]するプロセスを丁寧[ていねい]にノートに書[か]いた。", "sentence_source": "generated"}, {"text": "申し込みのプロセスは簡単で、五分で終わりました。", "target_word": "プロセス", "complexity_tier": "T3", "furigana": "申[もう]し込[こ]みのプロセスは簡単[かんたん]で、五分[ごふん]で終[お]わりました。", "sentence_source": "generated"}, {"text": "学ぶプロセスを楽しめば、勉強は続けやすくなります。", "target_word": "プロセス", "complexity_tier": "T3", "furigana": "学[まな]ぶプロセスを楽[たの]しめば、勉強[べんきょう]は続[つづ]けやすくなります。", "sentence_source": "generated"}, {"text": "審査のプロセスが分かりにくいと、客から苦情が出ました。", "target_word": "プロセス", "complexity_tier": "T3", "furigana": "審査[しんさ]のプロセスが分[わ]かりにくいと、客[きゃく]から苦情[くじょう]が出[で]ました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "プロセス", "label": "基本形"}], "register": "標準語（中立）", "sense_fingerprint": "物事を完成や結果まで進める手順・過程。仕事や制作、手続きの流れを指す。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44cca240-755f-469b-852b-7faa7d866358') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35226, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "プロセス", "is_correct": true, "explanation": "ここは〈プロセス〉の意味。完成に至るまでの過程を説明する文脈に合う。"}, {"text": "眼鏡", "is_correct": false, "explanation": "眼鏡は道具で、完成までの過程を表す語にはならない。"}, {"text": "寝言", "is_correct": false, "explanation": "寝言は眠っている時の発言で、完成までの過程とは結びつかない。"}, {"text": "雑草", "is_correct": false, "explanation": "雑草は植物のことで、完成までの過程を説明する対象にはならない。"}], "explanations": {"プロセス": "ここは〈プロセス〉の意味。完成に至るまでの過程を説明する文脈に合う。", "眼鏡": "眼鏡は道具で、完成までの過程を表す語にはならない。", "寝言": "寝言は眠っている時の発言で、完成までの過程とは結びつかない。", "雑草": "雑草は植物のことで、完成までの過程を説明する対象にはならない。"}, "sentence_index": 0, "correct_answer": "プロセス"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "試験のプロセスが届いた。", "explanation": "ここは〈結果〉の意味。プロセスは途中の手順のことで、届くものとしては使えない。"}, {"text": "彼のプロセスは明るく、誰とでもすぐ仲良くなる。", "explanation": "ここは〈性格〉の意味。プロセスは物事の手順のことで、人の性質には使わない。"}, {"text": "彼はプロセスが豊富で、歴史の質問に何でも答える。", "explanation": "ここは〈知識〉の意味。プロセスは物事の進め方のことで、知っている量の話には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4a4989a7-06d7-41dd-ba78-6cb1bfb73104') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35226, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "プロセス", "is_correct": true, "explanation": "ここは〈プロセス〉の意味。問題を解決するまでの過程をノートに書いたという文脈に合う。"}, {"text": "風船", "is_correct": false, "explanation": "風船は空気を入れる玩具で、問題を解決する過程とは結びつかない。"}, {"text": "足音", "is_correct": false, "explanation": "足音は歩く時の音で、問題を解決する過程を表す語にはならない。"}, {"text": "紅茶", "is_correct": false, "explanation": "紅茶は飲み物で、問題を解決する過程の記録の対象にはならない。"}], "explanations": {"プロセス": "ここは〈プロセス〉の意味。問題を解決するまでの過程をノートに書いたという文脈に合う。", "風船": "風船は空気を入れる玩具で、問題を解決する過程とは結びつかない。", "足音": "足音は歩く時の音で、問題を解決する過程を表す語にはならない。", "紅茶": "紅茶は飲み物で、問題を解決する過程の記録の対象にはならない。"}, "sentence_index": 6, "correct_answer": "プロセス"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "このスープはプロセスが濃く、少し塩辛い。", "explanation": "ここは〈味〉の意味。プロセスは物事の手順のことで、スープの濃さには使わない。"}, {"text": "友達のプロセスが大きくて、みんなが驚いた。", "explanation": "ここは〈体格〉の意味。プロセスは物事の手順のことで、人の体の大きさには使わない。"}, {"text": "彼女のプロセスは優しくて、聞いていて安心する。", "explanation": "ここは〈声〉の意味。プロセスは物事の進め方のことで、人の声の調子には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4a4989a7-06d7-41dd-ba78-6cb1bfb73104') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35226, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "新しい計画のプロセスに、会議で全員が確認した。", "corrected_sentence": "新しい計画のプロセスを、会議で全員が確認した。", "error_description": "「確認する」は目的語に「を」をとる動詞。誤りは「プロセスに」の「に」で、正しくは「プロセスを」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4a4989a7-06d7-41dd-ba78-6cb1bfb73104') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35226, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "子どもの成長のプロセスが、先生は静かに見守った。", "corrected_sentence": "子どもの成長のプロセスを、先生は静かに見守った。", "error_description": "「見守る」は目的語に「を」をとる動詞。誤りは「プロセスが」の「が」で、正しくは「プロセスを」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4a4989a7-06d7-41dd-ba78-6cb1bfb73104') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
