INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35231, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "正解。「飛躍を遂げる」の「を」で、遂げる対象を示す。"}, {"text": "が", "is_correct": false, "explanation": "「飛躍が遂げた」では、遂げる動作の対象にならず、「遂げる」の目的語として成立しない。"}, {"text": "に", "is_correct": false, "explanation": "「飛躍に遂げた」は、動作の相手や場所を示す「に」では「遂げる」の目的語にならず不自然。"}, {"text": "と", "is_correct": false, "explanation": "「飛躍と遂げた」は並列や相手を示す「と」で、「遂げる」の目的語にならない。"}], "correct_answer": "を", "explanations": {"を": "正解。「飛躍を遂げる」の「を」で、遂げる対象を示す。", "が": "「飛躍が遂げた」では、遂げる動作の対象にならず、「遂げる」の目的語として成立しない。", "に": "「飛躍に遂げた」は、動作の相手や場所を示す「に」では「遂げる」の目的語にならず不自然。", "と": "「飛躍と遂げた」は並列や相手を示す「と」で、「遂げる」の目的語にならない。"}, "error_tags": {"が": "subject", "に": "dative", "と": "comitative"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5fa85734-4702-4ee4-8b6d-fd6e1534aa8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35231, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "物事が急に大きく進歩したり、発展したりすること。", "primary_collocate": null, "pronunciation": "ひやく", "ipa": "çijaku", "syllable_count": 3, "sentences": [{"text": "微生物の代謝作用である発酵は、単なる保存技法の域を超え、主食の持つ潜在能力を飛躍的に拡張する化学的芸術である。", "target_word": "飛躍", "complexity_tier": "T4", "furigana": "微生物[びせいぶつ]の代謝作用[たいしゃさよう]である発酵[はっこう]は、単[たん]なる保存技法[ほぞんぎほう]の域[いき]を超[こ]え、主食[しゅしょく]の持[も]つ潜在能力[せんざいのうりょく]を飛躍的[ひやくてき]に拡張[かくちょう]する化学的芸術[かがくてきげいじゅつ]である。", "sentence_source": "mined"}, {"text": "この発明によって、医学は大きく飛躍した。", "target_word": "飛躍", "complexity_tier": "T3", "furigana": "この発明[はつめい]によって、医学[いがく]は大[おお]きく飛躍[ひやく]した。", "sentence_source": "generated"}, {"text": "彼は海外で学んだ経験をいかして、さらに飛躍したいと考えている。", "target_word": "飛躍", "complexity_tier": "T3", "furigana": "彼[かれ]は海外[かいがい]で学[まな]んだ経験[けいけん]をいかして、さらに飛躍[ひやく]したいと考[かんが]えている。", "sentence_source": "generated"}, {"text": "世界大会での優勝をきっかけに、その選手は飛躍の年を迎えた。", "target_word": "飛躍", "complexity_tier": "T3", "furigana": "世界大会[せかいたいかい]での優勝[ゆうしょう]をきっかけに、その選手[せんしゅ]は飛躍[ひやく]の年[とし]を迎[むか]えた。", "sentence_source": "generated"}, {"text": "新しい工場ができて、会社が飛躍する機会がやってきた。", "target_word": "飛躍", "complexity_tier": "T3", "furigana": "新[あたら]しい工場[こうじょう]ができて、会社[かいしゃ]が飛躍[ひやく]する機会[きかい]がやってきた。", "sentence_source": "generated"}, {"text": "小さな店だったが、通信販売を始めてから大きく飛躍した。", "target_word": "飛躍", "complexity_tier": "T3", "furigana": "小[ちい]さな店[みせ]だったが、通信販売[つうしんはんばい]を始[はじ]めてから大[おお]きく飛躍[ひやく]した。", "sentence_source": "generated"}, {"text": "今年は来年の飛躍に向けて、力をたくわえる時期だ。", "target_word": "飛躍", "complexity_tier": "T3", "furigana": "今年[ことし]は来年[らいねん]の飛躍[ひやく]に向[む]けて、力[ちから]をたくわえる時期[じき]だ。", "sentence_source": "generated"}, {"text": "彼女の歌は、デビュー三年目で飛躍を遂げた。", "target_word": "飛躍", "complexity_tier": "T3", "furigana": "彼女[かのじょ]の歌[うた]は、デビュー三年目[さんねんめ]で飛躍[ひやく]を遂[と]げた。", "sentence_source": "generated"}, {"text": "一年の留学は、私の英語力にとって大きな飛躍となった。", "target_word": "飛躍", "complexity_tier": "T3", "furigana": "一年[いちねん]の留学[りゅうがく]は、私[わたし]の英語力[えいごりょく]にとって大[おお]きな飛躍[ひやく]となった。", "sentence_source": "generated"}, {"text": "計画を立てても、実行しなければ飛躍は望めない。", "target_word": "飛躍", "complexity_tier": "T3", "furigana": "計画[けいかく]を立[た]てても、実行[じっこう]しなければ飛躍[ひやく]は望[のぞ]めない。", "sentence_source": "generated"}], "morphological_forms": [{"form": "飛躍する", "label": "基本形"}, {"form": "飛躍した", "label": "過去形"}, {"form": "飛躍して", "label": "て形"}], "register": "中立", "sense_fingerprint": "人・会社・技術などが急に大きく発展する、サ変名詞の飛躍", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 6 above tier T3: contains vocabulary far above tier T3: たくわえる (Zipf 1.5)']::text[], '2cadf245-b057-4a4f-80e4-458d2df7fe35') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35231, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "飛躍", "is_correct": true, "explanation": "正解。潜在能力を急に大きく伸ばす意味で、「飛躍的に拡張する」と文が通る。"}, {"text": "停滞", "is_correct": false, "explanation": "〈停滞〉は進まずにとどまること。「停滞的に拡張する」は意味が逆で成立しない。"}, {"text": "解散", "is_correct": false, "explanation": "〈解散〉は集まりを解くこと。「解散的に拡張する」は文脈に合わない。"}, {"text": "落胆", "is_correct": false, "explanation": "〈落胆〉は気落ちすること。「落胆的に拡張する」は成立しない。"}], "explanations": {"飛躍": "正解。潜在能力を急に大きく伸ばす意味で、「飛躍的に拡張する」と文が通る。", "停滞": "〈停滞〉は進まずにとどまること。「停滞的に拡張する」は意味が逆で成立しない。", "解散": "〈解散〉は集まりを解くこと。「解散的に拡張する」は文脈に合わない。", "落胆": "〈落胆〉は気落ちすること。「落胆的に拡張する」は成立しない。"}, "sentence_index": 0, "correct_answer": "飛躍"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "かつて栄えた産業が飛躍して、町はすっかりさびれた。", "explanation": "ここは〈衰退〉の意味。〈飛躍〉は物事が大きく良い方向へ進む意味なので、勢いを失う場面には使えない。"}, {"text": "この機械は、性能が少しずつ飛躍した。", "explanation": "ここは〈進歩〉に近いが、〈飛躍〉は急に大きく進む意味なので、少しずつ変わる様子には使えない。"}, {"text": "子どもが十年かけてゆっくり飛躍した。", "explanation": "ここは〈成長〉の意味。〈飛躍〉は急に大きく伸びる意味で、時間をかけて育つ変化には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5fa85734-4702-4ee4-8b6d-fd6e1534aa8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35231, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "飛躍", "is_correct": true, "explanation": "正解。来年に大きく伸びることを指し、「来年の飛躍に向けて」と文が通る。"}, {"text": "退化", "is_correct": false, "explanation": "〈退化〉は能力や機能が後退すること。「来年の退化に向けて力をたくわえる」は意味が逆になる。"}, {"text": "墜落", "is_correct": false, "explanation": "〈墜落〉は高いところから落ちること。「来年の墜落に向けて」は成立しない。"}, {"text": "転倒", "is_correct": false, "explanation": "〈転倒〉は倒れること。「来年の転倒に向けて」は文脈に合わない。"}], "explanations": {"飛躍": "正解。来年に大きく伸びることを指し、「来年の飛躍に向けて」と文が通る。", "退化": "〈退化〉は能力や機能が後退すること。「来年の退化に向けて力をたくわえる」は意味が逆になる。", "墜落": "〈墜落〉は高いところから落ちること。「来年の墜落に向けて」は成立しない。", "転倒": "〈転倒〉は倒れること。「来年の転倒に向けて」は文脈に合わない。"}, "sentence_index": 6, "correct_answer": "飛躍"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "夜の嵐で、船が飛躍した。", "explanation": "ここは〈沈没〉の意味。〈飛躍〉は物事が大きく進歩する意味で、船が水に沈む場面には使えない。"}, {"text": "父の体調が、ようやく飛躍した。", "explanation": "ここは〈回復〉の意味。〈飛躍〉は進歩・発展の意味で、体の状態が元に戻る場面では使えない。"}, {"text": "痛みが、薬で飛躍した。", "explanation": "ここは〈緩和〉の意味。〈飛躍〉は良い方向へ大きく伸びることで、痛みが和らぐ場面には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5fa85734-4702-4ee4-8b6d-fd6e1534aa8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35231, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "新製品の成功で、会社を大きく飛躍した。", "corrected_sentence": "新製品の成功で、会社が大きく飛躍した。", "error_description": "「飛躍する」は自動詞で、主語は「が」で示す。「会社を」は目的語になり、飛躍の主体としては誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5fa85734-4702-4ee4-8b6d-fd6e1534aa8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35231, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼の演技を、この一年で大きく飛躍した。", "corrected_sentence": "彼の演技は、この一年で大きく飛躍した。", "error_description": "「飛躍する」は自動詞なので、目的語の「を」は取れない。主語は「は」で示す。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5fa85734-4702-4ee4-8b6d-fd6e1534aa8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35239, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「水の圧力」と水と圧力を結ぶ「の」です。"}, {"text": "を", "is_correct": false, "explanation": "「水を圧力は」は名詞をつなげず不適切です。"}, {"text": "に", "is_correct": false, "explanation": "「水に圧力は強い」は意味が成り立ちません。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を表すので、「水へ圧力は」は不適切です。"}], "correct_answer": "の", "explanations": {"の": "「水の圧力」と水と圧力を結ぶ「の」です。", "を": "「水を圧力は」は名詞をつなげず不適切です。", "に": "「水に圧力は強い」は意味が成り立ちません。", "へ": "「へ」は方向を表すので、「水へ圧力は」は不適切です。"}, "error_tags": {"を": "object", "に": "target", "へ": "direction"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13322750-3a4e-4704-999d-63599f3d62c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35239, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "から", "options": [{"text": "から", "is_correct": true, "explanation": "圧力を加える相手の出どころを示す「から」です。"}, {"text": "を", "is_correct": false, "explanation": "「上司を圧力を」は「を」が重なり不適切です。"}, {"text": "へ", "is_correct": false, "explanation": "「上司へ圧力をかけられた」は受け身の出どころを示せず不適切です。"}, {"text": "で", "is_correct": false, "explanation": "「上司で圧力をかけられた」は圧力の出どころを示せず不自然です。"}], "correct_answer": "から", "explanations": {"から": "圧力を加える相手の出どころを示す「から」です。", "を": "「上司を圧力を」は「を」が重なり不適切です。", "へ": "「上司へ圧力をかけられた」は受け身の出どころを示せず不適切です。", "で": "「上司で圧力をかけられた」は圧力の出どころを示せず不自然です。"}, "error_tags": {"を": "object", "へ": "direction", "で": "location"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13322750-3a4e-4704-999d-63599f3d62c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35239, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "物体の表面を押す力、または人に強い影響を与える力。", "primary_collocate": null, "pronunciation": "あつりょく", "ipa": "atsɯɾʲokɯ", "syllable_count": 4, "sentences": [{"text": "さらに、こうした非伝統的な金融政策がインフレ期待のアンカーとして機能し得る一方で、過剰な流動性が実体経済における物価上昇圧力と相乗効果を生み、予期せぬスタグフレーションや財政主導のシナリオへと帰結するリスクを常に内包していることを、我々は冷徹に認識する責務を負っている。", "target_word": "圧力", "complexity_tier": "T6", "furigana": "さらに、こうした非伝統的[ひでんとうてき]な金融政策[きんゆうせいさく]がインフレ期待[きたい]のアンカーとして機能[きのう]し得[う]る一方[いっぽう]で、過剰[かじょう]な流動性[りゅうどうせい]が実体経済[じったいけいざい]における物価上昇圧力[ぶっかじょうしょうあつりょく]と相乗効果[そうじょうこうか]を生[う]み、予期[よき]せぬスタグフレーションや財政主導[ざいせいしゅどう]のシナリオへと帰結[きけつ]するリスクを常[つね]に内包[ないほう]していることを、我々[われわれ]は冷徹[れいてつ]に認識[にんしき]する責務[せきむ]を負[お]っている。", "sentence_source": "mined"}, {"text": "水の圧力は強い。", "target_word": "圧力", "complexity_tier": "T1", "furigana": "水[みず]の圧力[あつりょく]は強[つよ]い。", "sentence_source": "generated"}, {"text": "圧力が高いです。", "target_word": "圧力", "complexity_tier": "T2", "furigana": "圧力[あつりょく]が高[たか]いです。", "sentence_source": "generated"}, {"text": "タイヤの圧力を調べます。", "target_word": "圧力", "complexity_tier": "T2", "furigana": "タイヤの圧力[あつりょく]を調[しら]べます。", "sentence_source": "generated"}, {"text": "深い海では、水の圧力がとても高い。", "target_word": "圧力", "complexity_tier": "T3", "furigana": "深[ふか]い海[うみ]では、水[みず]の圧力[あつりょく]がとても高[たか]い。", "sentence_source": "generated"}, {"text": "周りの圧力に負けずに、自分の意見を言った。", "target_word": "圧力", "complexity_tier": "T3", "furigana": "周[まわ]りの圧力[あつりょく]に負[ま]けずに、自分[じぶん]の意見[いけん]を言[い]った。", "sentence_source": "generated"}, {"text": "国民の圧力で、政府は方針を変えた。", "target_word": "圧力", "complexity_tier": "T3", "furigana": "国民[こくみん]の圧力[あつりょく]で、政府[せいふ]は方針[ほうしん]を変[か]えた。", "sentence_source": "generated"}, {"text": "上司から圧力をかけられた。", "target_word": "圧力", "complexity_tier": "T4", "furigana": "上司[じょうし]から圧力[あつりょく]をかけられた。", "sentence_source": "generated"}, {"text": "この鍋は、中の圧力を高めて食べ物を早く煮る。", "target_word": "圧力", "complexity_tier": "T4", "furigana": "この鍋[なべ]は、中[なか]の圧力[あつりょく]を高[たか]めて食[た]べ物[もの]を早[はや]く煮[に]る。", "sentence_source": "generated"}, {"text": "強い圧力を感じながらも、彼は最後まで走り続けた。", "target_word": "圧力", "complexity_tier": "T4", "furigana": "強[つよ]い圧力[あつりょく]を感[かん]じながらも、彼[かれ]は最後[さいご]まで走[はし]り続[つづ]けた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "圧力団体", "label": "派生"}, {"form": "圧力計", "label": "派生"}, {"form": "圧力鍋", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 物を押す力や人への強い影響", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T2: contains vocabulary far above tier T2: スタグフレーション (Zipf 1.93)']::text[], '2f21d344-fdd8-4556-ab3d-6bddeaf03a3b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35239, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "圧力", "is_correct": true, "explanation": "物価を押し上げる力として「物価上昇圧力」の意味に合います。"}, {"text": "帽子", "is_correct": false, "explanation": "形は合うが、「物価上昇帽子」では意味が合わない。"}, {"text": "野菜", "is_correct": false, "explanation": "形は合うが、「物価上昇野菜」では意味が合わない。"}, {"text": "机", "is_correct": false, "explanation": "形は合うが、「物価上昇机」では意味が合わない。"}], "explanations": {"圧力": "物価を押し上げる力として「物価上昇圧力」の意味に合います。", "帽子": "形は合うが、「物価上昇帽子」では意味が合わない。", "野菜": "形は合うが、「物価上昇野菜」では意味が合わない。", "机": "形は合うが、「物価上昇机」では意味が合わない。"}, "sentence_index": 0, "correct_answer": "圧力"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "圧力を食べて、おなかがいっぱいになった。", "explanation": "圧力は食べ物ではないので、使い方が誤りです。"}, {"text": "窓の外の圧力は、赤くてとても甘い。", "explanation": "圧力は味や色のある物ではないので誤りです。"}, {"text": "圧力が三人、教室に入ってきた。", "explanation": "圧力は人ではなく力なので、人の数え方は誤りです。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13322750-3a4e-4704-999d-63599f3d62c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35239, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "圧力", "is_correct": true, "explanation": "国民が政府に与えた強い影響という意味に合います。"}, {"text": "靴下", "is_correct": false, "explanation": "形は合うが、国民の靴下で方針を変えるのは意味が合わない。"}, {"text": "天気", "is_correct": false, "explanation": "形は合うが、国民の天気で方針を変えるのは意味が合わない。"}, {"text": "辞書", "is_correct": false, "explanation": "形は合うが、国民の辞書で方針を変えるのは意味が合わない。"}], "explanations": {"圧力": "国民が政府に与えた強い影響という意味に合います。", "靴下": "形は合うが、国民の靴下で方針を変えるのは意味が合わない。", "天気": "形は合うが、国民の天気で方針を変えるのは意味が合わない。", "辞書": "形は合うが、国民の辞書で方針を変えるのは意味が合わない。"}, "sentence_index": 6, "correct_answer": "圧力"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "圧力を拾って、ポケットに入れた。", "explanation": "圧力は拾える物ではないので誤りです。"}, {"text": "強い圧力を飲みながら、彼は最後まで走り続けた。", "explanation": "圧力は飲む物ではないので誤りです。"}, {"text": "圧力の色は青くて、とても長い。", "explanation": "圧力は色や長さを持つ物ではないので誤りです。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13322750-3a4e-4704-999d-63599f3d62c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35239, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "ガスの圧力が調べます。", "corrected_sentence": "ガスの圧力を調べます。", "error_description": "「調べる」の対象を示す助詞は「が」ではなく「を」です。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13322750-3a4e-4704-999d-63599f3d62c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35239, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "周りの圧力を負けずに、自分の意見を言った。", "corrected_sentence": "周りの圧力に負けずに、自分の意見を言った。", "error_description": "「圧力」に負ける、と言うので、助詞は「を」ではなく「に」です。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13322750-3a4e-4704-999d-63599f3d62c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35242, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「インクがなくなった」の主語を示す「が」で、文が自然に通る。"}, {"text": "を", "is_correct": false, "explanation": "「なくなる」は目的語を取らないので、「を」は入らない。"}, {"text": "で", "is_correct": false, "explanation": "「インクでなくなった」は手段の意味になり、文の意味が通らない。"}, {"text": "と", "is_correct": false, "explanation": "「インクとなくなった」は文が成り立たない。"}], "correct_answer": "が", "explanations": {"が": "「インクがなくなった」の主語を示す「が」で、文が自然に通る。", "を": "「なくなる」は目的語を取らないので、「を」は入らない。", "で": "「インクでなくなった」は手段の意味になり、文の意味が通らない。", "と": "「インクとなくなった」は文が成り立たない。"}, "error_tags": {"を": "目的語の助詞", "で": "手段の助詞", "と": "相手の助詞"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19836b82-001c-42e6-ba97-1d1bf9ed206d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35242, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「インクを集める」と集める対象を示す「を」で、文が自然に通る。"}, {"text": "で", "is_correct": false, "explanation": "「インクで集める」は手段の意味になり、集める対象を示せない。"}, {"text": "が", "is_correct": false, "explanation": "「インクが集める」は主語になり、「姉は」と合わず文が崩れる。"}, {"text": "と", "is_correct": false, "explanation": "「インクと集める」は相手を表すことになり、対象の文脈に合わない。"}], "correct_answer": "を", "explanations": {"を": "「インクを集める」と集める対象を示す「を」で、文が自然に通る。", "で": "「インクで集める」は手段の意味になり、集める対象を示せない。", "が": "「インクが集める」は主語になり、「姉は」と合わず文が崩れる。", "と": "「インクと集める」は相手を表すことになり、対象の文脈に合わない。"}, "error_tags": {"で": "手段の助詞", "が": "主語の助詞", "と": "相手の助詞"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19836b82-001c-42e6-ba97-1d1bf9ed206d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35242, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "紙に字を書くときに使う、色のついた水。", "primary_collocate": null, "pronunciation": "いんく", "ipa": "iŋkɯ", "syllable_count": 3, "sentences": [{"text": "このペンは、青いインクで書きます。", "target_word": "インク", "complexity_tier": "T2", "furigana": "このペンは、青[あお]いインクで書[か]きます。", "sentence_source": "generated"}, {"text": "インクがなくなったので、買いに行きます。", "target_word": "インク", "complexity_tier": "T2", "furigana": "インクがなくなったので、買[か]いに行[い]きます。", "sentence_source": "generated"}, {"text": "机の上にインクをこぼしてしまいました。", "target_word": "インク", "complexity_tier": "T2", "furigana": "机[つくえ]の上[うえ]にインクをこぼしてしまいました。", "sentence_source": "generated"}, {"text": "手にインクがついて、黒くなりました。", "target_word": "インク", "complexity_tier": "T3", "furigana": "手[て]にインクがついて、黒[くろ]くなりました。", "sentence_source": "generated"}, {"text": "先生は、赤いインクで答えを直しました。", "target_word": "インク", "complexity_tier": "T3", "furigana": "先生[せんせい]は、赤[あか]いインクで答[こた]えを直[なお]しました。", "sentence_source": "generated"}, {"text": "万年筆に、新しいインクを入れました。", "target_word": "インク", "complexity_tier": "T3", "furigana": "万年筆[まんねんひつ]に、新[あたら]しいインクを入[い]れました。", "sentence_source": "generated"}, {"text": "インクが乾く前にさわると、字がにじみます。", "target_word": "インク", "complexity_tier": "T3", "furigana": "インクが乾[かわ]く前[まえ]にさわると、字[じ]がにじみます。", "sentence_source": "generated"}, {"text": "姉は、きれいな色のインクを集めています。", "target_word": "インク", "complexity_tier": "T3", "furigana": "姉[あね]は、きれいな色[いろ]のインクを集[あつ]めています。", "sentence_source": "generated"}, {"text": "水に落ちて、インクの字が消えてしまいました。", "target_word": "インク", "complexity_tier": "T3", "furigana": "水[みず]に落[お]ちて、インクの字[じ]が消[き]えてしまいました。", "sentence_source": "generated"}, {"text": "絵をかくために、黒いインクを使います。", "target_word": "インク", "complexity_tier": "T3", "furigana": "絵[え]をかくために、黒[くろ]いインクを使[つか]います。", "sentence_source": "generated"}], "morphological_forms": [{"form": "インク", "label": "基本形"}], "register": "標準（丁寧体）", "sense_fingerprint": "ペンなどで字を書くときに使う色のついた液体", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a823ebd7-d8b4-4527-9bc5-56dd45c51f93') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35242, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "インク", "is_correct": true, "explanation": "色のついた水の意味で、「青いインクで書きます」として自然に入る。"}, {"text": "消しゴム", "is_correct": false, "explanation": "消しゴムで字を書くことはなく、ここには入らない。"}, {"text": "定規", "is_correct": false, "explanation": "定規で字を書くことはなく、文が成り立たない。"}, {"text": "ホッチキス", "is_correct": false, "explanation": "ホッチキスは紙をとじる道具で、字を書く材料にはならない。"}], "explanations": {"インク": "色のついた水の意味で、「青いインクで書きます」として自然に入る。", "消しゴム": "消しゴムで字を書くことはなく、ここには入らない。", "定規": "定規で字を書くことはなく、文が成り立たない。", "ホッチキス": "ホッチキスは紙をとじる道具で、字を書く材料にはならない。"}, "sentence_index": 0, "correct_answer": "インク"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "紙と紙を、インクで貼り合わせました。", "explanation": "ここは〈のり〉の意味。インクは字を書くための色水で、ものを貼り合わせる働きはない。"}, {"text": "壁をインクで塗りました。", "explanation": "ここは〈ペンキ〉の意味。インクは紙に字や線を書く液体で、壁を塗る材料としては使わない。"}, {"text": "爪をインクで塗りました。", "explanation": "ここは〈マニキュア〉の意味。インクは紙に書くためのもので、爪に使う液体ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19836b82-001c-42e6-ba97-1d1bf9ed206d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35242, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "インク", "is_correct": true, "explanation": "乾くと字がにじむ液体の意味で、「インクが乾く前に」として自然に入る。"}, {"text": "ケーキ", "is_correct": false, "explanation": "ケーキは乾くものではなく、字がにじむ文脈に合わない。"}, {"text": "おにぎり", "is_correct": false, "explanation": "おにぎりが乾く前に字がにじむことはなく、文が成り立たない。"}, {"text": "座布団", "is_correct": false, "explanation": "座布団には字をにじませる性質はなく、ここには入らない。"}], "explanations": {"インク": "乾くと字がにじむ液体の意味で、「インクが乾く前に」として自然に入る。", "ケーキ": "ケーキは乾くものではなく、字がにじむ文脈に合わない。", "おにぎり": "おにぎりが乾く前に字がにじむことはなく、文が成り立たない。", "座布団": "座布団には字をにじませる性質はなく、ここには入らない。"}, "sentence_index": 6, "correct_answer": "インク"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "お皿をインクで洗いました。", "explanation": "ここは〈洗剤〉の意味。インクは色のついた液体で、汚れを落とす用途には使わない。"}, {"text": "インクをすって、字を書きます。", "explanation": "ここは〈墨〉の意味。墨は使う前にすって作るが、インクはすって使うものではない。"}, {"text": "インクをこねて、人形を作ります。", "explanation": "ここは〈粘土〉の意味。インクは液体で、こねて形を作る材料ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19836b82-001c-42e6-ba97-1d1bf9ed206d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35242, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "ボールペンは、黒いインクで切れやすいです。", "corrected_sentence": "ボールペンは、黒いインクが切れやすいです。", "error_description": "「インクが切れる」は主語を「が」で受ける。「で」にしたのが誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19836b82-001c-42e6-ba97-1d1bf9ed206d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35242, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "ペンにインクが入れます。", "corrected_sentence": "ペンにインクを入れます。", "error_description": "「入れる」の目的語であるインクは「を」で示す。「が」にすると誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19836b82-001c-42e6-ba97-1d1bf9ed206d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
