INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35243, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「インクが売られている」の主語を示す「が」で、文が通る。"}, {"text": "を", "is_correct": false, "explanation": "受け身の「売られている」では、インクは主語になるので「を」は入らない。"}, {"text": "と", "is_correct": false, "explanation": "「インクと売られている」は相手を表すことになり、文が成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「インクへ売られている」は方向の意味になり、売られる文脈に合わない。"}], "correct_answer": "が", "explanations": {"が": "「インクが売られている」の主語を示す「が」で、文が通る。", "を": "受け身の「売られている」では、インクは主語になるので「を」は入らない。", "と": "「インクと売られている」は相手を表すことになり、文が成り立たない。", "へ": "「インクへ売られている」は方向の意味になり、売られる文脈に合わない。"}, "error_tags": {"を": "目的語の助詞", "と": "相手の助詞", "へ": "方向の助詞"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19836b82-001c-42e6-ba97-1d1bf9ed206d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35243, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "筆記や印刷に使う、顔料や染料を溶かした液体。ペンや印刷機で紙に転写する。", "primary_collocate": null, "pronunciation": "いんく", "ipa": "iŋkɯ", "syllable_count": 3, "sentences": [{"text": "プリンターのインクが切れたので、交換しました。", "target_word": "インク", "complexity_tier": "T3", "furigana": "プリンターのインクが切[き]れたので、交換[こうかん]しました。", "sentence_source": "generated"}, {"text": "このインクは、水に濡れても落ちにくいです。", "target_word": "インク", "complexity_tier": "T3", "furigana": "このインクは、水[みず]に濡[ぬ]れても落[お]ちにくいです。", "sentence_source": "generated"}, {"text": "印刷機は、紙にインクを移して文字を刷ります。", "target_word": "インク", "complexity_tier": "T3", "furigana": "印刷機[いんさつき]は、紙[かみ]にインクを移[うつ]して文字[もじ]を刷[す]ります。", "sentence_source": "generated"}, {"text": "顔料のインクは、染料のインクより色あせにくいです。", "target_word": "インク", "complexity_tier": "T4", "furigana": "顔料[がんりょう]のインクは、染料[せんりょう]のインクより色[いろ]あせにくいです。", "sentence_source": "generated"}, {"text": "ボールペンのインクが、かばんの中で漏れました。", "target_word": "インク", "complexity_tier": "T3", "furigana": "ボールペンのインクが、かばんの中[なか]で漏[も]れました。", "sentence_source": "generated"}, {"text": "新聞の印刷には、速く乾くインクが使われます。", "target_word": "インク", "complexity_tier": "T4", "furigana": "新聞[しんぶん]の印刷[いんさつ]には、速[はや]く乾[かわ]くインクが使[つか]われます。", "sentence_source": "generated"}, {"text": "インクの色が薄いので、濃いものに変えましょう。", "target_word": "インク", "complexity_tier": "T3", "furigana": "インクの色[いろ]が薄[うす]いので、濃[こ]いものに変[か]えましょう。", "sentence_source": "generated"}, {"text": "専門店では、さまざまな種類のインクが売られています。", "target_word": "インク", "complexity_tier": "T4", "furigana": "専門店[せんもんてん]では、さまざまな種類[しゅるい]のインクが売[う]られています。", "sentence_source": "generated"}, {"text": "契約書にサインをするとき、消えないインクを使ってください。", "target_word": "インク", "complexity_tier": "T4", "furigana": "契約書[けいやくしょ]にサインをするとき、消[き]えないインクを使[つか]ってください。", "sentence_source": "generated"}, {"text": "古い本には、インクの匂いが少し残っています。", "target_word": "インク", "complexity_tier": "T4", "furigana": "古[ふる]い本[ほん]には、インクの匂[にお]いが少[すこ]し残[のこ]っています。", "sentence_source": "generated"}], "morphological_forms": [{"form": "インク", "label": "基本形"}], "register": "標準（丁寧体）", "sense_fingerprint": "筆記や印刷で紙に転写する、顔料や染料を溶かした液体", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a823ebd7-d8b4-4527-9bc5-56dd45c51f93') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35243, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "インク", "is_correct": true, "explanation": "プリンターのインクの意味で、「インクが切れた」として自然に入る。"}, {"text": "スプーン", "is_correct": false, "explanation": "プリンターのスプーンは存在せず、文が成り立たない。"}, {"text": "手袋", "is_correct": false, "explanation": "「プリンターの手袋」は意味が通らず、ここには入らない。"}, {"text": "歯ブラシ", "is_correct": false, "explanation": "歯ブラシはプリンターの部品ではなく、交換の文脈に合わない。"}], "explanations": {"インク": "プリンターのインクの意味で、「インクが切れた」として自然に入る。", "スプーン": "プリンターのスプーンは存在せず、文が成り立たない。", "手袋": "「プリンターの手袋」は意味が通らず、ここには入らない。", "歯ブラシ": "歯ブラシはプリンターの部品ではなく、交換の文脈に合わない。"}, "sentence_index": 0, "correct_answer": "インク"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "木材を、インクでしっかり接着しました。", "explanation": "ここは〈ボンド〉の意味。インクは色のついた液体で、接着の働きはない。"}, {"text": "インクを塗る前に、表面をよく磨きます。", "explanation": "ここは〈ペンキ〉の意味。インクは塗る材料ではなく、印刷や筆記に使う液体なので、塗る前提の文には合わない。"}, {"text": "インクで、歯をみがきます。", "explanation": "ここは〈歯磨き粉〉の意味。インクは歯を磨くものではなく、この用途には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19836b82-001c-42e6-ba97-1d1bf9ed206d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35243, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "インク", "is_correct": true, "explanation": "色の薄さを話す対象で、「インクの色が薄い」として自然に入る。"}, {"text": "コンセント", "is_correct": false, "explanation": "コンセントは色の薄さを話す対象ではなく、文が成り立たない。"}, {"text": "ガス", "is_correct": false, "explanation": "「ガスの色が薄い」という言い方は成り立たず、ここには入らない。"}, {"text": "水道", "is_correct": false, "explanation": "「水道の色が薄い」という文脈はなく、ここには入らない。"}], "explanations": {"インク": "色の薄さを話す対象で、「インクの色が薄い」として自然に入る。", "コンセント": "コンセントは色の薄さを話す対象ではなく、文が成り立たない。", "ガス": "「ガスの色が薄い」という言い方は成り立たず、ここには入らない。", "水道": "「水道の色が薄い」という文脈はなく、ここには入らない。"}, "sentence_index": 6, "correct_answer": "インク"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "朝、インクをまぶたにのせて、色をつけた。", "explanation": "ここは〈アイシャドウ〉の意味。インクは紙に書くための液体で、まぶたに使う化粧品ではない。"}, {"text": "インクは、爪に塗るための液体です。", "explanation": "ここは〈マニキュア〉の意味。インクは爪に塗るものではなく、紙に書くための液体。"}, {"text": "インクで、お皿を洗います。", "explanation": "ここは〈食器用洗剤〉の意味。インクは汚れを落とす液体ではなく、洗う用途には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19836b82-001c-42e6-ba97-1d1bf9ed206d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35243, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "消えないインクを、箱に番号を書きました。", "corrected_sentence": "消えないインクで、箱に番号を書きました。", "error_description": "書く道具・材料を示すのは「で」。「を」にすると、インクを書く対象にしてしまい誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19836b82-001c-42e6-ba97-1d1bf9ed206d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35243, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "古い本のインクを、紙に染み込みます。", "corrected_sentence": "古い本のインクは、紙に染み込みます。", "error_description": "「染み込む」の主語はインクなので「は」で示す。「を」にしたのが誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19836b82-001c-42e6-ba97-1d1bf9ed206d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35261, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「毎日の練習の蓄積」が主語となり、大会で大きな力になったという文の主語を示す。"}, {"text": "を", "is_correct": false, "explanation": "「蓄積を」は蓄積を何かに働きかける形になるが、ここは蓄積そのものが大きな力になる主語の文なので合わない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すので、蓄積が力になるという主語の文には合わない。"}, {"text": "に", "is_correct": false, "explanation": "「蓄積に」は到達点や相手を示すが、蓄積が大会で力になるという主語の文には合わない。"}], "correct_answer": "が", "explanations": {"が": "「毎日の練習の蓄積」が主語となり、大会で大きな力になったという文の主語を示す。", "を": "「蓄積を」は蓄積を何かに働きかける形になるが、ここは蓄積そのものが大きな力になる主語の文なので合わない。", "へ": "「へ」は方向を示すので、蓄積が力になるという主語の文には合わない。", "に": "「蓄積に」は到達点や相手を示すが、蓄積が大会で力になるという主語の文には合わない。"}, "error_tags": {"を": "object marker", "へ": "direction", "に": "goal or recipient"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ea9fa82-6a8e-445f-8c7b-21bcfdb23706') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35261, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ea9fa82-6a8e-445f-8c7b-21bcfdb23706') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35261, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "物や知識などを少しずつ集めて、たくさんにすること。また、その集まったもの。", "primary_collocate": null, "pronunciation": "ちくせき", "ipa": "tɕikuseki", "syllable_count": 4, "sentences": [{"text": "かかる感覚的知見の蓄積は、単一品種を基準とした旧来の分類体系を相対化し、微細な区画ごとの個性を階層的に位置づけるアペラシオンの概念を、より厳密かつ動的なヒエラルキーへと昇華させ、ワインの価値評価基準そのものを哲学的かつ実践的に再定義しているのである。", "target_word": "蓄積", "complexity_tier": "T5", "furigana": "かかる感覚的(かんかくてき)知見(ちけん)の蓄積(ちくせき)は、単一(たんいつ)品種(ひんしゅ)を基準(きじゅん)とした旧来(きゅうらい)の分類(ぶんるい)体系(たいけい)を相対化(そうたいか)し、微細(びさい)な区画(くかく)ごとの個性(こせい)を階層的(かいそうてき)に位置(いち)づけるアペラシオンの概念(がいねん)を、より厳密(げんみつ)かつ動的(どうてき)なヒエラルキーへと昇華(しょうか)させ、ワインの価値(かち)評価(ひょうか)基準(きじゅん)そのものを哲学的(てつがくてき)かつ実践的(じっせんてき)に再定義(さいていぎ)しているのである。", "sentence_source": "mined"}, {"text": "毎日の練習の蓄積が、大会で大きな力になった。", "target_word": "蓄積", "complexity_tier": "T3", "furigana": "毎日(まいにち)の練習(れんしゅう)の蓄積(ちくせき)が、大会(たいかい)で大(おお)きな力(ちから)になった。", "sentence_source": "generated"}, {"text": "長年の経験の蓄積があるので、彼の判断は信頼できる。", "target_word": "蓄積", "complexity_tier": "T4", "furigana": "長年(ながねん)の経験(けいけん)の蓄積(ちくせき)があるので、彼(かれ)の判断(はんだん)は信頼(しんらい)できる。", "sentence_source": "generated"}, {"text": "疲労が蓄積すると、風邪をひきやすくなる。", "target_word": "蓄積", "complexity_tier": "T4", "furigana": "疲労(ひろう)が蓄積(ちくせき)すると、風邪(かぜ)をひきやすくなる。", "sentence_source": "generated"}, {"text": "この会社は、研究データの蓄積では他社に負けない。", "target_word": "蓄積", "complexity_tier": "T4", "furigana": "この会社(かいしゃ)は、研究(けんきゅう)データの蓄積(ちくせき)では他社(たしゃ)に負(ま)けない。", "sentence_source": "generated"}, {"text": "脂肪が体に蓄積するのを防ぐため、夜遅い食事をやめた。", "target_word": "蓄積", "complexity_tier": "T4", "furigana": "脂肪(しぼう)が体(からだ)に蓄積(ちくせき)するのを防(ふせ)ぐため、夜遅(よるおそ)い食事(しょくじ)をやめた。", "sentence_source": "generated"}, {"text": "少しずつの蓄積でも、十年たてばたくさんになる。", "target_word": "蓄積", "complexity_tier": "T3", "furigana": "少(すこ)しずつの蓄積(ちくせき)でも、十年(じゅうねん)たてばたくさんになる。", "sentence_source": "generated"}, {"text": "知識の蓄積は、本を読み続けることでしか得られない。", "target_word": "蓄積", "complexity_tier": "T4", "furigana": "知識(ちしき)の蓄積(ちくせき)は、本(ほん)を読(よ)み続(つづ)けることでしか得(え)られない。", "sentence_source": "generated"}, {"text": "過去の災害の記録の蓄積が、防災計画の見直しにつながった。", "target_word": "蓄積", "complexity_tier": "T3", "furigana": "過去(かこ)の災害(さいがい)の記録(きろく)の蓄積(ちくせき)が、防災(ぼうさい)計画(けいかく)の見直(みなお)しにつながった。", "sentence_source": "generated"}, {"text": "ストレスの蓄積に気づかず、ついに倒れてしまった。", "target_word": "蓄積", "complexity_tier": "T4", "furigana": "ストレスの蓄積(ちくせき)に気(き)づかず、ついに倒(たお)れてしまった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "蓄積する", "label": "サ変動詞"}, {"form": "蓄積される", "label": "受身形"}, {"form": "蓄積した", "label": "過去形"}], "register": "formal", "sense_fingerprint": "物・知識・疲れなどが少しずつたまって増えること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T3: contains vocabulary far above tier T3: アペラシオン (Zipf 1.01)']::text[], '32b69eeb-98c8-40d8-b5f5-d42b8a81ba55') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35261, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "蓄積", "is_correct": true, "explanation": "文の主語として、積み重ねた知見が土台になって相対化や再定義を生むという流れに合う。"}, {"text": "欠如", "is_correct": false, "explanation": "欠如は足りない状態を表すので、知見が欠けた状態が再定義の土台になるという文意に合わない。"}, {"text": "解消", "is_correct": false, "explanation": "解消は問題や不足を取り除く意味で、積み重ねた知見を取り除く文になり、後の再定義と逆の流れになる。"}, {"text": "散逸", "is_correct": false, "explanation": "散逸は散らばって失われることで、集めた知見が土台になるという流れと正反対になる。"}], "explanations": {"蓄積": "文の主語として、積み重ねた知見が土台になって相対化や再定義を生むという流れに合う。", "欠如": "欠如は足りない状態を表すので、知見が欠けた状態が再定義の土台になるという文意に合わない。", "解消": "解消は問題や不足を取り除く意味で、積み重ねた知見を取り除く文になり、後の再定義と逆の流れになる。", "散逸": "散逸は散らばって失われることで、集めた知見が土台になるという流れと正反対になる。"}, "sentence_index": 0, "correct_answer": "蓄積"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この地域には工場が蓄積している。", "explanation": "ここは〈集積〉の意味。工場が一か所に集まる状態は集積と言い、蓄積は時間をかけて少しずつたまることを指すので合わない。"}, {"text": "切手を蓄積するのが趣味だ。", "explanation": "ここは〈収集〉の意味。珍しい物を趣味で集めることは「収集」と言い、蓄積は時間をかけてたまることを表すので合わない。"}, {"text": "アイデアが一瞬で蓄積した。", "explanation": "ここは〈ひらめく〉の意味。思いつきが一瞬で浮かぶことは「ひらめく」と言い、蓄積は少しずつ長い時間をかけてたまることを指すので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ea9fa82-6a8e-445f-8c7b-21bcfdb23706') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35261, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "蓄積", "is_correct": true, "explanation": "「少しずつの蓄積」が主語で、十年たてばたくさんになるという文の流れに合う。"}, {"text": "消失", "is_correct": false, "explanation": "消失は無くなることを表すので、少しずつ増えて十年後に多くなるという流れと逆になる。"}, {"text": "撤回", "is_correct": false, "explanation": "撤回は取り消すことなので、少しずつ増えて多くなるという内容とつながらない。"}, {"text": "解雇", "is_correct": false, "explanation": "解雇は職を失わせることで、数量が少しずつ増えてたくさんになるという文と合わない。"}], "explanations": {"蓄積": "「少しずつの蓄積」が主語で、十年たてばたくさんになるという文の流れに合う。", "消失": "消失は無くなることを表すので、少しずつ増えて十年後に多くなるという流れと逆になる。", "撤回": "撤回は取り消すことなので、少しずつ増えて多くなるという内容とつながらない。", "解雇": "解雇は職を失わせることで、数量が少しずつ増えてたくさんになるという文と合わない。"}, "sentence_index": 6, "correct_answer": "蓄積"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は勉強に蓄積して、時間を忘れた。", "explanation": "ここは〈集中〉の意味。勉強に心を向けて没頭することは集中と言い、蓄積は少しずつたまることなので合わない。"}, {"text": "荷物をトラックに蓄積して運んだ。", "explanation": "ここは〈積載〉の意味。車などに荷を載せることは積載と言い、蓄積は時間をかけて集まることを指すので合わない。"}, {"text": "胃で食べ物を蓄積して、栄養にした。", "explanation": "ここは〈消化〉の意味。胃が食べ物を分解することは消化と言い、蓄積は少しずつたまることなので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ea9fa82-6a8e-445f-8c7b-21bcfdb23706') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35261, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "連日の夜更かしで、疲労が蓄積ました。", "corrected_sentence": "連日の夜更かしで、疲労が蓄積しました。", "error_description": "「蓄積」はサ変動詞なので過去形は「蓄積しました」になる。「蓄積ました」は「し」が抜けた誤りで、正しくは「蓄積しました」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ea9fa82-6a8e-445f-8c7b-21bcfdb23706') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35261, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "毎月の少額の貯金が蓄積て、大きな額になった。", "corrected_sentence": "毎月の少額の貯金が蓄積して、大きな額になった。", "error_description": "「蓄積」はサ変動詞なので連用形は「蓄積し」になる。「蓄積て」は「し」が抜けた誤りで、正しくは「蓄積して」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ea9fa82-6a8e-445f-8c7b-21bcfdb23706') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
