INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35268, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "一部の人だけが持っている、特別なことができる力や権利。", "primary_collocate": null, "pronunciation": "とっけん", "ipa": "tokkeɴ", "syllable_count": 4, "sentences": [{"text": "姉は長女の特権として、家でいちばん大きい部屋を使っている。", "target_word": "特権", "complexity_tier": "T3", "furigana": "姉[あね]は長女[ちょうじょ]の特権[とっけん]として、家[いえ]でいちばん大[おお]きい部屋[へや]を使[つか]っている。", "sentence_source": "generated"}, {"text": "優勝したチームには、記念の試合で最初に打つ特権が与えられた。", "target_word": "特権", "complexity_tier": "T3", "furigana": "優勝[ゆうしょう]したチームには、記念[きねん]の試合[しあい]で最初[さいしょ]に打[う]つ特権[とっけん]が与[あた]えられた。", "sentence_source": "generated"}, {"text": "社長の特権を使って、彼は自分専用の駐車場を社内に作らせた。", "target_word": "特権", "complexity_tier": "T3", "furigana": "社長[しゃちょう]の特権[とっけん]を使[つか]って、彼[かれ]は自分専用[じぶんせんよう]の駐車場[ちゅうしゃじょう]を社内[しゃない]に作[つく]らせた。", "sentence_source": "generated"}, {"text": "年上だからといって、人に命令する特権があるわけではない。", "target_word": "特権", "complexity_tier": "T3", "furigana": "年上[としうえ]だからといって、人[ひと]に命令[めいれい]する特権[とっけん]があるわけではない。", "sentence_source": "generated"}, {"text": "最初に新製品を試せるのは、開発者だけの特権だ。", "target_word": "特権", "complexity_tier": "T3", "furigana": "最初[さいしょ]に新製品[しんせいひん]を試[ため]せるのは、開発者[かいはつしゃ]だけの特権[とっけん]だ。", "sentence_source": "generated"}, {"text": "学生だけの特権は、時間をたっぷり使って勉強できることだ。", "target_word": "特権", "complexity_tier": "T3", "furigana": "学生[がくせい]だけの特権[とっけん]は、時間[じかん]をたっぷり使[つか]って勉強[べんきょう]できることだ。", "sentence_source": "generated"}, {"text": "子どもの特権は、失敗しても笑って許してもらえることだ。", "target_word": "特権", "complexity_tier": "T3", "furigana": "子[こ]どもの特権[とっけん]は、失敗[しっぱい]しても笑[わら]って許[ゆる]してもらえることだ。", "sentence_source": "generated"}, {"text": "大統領は、一部の情報を秘密にする特権を持っている。", "target_word": "特権", "complexity_tier": "T3", "furigana": "大統領[だいとうりょう]は、一部[いちぶ]の情報[じょうほう]を秘密[ひみつ]にする特権[とっけん]を持[も]っている。", "sentence_source": "generated"}, {"text": "彼は特権を振りかざして、列に並ばずに店に入った。", "target_word": "特権", "complexity_tier": "T3", "furigana": "彼[かれ]は特権[とっけん]を振[ふ]りかざして、列[れつ]に並[なら]ばずに店[みせ]に入[はい]った。", "sentence_source": "generated"}, {"text": "弁護士には、依頼人との会話を秘密にする特権がある。", "target_word": "特権", "complexity_tier": "T3", "furigana": "弁護士[べんごし]には、依頼人[いらいにん]との会話[かいわ]を秘密[ひみつ]にする特権[とっけん]がある。", "sentence_source": "generated"}], "morphological_forms": [{"form": "特権", "label": "基本形"}, {"form": "特権的", "label": "〜的"}], "register": "やや硬い", "sense_fingerprint": "一部の人だけができる特別なことをする権利", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad29b17a-8ef9-4f71-bf29-c78f05e924aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35268, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "特権", "is_correct": true, "explanation": "「長女の特権として」で、長女だけに認められた特別な権利という意味になり、文に合う。"}, {"text": "判決", "is_correct": false, "explanation": "裁判所による判断。「長女の判決として」は意味が通らない。"}, {"text": "卒業", "is_correct": false, "explanation": "学校の課程を終えること。「長女の卒業として」は文に合わない。"}, {"text": "宿題", "is_correct": false, "explanation": "学校で出される課題。「長女の宿題として」では、部屋を使う理由になりません。"}], "explanations": {"特権": "「長女の特権として」で、長女だけに認められた特別な権利という意味になり、文に合う。", "判決": "裁判所による判断。「長女の判決として」は意味が通らない。", "卒業": "学校の課程を終えること。「長女の卒業として」は文に合わない。", "宿題": "学校で出される課題。「長女の宿題として」では、部屋を使う理由になりません。"}, "sentence_index": 0, "correct_answer": "特権"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "国民は誰でも、選挙で投票する特権を持っている。", "explanation": "ここは〈権利〉（誰もが持つ権利）の意味。特権は一部の人だけに認められるものなので、誰でも持つ場合には合わない。"}, {"text": "運転者には、信号を守る特権がある。", "explanation": "ここは〈義務〉（守らなければならないこと）の意味。特権は特別に認められた利益や権利なので、守るべき決まりを指す文には合わない。"}, {"text": "この商品には、保証期間の延長という特権がついている。", "explanation": "ここは〈特典〉（おまけとしての利益）の意味。特権は人や集団が持つ権利なので、商品に付くものとしては合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2226ed3-cbf0-4246-82b6-033e0babf68c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35268, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "特権", "is_correct": true, "explanation": "「子どもの特権」で、子どもだけに認められた特別な権利という意味になり、文に合う。"}, {"text": "食卓", "is_correct": false, "explanation": "食事をする台のこと。「子どもの食卓は、失敗しても…」では意味が通らない。"}, {"text": "税金", "is_correct": false, "explanation": "国に納めるお金。失敗を許してもらうことの話とは結びつかない。"}, {"text": "天気", "is_correct": false, "explanation": "空模様のこと。「子どもの天気」とは言えない。"}], "explanations": {"特権": "「子どもの特権」で、子どもだけに認められた特別な権利という意味になり、文に合う。", "食卓": "食事をする台のこと。「子どもの食卓は、失敗しても…」では意味が通らない。", "税金": "国に納めるお金。失敗を許してもらうことの話とは結びつかない。", "天気": "空模様のこと。「子どもの天気」とは言えない。"}, "sentence_index": 6, "correct_answer": "特権"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "捜査を進めるため、検察は特権を立ち上げた。", "explanation": "ここは〈特検〉（特別検察官）の意味。特権は立ち上げる組織ではないので、ここには合わない。"}, {"text": "残業をした社員には、きちんと特権が支払われる。", "explanation": "ここは〈手当〉（給与に加えて支払われる金銭）の意味。特権は金銭ではないので、支払われるものとしては合わない。"}, {"text": "その薬草は、昔から人々の健康に多くの特権を与えてきた。", "explanation": "ここは〈恩恵〉（ありがたい利益）の意味。特権は人や集団に認められる権利で、植物が与えるものではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2226ed3-cbf0-4246-82b6-033e0babf68c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35268, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼は特権な態度で、周りの人を不快にさせた。", "corrected_sentence": "彼は特権的な態度で、周りの人を不快にさせた。", "error_description": "「特権な」は誤り。「特権」は名詞なので、形容動詞として使うには「特権的な」の形にする必要がある。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2226ed3-cbf0-4246-82b6-033e0babf68c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35268, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この地域の住人には、夜間の駐車場を無料で使う特権をある。", "corrected_sentence": "この地域の住人には、夜間の駐車場を無料で使う特権がある。", "error_description": "「特権をある」は誤り。「ある」の主語は「が」で示すので、「特権がある」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2226ed3-cbf0-4246-82b6-033e0babf68c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35269, 3, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2226ed3-cbf0-4246-82b6-033e0babf68c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35269, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「特権を利用して」で、利用する対象を表す正しい助詞。"}, {"text": "が", "is_correct": false, "explanation": "「特権が利用して」は成り立たない。「利用する」は目的語に「を」を取る。"}, {"text": "に", "is_correct": false, "explanation": "「特権に利用して」は不自然。対象を示すには「を」を使う。"}, {"text": "と", "is_correct": false, "explanation": "「特権と利用して」は成り立たない。相手や並列を表す語ではない。"}], "correct_answer": "を", "explanations": {"を": "「特権を利用して」で、利用する対象を表す正しい助詞。", "が": "「特権が利用して」は成り立たない。「利用する」は目的語に「を」を取る。", "に": "「特権に利用して」は不自然。対象を示すには「を」を使う。", "と": "「特権と利用して」は成り立たない。相手や並列を表す語ではない。"}, "error_tags": {"が": "主格", "に": "方向・対象", "と": "相手・並立"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2226ed3-cbf0-4246-82b6-033e0babf68c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35269, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "特定の個人や集団だけが持つ、他の人には認められていない特別な権利や利益。", "primary_collocate": null, "pronunciation": "とっけん", "ipa": "tokkeɴ", "syllable_count": 4, "sentences": [{"text": "すなわち、限られた特権階級のみに奉仕することを潔しとしない独占的な美学こそが、地上に降り立つトレンドの羅針盤としての役割を担い、現代のファッション産業における生態系を永続的に循環させているのである。", "target_word": "特権", "complexity_tier": "T5", "furigana": "すなわち、限[かぎ]られた特権[とっけん]階級[かいきゅう]のみに奉仕[ほうし]することを潔[いさぎよ]しとしない独占的[どくせんてき]な美学[びがく]こそが、地上[ちじょう]に降[お]り立[た]つトレンドの羅針盤[らしんばん]としての役割[やくわり]を担[にな]い、現代[げんだい]のファッション産業[さんぎょう]における生態系[せいたいけい]を永続的[えいぞくてき]に循環[じゅんかん]させているのである。", "sentence_source": "mined"}, {"text": "昔の貴族は、税を払わなくてもよいという特権を持っていた。", "target_word": "特権", "complexity_tier": "T3", "furigana": "昔[むかし]の貴族[きぞく]は、税[ぜい]を払[はら]わなくてもよいという特権[とっけん]を持[も]っていた。", "sentence_source": "generated"}, {"text": "外交官には、法律の一部が適用されないという特権が認められている。", "target_word": "特権", "complexity_tier": "T3", "furigana": "外交官[がいこうかん]には、法律[ほうりつ]の一部[いちぶ]が適用[てきよう]されないという特権[とっけん]が認[みと]められている。", "sentence_source": "generated"}, {"text": "会員だけの特権として、新商品を一般発売の数日前に買うことができる。", "target_word": "特権", "complexity_tier": "T3", "furigana": "会員[かいいん]だけの特権[とっけん]として、新商品[しんしょうひん]を一般発売[いっぱんはつばい]の数日前[すうじつまえ]に買[か]うことができる。", "sentence_source": "generated"}, {"text": "一部の人が特権を守ろうとしたため、社会の改革はなかなか進まなかった。", "target_word": "特権", "complexity_tier": "T3", "furigana": "一部[いちぶ]の人[ひと]が特権[とっけん]を守[まも]ろうとしたため、社会[しゃかい]の改革[かいかく]はなかなか進[すす]まなかった。", "sentence_source": "generated"}, {"text": "大企業だけが特権を得ている制度に、小さな会社から不満の声が出た。", "target_word": "特権", "complexity_tier": "T3", "furigana": "大企業[だいきぎょう]だけが特権[とっけん]を得[え]ている制度[せいど]に、小[ちい]さな会社[かいしゃ]から不満[ふまん]の声[こえ]が出[で]た。", "sentence_source": "generated"}, {"text": "王は、その商人に塩を売る特権を与えた。", "target_word": "特権", "complexity_tier": "T3", "furigana": "王[おう]は、その商人[しょうにん]に塩[しお]を売[う]る特権[とっけん]を与[あた]えた。", "sentence_source": "generated"}, {"text": "政治家が特権を利用して家族に利益を与えたことが、批判された。", "target_word": "特権", "complexity_tier": "T3", "furigana": "政治家[せいじか]が特権[とっけん]を利用[りよう]して家族[かぞく]に利益[りえき]を与[あた]えたことが、批判[ひはん]された。", "sentence_source": "generated"}, {"text": "彼は、特権を失った後、普通の市民と同じ生活を送ることになった。", "target_word": "特権", "complexity_tier": "T3", "furigana": "彼[かれ]は、特権[とっけん]を失[うしな]った後[あと]、普通[ふつう]の市民[しみん]と同[おな]じ生活[せいかつ]を送[おく]ることになった。", "sentence_source": "generated"}, {"text": "国会議員の発言には、会議の中では責任を問われないという特権がある。", "target_word": "特権", "complexity_tier": "T3", "furigana": "国会議員[こっかいぎいん]の発言[はつげん]には、会議[かいぎ]の中[なか]では責任[せきにん]を問[と]われないという特権[とっけん]がある。", "sentence_source": "generated"}], "morphological_forms": [{"form": "特権", "label": "基本形"}, {"form": "特権的", "label": "〜的"}], "register": "やや硬い", "sense_fingerprint": "特定の人だけに認められた権利や利益", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T3: contains vocabulary far above tier T3: 潔し (Zipf 1.9)']::text[], 'ad29b17a-8ef9-4f71-bf29-c78f05e924aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35269, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "特権", "is_correct": true, "explanation": "「一部の大臣だけに許された特権」で、限られた人だけが持つ権利という意味になり、文に合う。"}, {"text": "羅針盤", "is_correct": false, "explanation": "方位を知るための器具。「許された羅針盤」は意味が通らない。"}, {"text": "生態系", "is_correct": false, "explanation": "生物と環境のつながりを指す語。「許された生態系」は意味が通らない。"}, {"text": "循環", "is_correct": false, "explanation": "めぐり巡ること。「許された循環」とは言わない。"}], "explanations": {"特権": "「一部の大臣だけに許された特権」で、限られた人だけが持つ権利という意味になり、文に合う。", "羅針盤": "方位を知るための器具。「許された羅針盤」は意味が通らない。", "生態系": "生物と環境のつながりを指す語。「許された生態系」は意味が通らない。", "循環": "めぐり巡ること。「許された循環」とは言わない。"}, "sentence_index": 0, "correct_answer": "特権"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "すべての国民は、教育を受ける特権を持っている。", "explanation": "ここは〈権利〉（誰もが持つ権利）の意味。特権は特定の人だけに認められるものなので、国民全員に当てはまる場合には合わない。"}, {"text": "親には、子どもを学校に通わせる特権がある。", "explanation": "ここは〈義務〉（しなければならないこと）の意味。特権は特別に認められた利益なので、果たすべき務めを指す文には合わない。"}, {"text": "この商品には、保証期間の延長という特権がついている。", "explanation": "ここは〈特典〉（おまけとしての利益）の意味。特権は人や集団が持つ権利なので、商品に付くものとしては合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2226ed3-cbf0-4246-82b6-033e0babf68c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35269, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "特権", "is_correct": true, "explanation": "「塩を売る特権を与えた」で、売ることを許される特別な権利という意味になり、文に合う。"}, {"text": "税金", "is_correct": false, "explanation": "国や領主に納めるお金。「塩を売る税金を与えた」とは言わない。"}, {"text": "利子", "is_correct": false, "explanation": "借りた金に付くお金。「塩を売る利子を与えた」は意味が通らない。"}, {"text": "借金", "is_correct": false, "explanation": "返すべき金銭。売る行為に対して与えるものではない。"}], "explanations": {"特権": "「塩を売る特権を与えた」で、売ることを許される特別な権利という意味になり、文に合う。", "税金": "国や領主に納めるお金。「塩を売る税金を与えた」とは言わない。", "利子": "借りた金に付くお金。「塩を売る利子を与えた」は意味が通らない。", "借金": "返すべき金銭。売る行為に対して与えるものではない。"}, "sentence_index": 6, "correct_answer": "特権"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "汚職の疑いを調べるため、政府は特権を任命した。", "explanation": "ここは〈特検〉（特別検察官）の意味。特権は人を任命するものではないので、ここには合わない。"}, {"text": "この仕事の特権は、月末にまとめて支払われる。", "explanation": "ここは〈報酬〉（働いた対価の金銭）の意味。特権は金銭ではない権利や利益なので、支払われるものとしては合わない。"}, {"text": "温暖な気候は、農業に大きな特権をもたらした。", "explanation": "ここは〈恩恵〉（ありがたい利益）の意味。特権は人や集団が持つ権利なので、気候がもたらす結果としては合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2226ed3-cbf0-4246-82b6-033e0babf68c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35269, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "会員は、一般客にはない特権に持っている。", "corrected_sentence": "会員は、一般客にはない特権を持っている。", "error_description": "「特権に持っている」は誤り。「持つ」の目的語には「を」を使うので、「特権を持っている」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2226ed3-cbf0-4246-82b6-033e0babf68c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35269, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "市長は、その特権を消費して、家族に便宜を図った。", "corrected_sentence": "市長は、その特権を利用して、家族に便宜を図った。", "error_description": "「特権を消費する」は誤り。特権は使って効果を得るものなので、「特権を利用する」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2226ed3-cbf0-4246-82b6-033e0babf68c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
