INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35271, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2226ed3-cbf0-4246-82b6-033e0babf68c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35271, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "経済的・政治的な地位や権力によって区分された社会の集団。例えば、労働者階級、資本家階級など。", "primary_collocate": null, "pronunciation": "かいきゅう", "ipa": "kaikʲɯː", "syllable_count": 4, "sentences": [{"text": "すなわち、限られた特権階級のみに奉仕することを潔しとしない独占的な美学こそが、地上に降り立つトレンドの羅針盤としての役割を担い、現代のファッション産業における生態系を永続的に循環させているのである。", "target_word": "階級", "complexity_tier": "T5", "furigana": "すなわち、限[かぎ]られた特権[とっけん]階級[かいきゅう]のみに奉仕[ほうし]することを潔[いさぎよ]しとしない独占的[どくせんてき]な美学[びがく]こそが、地上[ちじょう]に降[お]り立[た]つトレンドの羅針盤[らしんばん]としての役割[やくわり]を担[にな]い、現代[げんだい]のファッション産業[さんぎょう]における生態系[せいたいけい]を永続的[えいぞくてき]に循環[じゅんかん]させているのである。", "sentence_source": "mined"}, {"text": "昔のヨーロッパでは、生まれた階級によって、仕事や結婚相手まで決まっていた。", "target_word": "階級", "complexity_tier": "T3", "furigana": "昔[むかし]のヨーロッパでは、生[う]まれた階級[かいきゅう]によって、仕事[しごと]や結婚相手[けっこんあいて]まで決[き]まっていた。", "sentence_source": "generated"}, {"text": "二つの階級の間にある大きな差が、社会の問題になった。", "target_word": "階級", "complexity_tier": "T3", "furigana": "二[ふた]つの階級[かいきゅう]の間[あいだ]にある大[おお]きな差[さ]が、社会[しゃかい]の問題[もんだい]になった。", "sentence_source": "generated"}, {"text": "彼は貧しい階級に生まれたが、努力して政治家になった。", "target_word": "階級", "complexity_tier": "T3", "furigana": "彼[かれ]は貧[まず]しい階級[かいきゅう]に生[う]まれたが、努力[どりょく]して政治家[せいじか]になった。", "sentence_source": "generated"}, {"text": "革命によって、古い階級の支配が終わった。", "target_word": "階級", "complexity_tier": "T3", "furigana": "革命[かくめい]によって、古[ふる]い階級[かいきゅう]の支配[しはい]が終[お]わった。", "sentence_source": "generated"}, {"text": "小説の中で、作者は上の階級の人々の暮らしを皮肉っぽく描いている。", "target_word": "階級", "complexity_tier": "T3", "furigana": "小説[しょうせつ]の中[なか]で、作者[さくしゃ]は上[うえ]の階級[かいきゅう]の人々[ひとびと]の暮[く]らしを皮肉[ひにく]っぽく描[えが]いている。", "sentence_source": "generated"}, {"text": "同じ階級の人としか付き合わない習慣が、その町には残っていた。", "target_word": "階級", "complexity_tier": "T3", "furigana": "同[おな]じ階級[かいきゅう]の人[ひと]としか付[つ]き合[あ]わない習慣[しゅうかん]が、その町[まち]には残[のこ]っていた。", "sentence_source": "generated"}, {"text": "経済が成長すると、新しい階級が生まれて、社会の形が変わる。", "target_word": "階級", "complexity_tier": "T3", "furigana": "経済[けいざい]が成長[せいちょう]すると、新[あたら]しい階級[かいきゅう]が生[う]まれて、社会[しゃかい]の形[かたち]が変[か]わる。", "sentence_source": "generated"}, {"text": "この国では、階級が違っても、同じ学校で学ぶことができる。", "target_word": "階級", "complexity_tier": "T3", "furigana": "この国[くに]では、階級[かいきゅう]が違[ちが]っても、同[おな]じ学校[がっこう]で学[まな]ぶことができる。", "sentence_source": "generated"}, {"text": "歴史の授業で、貴族と市民という二つの階級の対立について学んだ。", "target_word": "階級", "complexity_tier": "T3", "furigana": "歴史[れきし]の授業[じゅぎょう]で、貴族[きぞく]と市民[しみん]という二[ふた]つの階級[かいきゅう]の対立[たいりつ]について学[まな]んだ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "階級", "label": "基本形"}, {"form": "階級的", "label": "〜的"}], "register": "やや硬い", "sense_fingerprint": "地位や権力で分けられた社会の集団", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T3: contains vocabulary far above tier T3: 潔し (Zipf 1.9)']::text[], 'ad29b17a-8ef9-4f71-bf29-c78f05e924aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35271, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "階級", "is_correct": true, "explanation": "「特権階級」で、特権を持つ社会の集団という意味になり、文に合う。"}, {"text": "美学", "is_correct": false, "explanation": "美についての考え方や理論。「特権美学」とは言わない。"}, {"text": "役割", "is_correct": false, "explanation": "任された務めや立場。「特権役割」は意味が通らない。"}, {"text": "循環", "is_correct": false, "explanation": "めぐり巡ること。「特権循環」とは言えない。"}], "explanations": {"階級": "「特権階級」で、特権を持つ社会の集団という意味になり、文に合う。", "美学": "美についての考え方や理論。「特権美学」とは言わない。", "役割": "任された務めや立場。「特権役割」は意味が通らない。", "循環": "めぐり巡ること。「特権循環」とは言えない。"}, "sentence_index": 0, "correct_answer": "階級"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "新学期になり、担任の先生は階級の係を決めた。", "explanation": "ここは〈学級〉（学校のクラス）の意味。階級は社会の身分の区分なので、学校の組の話には使わない。"}, {"text": "この計画は、三つの階級に分けて進めることになった。", "explanation": "ここは〈段階〉（進み具合の区切り）の意味。階級は地位や身分による区分なので、工程の順番には合わない。"}, {"text": "けがをしないよう、階級は手すりをつかんで上ろう。", "explanation": "ここは〈階段〉（建物の上り下りの段）の意味。階級は社会の区分なので、上る対象にはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2226ed3-cbf0-4246-82b6-033e0babf68c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35271, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "階級", "is_correct": true, "explanation": "「同じ階級の人としか付き合わない」で、社会的な身分の区分という意味になり、文に合う。"}, {"text": "天気", "is_correct": false, "explanation": "空模様のこと。「同じ天気の人」とは言わない。"}, {"text": "地震", "is_correct": false, "explanation": "大地の揺れのこと。「同じ地震の人」は意味が通らない。"}, {"text": "樹木", "is_correct": false, "explanation": "木のこと。「同じ樹木の人」は成り立たない。"}], "explanations": {"階級": "「同じ階級の人としか付き合わない」で、社会的な身分の区分という意味になり、文に合う。", "天気": "空模様のこと。「同じ天気の人」とは言わない。", "地震": "大地の揺れのこと。「同じ地震の人」は意味が通らない。", "樹木": "木のこと。「同じ樹木の人」は成り立たない。"}, "sentence_index": 6, "correct_answer": "階級"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この写真は、暗い部分の階級が細かく表現されている。", "explanation": "ここは〈階調〉（色や明るさの段階）の意味。階級は社会の区分なので、写真の明るさには使わない。"}, {"text": "文章は、三つの階級から成っている。", "explanation": "ここは〈段落〉（文章の区切り）の意味。階級は社会の区分なので、文章の構成には使わない。"}, {"text": "このマンションは、階級が多く眺めがよい。", "explanation": "ここは〈階数〉（建物の階の数）の意味。階級は社会の区分なので、建物の階の数には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2226ed3-cbf0-4246-82b6-033e0babf68c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35271, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼女は裕福な階級の生まれたので、大学へ進むことができた。", "corrected_sentence": "彼女は裕福な階級に生まれたので、大学へ進むことができた。", "error_description": "「階級の生まれた」は誤り。「生まれる」は場所や環境を「に」で示すので、「階級に生まれた」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2226ed3-cbf0-4246-82b6-033e0babf68c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35271, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "社会では、階級な差がなくなりつつある。", "corrected_sentence": "社会では、階級の差がなくなりつつある。", "error_description": "「階級な差」は誤り。「階級」は名詞なので、名詞と名詞をつなぐには「の」を使う必要がある。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2226ed3-cbf0-4246-82b6-033e0babf68c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35276, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「中心部に集中している」は「に」で集まる先を示す。〈集中〉は「に」を取る。"}, {"text": "を", "is_correct": false, "explanation": "〈集中〉は「を」を取らないので、「中心部を集中している」は成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は手段や場所を表すため、集まる先を示す「中心部で集中している」は合わない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を表すが、〈集中〉は「へ」ではなく「に」で集まる先を示すので合わない。"}], "correct_answer": "に", "explanations": {"に": "「中心部に集中している」は「に」で集まる先を示す。〈集中〉は「に」を取る。", "を": "〈集中〉は「を」を取らないので、「中心部を集中している」は成り立たない。", "で": "「で」は手段や場所を表すため、集まる先を示す「中心部で集中している」は合わない。", "へ": "「へ」は方向を表すが、〈集中〉は「へ」ではなく「に」で集まる先を示すので合わない。"}, "error_tags": {"を": "対象の格", "で": "手段・場所", "へ": "方向"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "分散", "is_correct": true, "explanation": "〈分散〉は一か所に集まるのとは逆に、散らばって広がるという意味で、〈集中〉の対義語。"}, {"text": "移動", "is_correct": false, "explanation": "場所を変える意味で、一か所に集まる〈集中〉の対義語ではない。"}, {"text": "分解", "is_correct": false, "explanation": "〈分解〉は物を部品に分けるという意味で、集まる・散らばるの対義関係にはならない。"}, {"text": "往来", "is_correct": false, "explanation": "〈往来〉は行き来することで、一か所に集まる〈集中〉の対義語ではない。"}], "correct_answer": "分散", "explanations": {"分散": "〈分散〉は一か所に集まるのとは逆に、散らばって広がるという意味で、〈集中〉の対義語。", "移動": "場所を変える意味で、一か所に集まる〈集中〉の対義語ではない。", "分解": "〈分解〉は物を部品に分けるという意味で、集まる・散らばるの対義関係にはならない。", "往来": "〈往来〉は行き来することで、一か所に集まる〈集中〉の対義語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b5a8c7b-643d-4f5e-afc9-22ef6f2db6a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35276, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「駅の近くに集中している」は「に」で集まる先を示す。〈集中〉は「に」を取る。"}, {"text": "が", "is_correct": false, "explanation": "「が」は主語を示すので、「近くが集中している」は集まる先を示せない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は相手や並列を表すため、集まる先を示す「近くと集中している」は合わない。"}, {"text": "から", "is_correct": false, "explanation": "「から」は起点を表すので、集まる先を示す〈集中〉の文には合わない。"}], "correct_answer": "に", "explanations": {"に": "「駅の近くに集中している」は「に」で集まる先を示す。〈集中〉は「に」を取る。", "が": "「が」は主語を示すので、「近くが集中している」は集まる先を示せない。", "と": "「と」は相手や並列を表すため、集まる先を示す「近くと集中している」は合わない。", "から": "「から」は起点を表すので、集まる先を示す〈集中〉の文には合わない。"}, "error_tags": {"が": "主語", "と": "相手・並列", "から": "起点"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "分散", "is_correct": true, "explanation": "〈分散〉は一か所に集まるのとは逆に、散らばって広がるという意味で、〈集中〉の対義語。"}, {"text": "撤退", "is_correct": false, "explanation": "〈撤退〉は引き下がる意味で、一か所に集まる〈集中〉の対義語ではない。"}, {"text": "放棄", "is_correct": false, "explanation": "〈放棄〉は途中でやめる意味で、集まる・散らばるの対義関係にはならない。"}, {"text": "分担", "is_correct": false, "explanation": "〈分担〉は役割を分け合う意味で、一か所に集まる〈集中〉の対義語ではない。"}], "correct_answer": "分散", "explanations": {"分散": "〈分散〉は一か所に集まるのとは逆に、散らばって広がるという意味で、〈集中〉の対義語。", "撤退": "〈撤退〉は引き下がる意味で、一か所に集まる〈集中〉の対義語ではない。", "放棄": "〈放棄〉は途中でやめる意味で、集まる・散らばるの対義関係にはならない。", "分担": "〈分担〉は役割を分け合う意味で、一か所に集まる〈集中〉の対義語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b5a8c7b-643d-4f5e-afc9-22ef6f2db6a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35276, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "ひとつのところに集まること。", "primary_collocate": null, "pronunciation": "しゅうちゅう", "ipa": "ɕɯːtɕɯː", "syllable_count": 4, "sentences": [{"text": "人口が東京に集中している。", "target_word": "集中", "complexity_tier": "T3", "furigana": "人口[じんこう]が東京[とうきょう]に集中[しゅうちゅう]している。", "sentence_source": "generated"}, {"text": "大きな会社は都市の中心部に集中している。", "target_word": "集中", "complexity_tier": "T3", "furigana": "大[おお]きな会社[かいしゃ]は都市[とし]の中心部[ちゅうしんぶ]に集中[しゅうちゅう]している。", "sentence_source": "generated"}, {"text": "朝の電車は、同じ時間に客が集中して混み合う。", "target_word": "集中", "complexity_tier": "T3", "furigana": "朝[あさ]の電車[でんしゃ]は、同[おな]じ時間[じかん]に客[きゃく]が集中[しゅうちゅう]して混[こ]み合[あ]う。", "sentence_source": "generated"}, {"text": "工場が海沿いに集中しているため、輸送が便利だ。", "target_word": "集中", "complexity_tier": "T3", "furigana": "工場[こうじょう]が海沿[うみぞ]いに集中[しゅうちゅう]しているため、輸送[ゆそう]が便利[べんり]だ。", "sentence_source": "generated"}, {"text": "観光客が夏休みに集中して、宿が取れなかった。", "target_word": "集中", "complexity_tier": "T3", "furigana": "観光客[かんこうきゃく]が夏休[なつやす]みに集中[しゅうちゅう]して、宿[やど]が取[と]れなかった。", "sentence_source": "generated"}, {"text": "仕事が一人に集中すると、その人は倒れてしまう。", "target_word": "集中", "complexity_tier": "T3", "furigana": "仕事[しごと]が一人[ひとり]に集中[しゅうちゅう]すると、その人[ひと]は倒[たお]れてしまう。", "sentence_source": "generated"}, {"text": "権力が一人に集中するのは危険だ。", "target_word": "集中", "complexity_tier": "T3", "furigana": "権力[けんりょく]が一人[ひとり]に集中[しゅうちゅう]するのは危険[きけん]だ。", "sentence_source": "generated"}, {"text": "病院が駅の近くに集中しているので、遠い町の人は不便だ。", "target_word": "集中", "complexity_tier": "T3", "furigana": "病院[びょういん]が駅[えき]の近[ちか]くに集中[しゅうちゅう]しているので、遠[とお]い町[まち]の人[ひと]は不便[ふべん]だ。", "sentence_source": "generated"}, {"text": "電話が一度に集中して、回線がつながらなくなった。", "target_word": "集中", "complexity_tier": "T3", "furigana": "電話[でんわ]が一度[いちど]に集中[しゅうちゅう]して、回線[かいせん]がつながらなくなった。", "sentence_source": "generated"}, {"text": "古い店は駅の北側に集中していて、南側にはほとんどない。", "target_word": "集中", "complexity_tier": "T3", "furigana": "古[ふる]い店[みせ]は駅[えき]の北側[きたがわ]に集中[しゅうちゅう]していて、南側[みなみがわ]にはほとんどない。", "sentence_source": "generated"}], "morphological_forms": [{"form": "集中", "label": "基本形"}, {"form": "集中する", "label": "する動詞"}, {"form": "集中して", "label": "て形"}, {"form": "集中している", "label": "ている形"}], "register": "中立（普通体）", "sense_fingerprint": "人・物・仕事などが一か所に集まること（一極集中）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '52b57e1b-0418-4914-982e-e477e0ea17e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35276, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "集中", "is_correct": true, "explanation": "「東京に集中している」は、人口が一か所に集まっている状態を表すので文に合う。"}, {"text": "感動", "is_correct": false, "explanation": "「東京に感動している」は心を動かされる意味で、人口の分布を表す文には合わない。"}, {"text": "更新", "is_correct": false, "explanation": "「東京を更新している」は新しくする意味で、人口の位置を表す文には合わない。"}, {"text": "集計", "is_correct": false, "explanation": "「集計」は数をまとめる意味で、人口が東京に集まっている状態には合わない。"}], "explanations": {"集中": "「東京に集中している」は、人口が一か所に集まっている状態を表すので文に合う。", "感動": "「東京に感動している」は心を動かされる意味で、人口の分布を表す文には合わない。", "更新": "「東京を更新している」は新しくする意味で、人口の位置を表す文には合わない。", "集計": "「集計」は数をまとめる意味で、人口が東京に集まっている状態には合わない。"}, "sentence_index": 0, "correct_answer": "集中"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "切手を集中した。", "explanation": "ここは〈収集〉の意味と取り違えている。切手などを集めて持つ意味で、人や物が一か所に集まる〈集中〉とは合わない。"}, {"text": "選手たちは校庭を集中した。", "explanation": "ここは〈占拠〉の意味と取り違えている。場所を占める意味で、人が一か所に集まる〈集中〉の使い方とは違うので合わない。"}, {"text": "議題を三つに集中した。", "explanation": "ここは〈集約〉の意味と取り違えている。まとめて一つにする意味で、人や物が一か所に集まる〈集中〉とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b5a8c7b-643d-4f5e-afc9-22ef6f2db6a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35276, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "集中", "is_correct": true, "explanation": "「権力が一人に集中する」は、権力が一人に集まる状態を表すので文に合う。"}, {"text": "放置", "is_correct": false, "explanation": "「放置」は何もせず置いておく意味で、権力が一人に集まる文には合わない。"}, {"text": "返却", "is_correct": false, "explanation": "「返却」は返す意味で、権力が一人に集まる状態を表す文には合わない。"}, {"text": "削除", "is_correct": false, "explanation": "「削除」は消す意味で、権力が一人に集まる文には合わない。"}], "explanations": {"集中": "「権力が一人に集中する」は、権力が一人に集まる状態を表すので文に合う。", "放置": "「放置」は何もせず置いておく意味で、権力が一人に集まる文には合わない。", "返却": "「返却」は返す意味で、権力が一人に集まる状態を表す文には合わない。", "削除": "「削除」は消す意味で、権力が一人に集まる文には合わない。"}, "sentence_index": 6, "correct_answer": "集中"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "先月の売上を支店ごとに集中した。", "explanation": "ここは〈集計〉の意味と取り違えている。数字をまとめる意味で、人や物が一か所に集まる〈集中〉とは違う。"}, {"text": "ファンを年齢で集中した。", "explanation": "ここは〈分類〉の意味と取り違えている。年齢などで分けて整理する意味で、一か所に集まる〈集中〉とは合わない。"}, {"text": "彼は締め切りまで論文に集中して、書き上げた。", "explanation": "ここは〈意識を向ける〉の意味。意識や力を一つのことに向ける意味で、人や物が一か所に集まる〈集中〉とは違う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b5a8c7b-643d-4f5e-afc9-22ef6f2db6a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35276, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "学校が駅の周辺を集中しているので、通学が便利だ。", "corrected_sentence": "学校が駅の周辺に集中しているので、通学が便利だ。", "error_description": "〈集中〉は「に」を取る。「を」を使うと、集まる先を示せなくなる。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b5a8c7b-643d-4f5e-afc9-22ef6f2db6a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35276, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "人口が都市に集中と、住宅が不足した。", "corrected_sentence": "人口が都市に集中して、住宅が不足した。", "error_description": "「集中して」の「て」が必要。「集中と」では、後ろの文「住宅が不足した」につながらない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b5a8c7b-643d-4f5e-afc9-22ef6f2db6a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35277, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "集中の対象を示す『に』で、『仕事に集中できない』と自然に続く。"}, {"text": "を", "is_correct": false, "explanation": "動作の対象を示す『を』だが、集中は『に』で対象を表すので『仕事を集中できない』は不自然。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す『へ』で、『仕事へ集中』は意味が通らない。"}, {"text": "から", "is_correct": false, "explanation": "起点を示す『から』で、対象を表す集中とは合わない。"}], "correct_answer": "に", "explanations": {"に": "集中の対象を示す『に』で、『仕事に集中できない』と自然に続く。", "を": "動作の対象を示す『を』だが、集中は『に』で対象を表すので『仕事を集中できない』は不自然。", "へ": "方向を示す『へ』で、『仕事へ集中』は意味が通らない。", "から": "起点を示す『から』で、対象を表す集中とは合わない。"}, "error_tags": {"を": "目的語", "へ": "方向", "から": "起点"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b5a8c7b-643d-4f5e-afc9-22ef6f2db6a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35277, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "集中の対象を示す『に』で、『本の内容に集中できない』と自然に続く。"}, {"text": "を", "is_correct": false, "explanation": "『を』は動作の対象を示すが、集中は『に』で対象を表すので不自然。"}, {"text": "で", "is_correct": false, "explanation": "手段や場所を示す『で』で、対象を表す集中の文には合わない。"}, {"text": "と", "is_correct": false, "explanation": "並列や相手を示す『と』で、『本の内容と集中』は意味が通らない。"}], "correct_answer": "に", "explanations": {"に": "集中の対象を示す『に』で、『本の内容に集中できない』と自然に続く。", "を": "『を』は動作の対象を示すが、集中は『に』で対象を表すので不自然。", "で": "手段や場所を示す『で』で、対象を表す集中の文には合わない。", "と": "並列や相手を示す『と』で、『本の内容と集中』は意味が通らない。"}, "error_tags": {"を": "目的語", "で": "手段", "と": "相手"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b5a8c7b-643d-4f5e-afc9-22ef6f2db6a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35277, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "意識や力を一つのことに向けること。", "primary_collocate": null, "pronunciation": "しゅうちゅう", "ipa": "ɕɯːtɕɯː", "syllable_count": 4, "sentences": [{"text": "テストの前は、静かな部屋で集中して勉強する。", "target_word": "集中", "complexity_tier": "T3", "furigana": "テストの前[まえ]は、静[しず]かな部屋[へや]で集中[しゅうちゅう]して勉強[べんきょう]する。", "sentence_source": "generated"}, {"text": "音楽がうるさくて、仕事に集中できない。", "target_word": "集中", "complexity_tier": "T3", "furigana": "音楽[おんがく]がうるさくて、仕事[しごと]に集中[しゅうちゅう]できない。", "sentence_source": "generated"}, {"text": "試合が始まると、選手たちは集中した顔つきになった。", "target_word": "集中", "complexity_tier": "T3", "furigana": "試合[しあい]が始[はじ]まると、選手[せんしゅ]たちは集中[しゅうちゅう]した顔[かお]つきになった。", "sentence_source": "generated"}, {"text": "彼は集中しているときは、呼ばれても気づかない。", "target_word": "集中", "complexity_tier": "T3", "furigana": "彼[かれ]は集中[しゅうちゅう]しているときは、呼[よ]ばれても気[き]づかない。", "sentence_source": "generated"}, {"text": "観客の目が舞台の上の俳優に集中した。", "target_word": "集中", "complexity_tier": "T3", "furigana": "観客[かんきゃく]の目[め]が舞台[ぶたい]の上[うえ]の俳優[はいゆう]に集中[しゅうちゅう]した。", "sentence_source": "generated"}, {"text": "疲れていて、授業に集中することができなかった。", "target_word": "集中", "complexity_tier": "T3", "furigana": "疲[つか]れていて、授業[じゅぎょう]に集中[しゅうちゅう]することができなかった。", "sentence_source": "generated"}, {"text": "締め切り前は、夜も集中して論文を書く。", "target_word": "集中", "complexity_tier": "T3", "furigana": "締[し]め切[き]り前[まえ]は、夜[よる]も集中[しゅうちゅう]して論文[ろんぶん]を書[か]く。", "sentence_source": "generated"}, {"text": "スマホを見ながらでは、本の内容に集中できない。", "target_word": "集中", "complexity_tier": "T3", "furigana": "スマホを見[み]ながらでは、本[ほん]の内容[ないよう]に集中[しゅうちゅう]できない。", "sentence_source": "generated"}, {"text": "大事な場面では、全員が一点に集中した。", "target_word": "集中", "complexity_tier": "T3", "furigana": "大事[だいじ]な場面[ばめん]では、全員[ぜんいん]が一点[いってん]に集中[しゅうちゅう]した。", "sentence_source": "generated"}, {"text": "集中して聞いていたので、先生の話をよく覚えている。", "target_word": "集中", "complexity_tier": "T3", "furigana": "集中[しゅうちゅう]して聞[き]いていたので、先生[せんせい]の話[はなし]をよく覚[おぼ]えている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "集中", "label": "基本形"}, {"form": "集中する", "label": "する動詞"}, {"form": "集中して", "label": "て形"}, {"form": "集中できない", "label": "可能否定形"}], "register": "中立（普通体）", "sense_fingerprint": "意識や力を一つのことに向ける", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '52b57e1b-0418-4914-982e-e477e0ea17e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35277, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "集中", "is_correct": true, "explanation": "意識を一つの勉強に向けるという意味で、静かな部屋での勉強に合う。"}, {"text": "散歩", "is_correct": false, "explanation": "外を歩き回ることで、勉強の仕方としては成り立たない。"}, {"text": "解散", "is_correct": false, "explanation": "集まりを終わらせることで、勉強の場面には合わない。"}, {"text": "放送", "is_correct": false, "explanation": "電波で情報を伝えることで、『放送して勉強する』は意味が通らない。"}], "explanations": {"集中": "意識を一つの勉強に向けるという意味で、静かな部屋での勉強に合う。", "散歩": "外を歩き回ることで、勉強の仕方としては成り立たない。", "解散": "集まりを終わらせることで、勉強の場面には合わない。", "放送": "電波で情報を伝えることで、『放送して勉強する』は意味が通らない。"}, "sentence_index": 0, "correct_answer": "集中"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "雨の日は、客が店に集中して、傘が売れた。", "explanation": "ここは〈一か所に集まる〉の意味。人が一か所に集まる意味で、意識を一つのことに向ける〈集中〉とは違う。"}, {"text": "彼は会社の集中になっている。", "explanation": "ここは〈中心〉の意味。集中は意識を向けること、または一か所に集まることで、人や組織の中心という意味にはならない。"}, {"text": "会議の資料を集中して、一冊にまとめた。", "explanation": "ここは〈集める〉の意味。資料をまとめて一か所に集めるのは他動詞『集める』を使い、『集中』は『〜に集中する』の形で意識や力を向けることを表すので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b5a8c7b-643d-4f5e-afc9-22ef6f2db6a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35277, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "集中", "is_correct": true, "explanation": "意識を一つの作業に向けるという意味で、『夜も集中して論文を書く』と自然に続く。"}, {"text": "出航", "is_correct": false, "explanation": "船が港を出ることで、論文を書く文には合わない。"}, {"text": "謝罪", "is_correct": false, "explanation": "わびることで、論文を書く文の意味には合わない。"}, {"text": "削除", "is_correct": false, "explanation": "消す意味で、論文を書く文の様子には合わない。"}], "explanations": {"集中": "意識を一つの作業に向けるという意味で、『夜も集中して論文を書く』と自然に続く。", "出航": "船が港を出ることで、論文を書く文には合わない。", "謝罪": "わびることで、論文を書く文の意味には合わない。", "削除": "消す意味で、論文を書く文の様子には合わない。"}, "sentence_index": 6, "correct_answer": "集中"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は古い切手を集中して、アルバムに貼った。", "explanation": "ここは〈収集〉の意味。切手などを集めて持つ意味で、意識を一つのことに向ける〈集中〉とは違う。"}, {"text": "大雨で、試合を集中した。", "explanation": "ここは〈中止〉の意味。試合は『中止する』もので、『集中する』の対象にはならない。"}, {"text": "先月の売り上げを集中して、表にまとめた。", "explanation": "ここは〈集計〉の意味。数字を合計するのは『集計』で、『集中』は意識を向けることを表す。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b5a8c7b-643d-4f5e-afc9-22ef6f2db6a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35277, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "雨の音がうるさくて、宿題を集中できない。", "corrected_sentence": "雨の音がうるさくて、宿題に集中できない。", "error_description": "誤り：『を』。正しくは『に』。集中は『〜に集中する』と対象を『に』で表すため、『を』は使えない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b5a8c7b-643d-4f5e-afc9-22ef6f2db6a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35277, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "夜の教室で、先生の説明を集中していた。", "corrected_sentence": "夜の教室で、先生の説明に集中していた。", "error_description": "誤り：『を』。正しくは『に』。集中の対象は『に』で表すため、『を』は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b5a8c7b-643d-4f5e-afc9-22ef6f2db6a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35294, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "多い", "is_correct": true, "explanation": "数が少ないの反対で、数が多いことを表す。"}, {"text": "大きい", "is_correct": false, "explanation": "大きいは大きさの意味で、数の反対語ではない。"}, {"text": "遅い", "is_correct": false, "explanation": "遅いは速さの反対語で、〈少ない〉の対義語ではない。"}, {"text": "重い", "is_correct": false, "explanation": "重いは重さの意味で、数量の反対語ではない。"}], "correct_answer": "多い", "explanations": {"多い": "数が少ないの反対で、数が多いことを表す。", "大きい": "大きいは大きさの意味で、数の反対語ではない。", "遅い": "遅いは速さの反対語で、〈少ない〉の対義語ではない。", "重い": "重いは重さの意味で、数量の反対語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bad1c4d-f01b-4f87-8fe3-07018ad5ba8b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35294, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "多い", "is_correct": true, "explanation": "数が少ないの反対で、数が多いことを表す。"}, {"text": "長い", "is_correct": false, "explanation": "長いは長さの意味で、数の反対語ではない。"}, {"text": "深い", "is_correct": false, "explanation": "深いは深さの意味で、数量の反対語ではない。"}, {"text": "強い", "is_correct": false, "explanation": "強いは力の程度を表し、〈少ない〉の対義語ではない。"}], "correct_answer": "多い", "explanations": {"多い": "数が少ないの反対で、数が多いことを表す。", "長い": "長いは長さの意味で、数の反対語ではない。", "深い": "深いは深さの意味で、数量の反対語ではない。", "強い": "強いは力の程度を表し、〈少ない〉の対義語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bad1c4d-f01b-4f87-8fe3-07018ad5ba8b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35294, 3, 'prompt1_core', '{"pos": "形容詞", "semantic_class": "property", "definition": "数が少ない。", "primary_collocate": null, "pronunciation": "すくない", "ipa": "sɯkɯnai", "syllable_count": 4, "sentences": [{"text": "この町には、図書館の数が少ない。", "target_word": "少ない", "complexity_tier": "T3", "furigana": "この町[まち]には、図書館[としょかん]の数[かず]が少[すく]ない。", "sentence_source": "generated"}, {"text": "去年は雪の日が少なかった。", "target_word": "少なかった", "complexity_tier": "T3", "furigana": "去年[きょねん]は雪[ゆき]の日[ひ]が少[すく]なかった。", "sentence_source": "generated"}, {"text": "参加者が少ないので、会は中止になった。", "target_word": "少ない", "complexity_tier": "T3", "furigana": "参加者[さんかしゃ]が少[すく]ないので、会[かい]は中止[ちゅうし]になった。", "sentence_source": "generated"}, {"text": "田舎では、電車の本数が少ない。", "target_word": "少ない", "complexity_tier": "T3", "furigana": "田舎[いなか]では、電車[でんしゃ]の本数[ほんすう]が少[すく]ない。", "sentence_source": "generated"}, {"text": "教室には、女子の生徒が少ない。", "target_word": "少ない", "complexity_tier": "T3", "furigana": "教室[きょうしつ]には、女子[じょし]の生徒[せいと]が少[すく]ない。", "sentence_source": "generated"}, {"text": "台風が来る回数は、去年より少ない。", "target_word": "少ない", "complexity_tier": "T3", "furigana": "台風[たいふう]が来[く]る回数[かいすう]は、去年[きょねん]より少[すく]ない。", "sentence_source": "generated"}, {"text": "数が少なければ、一人で運べる。", "target_word": "少なければ", "complexity_tier": "T3", "furigana": "数[かず]が少[すく]なければ、一人[ひとり]で運[はこ]べる。", "sentence_source": "generated"}, {"text": "この絵を描ける画家は少なくない。", "target_word": "少なくない", "complexity_tier": "T3", "furigana": "この絵[え]を描[か]ける画家[がか]は少[すく]なくない。", "sentence_source": "generated"}, {"text": "店に来る客が少ないから、早めに閉める。", "target_word": "少ない", "complexity_tier": "T3", "furigana": "店[みせ]に来[く]る客[きゃく]が少[すく]ないから、早[はや]めに閉[し]める。", "sentence_source": "generated"}, {"text": "山にすむ動物の種類が少なくなってきた。", "target_word": "少なく", "complexity_tier": "T3", "furigana": "山[やま]にすむ動物[どうぶつ]の種類[しゅるい]が少[すく]なくなってきた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "少なく", "label": "連用形"}, {"form": "少なかった", "label": "過去形"}, {"form": "少なくない", "label": "否定形"}, {"form": "少なければ", "label": "仮定形"}], "register": "neutral", "sense_fingerprint": "数えられるものの個数や人数がわずかである", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '48ed5f6e-9d04-40a4-a25c-2e0d32e54d62') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35294, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "少ない", "is_correct": true, "explanation": "図書館の数が少ないという意味に合い、文が通る。"}, {"text": "遠い", "is_correct": false, "explanation": "数は距離のように遠いとは言えないので、「図書館の数が遠い」は意味が通らない。"}, {"text": "重い", "is_correct": false, "explanation": "数を重いとは言わないので、「図書館の数が重い」は文として合わない。"}, {"text": "明るい", "is_correct": false, "explanation": "数の様子を明るいとは言わないので、文の意味が合わない。"}], "explanations": {"少ない": "図書館の数が少ないという意味に合い、文が通る。", "遠い": "数は距離のように遠いとは言えないので、「図書館の数が遠い」は意味が通らない。", "重い": "数を重いとは言わないので、「図書館の数が重い」は文として合わない。", "明るい": "数の様子を明るいとは言わないので、文の意味が合わない。"}, "sentence_index": 0, "correct_answer": "少ない"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この店は値段が少ない。", "explanation": "ここは〈低い〉（値段や程度が下だ）の意味。値段は数えられないので、〈少ない〉ではなく〈低い〉を使う。"}, {"text": "今朝は気分が少ない。", "explanation": "ここは〈重い〉（気持ちが沈む）の意味。気分は数えられないので、〈少ない〉は使えない。"}, {"text": "彼の性格は少ない。", "explanation": "ここは〈明るい〉（性格が陽気だ）の意味。性格の様子は数ではないので、〈少ない〉は合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bad1c4d-f01b-4f87-8fe3-07018ad5ba8b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35294, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "少なければ", "is_correct": true, "explanation": "仮定形で「数が少なければ」の条件が合い、後ろの「一人で運べる」につながる。"}, {"text": "大きければ", "is_correct": false, "explanation": "数が大きいと一人で運べる理由にならず、文が通らない。"}, {"text": "硬ければ", "is_correct": false, "explanation": "数を硬いとは言わないので、文の条件として意味が通らない。"}, {"text": "冷たければ", "is_correct": false, "explanation": "数を冷たいとは言わないので、条件として文の意味と合わない。"}], "explanations": {"少なければ": "仮定形で「数が少なければ」の条件が合い、後ろの「一人で運べる」につながる。", "大きければ": "数が大きいと一人で運べる理由にならず、文が通らない。", "硬ければ": "数を硬いとは言わないので、文の条件として意味が通らない。", "冷たければ": "数を冷たいとは言わないので、条件として文の意味と合わない。"}, "sentence_index": 6, "correct_answer": "少なければ"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "今朝は温度が少ない。", "explanation": "ここは〈高い〉（温度が上だ）の意味。温度は数えられないので、〈少ない〉は使えない。"}, {"text": "今夜は空が少ない。", "explanation": "ここは〈暗い〉（光が弱い）の意味。空の明るさは数量ではないので、〈少ない〉は合わない。"}, {"text": "彼は判断が少ない。", "explanation": "ここは〈速い〉（すばやい）の意味。判断の速さは数ではないので、〈少ない〉は合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bad1c4d-f01b-4f87-8fe3-07018ad5ba8b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35294, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "会場の席の数が少ないを、列を増やした。", "corrected_sentence": "会場の席の数が少ないので、列を増やした。", "error_description": "「少ない」の後は理由を表す「ので」が必要。誤りは「を」、正しくは「ので」。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "少なかった", "is_correct": true, "explanation": "過去形。「去年は」と過去の出来事を述べるので過去形が合う。"}, {"text": "少ない", "is_correct": false, "explanation": "現在形で、過去の出来事を述べる文には合わない。"}, {"text": "少なく", "is_correct": false, "explanation": "連用形で文を終えられず、述語として成り立たない。"}, {"text": "少なければ", "is_correct": false, "explanation": "仮定形になり「〜なら」の条件の意味になるので、事実を述べる文には合わない。"}], "correct_form": "少なかった", "base_form": "少ない", "form_label": "過去形", "sentence_index": 1, "explanations": {"少なかった": "過去形。「去年は」と過去の出来事を述べるので過去形が合う。", "少ない": "現在形で、過去の出来事を述べる文には合わない。", "少なく": "連用形で文を終えられず、述語として成り立たない。", "少なければ": "仮定形になり「〜なら」の条件の意味になるので、事実を述べる文には合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bad1c4d-f01b-4f87-8fe3-07018ad5ba8b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35294, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "部屋の数が少なくれば、掃除が楽になる。", "corrected_sentence": "部屋の数が少なければ、掃除が楽になる。", "error_description": "仮定形は「少なければ」。「少なくれば」は活用の誤り（「け」を「く」にした形）。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "少なくない", "is_correct": true, "explanation": "否定形。「少なくない」で「多くはいる」という否定の意味になり、文に合う。"}, {"text": "少なくて", "is_correct": false, "explanation": "て形で文を終えられず、述語として成り立たない。"}, {"text": "少なくなる", "is_correct": false, "explanation": "変化を表す形で「画家が少なくなる」の意味になり、文の意味と合わない。"}, {"text": "少なかったら", "is_correct": false, "explanation": "過去の条件を表すので、現在の状況を述べる文には合わない。"}], "correct_form": "少なくない", "base_form": "少ない", "form_label": "否定形", "sentence_index": 7, "explanations": {"少なくない": "否定形。「少なくない」で「多くはいる」という否定の意味になり、文に合う。", "少なくて": "て形で文を終えられず、述語として成り立たない。", "少なくなる": "変化を表す形で「画家が少なくなる」の意味になり、文の意味と合わない。", "少なかったら": "過去の条件を表すので、現在の状況を述べる文には合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bad1c4d-f01b-4f87-8fe3-07018ad5ba8b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35295, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "多い", "is_correct": true, "explanation": "量が少ないの反対で、量が多いことを表す。"}, {"text": "大きい", "is_correct": false, "explanation": "大きいは大きさの意味で、量の反対語ではない。"}, {"text": "強い", "is_correct": false, "explanation": "強いは力の程度で、〈少ない〉の対義語ではない。"}, {"text": "速い", "is_correct": false, "explanation": "速いは速度の意味で、量の反対語ではない。"}], "correct_answer": "多い", "explanations": {"多い": "量が少ないの反対で、量が多いことを表す。", "大きい": "大きいは大きさの意味で、量の反対語ではない。", "強い": "強いは力の程度で、〈少ない〉の対義語ではない。", "速い": "速いは速度の意味で、量の反対語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bad1c4d-f01b-4f87-8fe3-07018ad5ba8b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
