INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35295, 3, 'prompt1_core', '{"pos": "形容詞", "semantic_class": "property", "definition": "数量が少ししかないさま。", "primary_collocate": null, "pronunciation": "すくない", "ipa": "sɯkɯnai", "syllable_count": 4, "sentences": [{"text": "冷蔵庫の牛乳が少ないので、帰りに買って帰る。", "target_word": "少ない", "complexity_tier": "T3", "furigana": "冷蔵庫[れいぞうこ]の牛乳[ぎゅうにゅう]が少[すく]ないので、帰[かえ]りに買[か]って帰[かえ]る。", "sentence_source": "generated"}, {"text": "少ない水では、植物は元気に育たない。", "target_word": "少ない", "complexity_tier": "T3", "furigana": "少[すく]ない水[みず]では、植物[しょくぶつ]は元気[げんき]に育[そだ]たない。", "sentence_source": "generated"}, {"text": "給料が少ないので、貯金がなかなか増えない。", "target_word": "少ない", "complexity_tier": "T3", "furigana": "給料[きゅうりょう]が少[すく]ないので、貯金[ちょきん]がなかなか増[ふ]えない。", "sentence_source": "generated"}, {"text": "今月は使えるお金が少なく、外食を控えている。", "target_word": "少なく", "complexity_tier": "T3", "furigana": "今月[こんげつ]は使[つか]えるお金[かね]が少[すく]なく、外食[がいしょく]を控[ひか]えている。", "sentence_source": "generated"}, {"text": "スープの塩が少ないせいで、味がうすい。", "target_word": "少ない", "complexity_tier": "T3", "furigana": "スープの塩[しお]が少[すく]ないせいで、味[あじ]がうすい。", "sentence_source": "generated"}, {"text": "残りの時間が少ないから、急いで答えを書いた。", "target_word": "少ない", "complexity_tier": "T3", "furigana": "残[のこ]りの時間[じかん]が少[すく]ないから、急[いそ]いで答[こた]えを書[か]いた。", "sentence_source": "generated"}, {"text": "食べ物が少ない冬には、動物たちは巣にこもる。", "target_word": "少ない", "complexity_tier": "T3", "furigana": "食[た]べ物[もの]が少[すく]ない冬[ふゆ]には、動物[どうぶつ]たちは巣[す]にこもる。", "sentence_source": "generated"}, {"text": "睡眠の時間が少ない人は、昼間に眠くなりやすい。", "target_word": "少ない", "complexity_tier": "T3", "furigana": "睡眠[すいみん]の時間[じかん]が少[すく]ない人[ひと]は、昼間[ひるま]に眠[ねむ]くなりやすい。", "sentence_source": "generated"}, {"text": "荷物が少なければ、旅は楽になる。", "target_word": "少なければ", "complexity_tier": "T3", "furigana": "荷物[にもつ]が少[すく]なければ、旅[たび]は楽[らく]になる。", "sentence_source": "generated"}, {"text": "雨の量が少ない年は、米の育ちが悪い。", "target_word": "少ない", "complexity_tier": "T3", "furigana": "雨[あめ]の量[りょう]が少[すく]ない年[とし]は、米[こめ]の育[そだ]ちが悪[わる]い。", "sentence_source": "generated"}], "morphological_forms": [{"form": "少なく", "label": "連用形"}, {"form": "少なかった", "label": "過去形"}, {"form": "少なくない", "label": "否定形"}, {"form": "少なければ", "label": "仮定形"}], "register": "neutral", "sense_fingerprint": "量や程度が十分でなく、わずかしかない", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '48ed5f6e-9d04-40a4-a25c-2e0d32e54d62') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35295, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "少ない", "is_correct": true, "explanation": "牛乳の量が少ないので買って帰る、という理由が合う。"}, {"text": "遠い", "is_correct": false, "explanation": "牛乳が遠いという状態は理由として意味が通らない。"}, {"text": "明るい", "is_correct": false, "explanation": "牛乳を明るいとは言わないので、理由として文が合わない。"}, {"text": "硬い", "is_correct": false, "explanation": "牛乳が硬いことは買って帰る理由にならず、文が通らない。"}], "explanations": {"少ない": "牛乳の量が少ないので買って帰る、という理由が合う。", "遠い": "牛乳が遠いという状態は理由として意味が通らない。", "明るい": "牛乳を明るいとは言わないので、理由として文が合わない。", "硬い": "牛乳が硬いことは買って帰る理由にならず、文が通らない。"}, "sentence_index": 0, "correct_answer": "少ない"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼女は人柄が少ない。", "explanation": "ここは〈優しい〉（性質が穏やかだ）の意味。人柄は量ではないので、〈少ない〉は合わない。"}, {"text": "今日は足取りが少ない。", "explanation": "ここは〈軽い〉（動きが軽快だ）の意味。足取りは数えられないので、〈少ない〉は使えない。"}, {"text": "今朝は気温が少ない。", "explanation": "ここは〈高い〉（温度が上だ）の意味。気温は量ではないので、〈少ない〉は合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bad1c4d-f01b-4f87-8fe3-07018ad5ba8b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35295, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "少ない", "is_correct": true, "explanation": "食べ物の量が少ない冬、という意味に合い、巣にこもる理由が通る。"}, {"text": "寒い", "is_correct": false, "explanation": "食べ物を寒いとは言わないので、「食べ物が寒い冬」は意味が通らない。"}, {"text": "軽い", "is_correct": false, "explanation": "食べ物を軽いとは言わないので、文の意味と合わない。"}, {"text": "速い", "is_correct": false, "explanation": "食べ物を速いとは言わないので、「食べ物が速い冬」は成り立たない。"}], "explanations": {"少ない": "食べ物の量が少ない冬、という意味に合い、巣にこもる理由が通る。", "寒い": "食べ物を寒いとは言わないので、「食べ物が寒い冬」は意味が通らない。", "軽い": "食べ物を軽いとは言わないので、文の意味と合わない。", "速い": "食べ物を速いとは言わないので、「食べ物が速い冬」は成り立たない。"}, "sentence_index": 6, "correct_answer": "少ない"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "今回の計画は規模が少ない。", "explanation": "ここは〈小さい〉（大きさが小さい）の意味。規模の大小は量ではないので、〈少ない〉とは言わない。"}, {"text": "会議の期間が少ない。", "explanation": "ここは〈短い〉（時間の長さが短い）の意味。期間は数量ではないので、〈少ない〉は合わない。"}, {"text": "この店は売り場の範囲が少ない。", "explanation": "ここは〈狭い〉（広さが小さい）の意味。範囲の広さは量ではないので、〈少ない〉は使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bad1c4d-f01b-4f87-8fe3-07018ad5ba8b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35295, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "材料の量が少ないを、料理の味がうすくなる。", "corrected_sentence": "材料の量が少ないと、料理の味がうすくなる。", "error_description": "「少ないと」の条件の形が必要。誤りは「を」、正しくは「と」。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "少ない", "is_correct": true, "explanation": "辞書形。名詞「水」を修飾する形で、文に合う。"}, {"text": "少なかった", "is_correct": false, "explanation": "過去形。「少なかった水」は過去の水の話になり、一般的な事実には合わない。"}, {"text": "少なく", "is_correct": false, "explanation": "連用形は名詞を修飾できず、文が成り立たない。"}, {"text": "少なければ", "is_correct": false, "explanation": "仮定形は名詞を修飾できず、文が成り立たない。"}], "correct_form": "少ない", "base_form": "少ない", "form_label": "辞書形", "sentence_index": 1, "explanations": {"少ない": "辞書形。名詞「水」を修飾する形で、文に合う。", "少なかった": "過去形。「少なかった水」は過去の水の話になり、一般的な事実には合わない。", "少なく": "連用形は名詞を修飾できず、文が成り立たない。", "少なければ": "仮定形は名詞を修飾できず、文が成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bad1c4d-f01b-4f87-8fe3-07018ad5ba8b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35295, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "雨の量が少くれば、川の水は減る。", "corrected_sentence": "雨の量が少なければ、川の水は減る。", "error_description": "仮定形は「少なければ」。「少くれば」は活用の誤り（「な」が抜けている）。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "少ない", "is_correct": true, "explanation": "辞書形。「少ない人」と名詞を修飾する形で、文に合う。"}, {"text": "少なくて", "is_correct": false, "explanation": "て形は名詞を修飾できず、文が成り立たない。"}, {"text": "少なくない", "is_correct": false, "explanation": "否定形になり、「少なくない人」は意味が逆で文の内容と合わない。"}, {"text": "少なかったら", "is_correct": false, "explanation": "「〜たら」は名詞を修飾できず、文が成り立たない。"}], "correct_form": "少ない", "base_form": "少ない", "form_label": "辞書形", "sentence_index": 7, "explanations": {"少ない": "辞書形。「少ない人」と名詞を修飾する形で、文に合う。", "少なくて": "て形は名詞を修飾できず、文が成り立たない。", "少なくない": "否定形になり、「少なくない人」は意味が逆で文の内容と合わない。", "少なかったら": "「〜たら」は名詞を修飾できず、文が成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bad1c4d-f01b-4f87-8fe3-07018ad5ba8b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
