INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35299, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "他と違いがなく、一致していること。", "primary_collocate": null, "pronunciation": "どういつ", "ipa": "doːitsɯ", "syllable_count": 4, "sentences": [{"text": "次いで、ラズベリー等のジャムを対になる片割れ、あるいは同一の切片上に重ね合わせる。\n\n甘味と塩気、滑らかさと顆粒感が口腔内で織りなす対照的なハーモニーは、単なる栄養補給の域を超え、短時間での認知機能回復をもたらし、合理性と美学が融合した食の営みとして完成する。", "target_word": "同一", "complexity_tier": "T3", "furigana": "次[つ]いで、ラズベリー等[など]のジャムを対[つい]になる片割[かたわ]れ、あるいは同一[どういつ]の切片[せっぺん]上[じょう]に重[かさ]ね合[あ]わせる。\n\n甘味[かんみ]と塩気[しおけ]、滑[なめ]らかさと顆粒感[かりゅうかん]が口腔内[こうくうない]で織[お]りなす対照的[たいしょうてき]なハーモニーは、単[たん]なる栄養補給[えいようほきゅう]の域[いき]を超[こ]え、短時間[たんじかん]での認知機能回復[にんちきのうかいふく]をもたらし、合理性[ごうりせい]と美学[びがく]が融合[ゆうごう]した食[しょく]の営[いとな]みとして完成[かんせい]する。", "sentence_source": "mined"}, {"text": "この二つの商品は同一の工場で作られているので、品質に差がない。", "target_word": "同一", "complexity_tier": "T3", "furigana": "この二[ふた]つの商品[しょうひん]は同一[どういつ]の工場[こうじょう]で作[つく]られているので、品質[ひんしつ]に差[さ]がない。", "sentence_source": "generated"}, {"text": "その二人は名前が違うが、調べると同一の人物だった。", "target_word": "同一", "complexity_tier": "T3", "furigana": "その二人[ふたり]は名前[なまえ]が違[ちが]うが、調[しら]べると同一[どういつ]の人物[じんぶつ]だった。", "sentence_source": "generated"}, {"text": "双子でも、二人の指紋は同一ではない。", "target_word": "同一", "complexity_tier": "T3", "furigana": "双子[ふたご]でも、二人[ふたり]の指紋[しもん]は同一[どういつ]ではない。", "sentence_source": "generated"}, {"text": "同一の条件で実験しないと、結果を比べることができない。", "target_word": "同一", "complexity_tier": "T3", "furigana": "同一[どういつ]の条件[じょうけん]で実験[じっけん]しないと、結果[けっか]を比[くら]べることができない。", "sentence_source": "generated"}, {"text": "二つの書類の内容が同一かどうか、もう一度確認してください。", "target_word": "同一", "complexity_tier": "T3", "furigana": "二[ふた]つの書類[しょるい]の内容[ないよう]が同一[どういつ]かどうか、もう一度[いちど]確認[かくにん]してください。", "sentence_source": "generated"}, {"text": "入社した年が違うので、二人は同一の部署では働いていない。", "target_word": "同一", "complexity_tier": "T3", "furigana": "入社[にゅうしゃ]した年[とし]が違[ちが]うので、二人[ふたり]は同一[どういつ]の部署[ぶしょ]では働[はたら]いていない。", "sentence_source": "generated"}, {"text": "この問題は、さっきの問題と同一の方法で解ける。", "target_word": "同一", "complexity_tier": "T3", "furigana": "この問題[もんだい]は、さっきの問題[もんだい]と同一[どういつ]の方法[ほうほう]で解[と]ける。", "sentence_source": "generated"}, {"text": "兄と弟は同一の学校に通っていたが、学年が三つ離れている。", "target_word": "同一", "complexity_tier": "T3", "furigana": "兄[あに]と弟[おとうと]は同一[どういつ]の学校[がっこう]に通[かよ]っていたが、学年[がくねん]が三[みっ]つ離[はな]れている。", "sentence_source": "generated"}, {"text": "同一の電話番号から何度も着信があり、不審に思った。", "target_word": "同一", "complexity_tier": "T3", "furigana": "同一[どういつ]の電話番号[でんわばんごう]から何度[なんど]も着信[ちゃくしん]があり、不審[ふしん]に思[おも]った。", "sentence_source": "generated"}], "morphological_forms": [{"form": "同一", "label": "語幹"}, {"form": "同一の", "label": "連体形"}, {"form": "同一だ", "label": "断定形"}, {"form": "同一で", "label": "連用形"}, {"form": "同一ではない", "label": "否定形"}], "register": "標準（やや書き言葉）", "sense_fingerprint": "二つ以上のものに違いがなく、まったく同じであること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T3: contains vocabulary far above tier T3: 切片 (Zipf 1.86)']::text[], '349bdf37-e6c1-493d-99ce-08b9d759cd57') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35299, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "同一", "is_correct": true, "explanation": "「あるいは同一の切片上」で、重ね合わせる先が同じ一つの切片だと示す。ここでは正しい。"}, {"text": "同じく", "is_correct": false, "explanation": "副詞で「〜と同様に」の意味。名詞「切片」を直接修飾できないため、「同じくの切片」は成立しない。"}, {"text": "ぴったりと", "is_correct": false, "explanation": "副詞で、名詞を修飾する形にならない。「ぴったりとの切片」とは続かない。"}, {"text": "一致して", "is_correct": false, "explanation": "動詞の連用形。「一致しての切片」とは続かず、空欄の位置に入らない。"}], "explanations": {"同一": "「あるいは同一の切片上」で、重ね合わせる先が同じ一つの切片だと示す。ここでは正しい。", "同じく": "副詞で「〜と同様に」の意味。名詞「切片」を直接修飾できないため、「同じくの切片」は成立しない。", "ぴったりと": "副詞で、名詞を修飾する形にならない。「ぴったりとの切片」とは続かない。", "一致して": "動詞の連用形。「一致しての切片」とは続かず、空欄の位置に入らない。"}, "sentence_index": 0, "correct_answer": "同一"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は姉と同一に、ピアノがとても上手だ。", "explanation": "ここは〈同様〉（同じように）の意味。同一は「まったく同じであること」を表し、人の行為を並べて「〜と同じく」と言う用法はない。"}, {"text": "二人は同一に家を出た。", "explanation": "ここは〈同時〉（同じタイミングで）の意味。同一は違いがないことを指し、時間が重なる意味では使わない。"}, {"text": "彼は同一だから、どの仕事も任せられる。", "explanation": "ここは〈有能〉の意味。同一は「同じであること」で、能力の高さを表すために使うことはできない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2130322-bc1d-4da0-bd0a-c22bb2978233') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35299, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "同一", "is_correct": true, "explanation": "「二人は同一の部署では働いていない」で、同じ部署ではないことを示す。ここでは正しい。"}, {"text": "共に", "is_correct": false, "explanation": "副詞で「いっしょに」の意味。「共にの部署」と名詞を修飾できないため、空欄には入らない。"}, {"text": "揃って", "is_correct": false, "explanation": "動詞の連用形。「揃っての部署」とは続かず、名詞の前に置けない。"}, {"text": "一緒に", "is_correct": false, "explanation": "副詞。「一緒にの部署」とは続かず、「の部署」を修飾する形にならない。"}], "explanations": {"同一": "「二人は同一の部署では働いていない」で、同じ部署ではないことを示す。ここでは正しい。", "共に": "副詞で「いっしょに」の意味。「共にの部署」と名詞を修飾できないため、空欄には入らない。", "揃って": "動詞の連用形。「揃っての部署」とは続かず、名詞の前に置けない。", "一緒に": "副詞。「一緒にの部署」とは続かず、「の部署」を修飾する形にならない。"}, "sentence_index": 6, "correct_answer": "同一"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この部屋は同一が広くて、家具が多い。", "explanation": "ここは〈広さ〉の意味。同一は違いがないことを指し、空間の広さを表すために使うことはできない。"}, {"text": "その問題は同一が難しく、誰も解けなかった。", "explanation": "ここは〈難度〉の意味。同一は同じであることを表すので、問題の難しさを言い表す語ではない。"}, {"text": "二人の関係は同一に深まっていった。", "explanation": "ここは〈次第に〉の意味。同一は差がないことを指すため、変化の過程を表す副詞としては使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2130322-bc1d-4da0-bd0a-c22bb2978233') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35299, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この二つの鍵は同一を形をしている。", "corrected_sentence": "この二つの鍵は同一の形をしている。", "error_description": "「同一」を名詞「形」に連なる連体修飾にするには「の」が必要。「を」を使うと、「同一」が目的語になってしまい誤り。正しくは「同一の形」。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "同一の", "is_correct": true, "explanation": "連体形。「同一の工場」のように、後ろの名詞を修飾する形で文中と一致する。"}, {"text": "同一だ", "is_correct": false, "explanation": "断定形。「同一だ工場」と名詞に直接続かないため、この位置には入らない。"}, {"text": "同一で", "is_correct": false, "explanation": "連用形。名詞を修飾する位置には使えず、「同一で工場」は成立しない。"}, {"text": "同一だろう", "is_correct": false, "explanation": "推量形。「同一だろう工場」と名詞に続かず、この位置には入らない。"}], "correct_form": "同一の", "base_form": "同一", "form_label": "連体形", "sentence_index": 1, "explanations": {"同一の": "連体形。「同一の工場」のように、後ろの名詞を修飾する形で文中と一致する。", "同一だ": "断定形。「同一だ工場」と名詞に直接続かないため、この位置には入らない。", "同一で": "連用形。名詞を修飾する位置には使えず、「同一で工場」は成立しない。", "同一だろう": "推量形。「同一だろう工場」と名詞に続かず、この位置には入らない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2130322-bc1d-4da0-bd0a-c22bb2978233') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35299, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この二つの番号は同一の。", "corrected_sentence": "この二つの番号は同一だ。", "error_description": "文末の述語は「同一だ」の形が必要。「同一の」は連体形なので、文末に置くと文が成立しない。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "同一の", "is_correct": true, "explanation": "連体形。「同一の方法」のように後ろの名詞を修飾する形で、文中の形と一致する。"}, {"text": "同一なら", "is_correct": false, "explanation": "仮定形。「同一なら方法」と名詞に直接続かず、この位置には入らない。"}, {"text": "同一だろう", "is_correct": false, "explanation": "推量形。「同一だろう方法」と名詞に続かず、この位置には入らない。"}, {"text": "同一に", "is_correct": false, "explanation": "連用形。「同一に方法」と名詞を修飾できず、「の方法」の位置に入らない。"}], "correct_form": "同一の", "base_form": "同一", "form_label": "連体形", "sentence_index": 7, "explanations": {"同一の": "連体形。「同一の方法」のように後ろの名詞を修飾する形で、文中の形と一致する。", "同一なら": "仮定形。「同一なら方法」と名詞に直接続かず、この位置には入らない。", "同一だろう": "推量形。「同一だろう方法」と名詞に続かず、この位置には入らない。", "同一に": "連用形。「同一に方法」と名詞を修飾できず、「の方法」の位置に入らない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2130322-bc1d-4da0-bd0a-c22bb2978233') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35313, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "緩慢", "is_correct": true, "explanation": "動きや進み方が遅いことで、急速の反対。"}, {"text": "迅速", "is_correct": false, "explanation": "速いという意味で、急速と似た意味。"}, {"text": "活発", "is_correct": false, "explanation": "勢いがあるという意味で、速さの反対ではない。"}, {"text": "突然", "is_correct": false, "explanation": "前触れがないという意味で、速さの反対ではない。"}], "correct_answer": "緩慢", "explanations": {"緩慢": "動きや進み方が遅いことで、急速の反対。", "迅速": "速いという意味で、急速と似た意味。", "活発": "勢いがあるという意味で、速さの反対ではない。", "突然": "前触れがないという意味で、速さの反対ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7c1eeed-52e0-4ebb-a487-eb23e4bbef62') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35313, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "緩やか", "is_correct": true, "explanation": "変化がゆっくりしているさまで、急速の反対。"}, {"text": "急激", "is_correct": false, "explanation": "変化が速く激しいという意味で、急速と近い。"}, {"text": "顕著", "is_correct": false, "explanation": "はっきり目立つという意味で、速さの反対ではない。"}, {"text": "盛ん", "is_correct": false, "explanation": "勢いがあるという意味で、速さの反対ではない。"}], "correct_answer": "緩やか", "explanations": {"緩やか": "変化がゆっくりしているさまで、急速の反対。", "急激": "変化が速く激しいという意味で、急速と近い。", "顕著": "はっきり目立つという意味で、速さの反対ではない。", "盛ん": "勢いがあるという意味で、速さの反対ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7c1eeed-52e0-4ebb-a487-eb23e4bbef62') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35313, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "非常に速いさま。速やかなさま。", "primary_collocate": null, "pronunciation": "きゅうそく", "ipa": "kʲɯːsokɯ", "syllable_count": 4, "sentences": [{"text": "初期段階では、投資家からの資金調達を通じて事業の基盤を固め、市場での急速な成長を目指す。", "target_word": "急速", "complexity_tier": "T6", "furigana": "初期段階(しょきだんかい)では、投資家(とうしか)からの資金調達(しきんちょうたつ)を通(つう)じて事業(じぎょう)の基盤(きばん)を固(かた)め、市場(しじょう)での急速(きゅうそく)な成長(せいちょう)を目指(めざ)す。", "sentence_source": "mined"}, {"text": "変化は急速だ。", "target_word": "急速", "complexity_tier": "T1", "furigana": "変化(へんか)は急速(きゅうそく)だ。", "sentence_source": "generated"}, {"text": "急速に進む。", "target_word": "急速", "complexity_tier": "T1", "furigana": "急速(きゅうそく)に進(すす)む。", "sentence_source": "generated"}, {"text": "町は急速に変わりました。", "target_word": "急速", "complexity_tier": "T2", "furigana": "町(まち)は急速(きゅうそく)に変(か)わりました。", "sentence_source": "generated"}, {"text": "急速な変化が起きています。", "target_word": "急速", "complexity_tier": "T2", "furigana": "急速(きゅうそく)な変化(へんか)が起(お)きています。", "sentence_source": "generated"}, {"text": "技術が急速に進歩して、生活が便利になった。", "target_word": "急速", "complexity_tier": "T3", "furigana": "技術(ぎじゅつ)が急速(きゅうそく)に進歩(しんぽ)して、生活(せいかつ)が便利(べんり)になった。", "sentence_source": "generated"}, {"text": "急速な円安で、物の値段が上がっている。", "target_word": "急速", "complexity_tier": "T3", "furigana": "急速(きゅうそく)な円安(えんやす)で、物(もの)の値段(ねだん)が上(あ)がっている。", "sentence_source": "generated"}, {"text": "人口が急速に減ると、地方の経済は苦しくなる。", "target_word": "急速", "complexity_tier": "T4", "furigana": "人口(じんこう)が急速(きゅうそく)に減(へ)ると、地方(ちほう)の経済(けいざい)は苦(くる)しくなる。", "sentence_source": "generated"}, {"text": "病気は急速に広がったが、対策が早く、被害は小さかった。", "target_word": "急速", "complexity_tier": "T4", "furigana": "病気(びょうき)は急速(きゅうそく)に広(ひろ)がったが、対策(たいさく)が早(はや)く、被害(ひがい)は小(ちい)さかった。", "sentence_source": "generated"}, {"text": "急速で大きな変化についていけず、戸惑う人も少なくない。", "target_word": "急速", "complexity_tier": "T5", "furigana": "急速(きゅうそく)で大(おお)きな変化(へんか)についていけず、戸惑(とまど)う人(ひと)も少(すく)なくない。", "sentence_source": "generated"}], "morphological_forms": [{"form": "急速な", "label": "活用"}, {"form": "急速に", "label": "活用"}, {"form": "急速だ", "label": "活用"}], "register": "plain", "sense_fingerprint": "形状詞 | 非常に速く物事が進むさま", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a500faf0-6d25-4648-b5f5-dd873ded20cc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35313, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "急速", "is_correct": true, "explanation": "見出し語「きゅうそく」そのもの。"}, {"text": "給食", "is_correct": false, "explanation": "「きゅうしょく」で、三拍目が「そ」→「しょ」に変わる。"}, {"text": "救国", "is_correct": false, "explanation": "「きゅうこく」で、三拍目が「そ」→「こ」に変わる。"}, {"text": "急送", "is_correct": false, "explanation": "「きゅうそう」で、最後の拍が「く」→「う」に変わる。"}], "explanations": {"急速": "見出し語「きゅうそく」そのもの。", "給食": "「きゅうしょく」で、三拍目が「そ」→「しょ」に変わる。", "救国": "「きゅうこく」で、三拍目が「そ」→「こ」に変わる。", "急送": "「きゅうそう」で、最後の拍が「く」→「う」に変わる。"}, "sentence_index": null, "correct_answer": "急速"}, "level_3": {"options": [{"text": "急速", "is_correct": true, "explanation": "「急速な成長」で、非常に速い成長を表し意味が通る。"}, {"text": "不便", "is_correct": false, "explanation": "形は合うが意味が合わない。「不便な成長」は成長の説明にならない。"}, {"text": "退屈", "is_correct": false, "explanation": "形は合うが意味が合わない。「退屈な成長」は事業の目標に合わない。"}, {"text": "丁寧", "is_correct": false, "explanation": "形は合うが意味が合わない。「丁寧な成長」は市場の成長を表さない。"}], "explanations": {"急速": "「急速な成長」で、非常に速い成長を表し意味が通る。", "不便": "形は合うが意味が合わない。「不便な成長」は成長の説明にならない。", "退屈": "形は合うが意味が合わない。「退屈な成長」は事業の目標に合わない。", "丁寧": "形は合うが意味が合わない。「丁寧な成長」は市場の成長を表さない。"}, "sentence_index": 0, "correct_answer": "急速"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "急速なスープを飲んで、体が温まった。", "explanation": "急速は速さを表す語で、スープの味や温度を表せない。"}, {"text": "彼は急速な性格で、いつも落ち着いている。", "explanation": "急速は物事が速く進むさまで、人の性格を表す語ではない。"}, {"text": "彼女は急速な笑顔で迎えてくれた。", "explanation": "急速は笑顔の様子を表す語ではなく、変化の速さに使う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7c1eeed-52e0-4ebb-a487-eb23e4bbef62') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35313, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "急速", "is_correct": true, "explanation": "見出し語「きゅうそく」そのもの。"}, {"text": "教則", "is_correct": false, "explanation": "「きょうそく」で、最初の拍が「きゅ」→「きょ」に変わる。"}, {"text": "求職", "is_correct": false, "explanation": "「きゅうしょく」で、三拍目が「そ」→「しょ」に変わる。"}, {"text": "拘束", "is_correct": false, "explanation": "「こうそく」で、最初の拍が「きゅ」→「こ」に変わる。"}], "explanations": {"急速": "見出し語「きゅうそく」そのもの。", "教則": "「きょうそく」で、最初の拍が「きゅ」→「きょ」に変わる。", "求職": "「きゅうしょく」で、三拍目が「そ」→「しょ」に変わる。", "拘束": "「こうそく」で、最初の拍が「きゅ」→「こ」に変わる。"}, "sentence_index": null, "correct_answer": "急速"}, "level_3": {"options": [{"text": "急速", "is_correct": true, "explanation": "「急速な円安」で、速い変化を表し意味が通る。"}, {"text": "親切", "is_correct": false, "explanation": "形は合うが意味が合わない。「親切な円安」とは言わない。"}, {"text": "上品", "is_correct": false, "explanation": "形は合うが意味が合わない。「上品な円安」は意味をなさない。"}, {"text": "窮屈", "is_correct": false, "explanation": "形は合うが意味が合わない。「窮屈な円安」は為替の変化を表さない。"}], "explanations": {"急速": "「急速な円安」で、速い変化を表し意味が通る。", "親切": "形は合うが意味が合わない。「親切な円安」とは言わない。", "上品": "形は合うが意味が合わない。「上品な円安」は意味をなさない。", "窮屈": "形は合うが意味が合わない。「窮屈な円安」は為替の変化を表さない。"}, "sentence_index": 6, "correct_answer": "急速"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "急速で甘いケーキを、友達と食べた。", "explanation": "急速は物事が速く進むさまで、ケーキの味を表せない。"}, {"text": "彼は急速な帽子をかぶって出かけた。", "explanation": "急速は物の種類や形を表す語ではなく、変化の速さに使う。"}, {"text": "急速な猫が庭で寝ている。", "explanation": "急速は寝ている猫の様子を表す語ではなく、変化の速さに使う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7c1eeed-52e0-4ebb-a487-eb23e4bbef62') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35313, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この坂は急速で、歩くのが大変だ。", "corrected_sentence": "この坂は急で、歩くのが大変だ。", "error_description": "坂の傾きが大きい意味では「急速」ではなく「急」を使う。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "急速", "is_correct": true, "explanation": "「急速だ」の形で、語幹に「だ」が付くのが正しい。"}, {"text": "急速な", "is_correct": false, "explanation": "「急速なだ」となり、形が合わない。"}, {"text": "急速に", "is_correct": false, "explanation": "「急速にだ」となり、形が合わない。"}, {"text": "急速だ", "is_correct": false, "explanation": "「急速だだ」となり、形が合わない。"}], "correct_form": "急速", "base_form": "急速", "form_label": "語幹", "sentence_index": 1, "explanations": {"急速": "「急速だ」の形で、語幹に「だ」が付くのが正しい。", "急速な": "「急速なだ」となり、形が合わない。", "急速に": "「急速にだ」となり、形が合わない。", "急速だ": "「急速だだ」となり、形が合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7c1eeed-52e0-4ebb-a487-eb23e4bbef62') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35313, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼は急速に服を着替えて、家を出た。", "corrected_sentence": "彼は急いで服を着替えて、家を出た。", "error_description": "「急速」は変化や物事の進み方の速さに使う語で、人が急いで行う動作には「急いで」を使う。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "急速", "is_correct": true, "explanation": "後ろの「に」と合わせて「急速に減る」の形になる。"}, {"text": "急速な", "is_correct": false, "explanation": "「急速なに」となり、形が合わない。"}, {"text": "急速に", "is_correct": false, "explanation": "「急速にに」となり、形が合わない。"}, {"text": "急速だ", "is_correct": false, "explanation": "「急速だに」となり、形が合わない。"}], "correct_form": "急速", "base_form": "急速", "form_label": "語幹", "sentence_index": 7, "explanations": {"急速": "後ろの「に」と合わせて「急速に減る」の形になる。", "急速な": "「急速なに」となり、形が合わない。", "急速に": "「急速にに」となり、形が合わない。", "急速だ": "「急速だに」となり、形が合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7c1eeed-52e0-4ebb-a487-eb23e4bbef62') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
