INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35314, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "まちにすむ人たち", "primary_collocate": null, "pronunciation": "しみん", "ipa": "ɕimiɴ", "syllable_count": 3, "sentences": [{"text": "市民が集まって、公園のごみを拾った。", "target_word": "市民", "complexity_tier": "T3", "furigana": "市民[しみん]が集[あつ]まって、公園[こうえん]のごみを拾[ひろ]った。", "sentence_source": "generated"}, {"text": "この町の市民は、祭りをとても大切にしている。", "target_word": "市民", "complexity_tier": "T3", "furigana": "この町[まち]の市民[しみん]は、祭[まつ]りをとても大切[たいせつ]にしている。", "sentence_source": "generated"}, {"text": "市民のために、新しい図書館が作られた。", "target_word": "市民", "complexity_tier": "T3", "furigana": "市民[しみん]のために、新[あたら]しい図書館[としょかん]が作[つく]られた。", "sentence_source": "generated"}, {"text": "市長は、市民の声をよく聞く人だ。", "target_word": "市民", "complexity_tier": "T3", "furigana": "市長[しちょう]は、市民[しみん]の声[こえ]をよく聞[き]く人[ひと]だ。", "sentence_source": "generated"}, {"text": "雨の日も、市民は自転車で駅へ向かう。", "target_word": "市民", "complexity_tier": "T3", "furigana": "雨[あめ]の日[ひ]も、市民[しみん]は自転車[じてんしゃ]で駅[えき]へ向[む]かう。", "sentence_source": "generated"}, {"text": "町の市民が力を合わせて、川をきれいにした。", "target_word": "市民", "complexity_tier": "T3", "furigana": "町[まち]の市民[しみん]が力[ちから]を合[あ]わせて、川[かわ]をきれいにした。", "sentence_source": "generated"}, {"text": "市民なら、この体育館を安く使えます。", "target_word": "市民", "complexity_tier": "T3", "furigana": "市民[しみん]なら、この体育館[たいいくかん]を安[やす]く使[つか]えます。", "sentence_source": "generated"}, {"text": "夜遅くまで、市民たちは花火を楽しんだ。", "target_word": "市民", "complexity_tier": "T3", "furigana": "夜遅[よるおそ]くまで、市民[しみん]たちは花火[はなび]を楽[たの]しんだ。", "sentence_source": "generated"}, {"text": "駅前の広場は、市民の休む場所になっている。", "target_word": "市民", "complexity_tier": "T3", "furigana": "駅前[えきまえ]の広場[ひろば]は、市民[しみん]の休[やす]む場所[ばしょ]になっている。", "sentence_source": "generated"}, {"text": "市民からの手紙が、市役所に毎日届く。", "target_word": "市民", "complexity_tier": "T3", "furigana": "市民[しみん]からの手紙[てがみ]が、市役所[しやくしょ]に毎日[まいにち]届[とど]く。", "sentence_source": "generated"}], "morphological_forms": [{"form": "市民", "label": "base"}, {"form": "市民たち", "label": "plural"}], "register": "neutral", "sense_fingerprint": "市民: 町に住む人たち（住民）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bcd0e261-a606-4c8b-a65c-77d92cef559f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35314, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "市民", "is_correct": true, "explanation": "まちに住む人たちを指し、公園のごみを拾う主語として自然に合う。"}, {"text": "王様", "is_correct": false, "explanation": "王様が集まって公園のごみを拾う場面は現実的でなく、文の流れに合わない。"}, {"text": "神様", "is_correct": false, "explanation": "神様が公園でごみを拾ったという内容は、文脈として成り立たない。"}, {"text": "幽霊", "is_correct": false, "explanation": "幽霊が集まってごみを拾う場面は、ふつうの出来事として合わない。"}], "explanations": {"市民": "まちに住む人たちを指し、公園のごみを拾う主語として自然に合う。", "王様": "王様が集まって公園のごみを拾う場面は現実的でなく、文の流れに合わない。", "神様": "神様が公園でごみを拾ったという内容は、文脈として成り立たない。", "幽霊": "幽霊が集まってごみを拾う場面は、ふつうの出来事として合わない。"}, "sentence_index": 0, "correct_answer": "市民"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "夏休みに京都を旅行した市民が、有名な寺の前で写真を撮った。", "explanation": "ここでは市民を〈旅行で来た人〉の意味で使っているが、市民は〈まちに住む人〉を指す。旅行者は住んでいないので、観光客や旅行者を使う。"}, {"text": "この村の市民は、三十人ほどしかいない。", "explanation": "市民は市に住む人を指す。村に住む人は村民や住民と言うので、村の場面では合わない。"}, {"text": "この会議には、市民が三人出席して予算を説明した。", "explanation": "市役所の職員や役人の意味では市民とは言わない。職員や市職員を使う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '034c4210-ad68-4bb4-ae2e-8d82f9a50de0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35314, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "市民", "is_correct": true, "explanation": "この町に住む人として、市の体育館の割引の対象になると読め、「なら」の条件に合う。"}, {"text": "大統領", "is_correct": false, "explanation": "大統領が市の体育館を割引で使うという条件は、文の流れに合わない。"}, {"text": "王子", "is_correct": false, "explanation": "王子が体育館を安く使えるという条件は、この文脈として成り立たない。"}, {"text": "宇宙人", "is_correct": false, "explanation": "宇宙人が市の体育館の割引対象になるという内容は、文の流れに合わない。"}], "explanations": {"市民": "この町に住む人として、市の体育館の割引の対象になると読め、「なら」の条件に合う。", "大統領": "大統領が市の体育館を割引で使うという条件は、文の流れに合わない。", "王子": "王子が体育館を安く使えるという条件は、この文脈として成り立たない。", "宇宙人": "宇宙人が市の体育館の割引対象になるという内容は、文の流れに合わない。"}, "sentence_index": 6, "correct_answer": "市民"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "国会で法律を決めるのは、市民の仕事です。", "explanation": "国会で法律を決めるのは〈国民〉や国会議員の仕事で、市民とは言わない。市民は市に住む人を指すので、国の仕事の場面には合わない。"}, {"text": "この店の市民は、毎週金曜日に特売品を買いに来る。", "explanation": "店に来る客は〈客〉と言う。市民は町に住む人を指すので、店の客の意味では使わない。"}, {"text": "このジムの市民は、毎月の会費を前払いする。", "explanation": "〈会員〉の意味で使うなら自然だが、市民は市に住む人を指す。ジムの利用者は会員と言い、市民とは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '034c4210-ad68-4bb4-ae2e-8d82f9a50de0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35314, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "市民を集まって、公園の掃除をした。", "corrected_sentence": "市民が集まって、公園の掃除をした。", "error_description": "主語を示す「が」が正しい。「を」は他動詞の目的語に使うので、自動詞の「集まる」とは合わない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '034c4210-ad68-4bb4-ae2e-8d82f9a50de0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35314, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "市民を、この体育館を安く使える。", "corrected_sentence": "市民も、この体育館を安く使える。", "error_description": "「市民」も含めて『も』で示すのが正しい。「を」は目的語を示すので、ここでは「使える」の対象として合わない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '034c4210-ad68-4bb4-ae2e-8d82f9a50de0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35315, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「市民を代表して」の「を」。市民を対象にして代表するという意味で自然。"}, {"text": "で", "is_correct": false, "explanation": "「で」は場所や手段を表すので、人を示す市民には続かない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を表すので、「市民へ代表して」は意味が通らない。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較の基準を表すので、代表する対象の市民とは合わない。"}], "correct_answer": "を", "explanations": {"を": "「市民を代表して」の「を」。市民を対象にして代表するという意味で自然。", "で": "「で」は場所や手段を表すので、人を示す市民には続かない。", "へ": "「へ」は方向を表すので、「市民へ代表して」は意味が通らない。", "より": "「より」は比較の基準を表すので、代表する対象の市民とは合わない。"}, "error_tags": {"で": "location_means", "へ": "direction", "より": "comparison"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '034c4210-ad68-4bb4-ae2e-8d82f9a50de0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35315, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「市民の意見」の「の」。意見の持ち主を示す。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すので、「市民へ意見を聞く」は不自然。"}, {"text": "を", "is_correct": false, "explanation": "「を」は目的語を示すので、「市民を意見を聞く」と目的語が二つになり不自然。"}, {"text": "で", "is_correct": false, "explanation": "「で」は手段や場所を示すので、「市民で意見を聞く」は不自然。"}], "correct_answer": "の", "explanations": {"の": "「市民の意見」の「の」。意見の持ち主を示す。", "へ": "「へ」は方向を示すので、「市民へ意見を聞く」は不自然。", "を": "「を」は目的語を示すので、「市民を意見を聞く」と目的語が二つになり不自然。", "で": "「で」は手段や場所を示すので、「市民で意見を聞く」は不自然。"}, "error_tags": {"へ": "direction", "を": "object", "で": "means"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '034c4210-ad68-4bb4-ae2e-8d82f9a50de0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35315, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "都市に住んでいる人々。特に、一般の人々。", "primary_collocate": null, "pronunciation": "しみん", "ipa": "ɕimiɴ", "syllable_count": 3, "sentences": [{"text": "市民の生活を守るために、市は水道を新しくした。", "target_word": "市民", "complexity_tier": "T3", "furigana": "市民[しみん]の生活[せいかつ]を守[まも]るために、市[し]は水道[すいどう]を新[あたら]しくした。", "sentence_source": "generated"}, {"text": "市民を代表して、市長が式に出席した。", "target_word": "市民", "complexity_tier": "T3", "furigana": "市民[しみん]を代表[だいひょう]して、市長[しちょう]が式[しき]に出席[しゅっせき]した。", "sentence_source": "generated"}, {"text": "軍人ではなく、一般の市民が被害にあった。", "target_word": "市民", "complexity_tier": "T3", "furigana": "軍人[ぐんじん]ではなく、一般[いっぱん]の市民[しみん]が被害[ひがい]にあった。", "sentence_source": "generated"}, {"text": "戦争が始まり、市民は安全な場所へ逃げた。", "target_word": "市民", "complexity_tier": "T3", "furigana": "戦争[せんそう]が始[はじ]まり、市民[しみん]は安全[あんぜん]な場所[ばしょ]へ逃[に]げた。", "sentence_source": "generated"}, {"text": "市民が参加できる講座が、毎月開かれている。", "target_word": "市民", "complexity_tier": "T3", "furigana": "市民[しみん]が参加[さんか]できる講座[こうざ]が、毎月[まいつき]開[ひら]かれている。", "sentence_source": "generated"}, {"text": "値上げに反対して、市民が市役所の前に集まった。", "target_word": "市民", "complexity_tier": "T3", "furigana": "値上[ねあ]げに反対[はんたい]して、市民[しみん]が市役所[しやくしょ]の前[まえ]に集[あつ]まった。", "sentence_source": "generated"}, {"text": "彼は特別な地位のない、ふつうの市民として暮らしている。", "target_word": "市民", "complexity_tier": "T3", "furigana": "彼[かれ]は特別[とくべつ]な地位[ちい]のない、ふつうの市民[しみん]として暮[く]らしている。", "sentence_source": "generated"}, {"text": "市民の意見を聞くため、アンケートが行われた。", "target_word": "市民", "complexity_tier": "T3", "furigana": "市民[しみん]の意見[いけん]を聞[き]くため、アンケートが行[おこな]われた。", "sentence_source": "generated"}, {"text": "税金の使い道を、市民はきびしく見ている。", "target_word": "市民", "complexity_tier": "T3", "furigana": "税金[ぜいきん]の使[つか]い道[みち]を、市民[しみん]はきびしく見[み]ている。", "sentence_source": "generated"}, {"text": "災害のとき、市民が助け合う姿が見られた。", "target_word": "市民", "complexity_tier": "T3", "furigana": "災害[さいがい]のとき、市民[しみん]が助[たす]け合[あ]う姿[すがた]が見[み]られた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "市民", "label": "base"}, {"form": "市民たち", "label": "plural"}], "register": "neutral", "sense_fingerprint": "市民: 都市の一般の人々（軍人や役人ではない普通の人）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 8 above tier T2: contains vocabulary far above tier T2: きびしく (Zipf 2.15)']::text[], 'bcd0e261-a606-4c8b-a65c-77d92cef559f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35315, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "市民", "is_correct": true, "explanation": "都市の一般の人々を指し、生活を守る対象として自然に合う。"}, {"text": "王様", "is_correct": false, "explanation": "王様の生活を守るために市が水道を新しくする、という内容は文脈に合わない。"}, {"text": "神様", "is_correct": false, "explanation": "神様の生活を守るために水道を直すという内容は、現実的でなく合わない。"}, {"text": "幽霊", "is_correct": false, "explanation": "幽霊の生活を守るという内容は、市の水道工事の文脈と合わない。"}], "explanations": {"市民": "都市の一般の人々を指し、生活を守る対象として自然に合う。", "王様": "王様の生活を守るために市が水道を新しくする、という内容は文脈に合わない。", "神様": "神様の生活を守るために水道を直すという内容は、現実的でなく合わない。", "幽霊": "幽霊の生活を守るという内容は、市の水道工事の文脈と合わない。"}, "sentence_index": 0, "correct_answer": "市民"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "戦争が始まり、市民は前線へ出て敵と戦った。", "explanation": "ここでは軍人や兵士の意味になるが、市民は軍人ではない一般の人を指す。兵士や軍人と言う。"}, {"text": "市民は市役所の役人として、予算の計画を立てた。", "explanation": "役人を指す場面では市民とは言わない。市民は役人と区別される一般の人を表すので、役人や公務員を使う。"}, {"text": "山あいの村の市民は、畑で米を作って暮らしている。", "explanation": "市民は都市に住む人々を指す。村に住む人は〈村民〉や〈住民〉と言うので、村の場面では合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '034c4210-ad68-4bb4-ae2e-8d82f9a50de0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35315, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "市民", "is_correct": true, "explanation": "特別な地位のない、ふつうの人を指し、「ふつうの〜として暮らす」に自然に合う。"}, {"text": "大統領", "is_correct": false, "explanation": "特別な地位のない大統領という組み合わせは矛盾していて、文の流れに合わない。"}, {"text": "王子", "is_correct": false, "explanation": "特別な地位のない王子という表現は、王族である王子とは両立せず合わない。"}, {"text": "貴族", "is_correct": false, "explanation": "特別な地位のない貴族という内容は、貴族の身分と矛盾するので合わない。"}], "explanations": {"市民": "特別な地位のない、ふつうの人を指し、「ふつうの〜として暮らす」に自然に合う。", "大統領": "特別な地位のない大統領という組み合わせは矛盾していて、文の流れに合わない。", "王子": "特別な地位のない王子という表現は、王族である王子とは両立せず合わない。", "貴族": "特別な地位のない貴族という内容は、貴族の身分と矛盾するので合わない。"}, "sentence_index": 6, "correct_answer": "市民"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "国会で法律を決めるのは、市民の仕事だ。", "explanation": "ここは〈議員〉の意味で使っているが、市民は一般の人を指す。法律を決めるのは国会議員なので、議員を使う。"}, {"text": "この学校の市民は、毎朝校門の前で挨拶をする。", "explanation": "学校に通う人は〈生徒〉や学生と言う。市民は市に住む人を指すので、学校の場面では合わない。"}, {"text": "この会社の市民は、毎朝六時に出社する。", "explanation": "会社に勤める人を指す場面では市民とは言わない。社員や従業員を使う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '034c4210-ad68-4bb4-ae2e-8d82f9a50de0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35315, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "一般の市民に、役所の会議に参加した。", "corrected_sentence": "一般の市民が、役所の会議に参加した。", "error_description": "主語を示す「が」が正しい。「に」は相手や方向を表すので、「参加した」の主語としては合わない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '034c4210-ad68-4bb4-ae2e-8d82f9a50de0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35315, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "市民が声を、市長が聞いた。", "corrected_sentence": "市民の声を、市長が聞いた。", "error_description": "「市民の声」のように名詞を修飾するには「の」が必要。「が」は主語を示すので、「声」を修飾する形として合わない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '034c4210-ad68-4bb4-ae2e-8d82f9a50de0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
