INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35321, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "全体に対して、ある部分がしめる割合。", "primary_collocate": null, "pronunciation": "りつ", "ipa": "ɾitsɯ", "syllable_count": 2, "sentences": [{"text": "例えば、穀物や豆類を主食として摂取する際、その細胞壁に阻まれた栄養は、生体利用率が低いという宿命を背負っている。", "target_word": "率", "complexity_tier": "T3", "furigana": "例[たと]えば、穀物[こくもつ]や豆類[まめるい]を主食[しゅしょく]として摂取[せっしゅ]する際[さい]、その細胞壁[さいぼうへき]に阻[はば]まれた栄養[えいよう]は、生体利用率[せいたいりようりつ]が低[ひく]いという宿命[しゅくめい]を背負[せお]っている。", "sentence_source": "mined"}, {"text": "今年の売り上げのうち、ネット通販が占める率が去年より大きく上がった。", "target_word": "率", "complexity_tier": "T3", "furigana": "今年[ことし]の売[う]り上[あ]げのうち、ネット通販[つうはん]が占[し]める率[りつ]が去年[きょねん]より大[おお]きく上[あ]がった。", "sentence_source": "generated"}, {"text": "この薬は副作用が出る率が低いので、安心して使える。", "target_word": "率", "complexity_tier": "T3", "furigana": "この薬[くすり]は副作用[ふくさよう]が出[で]る率[りつ]が低[ひく]いので、安心[あんしん]して使[つか]える。", "sentence_source": "generated"}, {"text": "試験に合格する率を上げるために、毎日問題集を解いている。", "target_word": "率", "complexity_tier": "T3", "furigana": "試験[しけん]に合格[ごうかく]する率[りつ]を上[あ]げるために、毎日[まいにち]問題集[もんだいしゅう]を解[と]いている。", "sentence_source": "generated"}, {"text": "工場では、不良品が出る率を調べて、原因を探した。", "target_word": "率", "complexity_tier": "T3", "furigana": "工場[こうじょう]では、不良品[ふりょうひん]が出[で]る率[りつ]を調[しら]べて、原因[げんいん]を探[さが]した。", "sentence_source": "generated"}, {"text": "この地域では、全体の世帯のうち共働き世帯の率が十年で大きく上がった。", "target_word": "率", "complexity_tier": "T3", "furigana": "この地域[ちいき]では、全体[ぜんたい]の世帯[せたい]のうち共働[ともばたら]き世帯[せたい]の率[りつ]が十年[じゅうねん]で大[おお]きく上[あ]がった。", "sentence_source": "generated"}, {"text": "この大学は、卒業生が希望の会社に入る率が高いことで知られている。", "target_word": "率", "complexity_tier": "T3", "furigana": "この大学[だいがく]は、卒業生[そつぎょうせい]が希望[きぼう]の会社[かいしゃ]に入[はい]る率[りつ]が高[たか]いことで知[し]られている。", "sentence_source": "generated"}, {"text": "住民の中で高齢者がしめる率は年々増えている。", "target_word": "率", "complexity_tier": "T3", "furigana": "住民[じゅうみん]の中[なか]で高齢者[こうれいしゃ]がしめる率[りつ]は年々[ねんねん]増[ふ]えている。", "sentence_source": "generated"}, {"text": "アンケートでは、賛成と答えた人の率が五割を大きく上回った。", "target_word": "率", "complexity_tier": "T3", "furigana": "アンケートでは、賛成[さんせい]と答[こた]えた人[ひと]の率[りつ]が五割[ごわり]を大[おお]きく上回[うわまわ]った。", "sentence_source": "generated"}, {"text": "この工場では、全製品に占める不良品の率を毎月報告している。", "target_word": "率", "complexity_tier": "T3", "furigana": "この工場[こうじょう]では、全製品[ぜんせいひん]に占[し]める不良品[ふりょうひん]の率[りつ]を毎月[まいつき]報告[ほうこく]している。", "sentence_source": "generated"}], "morphological_forms": [{"form": "率", "label": "基本形"}], "register": "中立", "sense_fingerprint": "全体に対してある部分がしめる割合・比率", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T1: 7 words above tier T1 (max 2): 穀物 (Zipf 3.52), 豆類 (Zipf 2.6), 主食 (Zipf 3.48), 阻ま (Zipf 2.97), 生体 (Zipf 3.81), 宿命 (Zipf 3.57)']::text[], '95d3b987-f670-4e84-a902-8e7233637a42') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35321, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "率", "is_correct": true, "explanation": "「生体利用率」で、摂取した栄養のうち体が利用できる割合を指す。"}, {"text": "効果", "is_correct": false, "explanation": "「生体利用効果」は言わず、吸収される割合を表す語が必要な位置には合わない。"}, {"text": "時間", "is_correct": false, "explanation": "「生体利用時間」は割合を表す語ではなく、「が低い」という文脈に合わない。"}, {"text": "方法", "is_correct": false, "explanation": "「生体利用方法」では栄養の吸収される割合を指せず、文脈に合わない。"}], "explanations": {"率": "「生体利用率」で、摂取した栄養のうち体が利用できる割合を指す。", "効果": "「生体利用効果」は言わず、吸収される割合を表す語が必要な位置には合わない。", "時間": "「生体利用時間」は割合を表す語ではなく、「が低い」という文脈に合わない。", "方法": "「生体利用方法」では栄養の吸収される割合を指せず、文脈に合わない。"}, "sentence_index": 0, "correct_answer": "率"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この教室には、生徒の率が三十人いる。", "explanation": "ここは〈人数〉の意味。率は割合を表し、人の数は表さないので、生徒の数には使えない。"}, {"text": "ここから駅までの率は二キロある。", "explanation": "ここは〈距離〉の意味。率は割合を表し、長さは表さないので、駅までの距離には使えない。"}, {"text": "車の率を上げて、目的地に急ぐ。", "explanation": "ここは〈速度〉の意味。率は割合を表し、速さは表さないので、車の速さには使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d6d98c9-41ee-45f3-a318-58e42f1f84d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35321, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "率", "is_correct": true, "explanation": "「入る率が高い」で、就職や合格などの割合が高いことを表す。"}, {"text": "期間", "is_correct": false, "explanation": "「入る期間が高い」は成り立たず、割合の高さを表す語にならないので合わない。"}, {"text": "年齢", "is_correct": false, "explanation": "「入る年齢が高い」は成り立たず、割合を表す語としては合わない。"}, {"text": "天候", "is_correct": false, "explanation": "天候は空模様を表す語で、「入る」の割合を表す文脈には合わない。"}], "explanations": {"率": "「入る率が高い」で、就職や合格などの割合が高いことを表す。", "期間": "「入る期間が高い」は成り立たず、割合の高さを表す語にならないので合わない。", "年齢": "「入る年齢が高い」は成り立たず、割合を表す語としては合わない。", "天候": "天候は空模様を表す語で、「入る」の割合を表す文脈には合わない。"}, "sentence_index": 6, "correct_answer": "率"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この荷物の率は五キロある。", "explanation": "ここは〈重さ〉の意味。率は割合を表し、重さは表さないので、荷物の重量には使えない。"}, {"text": "山の率は千メートルだ。", "explanation": "ここは〈高さ〉の意味。率は割合を表し、長さや高さは表さないので、山の高さには使えない。"}, {"text": "作業にかかる率を短くする。", "explanation": "ここは〈所要時間〉の意味。率は割合を表し、時間は表さないので、作業時間の増減には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d6d98c9-41ee-45f3-a318-58e42f1f84d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35321, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "新しい機械を入れてから、不良品の率に下がった。", "corrected_sentence": "新しい機械を入れてから、不良品の率が下がった。", "error_description": "「下がる」の主語は「率」なので「が」が正しい。「に」は誤り（正しい形：不良品の率が下がった）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d6d98c9-41ee-45f3-a318-58e42f1f84d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35321, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "調査の結果、この地域の率を前年より下がった。", "corrected_sentence": "調査の結果、この地域の率が前年より下がった。", "error_description": "「下がる」は自動詞なので主語に「が」を取る。「率を」は誤りで、正しくは「率が」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d6d98c9-41ee-45f3-a318-58e42f1f84d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35323, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "下降", "is_correct": true, "explanation": "気球が上へ上がるのと反対に、下へ下がることを表す反対語。"}, {"text": "向上", "is_correct": false, "explanation": "程度が上がることで、「上昇」と近い意味であり、反対語ではない。"}, {"text": "増加", "is_correct": false, "explanation": "数量が増えることで、「上昇」に近く、反対語ではない。"}, {"text": "拡大", "is_correct": false, "explanation": "規模が大きくなることで、「上昇」に近く、反対語ではない。"}], "correct_answer": "下降", "explanations": {"下降": "気球が上へ上がるのと反対に、下へ下がることを表す反対語。", "向上": "程度が上がることで、「上昇」と近い意味であり、反対語ではない。", "増加": "数量が増えることで、「上昇」に近く、反対語ではない。", "拡大": "規模が大きくなることで、「上昇」に近く、反対語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5565bce-284d-44c9-b74e-bf8928672917') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35323, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「金利の上昇」と、名詞「上昇」の主体を示す「の」が正しい。"}, {"text": "が", "is_correct": false, "explanation": "「金利が上昇により」では「により」とつながらず、文として成り立たない。"}, {"text": "を", "is_correct": false, "explanation": "「金利を上昇により」では「により」とつながらず、文として成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を表すので、名詞同士をつなげない。"}], "correct_answer": "の", "explanations": {"の": "「金利の上昇」と、名詞「上昇」の主体を示す「の」が正しい。", "が": "「金利が上昇により」では「により」とつながらず、文として成り立たない。", "を": "「金利を上昇により」では「により」とつながらず、文として成り立たない。", "へ": "「へ」は方向を表すので、名詞同士をつなげない。"}, "error_tags": {"が": "wrong_case_marker", "を": "wrong_case_marker", "へ": "direction"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "低下", "is_correct": true, "explanation": "体温が上がるのと反対に、数値が下がることを表す反対語。"}, {"text": "上達", "is_correct": false, "explanation": "技術が上がることで、「上昇」に近く、反対語ではない。"}, {"text": "増大", "is_correct": false, "explanation": "量が大きくなることで、「上昇」に近く、反対語ではない。"}, {"text": "加速", "is_correct": false, "explanation": "速度が上がることで、「上昇」に近く、反対語ではない。"}], "correct_answer": "低下", "explanations": {"低下": "体温が上がるのと反対に、数値が下がることを表す反対語。", "上達": "技術が上がることで、「上昇」に近く、反対語ではない。", "増大": "量が大きくなることで、「上昇」に近く、反対語ではない。", "加速": "速度が上がることで、「上昇」に近く、反対語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5565bce-284d-44c9-b74e-bf8928672917') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35323, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "数値や程度が高くなること。上がること。", "primary_collocate": null, "pronunciation": "じょうしょう", "ipa": "dʑoːɕoː", "syllable_count": 4, "sentences": [{"text": "さらに、こうした非伝統的な金融政策がインフレ期待のアンカーとして機能し得る一方で、過剰な流動性が実体経済における物価上昇圧力と相乗効果を生み、予期せぬスタグフレーションや財政主導のシナリオへと帰結するリスクを常に内包していることを、我々は冷徹に認識する責務を負っている。", "target_word": "上昇", "complexity_tier": "T6", "furigana": "さらに、こうしたひでんとうてきなきんゆうせいさくがインフレきたいのアンカーとしてきのうしえるいっぽうで、かじょうなりゅうどうせいがじったいけいざいにおけるぶっかじょうしょうあつりょくとそうじょうこうかをうみ、よきせぬスタグフレーションやざいせいしゅどうのシナリオへときけつするリスクをつねにないほうしていることを、われわれはれいてつににんしきするせきむをおっている。", "sentence_source": "mined"}, {"text": "気温が上昇する。", "target_word": "上昇", "complexity_tier": "T1", "furigana": "きおんがじょうしょうする。", "sentence_source": "generated"}, {"text": "物価の上昇が続いています。", "target_word": "上昇", "complexity_tier": "T2", "furigana": "ぶっかのじょうしょうがつづいています。", "sentence_source": "generated"}, {"text": "気球はゆっくり上昇した。", "target_word": "上昇", "complexity_tier": "T3", "furigana": "ききゅうはゆっくりじょうしょうした。", "sentence_source": "generated"}, {"text": "水温が上昇して、魚が減っている。", "target_word": "上昇", "complexity_tier": "T3", "furigana": "すいおんがじょうしょうして、さかながへっている。", "sentence_source": "generated"}, {"text": "今年は失業率が上昇した。", "target_word": "上昇", "complexity_tier": "T3", "furigana": "ことしはしつぎょうりつがじょうしょうした。", "sentence_source": "generated"}, {"text": "株価は急に上昇し始めました。", "target_word": "上昇", "complexity_tier": "T2", "furigana": "かぶかはきゅうにじょうしょうしはじめました。", "sentence_source": "generated"}, {"text": "金利の上昇により、ローンの負担が重くなった。", "target_word": "上昇", "complexity_tier": "T4", "furigana": "きんりのじょうしょうにより、ローンのふたんがおもくなった。", "sentence_source": "generated"}, {"text": "上昇を続ける地価に、市民は不安を感じている。", "target_word": "上昇", "complexity_tier": "T4", "furigana": "じょうしょうをつづけるちかに、しみんはふあんをかんじている。", "sentence_source": "generated"}, {"text": "体温が上昇しないように、水をこまめに飲んだ。", "target_word": "上昇", "complexity_tier": "T4", "furigana": "たいおんがじょうしょうしないように、みずをこまめにのんだ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "上昇する", "label": "活用"}, {"form": "上昇した", "label": "活用"}, {"form": "上昇率", "label": "派生"}, {"form": "上昇気流", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 数値や程度が高くなること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T2: contains vocabulary far above tier T2: スタグフレーション (Zipf 1.93)']::text[], '78030f87-aae1-459b-9e77-753f1c3b3c04') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35323, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "上昇", "is_correct": true, "explanation": "聞こえた語そのもの「じょうしょう」で、正解。"}, {"text": "交渉", "is_correct": false, "explanation": "「こうしょう」で、最初の音が「じょ」ではなく「こ」。"}, {"text": "凍傷", "is_correct": false, "explanation": "「とうしょう」で、最初の音が「じょ」ではなく「と」。"}, {"text": "常食", "is_correct": false, "explanation": "「じょうしょく」で、最後の音が「う」ではなく「く」。"}, {"text": "少々", "is_correct": false, "explanation": "「しょうしょう」で、最初の音が「じょ」ではなく「しょ」。"}], "explanations": {"上昇": "聞こえた語そのもの「じょうしょう」で、正解。", "交渉": "「こうしょう」で、最初の音が「じょ」ではなく「こ」。", "凍傷": "「とうしょう」で、最初の音が「じょ」ではなく「と」。", "常食": "「じょうしょく」で、最後の音が「う」ではなく「く」。", "少々": "「しょうしょう」で、最初の音が「じょ」ではなく「しょ」。"}, "sentence_index": null, "correct_answer": "上昇"}, "level_3": {"options": [{"text": "上昇", "is_correct": true, "explanation": "物価が高くなる圧力という意味で、文脈に合う。"}, {"text": "出張", "is_correct": false, "explanation": "形は合うが意味が合わない。物価が出張する圧力という意味にならない。"}, {"text": "結婚", "is_correct": false, "explanation": "形は合うが意味が合わない。物価が結婚する圧力という意味にならない。"}, {"text": "卒業", "is_correct": false, "explanation": "形は合うが意味が合わない。物価が卒業する圧力という意味にならない。"}], "explanations": {"上昇": "物価が高くなる圧力という意味で、文脈に合う。", "出張": "形は合うが意味が合わない。物価が出張する圧力という意味にならない。", "結婚": "形は合うが意味が合わない。物価が結婚する圧力という意味にならない。", "卒業": "形は合うが意味が合わない。物価が卒業する圧力という意味にならない。"}, "sentence_index": 0, "correct_answer": "上昇"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "気球は地面に向かってゆっくり上昇した。", "explanation": "「上昇」は上へ上がることなので、「地面に向かって」という下向きの動きとは矛盾する。"}, {"text": "今朝は気温が上昇して、昨日よりずっと寒くなった。", "explanation": "「上昇」は数値が高くなることなので、「寒くなった」とは意味が矛盾する。"}, {"text": "弟は走って階段を上昇し、二階の部屋に入った。", "explanation": "人が階段を上がる動作には「上昇」は使わず、「上る」が自然。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5565bce-284d-44c9-b74e-bf8928672917') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35323, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "上昇", "is_correct": true, "explanation": "聞こえた語そのもの「じょうしょう」で、正解。"}, {"text": "褒賞", "is_correct": false, "explanation": "「ほうしょう」で、最初の音が「じょ」ではなく「ほ」。"}, {"text": "幼少", "is_correct": false, "explanation": "「ようしょう」で、最初の音が「じょ」ではなく「よ」。"}, {"text": "常習", "is_correct": false, "explanation": "「じょうしゅう」で、三番目の音が「しょ」ではなく「しゅ」。"}, {"text": "上々", "is_correct": false, "explanation": "「じょうじょう」で、三番目の音が「しょ」ではなく「じょ」。"}], "explanations": {"上昇": "聞こえた語そのもの「じょうしょう」で、正解。", "褒賞": "「ほうしょう」で、最初の音が「じょ」ではなく「ほ」。", "幼少": "「ようしょう」で、最初の音が「じょ」ではなく「よ」。", "常習": "「じょうしゅう」で、三番目の音が「しょ」ではなく「しゅ」。", "上々": "「じょうじょう」で、三番目の音が「しょ」ではなく「じょ」。"}, "sentence_index": null, "correct_answer": "上昇"}, "level_3": {"options": [{"text": "上昇", "is_correct": true, "explanation": "株価が上がり始めたという意味で、文脈に合う。"}, {"text": "卒業", "is_correct": false, "explanation": "形は合うが意味が合わない。株価が卒業し始めることはない。"}, {"text": "入浴", "is_correct": false, "explanation": "形は合うが意味が合わない。株価が入浴し始めることはない。"}, {"text": "乗車", "is_correct": false, "explanation": "形は合うが意味が合わない。株価が乗車し始めることはない。"}], "explanations": {"上昇": "株価が上がり始めたという意味で、文脈に合う。", "卒業": "形は合うが意味が合わない。株価が卒業し始めることはない。", "入浴": "形は合うが意味が合わない。株価が入浴し始めることはない。", "乗車": "形は合うが意味が合わない。株価が乗車し始めることはない。"}, "sentence_index": 6, "correct_answer": "上昇"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "雨が降り続いて、川の水位が上昇し、どんどん下がっていった。", "explanation": "「上昇」は高くなることなので、「下がっていった」とは意味が矛盾する。"}, {"text": "部屋が寒かったので、暖房を入れて室温が上昇しないようにした。", "explanation": "寒い部屋を暖めるのに「上昇しないように」は目的が逆で、意味が合わない。"}, {"text": "猫が机の上から床へ上昇して、ご飯を食べ始めた。", "explanation": "上から下へ移る動きに「上昇」は使えず、方向が逆。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5565bce-284d-44c9-b74e-bf8928672917') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35323, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "春になって、気温を上昇した。", "corrected_sentence": "春になって、気温が上昇した。", "error_description": "「上昇する」は自動詞的に使い、上がるものは「が」で示す。「気温を」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5565bce-284d-44c9-b74e-bf8928672917') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35323, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "今月は電気代を上昇している。", "corrected_sentence": "今月は電気代が上昇している。", "error_description": "上がるものは「が」で示す。「電気代を」では「上昇している」とつながらず誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5565bce-284d-44c9-b74e-bf8928672917') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35325, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "「相乗効果で」は、売り上げが伸びた原因を表します。"}, {"text": "を", "is_correct": false, "explanation": "「伸びる」は自動詞なので、「相乗効果を」とは言えません。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を表します。原因は表せないので文になりません。"}, {"text": "が", "is_correct": false, "explanation": "主語の「売り上げが」がすでにあるので、「相乗効果が」は入りません。"}], "correct_answer": "で", "explanations": {"で": "「相乗効果で」は、売り上げが伸びた原因を表します。", "を": "「伸びる」は自動詞なので、「相乗効果を」とは言えません。", "へ": "「へ」は方向を表します。原因は表せないので文になりません。", "が": "主語の「売り上げが」がすでにあるので、「相乗効果が」は入りません。"}, "error_tags": {"を": "object_marker", "へ": "direction", "が": "subject_marker"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "相殺", "is_correct": true, "explanation": "互いに打ち消し合うことで、「相乗」の反対です。"}, {"text": "協力", "is_correct": false, "explanation": "力を合わせることで、反対の意味ではありません。"}, {"text": "増幅", "is_correct": false, "explanation": "大きくすることで、「相乗」に近い意味です。"}, {"text": "相互", "is_correct": false, "explanation": "お互いという意味で、反対ではありません。"}], "correct_answer": "相殺", "explanations": {"相殺": "互いに打ち消し合うことで、「相乗」の反対です。", "協力": "力を合わせることで、反対の意味ではありません。", "増幅": "大きくすることで、「相乗」に近い意味です。", "相互": "お互いという意味で、反対ではありません。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9f253fac-b463-490d-880c-dfb43e853640') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35325, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「相乗効果を狙う」で、「狙う」の目的語を示します。"}, {"text": "が", "is_correct": false, "explanation": "「相乗効果が狙う」では、効果が狙う側になり意味が合いません。"}, {"text": "へ", "is_correct": false, "explanation": "「相乗効果へ狙う」は不自然で文になりません。"}, {"text": "に", "is_correct": false, "explanation": "「相乗効果に狙う」は「狙う」の目的語の形として誤りです。"}], "correct_answer": "を", "explanations": {"を": "「相乗効果を狙う」で、「狙う」の目的語を示します。", "が": "「相乗効果が狙う」では、効果が狙う側になり意味が合いません。", "へ": "「相乗効果へ狙う」は不自然で文になりません。", "に": "「相乗効果に狙う」は「狙う」の目的語の形として誤りです。"}, "error_tags": {"が": "subject_marker", "へ": "direction", "に": "target_marker"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "減殺", "is_correct": true, "explanation": "効果を弱めて減らすことで、「相乗」の反対です。"}, {"text": "増幅", "is_correct": false, "explanation": "大きくすることで、「相乗」に近い意味です。"}, {"text": "連携", "is_correct": false, "explanation": "協力してつながることで、反対の意味ではありません。"}, {"text": "協調", "is_correct": false, "explanation": "協力して歩調を合わせることで、反対ではありません。"}], "correct_answer": "減殺", "explanations": {"減殺": "効果を弱めて減らすことで、「相乗」の反対です。", "増幅": "大きくすることで、「相乗」に近い意味です。", "連携": "協力してつながることで、反対の意味ではありません。", "協調": "協力して歩調を合わせることで、反対ではありません。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9f253fac-b463-490d-880c-dfb43e853640') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35325, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "複数の要素が互いに影響し合い、効果を強め合うこと。", "primary_collocate": null, "pronunciation": "そうじょう", "ipa": "soːdʑoː", "syllable_count": 4, "sentences": [{"text": "さらに、こうした非伝統的な金融政策がインフレ期待のアンカーとして機能し得る一方で、過剰な流動性が実体経済における物価上昇圧力と相乗効果を生み、予期せぬスタグフレーションや財政主導のシナリオへと帰結するリスクを常に内包していることを、我々は冷徹に認識する責務を負っている。", "target_word": "相乗", "complexity_tier": "T6", "furigana": "さらに、こうした非伝統的[ひでんとうてき]な金融政策[きんゆうせいさく]がインフレ期待[きたい]のアンカーとして機能[きのう]し得[う]る一方[いっぽう]で、過剰[かじょう]な流動性[りゅうどうせい]が実体経済[じったいけいざい]における物価[ぶっか]上昇[じょうしょう]圧力[あつりょく]と相乗[そうじょう]効果[こうか]を生[う]み、予期[よき]せぬスタグフレーションや財政[ざいせい]主導[しゅどう]のシナリオへと帰結[きけつ]するリスクを常[つね]に内包[ないほう]していることを、我々[われわれ]は冷徹[れいてつ]に認識[にんしき]する責務[せきむ]を負[お]っている。", "sentence_source": "mined"}, {"text": "広告と値引きの相乗効果で、売り上げが伸びた。", "target_word": "相乗", "complexity_tier": "T3", "furigana": "広告[こうこく]と値引[ねび]きの相乗[そうじょう]効果[こうか]で、売[う]り上[あ]げが伸[の]びた。", "sentence_source": "generated"}, {"text": "二人の力が相乗して成果が出た。", "target_word": "相乗", "complexity_tier": "T3", "furigana": "二人[ふたり]の力[ちから]が相乗[そうじょう]して成果[せいか]が出[で]た。", "sentence_source": "generated"}, {"text": "音楽と映像が相乗して、感動が深まった。", "target_word": "相乗", "complexity_tier": "T3", "furigana": "音楽[おんがく]と映像[えいぞう]が相乗[そうじょう]して、感動[かんどう]が深[ふか]まった。", "sentence_source": "generated"}, {"text": "勉強と運動の相乗効果を期待している。", "target_word": "相乗", "complexity_tier": "T3", "furigana": "勉強[べんきょう]と運動[うんどう]の相乗[そうじょう]効果[こうか]を期待[きたい]している。", "sentence_source": "generated"}, {"text": "広告と値下げが相乗し、客が急に増えた。", "target_word": "相乗", "complexity_tier": "T3", "furigana": "広告[こうこく]と値下[ねさ]げが相乗[そうじょう]し、客[きゃく]が急[きゅう]に増[ふ]えた。", "sentence_source": "generated"}, {"text": "二つの会社の技術が相乗することで、新しい商品が生まれた。", "target_word": "相乗", "complexity_tier": "T4", "furigana": "二[ふた]つの会社[かいしゃ]の技術[ぎじゅつ]が相乗[そうじょう]することで、新[あたら]しい商品[しょうひん]が生[う]まれた。", "sentence_source": "generated"}, {"text": "相乗効果を狙うなら、役割を分けて協力するのがよい。", "target_word": "相乗", "complexity_tier": "T4", "furigana": "相乗[そうじょう]効果[こうか]を狙[ねら]うなら、役割[やくわり]を分[わ]けて協力[きょうりょく]するのがよい。", "sentence_source": "generated"}, {"text": "チームの意欲と環境の改善が相乗した結果、事故が大きく減った。", "target_word": "相乗", "complexity_tier": "T4", "furigana": "チームの意欲[いよく]と環境[かんきょう]の改善[かいぜん]が相乗[そうじょう]した結果[けっか]、事故[じこ]が大[おお]きく減[へ]った。", "sentence_source": "generated"}, {"text": "良い習慣は相乗して、やがて大きな変化を生む。", "target_word": "相乗", "complexity_tier": "T4", "furigana": "良[よ]い習慣[しゅうかん]は相乗[そうじょう]して、やがて大[おお]きな変化[へんか]を生[う]む。", "sentence_source": "generated"}], "morphological_forms": [{"form": "相乗する", "label": "派生"}, {"form": "相乗効果", "label": "派生"}, {"form": "相乗作用", "label": "派生"}, {"form": "相乗的", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | 要素が互いに効果を強め合うこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '61f01209-a5ab-450f-a9fd-dfc8a97e8f9f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35325, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "相乗", "is_correct": true, "explanation": "見出し語の「そうじょう」そのものです。"}, {"text": "操縦", "is_correct": false, "explanation": "「そうじゅう」は三音目だけが違う別の語です。"}, {"text": "総称", "is_correct": false, "explanation": "「そうしょう」は三音目だけが違う別の語です。"}, {"text": "想像", "is_correct": false, "explanation": "「そうぞう」は三音目だけが違う別の語です。"}, {"text": "相当", "is_correct": false, "explanation": "「そうとう」は三音目だけが違う別の語です。"}], "explanations": {"相乗": "見出し語の「そうじょう」そのものです。", "操縦": "「そうじゅう」は三音目だけが違う別の語です。", "総称": "「そうしょう」は三音目だけが違う別の語です。", "想像": "「そうぞう」は三音目だけが違う別の語です。", "相当": "「そうとう」は三音目だけが違う別の語です。"}, "sentence_index": null, "correct_answer": "相乗"}, "level_3": {"options": [{"text": "相乗", "is_correct": true, "explanation": "「相乗効果」で、要素が互いに強め合う効果を表します。"}, {"text": "単独", "is_correct": false, "explanation": "形は合うが意味が合わない。「単独効果」では強め合う意味が出ません。"}, {"text": "偶然", "is_correct": false, "explanation": "形は合うが意味が合わない。「偶然効果」は文脈に合いません。"}, {"text": "試験", "is_correct": false, "explanation": "形は合うが意味が合わない。「試験効果」は圧力との関係を表しません。"}], "explanations": {"相乗": "「相乗効果」で、要素が互いに強め合う効果を表します。", "単独": "形は合うが意味が合わない。「単独効果」では強め合う意味が出ません。", "偶然": "形は合うが意味が合わない。「偶然効果」は文脈に合いません。", "試験": "形は合うが意味が合わない。「試験効果」は圧力との関係を表しません。"}, "sentence_index": 0, "correct_answer": "相乗"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "兄と弟が相乗して、毎日けんかばかりしている。", "explanation": "「相乗」は良い効果を強め合うことで、けんかには使えません。"}, {"text": "彼は一人で相乗して、仕事を全部終えた。", "explanation": "「相乗」は複数の要素が影響し合うことで、一人の行動には使えません。"}, {"text": "二つの薬を混ぜたら相乗して、効果が打ち消し合った。", "explanation": "「相乗」は効果を強め合うことで、打ち消し合うことではありません。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9f253fac-b463-490d-880c-dfb43e853640') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35325, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "相乗", "is_correct": true, "explanation": "見出し語の「そうじょう」そのものです。"}, {"text": "総長", "is_correct": false, "explanation": "「そうちょう」は三音目だけが違う別の語です。"}, {"text": "操業", "is_correct": false, "explanation": "「そうぎょう」は三音目だけが違う別の語です。"}, {"text": "創造", "is_correct": false, "explanation": "「そうぞう」は三音目だけが違う別の語です。"}, {"text": "早々", "is_correct": false, "explanation": "「そうそう」は三音目だけが違う別の語です。"}], "explanations": {"相乗": "見出し語の「そうじょう」そのものです。", "総長": "「そうちょう」は三音目だけが違う別の語です。", "操業": "「そうぎょう」は三音目だけが違う別の語です。", "創造": "「そうぞう」は三音目だけが違う別の語です。", "早々": "「そうそう」は三音目だけが違う別の語です。"}, "sentence_index": null, "correct_answer": "相乗"}, "level_3": {"options": [{"text": "相乗", "is_correct": true, "explanation": "技術が互いに強め合って新商品が生まれたという意味で自然です。"}, {"text": "停止", "is_correct": false, "explanation": "形は合うが意味が合わない。技術が停止して新商品が生まれるのは不自然です。"}, {"text": "消滅", "is_correct": false, "explanation": "形は合うが意味が合わない。技術が消滅して新商品が生まれるのは矛盾します。"}, {"text": "欠席", "is_correct": false, "explanation": "形は合うが意味が合わない。技術は欠席しません。"}], "explanations": {"相乗": "技術が互いに強め合って新商品が生まれたという意味で自然です。", "停止": "形は合うが意味が合わない。技術が停止して新商品が生まれるのは不自然です。", "消滅": "形は合うが意味が合わない。技術が消滅して新商品が生まれるのは矛盾します。", "欠席": "形は合うが意味が合わない。技術は欠席しません。"}, "sentence_index": 6, "correct_answer": "相乗"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "雨が降ったので、試合が相乗して中止になった。", "explanation": "「相乗」は要素が効果を強め合うことで、中止の理由には使えません。"}, {"text": "机の上のペンが相乗して、床に落ちた。", "explanation": "「相乗」は物が動くことではなく、効果を強め合うことです。"}, {"text": "二つの悪い癖が相乗して、効果をすっかり打ち消してしまった。", "explanation": "「相乗」は強め合うことで、打ち消すことではありません。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9f253fac-b463-490d-880c-dfb43e853640') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35325, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "二人の力が相乗して、成果が少なくなった。", "corrected_sentence": "二人の力が相乗して、成果が大きくなった。", "error_description": "「相乗」は効果を強め合うので、「成果が少なくなった」は意味が合わない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9f253fac-b463-490d-880c-dfb43e853640') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35325, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "広告と値下げを相乗し、客が増えた。", "corrected_sentence": "広告と値下げが相乗し、客が増えた。", "error_description": "「相乗する」の主語は「が」で示すべきで、「を」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9f253fac-b463-490d-880c-dfb43e853640') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35335, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「革命が成功すると」の主語を示す「が」で、革命を主語として正しく示す。"}, {"text": "を", "is_correct": false, "explanation": "「成功する」は自動詞なので目的語の「を」は取らず、ここでは主語の「が」が必要。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表す「へ」は、成功の行き先を示す語ではないので合わない。"}, {"text": "より", "is_correct": false, "explanation": "比較の「より」は比べる対象が必要で、ここでは比較の文脈がないので意味が通らない。"}], "correct_answer": "が", "explanations": {"が": "「革命が成功すると」の主語を示す「が」で、革命を主語として正しく示す。", "を": "「成功する」は自動詞なので目的語の「を」は取らず、ここでは主語の「が」が必要。", "へ": "方向を表す「へ」は、成功の行き先を示す語ではないので合わない。", "より": "比較の「より」は比べる対象が必要で、ここでは比較の文脈がないので意味が通らない。"}, "error_tags": {"を": "目的語", "へ": "方向", "より": "比較"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9686e2d0-6371-4d95-b595-0553546cb3e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
