INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35335, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "ある状態から別の全く異なる状態へと変わること。特に、社会や制度などが根本的に変わること。", "primary_collocate": null, "pronunciation": "かくめい", "ipa": "kakɯmeː", "syllable_count": 4, "sentences": [{"text": "しかし、急激な革命によって、この循環に深刻な破綻をもたらした。", "target_word": "革命", "complexity_tier": "T4", "furigana": "しかし、急激[きゅうげき]な革命[かくめい]によって、この循環[じゅんかん]に深刻[しんこく]な破綻[はたん]をもたらした。", "sentence_source": "generated"}, {"text": "革命が成功すると、王の支配は終わり、新しい政府が作られた。", "target_word": "革命", "complexity_tier": "T3", "furigana": "革命[かくめい]が成功[せいこう]すると、王[おう]の支配[しはい]は終[お]わり、新[あたら]しい政府[せいふ]が作[つく]られた。", "sentence_source": "generated"}, {"text": "農民たちは革命を起こし、古い制度を倒した。", "target_word": "革命", "complexity_tier": "T3", "furigana": "農民[のうみん]たちは革命[かくめい]を起[お]こし、古[ふる]い制度[せいど]を倒[たお]した。", "sentence_source": "generated"}, {"text": "スマートフォンの登場は、人々の生活に革命をもたらした。", "target_word": "革命", "complexity_tier": "T3", "furigana": "スマートフォンの登場[とうじょう]は、人々[ひとびと]の生活[せいかつ]に革命[かくめい]をもたらした。", "sentence_source": "generated"}, {"text": "革命によって、国の政治の仕組みは根本から変わった。", "target_word": "革命", "complexity_tier": "T3", "furigana": "革命[かくめい]によって、国[くに]の政治[せいじ]の仕組[しく]みは根本[こんぽん]から変[か]わった。", "sentence_source": "generated"}, {"text": "彼の発明は医療の世界に革命を起こし、多くの命が救われた。", "target_word": "革命", "complexity_tier": "T3", "furigana": "彼[かれ]の発明[はつめい]は医療[いりょう]の世界[せかい]に革命[かくめい]を起[お]こし、多[おお]くの命[いのち]が救[すく]われた。", "sentence_source": "generated"}, {"text": "革命の指導者たちは、国民に新しい憲法を約束した。", "target_word": "革命", "complexity_tier": "T3", "furigana": "革命[かくめい]の指導者[しどうしゃ]たちは、国民[こくみん]に新[あたら]しい憲法[けんぽう]を約束[やくそく]した。", "sentence_source": "generated"}, {"text": "音楽の配信が広まり、レコード業界に革命が起きた。", "target_word": "革命", "complexity_tier": "T3", "furigana": "音楽[おんがく]の配信[はいしん]が広[ひろ]まり、レコード業界[ぎょうかい]に革命[かくめい]が起[お]きた。", "sentence_source": "generated"}, {"text": "長く続いた王政は、革命で倒れた。", "target_word": "革命", "complexity_tier": "T3", "furigana": "長[なが]く続[つづ]いた王政[おうせい]は、革命[かくめい]で倒[たお]れた。", "sentence_source": "generated"}, {"text": "革命のあと、国の名前も国旗も変わった。", "target_word": "革命", "complexity_tier": "T3", "furigana": "革命[かくめい]のあと、国[くに]の名前[なまえ]も国旗[こっき]も変[か]わった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "革命", "label": "基本形"}, {"form": "革命を", "label": "目的格"}, {"form": "革命が", "label": "主格"}, {"form": "革命で", "label": "手段格"}], "register": "neutral", "sense_fingerprint": "社会・制度・分野が根本から全く別の状態に変わること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0888c172-05ca-47fc-b033-bf6b11e5f019') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35335, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "革命", "is_correct": true, "explanation": "「急激な革命」は社会や制度の根本的な変化を指し、文脈に合う。"}, {"text": "恋愛", "is_correct": false, "explanation": "「急激な恋愛」は意味が通らず、循環の破綻の原因を表せない。"}, {"text": "名曲", "is_correct": false, "explanation": "「急激な名曲」は意味をなさず、循環の破綻の原因にならない。"}, {"text": "旅行", "is_correct": false, "explanation": "「急激な旅行」は意味が通らず、循環の破綻の原因を表せない。"}], "explanations": {"革命": "「急激な革命」は社会や制度の根本的な変化を指し、文脈に合う。", "恋愛": "「急激な恋愛」は意味が通らず、循環の破綻の原因を表せない。", "名曲": "「急激な名曲」は意味をなさず、循環の破綻の原因にならない。", "旅行": "「急激な旅行」は意味が通らず、循環の破綻の原因を表せない。"}, "sentence_index": 0, "correct_answer": "革命"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "天気が急に革命した。", "explanation": "ここは〈変化〉の意味。革命は社会や制度が根本から変わることを指すので、天気の移り変わりには使わない。"}, {"text": "古い冷蔵庫を革命して、電気代が少し安くなった。", "explanation": "ここは〈改良〉の意味。革命は根本的な変化なので、小さな改良を表すのには使わない。"}, {"text": "彼は、お茶を革命して飲み干した。", "explanation": "ここは〈一気に〉の意味。革命は社会や制度の根本的な変化を指すので、飲み方の勢いを表すのには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9686e2d0-6371-4d95-b595-0553546cb3e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35335, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "革命", "is_correct": true, "explanation": "「革命の指導者」は、社会を変える運動の指導者を指し、文脈に合う。"}, {"text": "雑音", "is_correct": false, "explanation": "「雑音の指導者」は意味が通らず、憲法を約束する指導者には合わない。"}, {"text": "迷路", "is_correct": false, "explanation": "「迷路の指導者」は不自然で、国民への約束を述べる文脈に合わない。"}, {"text": "嫌悪", "is_correct": false, "explanation": "「嫌悪の指導者」は意味をなさず、指導者の役割を表せない。"}], "explanations": {"革命": "「革命の指導者」は、社会を変える運動の指導者を指し、文脈に合う。", "雑音": "「雑音の指導者」は意味が通らず、憲法を約束する指導者には合わない。", "迷路": "「迷路の指導者」は不自然で、国民への約束を述べる文脈に合わない。", "嫌悪": "「嫌悪の指導者」は意味をなさず、指導者の役割を表せない。"}, "sentence_index": 6, "correct_answer": "革命"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は毎朝ジョギングの距離を革命した。", "explanation": "ここは〈延ばす〉の意味。革命は根本からの変化を表すので、距離を少し増やすことには使わない。"}, {"text": "雨の日は外出を革命するべきだ。", "explanation": "ここは〈控える〉の意味。革命は社会や制度の変化を指すので、外出を控える行動には使わない。"}, {"text": "彼は連休中、ずっと家で革命していた。", "explanation": "ここは〈ごろごろ過ごす〉の意味。革命は社会や制度の根本的な変化を指すので、休日の過ごし方には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9686e2d0-6371-4d95-b595-0553546cb3e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35335, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "長年の不満から、ついに革命を起きた。", "corrected_sentence": "長年の不満から、ついに革命が起きた。", "error_description": "「起きる」は自動詞なので「革命が起きる」と「が」を取る。「を」は他動詞「起こす」の目的語に付く助詞で、ここでは誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9686e2d0-6371-4d95-b595-0553546cb3e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35335, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "革命な成功は国の仕組みを変えた。", "corrected_sentence": "革命の成功は国の仕組みを変えた。", "error_description": "「革命」は名詞なので、名詞を修飾するには「の」を使う。「革命な」は形容動詞の語尾を名詞に付けた誤りで、語の形が合わない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9686e2d0-6371-4d95-b595-0553546cb3e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35336, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「背景に描かれている」の場所を示す「に」。"}, {"text": "を", "is_correct": false, "explanation": "「背景を描かれている」と目的語にすると、受け身の文が成り立たない。"}, {"text": "より", "is_correct": false, "explanation": "「背景より青い空が描かれている」は比較の形になり、場所の説明にならない。"}, {"text": "から", "is_correct": false, "explanation": "「絵の背景から青い空と白い雲が描かれている」は起点の意味になり、描かれる場所を示せない。"}], "correct_answer": "に", "explanations": {"に": "「背景に描かれている」の場所を示す「に」。", "を": "「背景を描かれている」と目的語にすると、受け身の文が成り立たない。", "より": "「背景より青い空が描かれている」は比較の形になり、場所の説明にならない。", "から": "「絵の背景から青い空と白い雲が描かれている」は起点の意味になり、描かれる場所を示せない。"}, "error_tags": {"を": "目的語", "より": "比較", "から": "起点"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ed848d40-3489-4681-91c1-79fe346d2be0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35336, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ed848d40-3489-4681-91c1-79fe346d2be0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35336, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "絵・写真・舞台などで、主役のうしろに見える景色や画面のこと。", "primary_collocate": null, "pronunciation": "はいけい", "ipa": "haikeː", "syllable_count": 4, "sentences": [{"text": "この写真は、後ろの山を背景にして撮った。", "target_word": "背景", "complexity_tier": "T3", "furigana": "この写真(しゃしん)は、後(うし)ろの山(やま)を背景(はいけい)にして撮(と)った。", "sentence_source": "generated"}, {"text": "絵の背景には、青い空と白い雲が描かれている。", "target_word": "背景", "complexity_tier": "T3", "furigana": "絵(え)の背景(はいけい)には、青(あお)い空(そら)と白(しろ)い雲(くも)が描(えが)かれている。", "sentence_source": "generated"}, {"text": "舞台の背景が、場面ごとに変わった。", "target_word": "背景", "complexity_tier": "T3", "furigana": "舞台(ぶたい)の背景(はいけい)が、場面(ばめん)ごとに変(か)わった。", "sentence_source": "generated"}, {"text": "夕日を背景に、鳥の群れが飛んでいった。", "target_word": "背景", "complexity_tier": "T3", "furigana": "夕日(ゆうひ)を背景(はいけい)に、鳥(とり)の群(む)れが飛(と)んでいった。", "sentence_source": "generated"}, {"text": "画面の背景を黒にすると、文字が見やすくなる。", "target_word": "背景", "complexity_tier": "T3", "furigana": "画面(がめん)の背景(はいけい)を黒(くろ)にすると、文字(もじ)が見(み)やすくなる。", "sentence_source": "generated"}, {"text": "桜の木を背景に、家族みんなで記念写真を撮った。", "target_word": "背景", "complexity_tier": "T3", "furigana": "桜(さくら)の木(き)を背景(はいけい)に、家族(かぞく)みんなで記念写真(きねんしゃしん)を撮(と)った。", "sentence_source": "generated"}, {"text": "背景がぼやけて、人物だけがはっきり写っている。", "target_word": "背景", "complexity_tier": "T3", "furigana": "背景(はいけい)がぼやけて、人物(じんぶつ)だけがはっきり写(うつ)っている。", "sentence_source": "generated"}, {"text": "この絵は人物が小さく、背景の森のほうが大きく描かれている。", "target_word": "背景", "complexity_tier": "T3", "furigana": "この絵(え)は人物(じんぶつ)が小(ちい)さく、背景(はいけい)の森(もり)のほうが大(おお)きく描(えが)かれている。", "sentence_source": "generated"}, {"text": "発表のスライドは、背景が白いほうが読みやすい。", "target_word": "背景", "complexity_tier": "T3", "furigana": "発表(はっぴょう)のスライドは、背景(はいけい)が白(しろ)いほうが読(よ)みやすい。", "sentence_source": "generated"}, {"text": "映画の背景に使われたのは、古い町の通りだった。", "target_word": "背景", "complexity_tier": "T3", "furigana": "映画(えいが)の背景(はいけい)に使(つか)われたのは、古(ふる)い町(まち)の通(とお)りだった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "背景", "label": "基本形"}, {"form": "背景に", "label": "に格"}, {"form": "背景の", "label": "の格"}], "register": "標準（普通体）", "sense_fingerprint": "背景（名詞）：絵・写真・舞台などで主役の後ろに見える景色や画面", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '947d9c0d-20b2-4311-9f05-a20f8a6414f0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35336, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "背景", "is_correct": true, "explanation": "「山を背景にして撮る」の形で、写真の後ろにある景色として合う。"}, {"text": "天気", "is_correct": false, "explanation": "気象の状態で、撮る場面の後ろの景色にはならないので合わない。"}, {"text": "電話", "is_correct": false, "explanation": "通信機器で、写真の後ろの景色にはならないので合わない。"}, {"text": "机", "is_correct": false, "explanation": "家具で、撮影の背景の形にはならないので合わない。"}], "explanations": {"背景": "「山を背景にして撮る」の形で、写真の後ろにある景色として合う。", "天気": "気象の状態で、撮る場面の後ろの景色にはならないので合わない。", "電話": "通信機器で、写真の後ろの景色にはならないので合わない。", "机": "家具で、撮影の背景の形にはならないので合わない。"}, "sentence_index": 0, "correct_answer": "背景"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この事件の背景には、会社の経営難があった。", "explanation": "ここは〈事情・いきさつ〉の意味。絵や写真の後ろの景色ではなく、物事の原因となる事情を指すので合わない。"}, {"text": "彼は背景を丸めて、重い荷物を持った。", "explanation": "ここは〈背中〉の意味。背景は絵や写真の後ろに見える景色で、体の背中は指さないので合わない。"}, {"text": "彼は私の背景に隠れて、驚かせようとした。", "explanation": "ここは〈背後〉（物陰・後ろ側）の意味。絵や写真の景色の意味では使わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ed848d40-3489-4681-91c1-79fe346d2be0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35336, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "背景", "is_correct": true, "explanation": "写真の中でぼやける部分の主語として合う。"}, {"text": "砂糖", "is_correct": false, "explanation": "調味料で、写真の中でぼやける対象にはならないので合わない。"}, {"text": "歌声", "is_correct": false, "explanation": "音で、写真には写らないのでぼやけるという文に合わない。"}, {"text": "足音", "is_correct": false, "explanation": "音で、写真の中でぼやけることはないので合わない。"}], "explanations": {"背景": "写真の中でぼやける部分の主語として合う。", "砂糖": "調味料で、写真の中でぼやける対象にはならないので合わない。", "歌声": "音で、写真には写らないのでぼやけるという文に合わない。", "足音": "音で、写真の中でぼやけることはないので合わない。"}, "sentence_index": 6, "correct_answer": "背景"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この料理の背景には、昔からの知恵がある。", "explanation": "ここは〈由来・事情〉の意味。絵や写真の後ろに見える景色ではなく、物事の成り立ちを指すので合わない。"}, {"text": "この映画の背景は、家族の絆を描くことだ。", "explanation": "ここは〈主題〉の意味。背景は後ろに見える景色や事情を指し、作品の中心となるテーマは指さないので合わない。"}, {"text": "この調査の背景は、新しい対策が必要だという結論だ。", "explanation": "ここは〈結論〉の意味。背景は後ろの景色や事情を指し、導き出された結論そのものは指さないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ed848d40-3489-4681-91c1-79fe346d2be0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35336, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この写真は、雪山を背景で撮った。", "corrected_sentence": "この写真は、雪山を背景に撮った。", "error_description": "「背景に撮る」の「に」が必要。「で」にすると場所や手段の意味になり、背景として写す意味が通らない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ed848d40-3489-4681-91c1-79fe346d2be0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35336, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "夜景を背景の、花火の写真を撮った。", "corrected_sentence": "夜景を背景に、花火の写真を撮った。", "error_description": "「背景に撮る」の「に」が必要。「の」は後ろに名詞を続ける形で、ここでは文が成り立たない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ed848d40-3489-4681-91c1-79fe346d2be0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35337, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「背景に」で、背景が出来事の土台・原因として存在することを示す。「背景には」の「に」にあたる。"}, {"text": "が", "is_correct": false, "explanation": "主語を示す助詞。「背景が は」と続くと文が成り立たない。"}, {"text": "を", "is_correct": false, "explanation": "目的語を示す助詞。「背景を は」は文法的に続かない。"}, {"text": "の", "is_correct": false, "explanation": "名詞を修飾する連体修飾の助詞。「背景のは」は不自然で、文の成分として続かない。"}], "correct_answer": "に", "explanations": {"に": "「背景に」で、背景が出来事の土台・原因として存在することを示す。「背景には」の「に」にあたる。", "が": "主語を示す助詞。「背景が は」と続くと文が成り立たない。", "を": "目的語を示す助詞。「背景を は」は文法的に続かない。", "の": "名詞を修飾する連体修飾の助詞。「背景のは」は不自然で、文の成分として続かない。"}, "error_tags": {"が": "主語", "を": "目的語", "の": "連体修飾"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ed848d40-3489-4681-91c1-79fe346d2be0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35337, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ed848d40-3489-4681-91c1-79fe346d2be0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35337, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "ある出来事や物事が生じる、その背後にある状況や原因となるもの。", "primary_collocate": null, "pronunciation": "はいけい", "ipa": "haikeː", "syllable_count": 4, "sentences": [{"text": "事件の背景には、長年の不満があった。", "target_word": "背景", "complexity_tier": "T3", "furigana": "事件(じけん)の背景(はいけい)には、長年(ながねん)の不満(ふまん)があった。", "sentence_source": "generated"}, {"text": "この小説が生まれた背景には、戦争の体験がある。", "target_word": "背景", "complexity_tier": "T3", "furigana": "この小説(しょうせつ)が生(う)まれた背景(はいけい)には、戦争(せんそう)の体験(たいけん)がある。", "sentence_source": "generated"}, {"text": "物価が上がった背景には、天気の影響がある。", "target_word": "背景", "complexity_tier": "T3", "furigana": "物価(ぶっか)が上(あ)がった背景(はいけい)には、天気(てんき)の影響(えいきょう)がある。", "sentence_source": "generated"}, {"text": "彼の発言の背景を知らないと、意味が分からない。", "target_word": "背景", "complexity_tier": "T3", "furigana": "彼(かれ)の発言(はつげん)の背景(はいけい)を知(し)らないと、意味(いみ)が分(わ)からない。", "sentence_source": "generated"}, {"text": "若者が都会へ出る背景には、仕事の問題がある。", "target_word": "背景", "complexity_tier": "T3", "furigana": "若者(わかもの)が都会(とかい)へ出(で)る背景(はいけい)には、仕事(しごと)の問題(もんだい)がある。", "sentence_source": "generated"}, {"text": "法律が変わった背景を、先生が説明してくれた。", "target_word": "背景", "complexity_tier": "T3", "furigana": "法律(ほうりつ)が変(か)わった背景(はいけい)を、先生(せんせい)が説明(せつめい)してくれた。", "sentence_source": "generated"}, {"text": "自信のなさの背景には、過去の失敗がある。", "target_word": "背景", "complexity_tier": "T3", "furigana": "自信(じしん)のなさの背景(はいけい)には、過去(かこ)の失敗(しっぱい)がある。", "sentence_source": "generated"}, {"text": "ニュースを見るときは、出来事の背景も考えよう。", "target_word": "背景", "complexity_tier": "T3", "furigana": "ニュースを見(み)るときは、出来事(できごと)の背景(はいけい)も考(かんが)えよう。", "sentence_source": "generated"}, {"text": "この祭りの背景には、豊作を願う気持ちがある。", "target_word": "背景", "complexity_tier": "T3", "furigana": "この祭(まつ)りの背景(はいけい)には、豊作(ほうさく)を願(ねが)う気持(きも)ちがある。", "sentence_source": "generated"}, {"text": "二人が争う背景に、家族の問題があった。", "target_word": "背景", "complexity_tier": "T3", "furigana": "二人(ふたり)が争(あらそ)う背景(はいけい)に、家族(かぞく)の問題(もんだい)があった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "背景", "label": "基本形"}, {"form": "背景に", "label": "に格"}, {"form": "背景を", "label": "を格"}], "register": "標準（普通体）", "sense_fingerprint": "背景（名詞）：出来事の裏にある事情・状況・原因", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '947d9c0d-20b2-4311-9f05-a20f8a6414f0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35337, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "背景", "is_correct": true, "explanation": "出来事の背後にある事情を表す語。「事件の背景には〜」の文脈に合う。"}, {"text": "季節", "is_correct": false, "explanation": "四季の区分を指すので、事件の背後の事情という文脈には入らない。"}, {"text": "気温", "is_correct": false, "explanation": "空気の温度のことで、事件の原因や事情を述べる文脈とは合わない。"}, {"text": "天気", "is_correct": false, "explanation": "その時の空模様のことで、事件の背後にある事情としては成り立たない。"}], "explanations": {"背景": "出来事の背後にある事情を表す語。「事件の背景には〜」の文脈に合う。", "季節": "四季の区分を指すので、事件の背後の事情という文脈には入らない。", "気温": "空気の温度のことで、事件の原因や事情を述べる文脈とは合わない。", "天気": "その時の空模様のことで、事件の背後にある事情としては成り立たない。"}, "sentence_index": 0, "correct_answer": "背景"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この写真の背景は、青い空だ。", "explanation": "ここは〈背景画〉の意味との混同。写真の後ろに広がる景色を指す語で、出来事の事情という意味ではないので合わない。"}, {"text": "この菓子の背景は、国産の小麦粉だ。", "explanation": "ここは〈原料〉の意味との混同。背景は出来事を取り巻く状況を指し、材料や成分には使わないので合わない。"}, {"text": "その試合の背景は、三対零の大差だった。", "explanation": "ここは〈スコア〉の意味との混同。背景は出来事の前にある事情を指し、試合の点数や結果には使わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ed848d40-3489-4681-91c1-79fe346d2be0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35337, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "背景", "is_correct": true, "explanation": "「自信のなさの背景には」と、その原因・事情を表す文脈に合う。"}, {"text": "体重", "is_correct": false, "explanation": "体の重さのことで、自信のなさの背後の事情を述べる文脈には入らない。"}, {"text": "年齢", "is_correct": false, "explanation": "何歳かを表す語で、「自信のなさの年齢には」という形では事情を示せない。"}, {"text": "身長", "is_correct": false, "explanation": "背の高さのことで、自信のなさの背後にある事情とは結びつかない。"}], "explanations": {"背景": "「自信のなさの背景には」と、その原因・事情を表す文脈に合う。", "体重": "体の重さのことで、自信のなさの背後の事情を述べる文脈には入らない。", "年齢": "何歳かを表す語で、「自信のなさの年齢には」という形では事情を示せない。", "身長": "背の高さのことで、自信のなさの背後にある事情とは結びつかない。"}, "sentence_index": 6, "correct_answer": "背景"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "今日の背景は、白いシャツとグレーのズボンだ。", "explanation": "ここは〈服装〉の意味との混同。背景は出来事の状況を指し、身につけている服の組み合わせには使わないので合わない。"}, {"text": "彼の背景はとても冷たかった。", "explanation": "ここは〈態度〉の意味との混同。背景は事情や状況を指し、人の振る舞いの冷たさを表すことはできない。"}, {"text": "昨日は背景がずっと悪くて、熱が出た。", "explanation": "ここは〈体調〉の意味との混同。背景は出来事の事情を指し、人の体の調子を表すことはできないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ed848d40-3489-4681-91c1-79fe346d2be0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35337, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "値上げの背景を、原材料費の高騰があった。", "corrected_sentence": "値上げの背景には、原材料費の高騰があった。", "error_description": "助詞の誤り。「背景」の後は「には」で、場所・土台を示す「に」が必要。「を」は動詞を伴わない限り文が成り立たない。正しくは「値上げの背景には」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ed848d40-3489-4681-91c1-79fe346d2be0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35337, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "事件の背景に調べる必要がある。", "corrected_sentence": "事件の背景を調べる必要がある。", "error_description": "助詞の誤り。「調べる」の目的語には「を」を付ける。「に」は誤り。正しくは「事件の背景を調べる必要がある」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ed848d40-3489-4681-91c1-79fe346d2be0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
