INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35340, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "なくてはならないこと。", "primary_collocate": null, "pronunciation": "ふかけつ", "ipa": "ɸɯkaket͡sɯ", "syllable_count": 4, "sentences": [{"text": "健康のためには、睡眠が不可欠だ。", "target_word": "不可欠", "complexity_tier": "T3", "furigana": "健康(けんこう)のためには、睡眠(すいみん)が不可欠(ふかけつ)だ。", "sentence_source": "generated"}, {"text": "水は生き物にとって不可欠なものです。", "target_word": "不可欠", "complexity_tier": "T3", "furigana": "水(みず)は生(い)き物(もの)にとって不可欠(ふかけつ)なものです。", "sentence_source": "generated"}, {"text": "この仕事には、チームの協力が不可欠である。", "target_word": "不可欠", "complexity_tier": "T3", "furigana": "この仕事(しごと)には、チームの協力(きょうりょく)が不可欠(ふかけつ)である。", "sentence_source": "generated"}, {"text": "海外旅行にパスポートは不可欠だ。", "target_word": "不可欠", "complexity_tier": "T3", "furigana": "海外旅行(かいがいりょこう)にパスポートは不可欠(ふかけつ)だ。", "sentence_source": "generated"}, {"text": "彼の経験は、計画の成功に不可欠だった。", "target_word": "不可欠", "complexity_tier": "T3", "furigana": "彼(かれ)の経験(けいけん)は、計画(けいかく)の成功(せいこう)に不可欠(ふかけつ)だった。", "sentence_source": "generated"}, {"text": "不可欠な道具をリュックに入れた。", "target_word": "不可欠", "complexity_tier": "T3", "furigana": "不可欠(ふかけつ)な道具(どうぐ)をリュックに入(い)れた。", "sentence_source": "generated"}, {"text": "読書は、言葉を学ぶうえで不可欠だと思う。", "target_word": "不可欠", "complexity_tier": "T3", "furigana": "読書(どくしょ)は、言葉(ことば)を学(まな)ぶうえで不可欠(ふかけつ)だと思(おも)う。", "sentence_source": "generated"}, {"text": "山登りでは、地図と水が不可欠です。", "target_word": "不可欠", "complexity_tier": "T3", "furigana": "山登(やまのぼ)りでは、地図(ちず)と水(みず)が不可欠(ふかけつ)です。", "sentence_source": "generated"}, {"text": "話し合いでは、相手の意見を聞くことが不可欠だ。", "target_word": "不可欠", "complexity_tier": "T3", "furigana": "話(はな)し合(あ)いでは、相手(あいて)の意見(いけん)を聞(き)くことが不可欠(ふかけつ)だ。", "sentence_source": "generated"}, {"text": "毎日の運動は、体力をつけるために不可欠になった。", "target_word": "不可欠", "complexity_tier": "T3", "furigana": "毎日(まいにち)の運動(うんどう)は、体力(たいりょく)をつけるために不可欠(ふかけつ)になった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "不可欠だ", "label": "断定形"}, {"form": "不可欠な", "label": "連体形"}, {"form": "不可欠で", "label": "連用形（で）"}, {"form": "不可欠に", "label": "連用形（に）"}, {"form": "不可欠だった", "label": "過去形"}], "register": "やや硬い標準語", "sense_fingerprint": "それがないと成り立たないほど必要である", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c0767258-83b5-4171-bcae-53bbc15f4a23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35340, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "不可欠", "is_correct": true, "explanation": "文中の形。「健康のためには、睡眠が不可欠だ」で、なくてはならない意味が自然。"}, {"text": "不愉快", "is_correct": false, "explanation": "「睡眠が不愉快だ」は健康のために必要な話の流れに合わず、意味が通らない。"}, {"text": "不穏", "is_correct": false, "explanation": "「睡眠が不穏だ」は不安で落ち着かない意味になり、健康の文脈と合わない。"}, {"text": "不活発", "is_correct": false, "explanation": "「睡眠が不活発だ」は動きが鈍い意味で、健康のために必要だという文と合わない。"}], "explanations": {"不可欠": "文中の形。「健康のためには、睡眠が不可欠だ」で、なくてはならない意味が自然。", "不愉快": "「睡眠が不愉快だ」は健康のために必要な話の流れに合わず、意味が通らない。", "不穏": "「睡眠が不穏だ」は不安で落ち着かない意味になり、健康の文脈と合わない。", "不活発": "「睡眠が不活発だ」は動きが鈍い意味で、健康のために必要だという文と合わない。"}, "sentence_index": 0, "correct_answer": "不可欠"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "古い雑誌は不可欠だから、まとめて捨てた。", "explanation": "ここは〈不要〉の場面。捨てる理由と〈不可欠〉の意味が矛盾し、無くてはならない意味とは合わない。"}, {"text": "不可欠な音が一晩中続いた。", "explanation": "ここは〈不快〉の場面。音の気持ち悪さを表す語で、〈不可欠〉の必要だという意味とは合わない。"}, {"text": "彼は不可欠な手つきで、包丁を持った。", "explanation": "ここは〈不器用〉の場面。手つきの下手さを表す語で、〈不可欠〉は手つきには合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '61c717cd-5f43-408e-bc1d-bd831fa0a53c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35340, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "不可欠", "is_correct": true, "explanation": "文中の形。「言葉を学ぶうえで不可欠だと思う」で、必要不可欠の意味が自然。"}, {"text": "不徹底", "is_correct": false, "explanation": "「言葉を学ぶうえで不徹底だと思う」は徹底していない意味になり、文の意図と合わない。"}, {"text": "不均衡", "is_correct": false, "explanation": "「言葉を学ぶうえで不均衡だと思う」は釣り合いが取れない意味で、読書の話と合わない。"}, {"text": "不規則", "is_correct": false, "explanation": "「言葉を学ぶうえで不規則だと思う」は決まりがない意味で、学びの評価として合わない。"}], "explanations": {"不可欠": "文中の形。「言葉を学ぶうえで不可欠だと思う」で、必要不可欠の意味が自然。", "不徹底": "「言葉を学ぶうえで不徹底だと思う」は徹底していない意味になり、文の意図と合わない。", "不均衡": "「言葉を学ぶうえで不均衡だと思う」は釣り合いが取れない意味で、読書の話と合わない。", "不規則": "「言葉を学ぶうえで不規則だと思う」は決まりがない意味で、学びの評価として合わない。"}, "sentence_index": 6, "correct_answer": "不可欠"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "不可欠なやり取りは省こう。", "explanation": "ここは〈無用〉の場面。省く内容に〈不可欠〉を使うと、必要だと言いながら省くという矛盾が生じる。"}, {"text": "彼は不可欠な顔をしていた。", "explanation": "ここは〈不満〉の場面。顔の様子を表すには〈不満〉が自然で、〈不可欠〉は合わない。"}, {"text": "成績が不可欠で、みんな心配した。", "explanation": "ここは〈不振〉の場面。成績の悪さを表すのは〈不振〉で、〈不可欠〉では意味が通らない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '61c717cd-5f43-408e-bc1d-bd831fa0a53c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35340, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この実験には、正確な記録を不可欠だ。", "corrected_sentence": "この実験には、正確な記録が不可欠だ。", "error_description": "「不可欠だ」の前には「が」を使う。「を」は目的語を示すため、述語には使えない。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "不可欠", "is_correct": true, "explanation": "文中の語幹。直後の「な」が付いて「不可欠なもの」と名詞を修飾する。"}, {"text": "不可欠だ", "is_correct": false, "explanation": "断定形。「不可欠だもの」では名詞を修飾できず、文として成り立たない。"}, {"text": "不可欠で", "is_correct": false, "explanation": "連用形（で）。「不可欠で、もの」と続けても名詞を修飾できず、文の形が合わない。"}, {"text": "不可欠に", "is_correct": false, "explanation": "連用形（に）。副詞的な形になり、名詞を修飾する形として使えない。"}], "correct_form": "不可欠", "base_form": "不可欠だ", "form_label": "語幹", "sentence_index": 1, "explanations": {"不可欠": "文中の語幹。直後の「な」が付いて「不可欠なもの」と名詞を修飾する。", "不可欠だ": "断定形。「不可欠だもの」では名詞を修飾できず、文として成り立たない。", "不可欠で": "連用形（で）。「不可欠で、もの」と続けても名詞を修飾できず、文の形が合わない。", "不可欠に": "連用形（に）。副詞的な形になり、名詞を修飾する形として使えない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '61c717cd-5f43-408e-bc1d-bd831fa0a53c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35340, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この作業には、慎重な確認が不可欠なだ。", "corrected_sentence": "この作業には、慎重な確認が不可欠だ。", "error_description": "「不可欠なだ」は誤った語尾。述語の形は「不可欠だ」で、「な」は付けない。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "不可欠", "is_correct": true, "explanation": "文中の語幹。「地図と水が不可欠です」の述語として使われている。"}, {"text": "不可欠な", "is_correct": false, "explanation": "連体形。名詞を修飾する形で、「不可欠です」で文を結ぶ文には合わない。"}, {"text": "不可欠だった", "is_correct": false, "explanation": "過去形。現在の「です」の文と時制が合わず、必要性の一般的な説明にならない。"}, {"text": "不可欠である", "is_correct": false, "explanation": "である体。「です」の丁寧な文体と合わない。"}], "correct_form": "不可欠", "base_form": "不可欠だ", "form_label": "語幹", "sentence_index": 7, "explanations": {"不可欠": "文中の語幹。「地図と水が不可欠です」の述語として使われている。", "不可欠な": "連体形。名詞を修飾する形で、「不可欠です」で文を結ぶ文には合わない。", "不可欠だった": "過去形。現在の「です」の文と時制が合わず、必要性の一般的な説明にならない。", "不可欠である": "である体。「です」の丁寧な文体と合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '61c717cd-5f43-408e-bc1d-bd831fa0a53c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35352, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「箱の内に」の「に」。入っている場所を示す。"}, {"text": "で", "is_correct": false, "explanation": "「で」は動作の場所を示すので、「入っていた」という状態の文には合わない。"}, {"text": "を", "is_correct": false, "explanation": "「を」は目的語を示すが、「入っていた」は目的語を取らない状態表現なので不自然。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較を示すので、場所の説明にはならない。"}], "correct_answer": "に", "explanations": {"に": "「箱の内に」の「に」。入っている場所を示す。", "で": "「で」は動作の場所を示すので、「入っていた」という状態の文には合わない。", "を": "「を」は目的語を示すが、「入っていた」は目的語を取らない状態表現なので不自然。", "より": "「より」は比較を示すので、場所の説明にはならない。"}, "error_tags": {"で": "location_action", "を": "object", "より": "comparison"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '034c4210-ad68-4bb4-ae2e-8d82f9a50de0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35352, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「城の内に」の「に」。存在する場所を示す。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は移動の方向を示すので、「ある」という存在の文には合わない。"}, {"text": "を", "is_correct": false, "explanation": "「を」は目的語を示すので、存在を表す文には使えない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は動作の場所を示すので、存在を表す「ある」とは結びつかず不自然。"}], "correct_answer": "に", "explanations": {"に": "「城の内に」の「に」。存在する場所を示す。", "へ": "「へ」は移動の方向を示すので、「ある」という存在の文には合わない。", "を": "「を」は目的語を示すので、存在を表す文には使えない。", "で": "「で」は動作の場所を示すので、存在を表す「ある」とは結びつかず不自然。"}, "error_tags": {"へ": "direction", "を": "object", "で": "location_action"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '034c4210-ad68-4bb4-ae2e-8d82f9a50de0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35352, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "ものの、うちがわのほう。", "primary_collocate": null, "pronunciation": "うち", "ipa": "ɯt͡ɕi", "syllable_count": 2, "sentences": [{"text": "彼は心の内を誰にも話さなかった。", "target_word": "内", "complexity_tier": "T3", "furigana": "彼[かれ]は心[こころ]の内[うち]を誰[だれ]にも話[はな]さなかった。", "sentence_source": "generated"}, {"text": "箱の内に小さな手紙が入っていた。", "target_word": "内", "complexity_tier": "T3", "furigana": "箱[はこ]の内[うち]に小[ちい]さな手紙[てがみ]が入[はい]っていた。", "sentence_source": "generated"}, {"text": "戸の内と外では、音の聞こえ方がまるで違う。", "target_word": "内", "complexity_tier": "T3", "furigana": "戸[と]の内[うち]と外[そと]では、音[おと]の聞[き]こえ方[かた]がまるで違[ちが]う。", "sentence_source": "generated"}, {"text": "怒りを内に秘めて、彼は静かに座っていた。", "target_word": "内", "complexity_tier": "T3", "furigana": "怒[いか]りを内[うち]に秘[ひ]めて、彼[かれ]は静[しず]かに座[すわ]っていた。", "sentence_source": "generated"}, {"text": "塀の内は静かで、外の道路の音が聞こえない。", "target_word": "内", "complexity_tier": "T3", "furigana": "塀[へい]の内[うち]は静[しず]かで、外[そと]の道路[どうろ]の音[おと]が聞[き]こえない。", "sentence_source": "generated"}, {"text": "私は自分の胸の内を、日記にだけ書いている。", "target_word": "内", "complexity_tier": "T3", "furigana": "私[わたし]は自分[じぶん]の胸[むね]の内[うち]を、日記[にっき]にだけ書[か]いている。", "sentence_source": "generated"}, {"text": "内と外をはっきり分けるために、門を作った。", "target_word": "内", "complexity_tier": "T3", "furigana": "内[うち]と外[そと]をはっきり分[わ]けるために、門[もん]を作[つく]った。", "sentence_source": "generated"}, {"text": "城の内には、広い庭があるそうだ。", "target_word": "内", "complexity_tier": "T3", "furigana": "城[しろ]の内[うち]には、広[ひろ]い庭[にわ]があるそうだ。", "sentence_source": "generated"}, {"text": "彼女の腹の内は、誰にも読めなかった。", "target_word": "内", "complexity_tier": "T3", "furigana": "彼女[かのじょ]の腹[はら]の内[うち]は、誰[だれ]にも読[よ]めなかった。", "sentence_source": "generated"}, {"text": "袋の内が濡れていたので、全部出して乾かした。", "target_word": "内", "complexity_tier": "T3", "furigana": "袋[ふくろ]の内[うち]が濡[ぬ]れていたので、全部[ぜんぶ]出[だ]して乾[かわ]かした。", "sentence_source": "generated"}], "morphological_forms": [{"form": "内", "label": "base"}, {"form": "内に", "label": "locative"}], "register": "neutral", "sense_fingerprint": "内(うち): ものの内側・内部（心の内、塀の内など）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bcd0e261-a606-4c8b-a65c-77d92cef559f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35352, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "内", "is_correct": true, "explanation": "「心の内」で、心の内側という意味。誰にも話さなかったという文に合う。"}, {"text": "外", "is_correct": false, "explanation": "「心の外」は内側の反対を指すので、心の中を話さないという文脈に合わない。"}, {"text": "前", "is_correct": false, "explanation": "「心の前」は位置として不自然で、内側を指す語が必要な場面に合わない。"}, {"text": "隣", "is_correct": false, "explanation": "「心の隣」は意味が通らず、心の内側を表す語としては合わない。"}], "explanations": {"内": "「心の内」で、心の内側という意味。誰にも話さなかったという文に合う。", "外": "「心の外」は内側の反対を指すので、心の中を話さないという文脈に合わない。", "前": "「心の前」は位置として不自然で、内側を指す語が必要な場面に合わない。", "隣": "「心の隣」は意味が通らず、心の内側を表す語としては合わない。"}, "sentence_index": 0, "correct_answer": "内"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "十人の内、三人が合格した。", "explanation": "ここは〈〜のうち〉（範囲を示す）の意味。ものの内側という意味ではない。"}, {"text": "彼の体の内は、クラスの誰よりも背が高い。", "explanation": "背の高さは外から見える特徴なので、〈内側〉を表す「内」ではなく〈外見〉を言う語を使う。「内」は体の中身を指すので、ここでは合わない。"}, {"text": "夏休みの内に、宿題を終わらせよう。", "explanation": "ここは〈〜のあいだに〉（期間）の意味。ものの内側という意味ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '034c4210-ad68-4bb4-ae2e-8d82f9a50de0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35352, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "内", "is_correct": true, "explanation": "「内と外」で、内側と外側を対比する表現。分けるという文に合う。"}, {"text": "上", "is_correct": false, "explanation": "「上と外」では上下の位置を示すことになり、内と外の区別という文の意味と合わない。"}, {"text": "下", "is_correct": false, "explanation": "「下と外」では上下の位置関係になり、内外を分ける文脈には合わない。"}, {"text": "脇", "is_correct": false, "explanation": "「脇と外」は横の位置を示すので、内側と外側を分けるという意味には合わない。"}], "explanations": {"内": "「内と外」で、内側と外側を対比する表現。分けるという文に合う。", "上": "「上と外」では上下の位置を示すことになり、内と外の区別という文の意味と合わない。", "下": "「下と外」では上下の位置関係になり、内外を分ける文脈には合わない。", "脇": "「脇と外」は横の位置を示すので、内側と外側を分けるという意味には合わない。"}, "sentence_index": 6, "correct_answer": "内"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼女は内向的で、明るい性格の内が強い。", "explanation": "〈心の中〉の意味なら「心の内」と言えるが、「強い」とは続かない。性格の強さは〈芯〉や〈気〉で表すので、「内」は合わない。"}, {"text": "値段の内を見て、安いと思った。", "explanation": "〈内訳〉の意味で使うなら「値段の内訳」と言う。ここは内側から中身を見るという意味になり、内訳を表す語としては合わない。"}, {"text": "明日の内に返事をください。", "explanation": "ここは〈〜のあいだに〉（期間）の意味。ものの内側という意味ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '034c4210-ad68-4bb4-ae2e-8d82f9a50de0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35352, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "机の内で小さな鍵が入っていた。", "corrected_sentence": "机の内に小さな鍵が入っていた。", "error_description": "中に入っている場所を示すには「に」が正しい。「で」は動作の場所を示すので、「入っていた」という状態には合わない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '034c4210-ad68-4bb4-ae2e-8d82f9a50de0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35352, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "鞄の内を古い写真が挟まっていた。", "corrected_sentence": "鞄の内に古い写真が挟まっていた。", "error_description": "挟まっている場所を示すには「に」が正しい。「を」は目的語を示すので、この文の場所を表す形としては合わない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '034c4210-ad68-4bb4-ae2e-8d82f9a50de0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35353, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「内にこそ宿る」の「に」。存在する場所を示す格助詞で、この文の正解。"}, {"text": "を", "is_correct": false, "explanation": "「宿る」は目的語をとらない自動詞なので、「内を」は文が成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は移動の方向を表すが、ここは存在の場所を示す文脈なので合わない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並列や相手を表すが、「内と宿る」は意味が通らない。"}], "correct_answer": "に", "explanations": {"に": "「内にこそ宿る」の「に」。存在する場所を示す格助詞で、この文の正解。", "を": "「宿る」は目的語をとらない自動詞なので、「内を」は文が成り立たない。", "へ": "「へ」は移動の方向を表すが、ここは存在の場所を示す文脈なので合わない。", "と": "「と」は並列や相手を表すが、「内と宿る」は意味が通らない。"}, "error_tags": {"を": "目的語の誤り", "へ": "移動の方向", "と": "並列・引用"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "外", "is_correct": true, "explanation": "「内」の対義語で、範囲や内部の反対、つまり範囲の外側を表す。"}, {"text": "上", "is_correct": false, "explanation": "上方向の位置を表す語で、内外の対義関係にはない。"}, {"text": "前", "is_correct": false, "explanation": "時間や位置の前方を表す語で、内部の対義語にはならない。"}, {"text": "隣", "is_correct": false, "explanation": "隣接する場所を表す語で、内部の反対語ではない。"}], "correct_answer": "外", "explanations": {"外": "「内」の対義語で、範囲や内部の反対、つまり範囲の外側を表す。", "上": "上方向の位置を表す語で、内外の対義関係にはない。", "前": "時間や位置の前方を表す語で、内部の対義語にはならない。", "隣": "隣接する場所を表す語で、内部の反対語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64e7d4f9-aee5-437b-a6be-eb6c0a13dc6e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35353, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「若い内に」の「に」。ある期間の範囲の中で、の意味を表す格助詞で正解。"}, {"text": "の", "is_correct": false, "explanation": "「の」は連体修飾に使うが、「若い内の、」の後には名詞が続かず文が成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は移動の方向を表すが、期間を示す文脈には合わない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並列や相手を表すが、「若い内と、」では文が続かない。"}], "correct_answer": "に", "explanations": {"に": "「若い内に」の「に」。ある期間の範囲の中で、の意味を表す格助詞で正解。", "の": "「の」は連体修飾に使うが、「若い内の、」の後には名詞が続かず文が成り立たない。", "へ": "「へ」は移動の方向を表すが、期間を示す文脈には合わない。", "と": "「と」は並列や相手を表すが、「若い内と、」では文が続かない。"}, "error_tags": {"の": "連体修飾", "へ": "移動の方向", "と": "並列・引用"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64e7d4f9-aee5-437b-a6be-eb6c0a13dc6e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35353, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "物事の範囲や内部にあること。また、その部分。", "primary_collocate": null, "pronunciation": "うち", "ipa": "ɯtɕi", "syllable_count": 2, "sentences": [{"text": "期限の内に申込書を提出してください。", "target_word": "内", "complexity_tier": "T3", "furigana": "期限[きげん]の内[うち]に申込書[もうしこみしょ]を提出[ていしゅつ]してください。", "sentence_source": "generated"}, {"text": "社会経済現象の真の駆動力は、還元主義的な分析の彼方、ネットワーク全体の創発的特性の内にこそ宿っていると言えよう。", "target_word": "内", "complexity_tier": "T5", "furigana": "社会経済現象[しゃかいけいざいげんしょう]の真[しん]の駆動力[くどうりょく]は、還元主義的[かんげんしゅぎてき]な分析[ぶんせき]の彼方[かなた]、ネットワーク全体[ぜんたい]の創発的[そうはつてき]特性[とくせい]の内[うち]にこそ宿[やど]っていると言[い]えよう。", "sentence_source": "mined"}, {"text": "子どもたちは家の内で遊んでいます。", "target_word": "内", "complexity_tier": "T2", "furigana": "子[こ]どもたちは家[いえ]の内[うち]で遊[あそ]んでいます。", "sentence_source": "generated"}, {"text": "木漏れ日がその頬を静かに照らす中、彼はただ黙々と、自らの内なる飢えと、この季節の恵みとを一体化させていくのである。", "target_word": "内", "complexity_tier": "T5", "furigana": "木漏[こも]れ日[び]がその頬[ほお]を静[しず]かに照[て]らす中[なか]、彼[かれ]はただ黙々[もくもく]と、自[みずか]らの内[うち]なる飢[う]えと、この季節[きせつ]の恵[めぐ]みとを一体化[いったいか]させていくのである。", "sentence_source": "mined"}, {"text": "今週の内に報告書を出してください。", "target_word": "内", "complexity_tier": "T3", "furigana": "今週[こんしゅう]の内[うち]に報告書[ほうこくしょ]を出[だ]してください。", "sentence_source": "generated"}, {"text": "三人の内、二人が賛成しました。", "target_word": "内", "complexity_tier": "T3", "furigana": "三人[さんにん]の内[うち]、二人[ふたり]が賛成[さんせい]しました。", "sentence_source": "generated"}, {"text": "雨が降らない内に、洗濯物を取り込みました。", "target_word": "内", "complexity_tier": "T3", "furigana": "雨[あめ]が降[ふ]らない内[うち]に、洗濯物[せんたくもの]を取[と]り込[こ]みました。", "sentence_source": "generated"}, {"text": "若い内に、いろいろな国を見ておきたいです。", "target_word": "内", "complexity_tier": "T3", "furigana": "若[わか]い内[うち]に、いろいろな国[くに]を見[み]ておきたいです。", "sentence_source": "generated"}, {"text": "彼女は長い間隠していた心の内を打ち明けました。", "target_word": "内", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は長[なが]い間[あいだ]隠[かく]していた心[こころ]の内[うち]を打[う]ち明[あ]けました。", "sentence_source": "generated"}, {"text": "知らない内に、外はすっかり暗くなっていました。", "target_word": "内", "complexity_tier": "T3", "furigana": "知[し]らない内[うち]に、外[そと]はすっかり暗[くら]くなっていました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "内", "label": "基本形"}, {"form": "内に", "label": "に格"}, {"form": "内の", "label": "連体修飾"}], "register": "neutral", "sense_fingerprint": "範囲・内部・うちに（その間に）を表す名詞「内」", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 1 above tier T1: contains vocabulary far above tier T1: 創発 (Zipf 2.41)','sentence 3 above tier T1: 6 words above tier T1 (max 2): 木漏れ日 (Zipf 2.6), 頬 (Zipf 3.86), 照らす (Zipf 3.37), 黙々と (Zipf 3.25), 恵み (Zipf 3.65), 一体化 (Zipf 3.35)']::text[], '08e7e9f6-0f05-455b-afc5-ee87762d7379') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35353, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "内", "is_correct": true, "explanation": "「期限の内に」の「内」。期限の範囲の中で、の意味で、この文の正解。"}, {"text": "外", "is_correct": false, "explanation": "「期限の外に」は期限を過ぎた範囲を指し、「提出してください」の指示に合わない。"}, {"text": "下", "is_correct": false, "explanation": "「期限の下に」は位置を表す語で、期限の範囲は示せず文が合わない。"}, {"text": "奥", "is_correct": false, "explanation": "「期限の奥に」は奥まった場所を表す語で、時間の範囲を示せず合わない。"}], "explanations": {"内": "「期限の内に」の「内」。期限の範囲の中で、の意味で、この文の正解。", "外": "「期限の外に」は期限を過ぎた範囲を指し、「提出してください」の指示に合わない。", "下": "「期限の下に」は位置を表す語で、期限の範囲は示せず文が合わない。", "奥": "「期限の奥に」は奥まった場所を表す語で、時間の範囲を示せず合わない。"}, "sentence_index": 0, "correct_answer": "内"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "うちの会社は来月から、週休三日制を始めることになりました。", "explanation": "ここは〈うち〉＝「我が社」の意味。〈内〉の「範囲・内部」の意味ではなく所属を指す用法なので合わない。"}, {"text": "彼女は内気で、人前で話すのが苦手です。", "explanation": "ここは「内気」（恥ずかしがりの性格）の意味。〈内〉の「範囲・内部」とは別の語で、この定義には合わない。"}, {"text": "食事内ですので、後にしていただけますか。", "explanation": "ここは〈中〉の意味。「食事中」は動作の最中を表す語で、〈内〉は「食事内」とは言わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64e7d4f9-aee5-437b-a6be-eb6c0a13dc6e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35353, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "内", "is_correct": true, "explanation": "「雨が降らない内に」の「内」。ある状態が続いている間に、の意味で正解。"}, {"text": "窓", "is_correct": false, "explanation": "「降らない窓に」は時間の範囲を表さず、場所としても文が成り立たない。"}, {"text": "色", "is_correct": false, "explanation": "「降らない色に」は意味が通らず、時間や場所を表さない。"}, {"text": "机", "is_correct": false, "explanation": "「降らない机に」は時間を表さず、意味が通らない。"}], "explanations": {"内": "「雨が降らない内に」の「内」。ある状態が続いている間に、の意味で正解。", "窓": "「降らない窓に」は時間の範囲を表さず、場所としても文が成り立たない。", "色": "「降らない色に」は意味が通らず、時間や場所を表さない。", "机": "「降らない机に」は時間を表さず、意味が通らない。"}, "sentence_index": 6, "correct_answer": "内"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "新しい内閣が来月発足することになりました。", "explanation": "ここは〈内閣〉の意味。政府の組織を指す別の語で、〈内〉の「範囲・内部」の意味では使わないので合わない。"}, {"text": "来年の春、就職の内定が出ました。", "explanation": "ここは〈内定〉の意味。正式な採用の前段階を指す別の語で、〈内〉の「範囲・内部」とは違うので合わない。"}, {"text": "費用の内訳を、もう一度確認させてください。", "explanation": "ここは〈内訳〉（内容の明細）の意味。〈内〉の「範囲・内部にあること」とは別の語で、ここでは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64e7d4f9-aee5-437b-a6be-eb6c0a13dc6e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35353, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "週末の内が部屋を片付けます。", "corrected_sentence": "週末の内に部屋を片付けます。", "error_description": "「内」は時間の範囲を表し、「片付けます」の主語にはならないので「が」は誤り。時間の範囲を示す「に」が必要。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64e7d4f9-aee5-437b-a6be-eb6c0a13dc6e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35353, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "お客さんが来ない内を、掃除をしておきます。", "corrected_sentence": "お客さんが来ない内に、掃除をしておきます。", "error_description": "時間の範囲を表す「内」の後には「に」が必要。「を」は目的語を示すため誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64e7d4f9-aee5-437b-a6be-eb6c0a13dc6e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35355, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「恩恵を受ける」で受ける対象を示します。"}, {"text": "に", "is_correct": false, "explanation": "「恩恵に受けています」とは言えません。"}, {"text": "で", "is_correct": false, "explanation": "「恩恵で受けています」では受ける対象が示せません。"}, {"text": "と", "is_correct": false, "explanation": "「恩恵と受けています」は文として成り立ちません。"}], "correct_answer": "を", "explanations": {"を": "「恩恵を受ける」で受ける対象を示します。", "に": "「恩恵に受けています」とは言えません。", "で": "「恩恵で受けています」では受ける対象が示せません。", "と": "「恩恵と受けています」は文として成り立ちません。"}, "error_tags": {"に": "target_marker", "で": "means_marker", "と": "quotation_or_accompaniment"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "弊害", "is_correct": true, "explanation": "利益と反対に害を与えるもので、恩恵の反対です。"}, {"text": "利益", "is_correct": false, "explanation": "得になることで、恩恵に近い語です。"}, {"text": "好意", "is_correct": false, "explanation": "親切な気持ちで、恩恵の反対ではありません。"}, {"text": "援助", "is_correct": false, "explanation": "助けることで、恩恵に近い語です。"}], "correct_answer": "弊害", "explanations": {"弊害": "利益と反対に害を与えるもので、恩恵の反対です。", "利益": "得になることで、恩恵に近い語です。", "好意": "親切な気持ちで、恩恵の反対ではありません。", "援助": "助けることで、恩恵に近い語です。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b8fb9dc-8519-4141-82f0-8afe6c53eb23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35355, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "恩恵を主題として示し、「小さくない」と述べます。"}, {"text": "を", "is_correct": false, "explanation": "「恩恵を、決して小さくない」では述語とつながりません。"}, {"text": "に", "is_correct": false, "explanation": "「恩恵に、決して小さくない」は文として成り立ちません。"}, {"text": "と", "is_correct": false, "explanation": "「恩恵と、決して小さくない」は文として成り立ちません。"}], "correct_answer": "は", "explanations": {"は": "恩恵を主題として示し、「小さくない」と述べます。", "を": "「恩恵を、決して小さくない」では述語とつながりません。", "に": "「恩恵に、決して小さくない」は文として成り立ちません。", "と": "「恩恵と、決して小さくない」は文として成り立ちません。"}, "error_tags": {"を": "object_marker", "に": "target_marker", "と": "quotation_or_accompaniment"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "被害", "is_correct": true, "explanation": "損害を受けることで、恩恵の反対です。"}, {"text": "利得", "is_correct": false, "explanation": "得をすることで、恩恵に近い語です。"}, {"text": "贈与", "is_correct": false, "explanation": "物を与えることで、恩恵の反対ではありません。"}, {"text": "祝福", "is_correct": false, "explanation": "幸せを祈ることで、恩恵の反対ではありません。"}], "correct_answer": "被害", "explanations": {"被害": "損害を受けることで、恩恵の反対です。", "利得": "得をすることで、恩恵に近い語です。", "贈与": "物を与えることで、恩恵の反対ではありません。", "祝福": "幸せを祈ることで、恩恵の反対ではありません。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b8fb9dc-8519-4141-82f0-8afe6c53eb23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35355, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "他者から受ける利益や助け。めぐみ。", "primary_collocate": null, "pronunciation": "おんけい", "ipa": "oŋkeː", "syllable_count": 4, "sentences": [{"text": "鉢という限定された宇宙の中で、命は水という恩恵を糧に、時を重ねてその緑を深めていく。", "target_word": "恩恵", "complexity_tier": "T6", "furigana": "鉢[はち]という限定[げんてい]された宇宙[うちゅう]の中[なか]で、命[いのち]は水[みず]という恩恵[おんけい]を糧[かて]に、時[とき]を重[かさ]ねてその緑[みどり]を深[ふか]めていく。", "sentence_source": "mined"}, {"text": "自然の恩恵を受けています。", "target_word": "恩恵", "complexity_tier": "T2", "furigana": "自然[しぜん]の恩恵[おんけい]を受[う]けています。", "sentence_source": "generated"}, {"text": "雨は農家への恩恵です。", "target_word": "恩恵", "complexity_tier": "T2", "furigana": "雨[あめ]は農家[のうか]への恩恵[おんけい]です。", "sentence_source": "generated"}, {"text": "科学の恩恵で、生活が便利になった。", "target_word": "恩恵", "complexity_tier": "T3", "furigana": "科学[かがく]の恩恵[おんけい]で、生活[せいかつ]が便利[べんり]になった。", "sentence_source": "generated"}, {"text": "私たちは多くの恩恵を受けている。", "target_word": "恩恵", "complexity_tier": "T3", "furigana": "私[わたし]たちは多[おお]くの恩恵[おんけい]を受[う]けている。", "sentence_source": "generated"}, {"text": "制度が変われば、恩恵を受ける人も変わる。", "target_word": "恩恵", "complexity_tier": "T4", "furigana": "制度[せいど]が変[か]われば、恩恵[おんけい]を受[う]ける人[ひと]も変[か]わる。", "sentence_source": "generated"}, {"text": "川の恩恵に感謝して、毎年祭りを開く。", "target_word": "恩恵", "complexity_tier": "T4", "furigana": "川[かわ]の恩恵[おんけい]に感謝[かんしゃ]して、毎年[まいとし]祭[まつ]りを開[ひら]く。", "sentence_source": "generated"}, {"text": "技術の進歩がもたらした恩恵は、決して小さくない。", "target_word": "恩恵", "complexity_tier": "T5", "furigana": "技術[ぎじゅつ]の進歩[しんぽ]がもたらした恩恵[おんけい]は、決[けっ]して小[ちい]さくない。", "sentence_source": "generated"}, {"text": "恩恵は大きい。", "target_word": "恩恵", "complexity_tier": "T1", "furigana": "恩恵[おんけい]は大[おお]きい。", "sentence_source": "generated"}, {"text": "都会ではこの恩恵がない。", "target_word": "恩恵", "complexity_tier": "T3", "furigana": "都会[とかい]ではこの恩恵[おんけい]がない。", "sentence_source": "generated"}], "morphological_forms": [], "register": "formal", "sense_fingerprint": "名詞 | 他者から受ける利益や助け", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c5211d9c-157e-40de-b755-e90087d97fda') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35355, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "恩恵", "is_correct": true, "explanation": "見出し語そのものです。"}, {"text": "音声", "is_correct": false, "explanation": "おんせい。3番目の「け」が「せ」に変わる1モーラ違いです。"}, {"text": "音程", "is_correct": false, "explanation": "おんてい。3番目の「け」が「て」に変わる1モーラ違いです。"}, {"text": "根茎", "is_correct": false, "explanation": "こんけい。最初の「お」が「こ」に変わる1モーラ違いです。"}], "explanations": {"恩恵": "見出し語そのものです。", "音声": "おんせい。3番目の「け」が「せ」に変わる1モーラ違いです。", "音程": "おんてい。3番目の「け」が「て」に変わる1モーラ違いです。", "根茎": "こんけい。最初の「お」が「こ」に変わる1モーラ違いです。"}, "sentence_index": null, "correct_answer": "恩恵"}, "level_3": {"options": [{"text": "恩恵", "is_correct": true, "explanation": "水から受ける利益という意味に合います。"}, {"text": "障害", "is_correct": false, "explanation": "形は合うが意味が合わない。水が命の糧になる文脈に反します。"}, {"text": "災難", "is_correct": false, "explanation": "形は合うが意味が合わない。糧にするものとして不自然です。"}, {"text": "規則", "is_correct": false, "explanation": "形は合うが意味が合わない。水を規則とは言いません。"}], "explanations": {"恩恵": "水から受ける利益という意味に合います。", "障害": "形は合うが意味が合わない。水が命の糧になる文脈に反します。", "災難": "形は合うが意味が合わない。糧にするものとして不自然です。", "規則": "形は合うが意味が合わない。水を規則とは言いません。"}, "sentence_index": 0, "correct_answer": "恩恵"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "地震の恩恵で、家がたくさん壊れた。", "explanation": "恩恵は受ける利益なので、被害を表す文脈には使えません。"}, {"text": "彼は恩恵を飲んで、元気になった。", "explanation": "恩恵は抽象的な利益で、飲むことはできません。"}, {"text": "友人に恩恵を貸してもらった。", "explanation": "恩恵は物のように貸し借りするものではなく、使い方が不自然です。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b8fb9dc-8519-4141-82f0-8afe6c53eb23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35355, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "恩恵", "is_correct": true, "explanation": "見出し語そのものです。"}, {"text": "穏健", "is_correct": false, "explanation": "おんけん。最後の「い」が「ん」に変わる1モーラ違いです。"}, {"text": "温帯", "is_correct": false, "explanation": "おんたい。3番目の「け」が「た」に変わる1モーラ違いです。"}, {"text": "音階", "is_correct": false, "explanation": "おんかい。3番目の「け」が「か」に変わる1モーラ違いです。"}], "explanations": {"恩恵": "見出し語そのものです。", "穏健": "おんけん。最後の「い」が「ん」に変わる1モーラ違いです。", "温帯": "おんたい。3番目の「け」が「た」に変わる1モーラ違いです。", "音階": "おんかい。3番目の「け」が「か」に変わる1モーラ違いです。"}, "sentence_index": null, "correct_answer": "恩恵"}, "level_3": {"options": [{"text": "恩恵", "is_correct": true, "explanation": "川から受ける利益に感謝するという意味に合います。"}, {"text": "被害", "is_correct": false, "explanation": "形は合うが意味が合わない。被害に感謝して祭りを開くとは言えません。"}, {"text": "汚染", "is_correct": false, "explanation": "形は合うが意味が合わない。感謝の対象になりません。"}, {"text": "事故", "is_correct": false, "explanation": "形は合うが意味が合わない。事故に感謝して祭りを開く文脈ではありません。"}], "explanations": {"恩恵": "川から受ける利益に感謝するという意味に合います。", "被害": "形は合うが意味が合わない。被害に感謝して祭りを開くとは言えません。", "汚染": "形は合うが意味が合わない。感謝の対象になりません。", "事故": "形は合うが意味が合わない。事故に感謝して祭りを開く文脈ではありません。"}, "sentence_index": 6, "correct_answer": "恩恵"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は借金の恩恵に苦しんでいる。", "explanation": "恩恵は利益を指すので、苦しみの原因には使えません。"}, {"text": "恩恵を食べすぎておなかが痛い。", "explanation": "恩恵は抽象的な利益で、食べることはできません。"}, {"text": "事故の恩恵で、大きな被害が出た。", "explanation": "恩恵は良い利益を表すため、被害が出たという内容と合いません。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b8fb9dc-8519-4141-82f0-8afe6c53eb23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35355, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "雨は農家への恩恵で、作物が枯れてしまった。", "corrected_sentence": "雨は農家への恩恵で、作物が育った。", "error_description": "恩恵は利益を意味するのに、作物が枯れたという悪い結果が続いていて矛盾している。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b8fb9dc-8519-4141-82f0-8afe6c53eb23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35355, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "私たちは多くの恩恵を飲んでいる。", "corrected_sentence": "私たちは多くの恩恵を受けている。", "error_description": "「恩恵」と結びつく動詞は「受ける」で、「飲む」は不適切。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b8fb9dc-8519-4141-82f0-8afe6c53eb23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
