INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35363, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「検証を行う」で、行う対象（動作の目的語）を示す。正しい。"}, {"text": "が", "is_correct": false, "explanation": "「検証が行った」では検証が主語になり、記者が行う文の形にならない。"}, {"text": "で", "is_correct": false, "explanation": "「検証で行った」は手段を表すが、行うは対象を取るのでここには合わない。"}, {"text": "と", "is_correct": false, "explanation": "「検証と行った」は相手や共同を表す形で、行う対象を示す文脈に合わない。"}], "correct_answer": "を", "explanations": {"を": "「検証を行う」で、行う対象（動作の目的語）を示す。正しい。", "が": "「検証が行った」では検証が主語になり、記者が行う文の形にならない。", "で": "「検証で行った」は手段を表すが、行うは対象を取るのでここには合わない。", "と": "「検証と行った」は相手や共同を表す形で、行う対象を示す文脈に合わない。"}, "error_tags": {"が": "主語", "で": "手段", "と": "相手"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '815f5587-2a9c-42ca-9db8-5f13ee1b65f5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35363, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "物事の正しさや真実を、調べたり確かめたりして判断すること。", "primary_collocate": null, "pronunciation": "けんしょう", "ipa": "keɴɕoː", "syllable_count": 4, "sentences": [{"text": "いかなる偽装も、この厳密な科学的検証の前には無力化されるほかない。", "target_word": "検証", "complexity_tier": "T3", "furigana": "いかなる偽装[ぎそう]も、この厳密[げんみつ]な科学的[かがくてき]検証[けんしょう]の前[まえ]には無力化[むりょくか]されるほかない。", "sentence_source": "mined"}, {"text": "新しい薬の効果を、実験によって検証する必要がある。", "target_word": "検証", "complexity_tier": "T3", "furigana": "新[あたら]しい薬[くすり]の効果[こうか]を、実験[じっけん]によって検証[けんしょう]する必要[ひつよう]がある。", "sentence_source": "generated"}, {"text": "研究チームは仮説が正しいかどうかを検証した。", "target_word": "検証", "complexity_tier": "T3", "furigana": "研究[けんきゅう]チームは仮説[かせつ]が正[ただ]しいかどうかを検証[けんしょう]した。", "sentence_source": "generated"}, {"text": "検証の結果、報告書に重大な誤りがあったことがわかった。", "target_word": "検証", "complexity_tier": "T3", "furigana": "検証[けんしょう]の結果[けっか]、報告書[ほうこくしょ]に重大[じゅうだい]な誤[あやま]りがあったことがわかった。", "sentence_source": "generated"}, {"text": "この数字が本当に正しいか、第三者による検証が求められている。", "target_word": "検証", "complexity_tier": "T3", "furigana": "この数字[すうじ]が本当[ほんとう]に正[ただ]しいか、第三者[だいさんしゃ]による検証[けんしょう]が求[もと]められている。", "sentence_source": "generated"}, {"text": "事故の原因を検証するため、専門家の委員会が設けられた。", "target_word": "検証", "complexity_tier": "T3", "furigana": "事故[じこ]の原因[げんいん]を検証[けんしょう]するため、専門家[せんもんか]の委員会[いいんかい]が設[もう]けられた。", "sentence_source": "generated"}, {"text": "検証を重ねたうえで、ようやく結論を発表した。", "target_word": "検証", "complexity_tier": "T3", "furigana": "検証[けんしょう]を重[かさ]ねたうえで、ようやく結論[けつろん]を発表[はっぴょう]した。", "sentence_source": "generated"}, {"text": "うわさが事実かどうか、記者は現地で検証を行った。", "target_word": "検証", "complexity_tier": "T3", "furigana": "うわさが事実[じじつ]かどうか、記者[きしゃ]は現地[げんち]で検証[けんしょう]を行[おこな]った。", "sentence_source": "generated"}, {"text": "十分な検証もせずに結論を出すのは危険だ。", "target_word": "検証", "complexity_tier": "T3", "furigana": "十分[じゅうぶん]な検証[けんしょう]もせずに結論[けつろん]を出[だ]すのは危険[きけん]だ。", "sentence_source": "generated"}, {"text": "動画の映像が本物かを検証する技術が進歩している。", "target_word": "検証", "complexity_tier": "T3", "furigana": "動画[どうが]の映像[えいぞう]が本物[ほんもの]かを検証[けんしょう]する技術[ぎじゅつ]が進歩[しんぽ]している。", "sentence_source": "generated"}], "morphological_forms": [{"form": "検証する", "label": "dictionary form (suru-verb)"}, {"form": "検証した", "label": "past"}, {"form": "検証している", "label": "progressive"}, {"form": "検証される", "label": "passive"}], "register": "formal", "sense_fingerprint": "事実・仮説・効果などの正しさを調べて確かめ、判断すること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0bf4c2f4-d106-46cc-9bb1-e6df9b77d143') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35363, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "検証", "is_correct": true, "explanation": "正しさを調べて確かめる行為を指し、偽装が科学的検証の前で無力化されるという文脈に合う。"}, {"text": "解説", "is_correct": false, "explanation": "「科学的解説の前には無力化されるほかない」は文脈として通らない。解説は説き明かす行為。"}, {"text": "運搬", "is_correct": false, "explanation": "「科学的運搬」という言い方は不自然で、無力化の前提にも合わない。"}, {"text": "製造", "is_correct": false, "explanation": "「科学的製造の前では偽装が無力化される」という意味にならない。"}], "explanations": {"検証": "正しさを調べて確かめる行為を指し、偽装が科学的検証の前で無力化されるという文脈に合う。", "解説": "「科学的解説の前には無力化されるほかない」は文脈として通らない。解説は説き明かす行為。", "運搬": "「科学的運搬」という言い方は不自然で、無力化の前提にも合わない。", "製造": "「科学的製造の前では偽装が無力化される」という意味にならない。"}, "sentence_index": 0, "correct_answer": "検証"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "朝ごはんに、卵を検証して焼いた。", "explanation": "ここは〈焼く〉の意味。卵を焼く調理は検証の意味ではない。"}, {"text": "週末、庭の花を検証して、部屋に飾った。", "explanation": "ここは〈生ける〉の意味。花を飾る行為で、正しさを判断する検証とは違う。"}, {"text": "夕食に、母はトマトを検証して、サラダにした。", "explanation": "ここは〈切る〉の意味。食材を刻んで料理する行為で、検証とは違う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '815f5587-2a9c-42ca-9db8-5f13ee1b65f5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35363, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "検証", "is_correct": true, "explanation": "確かめる作業を繰り返すという意味で、結論を出す前の段階として文脈に合う。"}, {"text": "清掃", "is_correct": false, "explanation": "「清掃を重ねたうえで結論を発表した」は結論に結びつかない。清掃はごみを取り除いて綺麗にする作業。"}, {"text": "栽培", "is_correct": false, "explanation": "「栽培を重ねたうえで結論を発表した」は通らない。栽培は作物や植物を育てる作業。"}, {"text": "梱包", "is_correct": false, "explanation": "「梱包を重ねたうえで結論を発表した」という流れは不自然。"}], "explanations": {"検証": "確かめる作業を繰り返すという意味で、結論を出す前の段階として文脈に合う。", "清掃": "「清掃を重ねたうえで結論を発表した」は結論に結びつかない。清掃はごみを取り除いて綺麗にする作業。", "栽培": "「栽培を重ねたうえで結論を発表した」は通らない。栽培は作物や植物を育てる作業。", "梱包": "「梱包を重ねたうえで結論を発表した」という流れは不自然。"}, "sentence_index": 6, "correct_answer": "検証"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "毎朝、食卓の皿を検証して、テーブルに並べている。", "explanation": "ここは〈並べる〉の意味。皿を置く動作で、正しさを判断する検証とは違う。"}, {"text": "彼女は週末、部屋の壁を検証して、きれいに塗った。", "explanation": "ここは〈塗る〉の意味。壁を塗る作業で、検証の意味ではない。"}, {"text": "図書館で新しい本を検証して、ラベルを貼った。", "explanation": "ここは〈貼る〉の意味。本に印字物を付ける作業で、検証とは違う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '815f5587-2a9c-42ca-9db8-5f13ee1b65f5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35363, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "事故の原因を検証なため、専門家の委員会を設けた。", "corrected_sentence": "事故の原因を検証するため、専門家の委員会を設けた。", "error_description": "誤: 検証な / 正: 検証する。検証はサ変名詞で、動詞として使うには「する」が必要。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '815f5587-2a9c-42ca-9db8-5f13ee1b65f5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35363, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "その報告が正しいかどうか、局は検証が行った。", "corrected_sentence": "その報告が正しいかどうか、局は検証を行った。", "error_description": "誤: 検証が行った / 正: 検証を行った。「行う」は対象を「を」で受けるので、ここの「が」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '815f5587-2a9c-42ca-9db8-5f13ee1b65f5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35368, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「スピードを落として」の目的語を示す。"}, {"text": "が", "is_correct": false, "explanation": "主語を示すが、「スピードが落として」は成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "位置・方向を示すが、「スピードに落とす」は不自然。"}, {"text": "と", "is_correct": false, "explanation": "並列を示すが、落とす対象にはならない。"}], "correct_answer": "を", "explanations": {"を": "「スピードを落として」の目的語を示す。", "が": "主語を示すが、「スピードが落として」は成り立たない。", "に": "位置・方向を示すが、「スピードに落とす」は不自然。", "と": "並列を示すが、落とす対象にはならない。"}, "error_tags": {"を": "目的語", "が": "主語", "に": "位置・方向", "と": "並列"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3cdb77ee-5326-404e-a91e-0d767cc9c290') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35368, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「スピードを上げて」の目的語を示す。"}, {"text": "から", "is_correct": false, "explanation": "起点を示すが、「スピードから上げて」は成り立たない。"}, {"text": "より", "is_correct": false, "explanation": "比較を示すが、「スピードより上げて」は比べる文にならない。"}, {"text": "の", "is_correct": false, "explanation": "連体修飾の助詞だが、「スピードの上げて」は文が成り立たない。"}], "correct_answer": "を", "explanations": {"を": "「スピードを上げて」の目的語を示す。", "から": "起点を示すが、「スピードから上げて」は成り立たない。", "より": "比較を示すが、「スピードより上げて」は比べる文にならない。", "の": "連体修飾の助詞だが、「スピードの上げて」は文が成り立たない。"}, "error_tags": {"を": "目的語", "から": "起点", "より": "比較", "の": "連体修飾"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3cdb77ee-5326-404e-a91e-0d767cc9c290') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35368, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "物事の進む速さのこと。", "primary_collocate": null, "pronunciation": "すぴーど", "ipa": "sɯpiːdo", "syllable_count": 4, "sentences": [{"text": "自転車で坂を下ると、スピードがどんどん出る。", "target_word": "スピード", "complexity_tier": "T3", "furigana": "自転車[じてんしゃ]で坂[さか]を下[くだ]ると、スピードがどんどん出[で]る。", "sentence_source": "generated"}, {"text": "バスは雨の日、いつもよりスピードを落として走る。", "target_word": "スピード", "complexity_tier": "T3", "furigana": "バスは雨[あめ]の日[ひ]、いつもよりスピードを落[お]として走[はし]る。", "sentence_source": "generated"}, {"text": "子どもの成長のスピードには、毎日驚かされます。", "target_word": "スピード", "complexity_tier": "T3", "furigana": "子[こ]どもの成長[せいちょう]のスピードには、毎日[まいにち]驚[おどろ]かされます。", "sentence_source": "generated"}, {"text": "先生の話すスピードが速すぎて、メモが間に合わなかった。", "target_word": "スピード", "complexity_tier": "T3", "furigana": "先生[せんせい]の話[はな]すスピードが速[はや]すぎて、メモが間[ま]に合[あ]わなかった。", "sentence_source": "generated"}, {"text": "彼は走るスピードではクラスで一番だ。", "target_word": "スピード", "complexity_tier": "T3", "furigana": "彼[かれ]は走[はし]るスピードではクラスで一番[いちばん]だ。", "sentence_source": "generated"}, {"text": "新幹線は、とても高いスピードで走っています。", "target_word": "スピード", "complexity_tier": "T3", "furigana": "新幹線[しんかんせん]は、とても高[たか]いスピードで走[はし]っています。", "sentence_source": "generated"}, {"text": "作業のスピードを上げるために、道具を新しくした。", "target_word": "スピード", "complexity_tier": "T3", "furigana": "作業[さぎょう]のスピードを上[あ]げるために、道具[どうぐ]を新[あたら]しくした。", "sentence_source": "generated"}, {"text": "ジェットコースターが急にスピードを上げて、思わず声が出た。", "target_word": "スピード", "complexity_tier": "T3", "furigana": "ジェットコースターが急[きゅう]にスピードを上[あ]げて、思[おも]わず声[こえ]が出[で]た。", "sentence_source": "generated"}, {"text": "工事のスピードが遅く、完成は来年になりそうです。", "target_word": "スピード", "complexity_tier": "T3", "furigana": "工事[こうじ]のスピードが遅[おそ]く、完成[かんせい]は来年[らいねん]になりそうです。", "sentence_source": "generated"}, {"text": "川の流れのスピードは、雨のあとで急に速くなった。", "target_word": "スピード", "complexity_tier": "T3", "furigana": "川[かわ]の流[なが]れのスピードは、雨[あめ]のあとで急[きゅう]に速[はや]くなった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "スピード", "label": "名詞形"}], "register": "neutral", "sense_fingerprint": "物や仕事が進んでいく速さ（英 speed）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cc0a982a-50ff-4c39-bd65-8c88b1cfa552') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35368, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "スピード", "is_correct": true, "explanation": "坂を下ると速さが増すという意味で、「出る」と結びつく語。"}, {"text": "天気", "is_correct": false, "explanation": "天気が出るという使い方はしない。"}, {"text": "教養", "is_correct": false, "explanation": "教養が出るという使い方はしない。"}, {"text": "哲学", "is_correct": false, "explanation": "哲学が出るとは言わない。"}], "explanations": {"スピード": "坂を下ると速さが増すという意味で、「出る」と結びつく語。", "天気": "天気が出るという使い方はしない。", "教養": "教養が出るという使い方はしない。", "哲学": "哲学が出るとは言わない。"}, "sentence_index": 0, "correct_answer": "スピード"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "ラジオのスピードを大きくしたら、隣の部屋まで聞こえた。", "explanation": "ここは〈音量〉の意味。音の大きさはスピードと言わず、音量を大きくすると言う。"}, {"text": "お風呂のスピードがぬるくて、入れなかった。", "explanation": "ここは〈温度〉の意味。ぬるいのは湯の温度で、スピードは速さの語なので合わない。"}, {"text": "壁のスピードが淡くて、部屋が明るく見える。", "explanation": "ここは〈色合い〉の意味。淡い・濃いは色の話で、スピードは速さの語なので壁の色には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3cdb77ee-5326-404e-a91e-0d767cc9c290') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35368, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "スピード", "is_correct": true, "explanation": "作業の速さを上げるという意味で、この文の空欄に入る語。"}, {"text": "地図", "is_correct": false, "explanation": "地図を上げるという使い方はしない。"}, {"text": "家具", "is_correct": false, "explanation": "家具を上げるという意味にはならない。"}, {"text": "文法", "is_correct": false, "explanation": "文法を上げるという使い方はしない。"}], "explanations": {"スピード": "作業の速さを上げるという意味で、この文の空欄に入る語。", "地図": "地図を上げるという使い方はしない。", "家具": "家具を上げるという意味にはならない。", "文法": "文法を上げるという使い方はしない。"}, "sentence_index": 6, "correct_answer": "スピード"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "今日はスピードが高くて、じめじめする。", "explanation": "ここは〈湿度〉の意味。湿気の多さはスピードでは言えず、速さの語は合わない。"}, {"text": "雨が降ったあと、川のスピードが一メートルも上がった。", "explanation": "ここは〈水位〉の意味。一メートル上がるのは水位で、速さを表すスピードでは言えない。"}, {"text": "雨が多い年は、この池のスピードが一メートル深くなる。", "explanation": "ここは〈水深〉の意味。深くなるのは水深で、スピードは速さの語なので深さには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3cdb77ee-5326-404e-a91e-0d767cc9c290') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35368, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "カーブの手前では、スピードに落としてください。", "corrected_sentence": "カーブの手前では、スピードを落としてください。", "error_description": "「スピードを落とす」が正しい。「に」では「落とす」の目的語にならず、文が成り立たない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3cdb77ee-5326-404e-a91e-0d767cc9c290') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35368, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "新しい道具で、作業のスピードを上がった。", "corrected_sentence": "新しい道具で、作業のスピードを上げた。", "error_description": "「上げた」が正しい。「上がる」は自動詞なので「スピードを」の目的語を取れず、「上がった」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3cdb77ee-5326-404e-a91e-0d767cc9c290') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35379, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "雨が降る場所を表す「で」が入る。"}, {"text": "を", "is_correct": false, "explanation": "「降る」は目的語を取らないので、「を」は文法的に合わない。"}, {"text": "と", "is_correct": false, "explanation": "「各地と雨が降った」では意味が通らず、文法的に合わない。"}, {"text": "や", "is_correct": false, "explanation": "並列の「や」は後ろに続く名詞が必要で、この文では成り立たない。"}], "correct_answer": "で", "explanations": {"で": "雨が降る場所を表す「で」が入る。", "を": "「降る」は目的語を取らないので、「を」は文法的に合わない。", "と": "「各地と雨が降った」では意味が通らず、文法的に合わない。", "や": "並列の「や」は後ろに続く名詞が必要で、この文では成り立たない。"}, "error_tags": {"を": "object_marker", "と": "comitative", "や": "listing"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd294d06f-130c-4a48-9148-a42e60f247cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35379, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "研究が進められている場所を表す「で」が入る。"}, {"text": "を", "is_correct": false, "explanation": "「進められている」は受身で、研究が行われる場所を「を」で示すことはできない。"}, {"text": "が", "is_correct": false, "explanation": "「各地が」と「研究が」が並び、主語が二重になって文法的に合わない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表す「へ」は、研究が行われる場所を示せず、文が成り立たない。"}], "correct_answer": "で", "explanations": {"で": "研究が進められている場所を表す「で」が入る。", "を": "「進められている」は受身で、研究が行われる場所を「を」で示すことはできない。", "が": "「各地が」と「研究が」が並び、主語が二重になって文法的に合わない。", "へ": "方向を表す「へ」は、研究が行われる場所を示せず、文が成り立たない。"}, "error_tags": {"を": "object_marker", "が": "subject_marker", "へ": "direction"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd294d06f-130c-4a48-9148-a42e60f247cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35379, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "あちこちの場所。それぞれの地方。", "primary_collocate": null, "pronunciation": "かくち", "ipa": "kakɯtɕi", "syllable_count": 3, "sentences": [{"text": "近年、都市の無秩序な拡大に伴う緑の希薄化に歯止めをかけるべく、地域コミュニティガーデンプロジェクトが各地で顕在化している。", "target_word": "各地", "complexity_tier": "T6", "furigana": "近年[きんねん]、都市[とし]の無秩序[むちつじょ]な拡大[かくだい]に伴[ともな]う緑[みどり]の希薄化[きはくか]に歯止[はど]めをかけるべく、地域[ちいき]コミュニティガーデンプロジェクトが各地[かくち]で顕在化[けんざいか]している。", "sentence_source": "mined"}, {"text": "各地で雨が降った。", "target_word": "各地", "complexity_tier": "T1", "furigana": "各地[かくち]で雨[あめ]が降[ふ]った。", "sentence_source": "generated"}, {"text": "各地から人が来た。", "target_word": "各地", "complexity_tier": "T1", "furigana": "各地[かくち]から人[ひと]が来[き]た。", "sentence_source": "generated"}, {"text": "各地の名物を食べ比べた。", "target_word": "各地", "complexity_tier": "T2", "furigana": "各地[かくち]の名物[めいぶつ]を食[た]べ比[くら]べた。", "sentence_source": "generated"}, {"text": "台風は各地に被害をもたらした。", "target_word": "各地", "complexity_tier": "T2", "furigana": "台風[たいふう]は各地[かくち]に被害[ひがい]をもたらした。", "sentence_source": "generated"}, {"text": "全国各地を旅するのが夢だ。", "target_word": "各地", "complexity_tier": "T3", "furigana": "全国[ぜんこく]各地[かくち]を旅[たび]するのが夢[ゆめ]だ。", "sentence_source": "generated"}, {"text": "各地の祭りが中止になった。", "target_word": "各地", "complexity_tier": "T2", "furigana": "各地[かくち]の祭[まつ]りが中止[ちゅうし]になった。", "sentence_source": "generated"}, {"text": "世界各地で、同じような研究が進められている。", "target_word": "各地", "complexity_tier": "T4", "furigana": "世界[せかい]各地[かくち]で、同[おな]じような研究[けんきゅう]が進[すす]められている。", "sentence_source": "generated"}, {"text": "各地は大雪で、電車が止まった。", "target_word": "各地", "complexity_tier": "T2", "furigana": "各地[かくち]は大雪[おおゆき]で、電車[でんしゃ]が止[と]まった。", "sentence_source": "generated"}, {"text": "各地を回って、米作りの話を聞いた。", "target_word": "各地", "complexity_tier": "T3", "furigana": "各地[かくち]を回[まわ]って、米作[こめづく]りの話[はなし]を聞[き]いた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "全国各地", "label": "派生"}, {"form": "世界各地", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | あちこちの場所・それぞれの地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T2: 4 words above tier T2 (max 3): 無秩序 (Zipf 2.99), 希薄 (Zipf 3.22), 歯止め (Zipf 3.18), 顕在 (Zipf 3.05)']::text[], '57ac3fe2-6ce0-4a2e-b7a6-92b185db239c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35379, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "各地", "is_correct": true, "explanation": "「かくち」が見出し語で、これが正解。"}, {"text": "各自", "is_correct": false, "explanation": "「かくじ」で、最後の「ち」が「じ」に変わっている。"}, {"text": "格差", "is_correct": false, "explanation": "「かくさ」で、最後の「ち」が「さ」に変わっている。"}, {"text": "角度", "is_correct": false, "explanation": "「かくど」で、最後の「ち」が「ど」に変わっている。"}, {"text": "感知", "is_correct": false, "explanation": "「かんち」で、二つ目の「く」が「ん」に変わっている。"}], "explanations": {"各地": "「かくち」が見出し語で、これが正解。", "各自": "「かくじ」で、最後の「ち」が「じ」に変わっている。", "格差": "「かくさ」で、最後の「ち」が「さ」に変わっている。", "角度": "「かくど」で、最後の「ち」が「ど」に変わっている。", "感知": "「かんち」で、二つ目の「く」が「ん」に変わっている。"}, "sentence_index": null, "correct_answer": "各地"}, "level_3": {"options": [{"text": "各地", "is_correct": true, "explanation": "あちこちの場所で取り組みが広がっているという意味になり、文に合う。"}, {"text": "宇宙", "is_correct": false, "explanation": "形は合うが意味が合わない。地域のガーデンプロジェクトが宇宙で顕在化するとは言えない。"}, {"text": "海中", "is_correct": false, "explanation": "形は合うが意味が合わない。緑地やガーデンの取り組みが海中で顕在化するのは不自然。"}, {"text": "体内", "is_correct": false, "explanation": "形は合うが意味が合わない。地域のガーデンプロジェクトが体内で広がるとは言えない。"}], "explanations": {"各地": "あちこちの場所で取り組みが広がっているという意味になり、文に合う。", "宇宙": "形は合うが意味が合わない。地域のガーデンプロジェクトが宇宙で顕在化するとは言えない。", "海中": "形は合うが意味が合わない。緑地やガーデンの取り組みが海中で顕在化するのは不自然。", "体内": "形は合うが意味が合わない。地域のガーデンプロジェクトが体内で広がるとは言えない。"}, "sentence_index": 0, "correct_answer": "各地"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この小さな部屋の各地に本が置いてある。", "explanation": "「各地」は地方や土地を指す語で、部屋の中のあちこちには使えない。"}, {"text": "各地は昨日、私に電話をかけてきた。", "explanation": "「各地」は場所を表す語で、人のように電話をかける主語にはならない。"}, {"text": "各地を飲んで元気になった。", "explanation": "「各地」は飲む対象ではなく、「飲む」との組み合わせが成り立たない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd294d06f-130c-4a48-9148-a42e60f247cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35379, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "各地", "is_correct": true, "explanation": "「かくち」が見出し語で、これが正解。"}, {"text": "覚悟", "is_correct": false, "explanation": "「かくご」で、最後の「ち」が「ご」に変わっている。"}, {"text": "隔離", "is_correct": false, "explanation": "「かくり」で、最後の「ち」が「り」に変わっている。"}, {"text": "隠し", "is_correct": false, "explanation": "「かくし」で、最後の「ち」が「し」に変わっている。"}, {"text": "各位", "is_correct": false, "explanation": "「かくい」で、最後の「ち」が「い」に変わっている。"}], "explanations": {"各地": "「かくち」が見出し語で、これが正解。", "覚悟": "「かくご」で、最後の「ち」が「ご」に変わっている。", "隔離": "「かくり」で、最後の「ち」が「り」に変わっている。", "隠し": "「かくし」で、最後の「ち」が「し」に変わっている。", "各位": "「かくい」で、最後の「ち」が「い」に変わっている。"}, "sentence_index": null, "correct_answer": "各地"}, "level_3": {"options": [{"text": "各地", "is_correct": true, "explanation": "あちこちの地方の祭りが中止になったという意味で、文に合う。"}, {"text": "海底", "is_correct": false, "explanation": "形は合うが意味が合わない。海底で祭りが行われて中止になるとは考えにくい。"}, {"text": "体内", "is_correct": false, "explanation": "形は合うが意味が合わない。体内の祭りという表現は文脈に合わない。"}, {"text": "机上", "is_correct": false, "explanation": "形は合うが意味が合わない。机の上の祭りでは、中止になる話として不自然。"}], "explanations": {"各地": "あちこちの地方の祭りが中止になったという意味で、文に合う。", "海底": "形は合うが意味が合わない。海底で祭りが行われて中止になるとは考えにくい。", "体内": "形は合うが意味が合わない。体内の祭りという表現は文脈に合わない。", "机上": "形は合うが意味が合わない。机の上の祭りでは、中止になる話として不自然。"}, "sentence_index": 6, "correct_answer": "各地"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "このノートの各地に名前を書いた。", "explanation": "「各地」は地方や土地を指す語で、ノートの紙面の各所には使えない。"}, {"text": "各地の昨日は雨だった。", "explanation": "「各地」は場所を表す語で、時間を指す「昨日」を修飾する使い方はできない。"}, {"text": "各地を一つ買って帰った。", "explanation": "「各地」は買って持ち帰れる物ではなく、数える対象としても使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd294d06f-130c-4a48-9148-a42e60f247cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35379, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "先週、各地を大雪が降った。", "corrected_sentence": "先週、各地で大雪が降った。", "error_description": "「各地」の後の助詞が誤り。降る場所を表すので「を」ではなく「で」を使う。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd294d06f-130c-4a48-9148-a42e60f247cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35379, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "秋になると、各地を祭りが開かれる。", "corrected_sentence": "秋になると、各地で祭りが開かれる。", "error_description": "「各地」の後の助詞が誤り。行事が行われる場所には「を」ではなく「で」を使う。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd294d06f-130c-4a48-9148-a42e60f247cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35391, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "固定する先を示す「に」。"}, {"text": "を", "is_correct": false, "explanation": "「棚を」とすでに使われ、かべを目的語にできない。"}, {"text": "が", "is_correct": false, "explanation": "「かべが固定する」では主語になり、意味が合わない。"}, {"text": "の", "is_correct": false, "explanation": "「かべの固定する」は名詞に動詞が続き、文法的に成り立たない。"}], "correct_answer": "に", "explanations": {"に": "固定する先を示す「に」。", "を": "「棚を」とすでに使われ、かべを目的語にできない。", "が": "「かべが固定する」では主語になり、意味が合わない。", "の": "「かべの固定する」は名詞に動詞が続き、文法的に成り立たない。"}, "error_tags": {"を": "object_marker", "が": "subject_marker", "の": "possessive"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "流動", "is_correct": true, "explanation": "動かない「固定」に対して、流れ動くことを表す反対語。"}, {"text": "静止", "is_correct": false, "explanation": "止まることで、「固定」に近い意味の語。"}, {"text": "保持", "is_correct": false, "explanation": "保ち続けることで、反対語ではない。"}, {"text": "安定", "is_correct": false, "explanation": "落ち着くことで、「固定」の反対語ではない。"}], "correct_answer": "流動", "explanations": {"流動": "動かない「固定」に対して、流れ動くことを表す反対語。", "静止": "止まることで、「固定」に近い意味の語。", "保持": "保ち続けることで、反対語ではない。", "安定": "落ち着くことで、「固定」の反対語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a1e263f5-edd4-41a4-8d05-3c8d6085553b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35391, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "固定する対象「足」を示す「を」。"}, {"text": "の", "is_correct": false, "explanation": "「足の固定してもらった」は名詞に動詞が続き、文法的に成り立たない。"}, {"text": "が", "is_correct": false, "explanation": "「足が固定してもらった」は主語が合わない。"}, {"text": "で", "is_correct": false, "explanation": "「足で固定してもらった」は意味が変わり、対象が示されない。"}], "correct_answer": "を", "explanations": {"を": "固定する対象「足」を示す「を」。", "の": "「足の固定してもらった」は名詞に動詞が続き、文法的に成り立たない。", "が": "「足が固定してもらった」は主語が合わない。", "で": "「足で固定してもらった」は意味が変わり、対象が示されない。"}, "error_tags": {"の": "possessive", "が": "subject_marker", "で": "means"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "変動", "is_correct": true, "explanation": "変わらない「固定」に対して、変わり動くことを表す反対語。"}, {"text": "一定", "is_correct": false, "explanation": "変わらないことで、「固定」に近い意味の語。"}, {"text": "維持", "is_correct": false, "explanation": "保ち続けることで、反対語ではない。"}, {"text": "継続", "is_correct": false, "explanation": "続けることで、「固定」の反対語ではない。"}], "correct_answer": "変動", "explanations": {"変動": "変わらない「固定」に対して、変わり動くことを表す反対語。", "一定": "変わらないことで、「固定」に近い意味の語。", "維持": "保ち続けることで、反対語ではない。", "継続": "続けることで、「固定」の反対語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a1e263f5-edd4-41a4-8d05-3c8d6085553b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35391, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "物事が動かず、同じ状態のままであること。また、そうすること。", "primary_collocate": null, "pronunciation": "こてい", "ipa": "kotei", "syllable_count": 3, "sentences": [{"text": "この理論的基盤は、建物に込められた作者の意図や固定的な意味を脱構築し、その背後にある社会的な文脈や矛盾を浮き彫りにします。", "target_word": "固定", "complexity_tier": "T6", "furigana": "この理論的基盤[りろんてききばん]は、建物[たてもの]に込[こ]められた作者[さくしゃ]の意図[いと]や固定的[こていてき]な意味[いみ]を脱構築[だつこうちく]し、その背後[はいご]にある社会的[しゃかいてき]な文脈[ぶんみゃく]や矛盾[むじゅん]を浮[う]き彫[ぼ]りにします。", "sentence_source": "mined"}, {"text": "棚をかべに固定する。", "target_word": "固定", "complexity_tier": "T3", "furigana": "棚[たな]をかべに固定[こてい]する。", "sentence_source": "generated"}, {"text": "カメラを三脚に固定して、写真を撮った。", "target_word": "固定", "complexity_tier": "T3", "furigana": "カメラを三脚[さんきゃく]に固定[こてい]して、写真[しゃしん]を撮[と]った。", "sentence_source": "generated"}, {"text": "机の位置は固定されている。", "target_word": "固定", "complexity_tier": "T3", "furigana": "机[つくえ]の位置[いち]は固定[こてい]されている。", "sentence_source": "generated"}, {"text": "固定した考えにとらわれてはいけない。", "target_word": "固定", "complexity_tier": "T4", "furigana": "固定[こてい]した考[かんが]えにとらわれてはいけない。", "sentence_source": "generated"}, {"text": "ネジで板を固定します。", "target_word": "固定", "complexity_tier": "T2", "furigana": "ネジで板[いた]を固定[こてい]します。", "sentence_source": "generated"}, {"text": "テレビを台にしっかり固定した。", "target_word": "固定", "complexity_tier": "T3", "furigana": "テレビを台[だい]にしっかり固定[こてい]した。", "sentence_source": "generated"}, {"text": "骨折した足を固定してもらった。", "target_word": "固定", "complexity_tier": "T3", "furigana": "骨折[こっせつ]した足[あし]を固定[こてい]してもらった。", "sentence_source": "generated"}, {"text": "固定されたイメージを変えるのは、簡単ではない。", "target_word": "固定", "complexity_tier": "T4", "furigana": "固定[こてい]されたイメージを変[か]えるのは、簡単[かんたん]ではない。", "sentence_source": "generated"}, {"text": "家賃は毎月固定で、変わらない。", "target_word": "固定", "complexity_tier": "T3", "furigana": "家賃[やちん]は毎月[まいつき]固定[こてい]で、変[か]わらない。", "sentence_source": "generated"}], "morphological_forms": [{"form": "固定する", "label": "活用"}, {"form": "固定された", "label": "活用"}, {"form": "固定的", "label": "派生"}, {"form": "固定化", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 動かず同じ状態に保つこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c32dd9f-f08f-4e2d-bcb5-5d9708f30642') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35391, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "固定", "is_correct": true, "explanation": "見出し語。"}, {"text": "規定", "is_correct": false, "explanation": "「こ」が「き」に変わる一音違い。"}, {"text": "査定", "is_correct": false, "explanation": "「こ」が「さ」に変わる一音違い。"}, {"text": "指定", "is_correct": false, "explanation": "「こ」が「し」に変わる一音違い。"}, {"text": "固体", "is_correct": false, "explanation": "「て」が「た」に変わる一音違い。"}], "explanations": {"固定": "見出し語。", "規定": "「こ」が「き」に変わる一音違い。", "査定": "「こ」が「さ」に変わる一音違い。", "指定": "「こ」が「し」に変わる一音違い。", "固体": "「て」が「た」に変わる一音違い。"}, "sentence_index": null, "correct_answer": "固定"}, "level_3": {"options": [{"text": "固定", "is_correct": true, "explanation": "「固定的な意味」で動かない決まった意味を表し、文脈に合う。"}, {"text": "健康", "is_correct": false, "explanation": "形は合うが、「健康的な意味」は建物の意味の説明として合わない。"}, {"text": "活動", "is_correct": false, "explanation": "形は合うが、意味の性質として活動的は合わない。"}, {"text": "運動", "is_correct": false, "explanation": "形は合うが、意味の性質として運動的は合わない。"}], "explanations": {"固定": "「固定的な意味」で動かない決まった意味を表し、文脈に合う。", "健康": "形は合うが、「健康的な意味」は建物の意味の説明として合わない。", "活動": "形は合うが、意味の性質として活動的は合わない。", "運動": "形は合うが、意味の性質として運動的は合わない。"}, "sentence_index": 0, "correct_answer": "固定"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "風が強くて、洗濯物が固定して空に飛んでいった。", "explanation": "「固定」は動かないことなのに、飛んでいく場面に使っていて意味が逆。"}, {"text": "私は毎日固定を食べて、元気に過ごしている。", "explanation": "「固定」は食べ物ではないので、「食べる」とは結びつかない。"}, {"text": "天気が固定して、朝は晴れ、昼は雨になった。", "explanation": "「固定」は変わらないことなのに、変わる天気に使っていて意味が合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a1e263f5-edd4-41a4-8d05-3c8d6085553b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35391, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "固定", "is_correct": true, "explanation": "見出し語。"}, {"text": "不定", "is_correct": false, "explanation": "「こ」が「ふ」に変わる一音違い。"}, {"text": "否定", "is_correct": false, "explanation": "「こ」が「ひ」に変わる一音違い。"}, {"text": "仮定", "is_correct": false, "explanation": "「こ」が「か」に変わる一音違い。"}, {"text": "古典", "is_correct": false, "explanation": "「い」が「ん」に変わる一音違い。"}], "explanations": {"固定": "見出し語。", "不定": "「こ」が「ふ」に変わる一音違い。", "否定": "「こ」が「ひ」に変わる一音違い。", "仮定": "「こ」が「か」に変わる一音違い。", "古典": "「い」が「ん」に変わる一音違い。"}, "sentence_index": null, "correct_answer": "固定"}, "level_3": {"options": [{"text": "固定", "is_correct": true, "explanation": "テレビを台に動かないようにする意味で、文に合う。"}, {"text": "料理", "is_correct": false, "explanation": "形は合うが、テレビを台に料理することはできない。"}, {"text": "散歩", "is_correct": false, "explanation": "形は合うが、散歩は物を目的語に取らず意味が合わない。"}, {"text": "勉強", "is_correct": false, "explanation": "形は合うが、テレビを台に勉強するという意味は成り立たない。"}], "explanations": {"固定": "テレビを台に動かないようにする意味で、文に合う。", "料理": "形は合うが、テレビを台に料理することはできない。", "散歩": "形は合うが、散歩は物を目的語に取らず意味が合わない。", "勉強": "形は合うが、テレビを台に勉強するという意味は成り立たない。"}, "sentence_index": 6, "correct_answer": "固定"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "家賃は毎月固定で、先月は安く今月は高かった。", "explanation": "「固定」は変わらないことなのに、金額が変わる場面に使っていて意味が合わない。"}, {"text": "固定をはさみで切って、紙に貼った。", "explanation": "「固定」は状態を表す語で、切って貼れる物ではない。"}, {"text": "彼は固定に走って、駅まで行った。", "explanation": "「固定」は動かないことで、「走る」の行き先にはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a1e263f5-edd4-41a4-8d05-3c8d6085553b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35391, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "板をネジを固定します。", "corrected_sentence": "板をネジで固定します。", "error_description": "固定する手段は「で」で示す。「を」が重なるのは誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a1e263f5-edd4-41a4-8d05-3c8d6085553b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35391, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "家賃は毎月固定を、変わらない。", "corrected_sentence": "家賃は毎月固定で、変わらない。", "error_description": "状態を表す「固定で」とすべきところに「を」が使われている。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a1e263f5-edd4-41a4-8d05-3c8d6085553b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35392, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "「大きな国家では」と範囲や場を示し、「地域によって違う」と合う。"}, {"text": "を", "is_correct": false, "explanation": "「国家を」は目的語で、後ろの「は」と続かず文が崩れる。"}, {"text": "の", "is_correct": false, "explanation": "「国家の」と連体修飾になり、「大きな国家の、は」の形で文の主語にならない。"}, {"text": "から", "is_correct": false, "explanation": "起点の「から」で、「国家からは地域によって違う」は意味が通らない。"}], "correct_answer": "で", "explanations": {"で": "「大きな国家では」と範囲や場を示し、「地域によって違う」と合う。", "を": "「国家を」は目的語で、後ろの「は」と続かず文が崩れる。", "の": "「国家の」と連体修飾になり、「大きな国家の、は」の形で文の主語にならない。", "から": "起点の「から」で、「国家からは地域によって違う」は意味が通らない。"}, "error_tags": {"を": "対象", "の": "連体修飾", "から": "起点"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9297dc18-f5ac-4488-a97e-eae535564182') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35392, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「国家の歴史」と「歴史」を修飾する「の」で、名詞句をつなぐ。"}, {"text": "を", "is_correct": false, "explanation": "「国家を歴史を学ぶ」は目的語が重なり、「学ぶ」と合わない。"}, {"text": "に", "is_correct": false, "explanation": "「国家に歴史を学ぶ」は帰着先の「に」で、「学ぶ」の対象にならない。"}, {"text": "へ", "is_correct": false, "explanation": "方向の「へ」で、「国家へ歴史を学ぶ」は学ぶ対象を示せない。"}], "correct_answer": "の", "explanations": {"の": "「国家の歴史」と「歴史」を修飾する「の」で、名詞句をつなぐ。", "を": "「国家を歴史を学ぶ」は目的語が重なり、「学ぶ」と合わない。", "に": "「国家に歴史を学ぶ」は帰着先の「に」で、「学ぶ」の対象にならない。", "へ": "方向の「へ」で、「国家へ歴史を学ぶ」は学ぶ対象を示せない。"}, "error_tags": {"を": "対象", "に": "帰着・対象", "へ": "方向"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9297dc18-f5ac-4488-a97e-eae535564182') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35392, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "自分の国。たくさんの人が住んでいる、一つのまとまりのある国のこと。", "primary_collocate": null, "pronunciation": "こっか", "ipa": "kokːa", "syllable_count": 3, "sentences": [{"text": "この国家には、一億人以上の人が住んでいます。", "target_word": "国家", "complexity_tier": "T3", "furigana": "この国家[こっか]には、一億人[いちおくにん]以上[いじょう]の人[ひと]が住[す]んでいます。", "sentence_source": "generated"}, {"text": "大きな国家では、地域によって気候がまったく違います。", "target_word": "国家", "complexity_tier": "T3", "furigana": "大[おお]きな国家[こっか]では、地域[ちいき]によって気候[きこう]がまったく違[ちが]います。", "sentence_source": "generated"}, {"text": "選手たちは国家の代表として、大会に出場しました。", "target_word": "国家", "complexity_tier": "T3", "furigana": "選手[せんしゅ]たちは国家[こっか]の代表[だいひょう]として、大会[たいかい]に出場[しゅつじょう]しました。", "sentence_source": "generated"}, {"text": "国家が豊かになるには、国民みんなの努力が必要です。", "target_word": "国家", "complexity_tier": "T3", "furigana": "国家[こっか]が豊[ゆた]かになるには、国民[こくみん]みんなの努力[どりょく]が必要[ひつよう]です。", "sentence_source": "generated"}, {"text": "彼は自分の国家に誇りを持ちながら、外国で働いている。", "target_word": "国家", "complexity_tier": "T3", "furigana": "彼[かれ]は自分[じぶん]の国家[こっか]に誇[ほこ]りを持[も]ちながら、外国[がいこく]で働[はたら]いている。", "sentence_source": "generated"}, {"text": "国家の祝日には、町中に旗が飾られます。", "target_word": "国家", "complexity_tier": "T3", "furigana": "国家[こっか]の祝日[しゅくじつ]には、町中[まちじゅう]に旗[はた]が飾[かざ]られます。", "sentence_source": "generated"}, {"text": "この国家は島が多く、船で移動する人がたくさんいます。", "target_word": "国家", "complexity_tier": "T3", "furigana": "この国家[こっか]は島[しま]が多[おお]く、船[ふね]で移動[いどう]する人[ひと]がたくさんいます。", "sentence_source": "generated"}, {"text": "国家の歴史を学ぶと、今の暮らしがよくわかります。", "target_word": "国家", "complexity_tier": "T3", "furigana": "国家[こっか]の歴史[れきし]を学[まな]ぶと、今[いま]の暮[く]らしがよくわかります。", "sentence_source": "generated"}, {"text": "小さい国家でも、独自の文化を持っています。", "target_word": "国家", "complexity_tier": "T3", "furigana": "小[ちい]さい国家[こっか]でも、独自[どくじ]の文化[ぶんか]を持[も]っています。", "sentence_source": "generated"}, {"text": "国家の行事に、多くの国民が参加しました。", "target_word": "国家", "complexity_tier": "T3", "furigana": "国家[こっか]の行事[ぎょうじ]に、多[おお]くの国民[こくみん]が参加[さんか]しました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "国家", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "人々が暮らす、一つのまとまりのある国(自分の国)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd0118fb7-8c88-4730-aa9e-d75a197e3036') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35392, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "国家", "is_correct": true, "explanation": "「この国家」は人々が暮らす国を指し、一億人が住むという文と合う。"}, {"text": "会社", "is_correct": false, "explanation": "会社には人が暮らすことはなく、「住んでいます」と合わない。"}, {"text": "建物", "is_correct": false, "explanation": "建物に一億人が住むのは不自然で、文の規模と合わない。"}, {"text": "大学", "is_correct": false, "explanation": "大学は人が暮らす場所ではなく、一億人の居住とは合わない。"}], "explanations": {"国家": "「この国家」は人々が暮らす国を指し、一億人が住むという文と合う。", "会社": "会社には人が暮らすことはなく、「住んでいます」と合わない。", "建物": "建物に一億人が住むのは不自然で、文の規模と合わない。", "大学": "大学は人が暮らす場所ではなく、一億人の居住とは合わない。"}, "sentence_index": 0, "correct_answer": "国家"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この国家の台所では、毎朝家族のためにみそ汁を作っている。", "explanation": "ここは〈家庭の台所〉の意味。国家は国民が住む国のことなので、家の中の台所を指す言い方にはならない。"}, {"text": "祖父母は、故郷の国家で、今も小さな畑を耕している。", "explanation": "ここは〈故郷・地元〉の意味。国家は多くの国民が住む一つの国を指すので、小さな村の暮らしを表す言葉としては使わない。"}, {"text": "この国家の店は、毎週日曜日に全部休みになる。", "explanation": "ここは〈店〉の意味。国家は国民が住む国のことなので、個々の店の定休日の話には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9297dc18-f5ac-4488-a97e-eae535564182') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35392, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "国家", "is_correct": true, "explanation": "「この国家」は島が多い国を指し、島の多さと船での移動という文脈と合う。"}, {"text": "学校", "is_correct": false, "explanation": "学校は島が多いという性質を持たず、文の主語として意味が合わない。"}, {"text": "病院", "is_correct": false, "explanation": "病院は島が多いという文と合わず、文脈に合わない。"}, {"text": "駅", "is_correct": false, "explanation": "駅には島が多いという特徴はなく、文の内容と合わない。"}], "explanations": {"国家": "「この国家」は島が多い国を指し、島の多さと船での移動という文脈と合う。", "学校": "学校は島が多いという性質を持たず、文の主語として意味が合わない。", "病院": "病院は島が多いという文と合わず、文脈に合わない。", "駅": "駅には島が多いという特徴はなく、文の内容と合わない。"}, "sentence_index": 6, "correct_answer": "国家"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "国家の運動会に、多くの住民が参加しました。", "explanation": "ここは〈地域〉の意味。運動会は地域の行事で、国家の行事とは言わない。"}, {"text": "国家の忘年会に、多くの社員が参加しました。", "explanation": "ここは〈会社〉の意味。忘年会は会社内の行事で、国家の行事とは言えない。"}, {"text": "国家の卒業式に、多くの学生が参加しました。", "explanation": "ここは〈大学〉の意味。卒業式は学校の行事で、国家の卒業式とは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9297dc18-f5ac-4488-a97e-eae535564182') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35392, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "大きな国家を、冬でも雪が降らない地域があります。", "corrected_sentence": "大きな国家では、冬でも雪が降らない地域があります。", "error_description": "誤りは「国家を」。正しくは「国家では」で、範囲を示す「では」が必要。「を」では目的語になるが、後ろに動詞がなく文が成り立たない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9297dc18-f5ac-4488-a97e-eae535564182') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35392, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "国家を伝統を大切にする人が増えています。", "corrected_sentence": "国家の伝統を大切にする人が増えています。", "error_description": "誤りは「国家を」。正しくは「国家の」で、「伝統」を修飾する「の」が必要。「を」を二つ重ねると目的語が重なり、文が成り立たない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9297dc18-f5ac-4488-a97e-eae535564182') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35393, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "「国家は」と主題を示し、文の主語として自然に成り立つ。"}, {"text": "を", "is_correct": false, "explanation": "「国家を国民を守る」は目的語が二つ重なり、文が崩れる。"}, {"text": "に", "is_correct": false, "explanation": "「国家に国民を守る」は帰着先の「に」で、「守る」の対象として意味が通らない。"}, {"text": "へ", "is_correct": false, "explanation": "方向の「へ」で、「国家へ国民を守る」は守る対象を示せない。"}], "correct_answer": "は", "explanations": {"は": "「国家は」と主題を示し、文の主語として自然に成り立つ。", "を": "「国家を国民を守る」は目的語が二つ重なり、文が崩れる。", "に": "「国家に国民を守る」は帰着先の「に」で、「守る」の対象として意味が通らない。", "へ": "方向の「へ」で、「国家へ国民を守る」は守る対象を示せない。"}, "error_tags": {"を": "対象", "に": "帰着・対象", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9297dc18-f5ac-4488-a97e-eae535564182') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35393, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「国家の安全」と「安全」を修飾する「の」で、名詞句をつなぐ。"}, {"text": "で", "is_correct": false, "explanation": "手段・場所の「で」だが、「国家で安全を守る」は国家を手段とする言い方として不自然。"}, {"text": "や", "is_correct": false, "explanation": "並列の「や」は並べる名詞が必要で、「国家や安全を守る」は文として不自然。"}, {"text": "まで", "is_correct": false, "explanation": "添加の「まで」だが、「国家まで安全を守る」は文脈と合わず不自然。"}], "correct_answer": "の", "explanations": {"の": "「国家の安全」と「安全」を修飾する「の」で、名詞句をつなぐ。", "で": "手段・場所の「で」だが、「国家で安全を守る」は国家を手段とする言い方として不自然。", "や": "並列の「や」は並べる名詞が必要で、「国家や安全を守る」は文として不自然。", "まで": "添加の「まで」だが、「国家まで安全を守る」は文脈と合わず不自然。"}, "error_tags": {"で": "手段・場所", "や": "並列", "まで": "限度・添加"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9297dc18-f5ac-4488-a97e-eae535564182') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35393, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "一つの政府によって統治され、明確な境界を持つ政治的な共同体。国民によって構成され、主権を持つ。", "primary_collocate": null, "pronunciation": "こっか", "ipa": "kokːa", "syllable_count": 3, "sentences": [{"text": "独立した政府を持つ国家は、国連に加盟できます。", "target_word": "国家", "complexity_tier": "T3", "furigana": "独立[どくりつ]した政府[せいふ]を持[も]つ国家[こっか]は、国連[こくれん]に加盟[かめい]できます。", "sentence_source": "generated"}, {"text": "国家は国民を守るために、法律を作ります。", "target_word": "国家", "complexity_tier": "T3", "furigana": "国家[こっか]は国民[こくみん]を守[まも]るために、法律[ほうりつ]を作[つく]ります。", "sentence_source": "generated"}, {"text": "この国家は、百年前に独立しました。", "target_word": "国家", "complexity_tier": "T3", "furigana": "この国家[こっか]は、百年前[ひゃくねんまえ]に独立[どくりつ]しました。", "sentence_source": "generated"}, {"text": "国家の予算は、国民が払う税金で成り立っています。", "target_word": "国家", "complexity_tier": "T3", "furigana": "国家[こっか]の予算[よさん]は、国民[こくみん]が払[はら]う税金[ぜいきん]で成[な]り立[た]っています。", "sentence_source": "generated"}, {"text": "小さな国家でも、国連では一票を持っています。", "target_word": "国家", "complexity_tier": "T3", "furigana": "小[ちい]さな国家[こっか]でも、国連[こくれん]では一票[いっぴょう]を持[も]っています。", "sentence_source": "generated"}, {"text": "国家が認めた資格がなければ、医者として働けません。", "target_word": "国家", "complexity_tier": "T3", "furigana": "国家[こっか]が認[みと]めた資格[しかく]がなければ、医者[いしゃ]として働[はたら]けません。", "sentence_source": "generated"}, {"text": "二つの国家の間で、国境についての話し合いが続いています。", "target_word": "国家", "complexity_tier": "T3", "furigana": "二[ふた]つの国家[こっか]の間[あいだ]で、国境[こっきょう]についての話[はな]し合[あ]いが続[つづ]いています。", "sentence_source": "generated"}, {"text": "国家の安全を守るのは、政府の大切な仕事です。", "target_word": "国家", "complexity_tier": "T3", "furigana": "国家[こっか]の安全[あんぜん]を守[まも]るのは、政府[せいふ]の大切[たいせつ]な仕事[しごと]です。", "sentence_source": "generated"}, {"text": "新しい国家が生まれると、他の国々がそれを認めるかどうかが問題になります。", "target_word": "国家", "complexity_tier": "T3", "furigana": "新[あたら]しい国家[こっか]が生[う]まれると、他[ほか]の国々[くにぐに]がそれを認[みと]めるかどうかが問題[もんだい]になります。", "sentence_source": "generated"}, {"text": "国家には、国民と領土と主権の三つが必要だと言われます。", "target_word": "国家", "complexity_tier": "T3", "furigana": "国家[こっか]には、国民[こくみん]と領土[りょうど]と主権[しゅけん]の三[みっ]つが必要[ひつよう]だと言[い]われます。", "sentence_source": "generated"}], "morphological_forms": [{"form": "国家", "label": "基本形"}], "register": "formal", "sense_fingerprint": "主権・領土・国民を備えた政治的共同体としての国(国家)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd0118fb7-8c88-4730-aa9e-d75a197e3036') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35393, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "国家", "is_correct": true, "explanation": "独立した政府を持つ主体で、国連に加盟できるのは国家なので合う。"}, {"text": "主権", "is_correct": false, "explanation": "主権は加盟する主体ではなく、「加盟できます」の主語にならない。"}, {"text": "領土", "is_correct": false, "explanation": "領土は国連に加盟する主体ではなく、文の主語として合わない。"}, {"text": "天候", "is_correct": false, "explanation": "天候は加盟できる主体ではなく、文の意味が通らない。"}], "explanations": {"国家": "独立した政府を持つ主体で、国連に加盟できるのは国家なので合う。", "主権": "主権は加盟する主体ではなく、「加盟できます」の主語にならない。", "領土": "領土は国連に加盟する主体ではなく、文の主語として合わない。", "天候": "天候は加盟できる主体ではなく、文の意味が通らない。"}, "sentence_index": 0, "correct_answer": "国家"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この国家は、同じ言葉と習慣を持つ一族が、川辺で代々暮らしている。", "explanation": "ここは〈民族〉の意味。国家は政府が統治する政治の共同体なので、血縁でまとまる一族の集まりを指すことはできない。"}, {"text": "この国家の子ども部屋は、いつもおもちゃで散らかっている。", "explanation": "ここは〈部屋〉の意味。国家は政治の共同体を指すので、家の中の子ども部屋の話には使わない。"}, {"text": "この会社の国家は、三つの部門に分かれている。", "explanation": "ここは〈組織〉の意味。国家は国の政治的共同体で、会社の内部の部門を指すことはできない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9297dc18-f5ac-4488-a97e-eae535564182') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35393, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "国家", "is_correct": true, "explanation": "「二つの国家」は国どうしを表し、国境についての話し合いと合う。"}, {"text": "会社", "is_correct": false, "explanation": "会社どうしが国境について話し合うことはなく、文が成り立たない。"}, {"text": "学校", "is_correct": false, "explanation": "学校どうしの間で国境の話し合いは起こらず、意味が合わない。"}, {"text": "病院", "is_correct": false, "explanation": "病院どうしが国境について話すのは不自然で、文脈と合わない。"}], "explanations": {"国家": "「二つの国家」は国どうしを表し、国境についての話し合いと合う。", "会社": "会社どうしが国境について話し合うことはなく、文が成り立たない。", "学校": "学校どうしの間で国境の話し合いは起こらず、意味が合わない。", "病院": "病院どうしが国境について話すのは不自然で、文脈と合わない。"}, "sentence_index": 6, "correct_answer": "国家"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この国家は、党員の投票で党首を選ぶ。", "explanation": "ここは〈政党〉の意味。国家には党員や党首を投票で選ぶ仕組みはないので、政党の内部の話には使わない。"}, {"text": "この国家は、会員の意見をまとめて方針を決める。", "explanation": "ここは〈団体〉の意味。国家には会員ではなく国民がいるので、会員の意見をまとめる団体の話には合わない。"}, {"text": "この国家の市役所は、市民の相談窓口を毎日開いている。", "explanation": "ここは〈都市〉の意味。市役所は地方の自治体の機関なので、国家の機関を指す言い方とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9297dc18-f5ac-4488-a97e-eae535564182') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35393, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "国家を国民の権利を守るために、法律を作ります。", "corrected_sentence": "国家は国民の権利を守るために、法律を作ります。", "error_description": "誤りは「国家を」。正しくは「国家は」で、主題を示す「は」が必要。「を」では国家が目的語になり、「守る」の主体が立たず文が崩れる。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9297dc18-f5ac-4488-a97e-eae535564182') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35393, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "国家を独立を守るのは、政府と国民の共通の務めです。", "corrected_sentence": "国家の独立を守るのは、政府と国民の共通の務めです。", "error_description": "誤りは「国家を」。正しくは「国家の」で、「独立」を修飾する「の」が必要。「を」では目的語が二つ重なり、文が成り立たない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9297dc18-f5ac-4488-a97e-eae535564182') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35394, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「大切にする」の目的語を示す。アイデンティティーを大切にするという文になる。"}, {"text": "が", "is_correct": false, "explanation": "主語を示す助詞だが、「大切にする」の目的語は『を』になるので合わない。"}, {"text": "に", "is_correct": false, "explanation": "対象を示すが、「大切にする」では『を』を使うので合わない。"}, {"text": "で", "is_correct": false, "explanation": "場所や手段を示す助詞で、「大切にする」の目的語にはならない。"}], "correct_answer": "を", "explanations": {"を": "「大切にする」の目的語を示す。アイデンティティーを大切にするという文になる。", "が": "主語を示す助詞だが、「大切にする」の目的語は『を』になるので合わない。", "に": "対象を示すが、「大切にする」では『を』を使うので合わない。", "で": "場所や手段を示す助詞で、「大切にする」の目的語にはならない。"}, "error_tags": {"が": "主語", "に": "対象・方向", "で": "場所・手段"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19836b82-001c-42e6-ba97-1d1bf9ed206d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35394, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「揺らぐ」の主語を示す。自分のアイデンティティーが揺らぐという文になる。"}, {"text": "を", "is_correct": false, "explanation": "目的語を示すが、「揺らぐ」は自動詞なので目的語を取らないので合わない。"}, {"text": "で", "is_correct": false, "explanation": "場所や手段を示すが、「揺らぐ」の主語にはならないので合わない。"}, {"text": "の", "is_correct": false, "explanation": "所有や連体修飾を示すが、文の主語を示さないので合わない。"}], "correct_answer": "が", "explanations": {"が": "「揺らぐ」の主語を示す。自分のアイデンティティーが揺らぐという文になる。", "を": "目的語を示すが、「揺らぐ」は自動詞なので目的語を取らないので合わない。", "で": "場所や手段を示すが、「揺らぐ」の主語にはならないので合わない。", "の": "所有や連体修飾を示すが、文の主語を示さないので合わない。"}, "error_tags": {"を": "目的語", "で": "場所・手段", "の": "所有・連体修飾"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19836b82-001c-42e6-ba97-1d1bf9ed206d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35394, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "自分は何者か、という自分自身についての認識。自分らしさ。", "primary_collocate": null, "pronunciation": "あいでんてぃてぃー", "ipa": "aidentitiː", "syllable_count": 9, "sentences": [{"text": "外国で暮らすと、自分のアイデンティティーを考えます。", "target_word": "アイデンティティー", "complexity_tier": "T3", "furigana": "外国[がいこく]で暮[く]らすと、自分[じぶん]のアイデンティティーを考[かんが]えます。", "sentence_source": "generated"}, {"text": "彼は、日本人としてのアイデンティティーを大切にしています。", "target_word": "アイデンティティー", "complexity_tier": "T3", "furigana": "彼[かれ]は、日本人[にほんじん]としてのアイデンティティーを大切[たいせつ]にしています。", "sentence_source": "generated"}, {"text": "名前は、その人のアイデンティティーの一部です。", "target_word": "アイデンティティー", "complexity_tier": "T3", "furigana": "名前[なまえ]は、その人[ひと]のアイデンティティーの一部[いちぶ]です。", "sentence_source": "generated"}, {"text": "子どものころ、自分のアイデンティティーが分からず悩みました。", "target_word": "アイデンティティー", "complexity_tier": "T3", "furigana": "子[こ]どものころ、自分[じぶん]のアイデンティティーが分[わ]からず悩[なや]みました。", "sentence_source": "generated"}, {"text": "方言は、この町の人々のアイデンティティーを表しています。", "target_word": "アイデンティティー", "complexity_tier": "T4", "furigana": "方言[ほうげん]は、この町[まち]の人々[ひとびと]のアイデンティティーを表[あらわ]しています。", "sentence_source": "generated"}, {"text": "アイデンティティーを失うと、自分が誰か分からなくなります。", "target_word": "アイデンティティー", "complexity_tier": "T3", "furigana": "アイデンティティーを失[うしな]うと、自分[じぶん]が誰[だれ]か分[わ]からなくなります。", "sentence_source": "generated"}, {"text": "私は、アイデンティティーについて作文を書きました。", "target_word": "アイデンティティー", "complexity_tier": "T3", "furigana": "私[わたし]は、アイデンティティーについて作文[さくぶん]を書[か]きました。", "sentence_source": "generated"}, {"text": "転校して友だちと離れ、自分のアイデンティティーが揺らぎました。", "target_word": "アイデンティティー", "complexity_tier": "T4", "furigana": "転校[てんこう]して友[とも]だちと離[はな]れ、自分[じぶん]のアイデンティティーが揺[ゆ]らぎました。", "sentence_source": "generated"}, {"text": "彼女は、アイデンティティーを探す旅に出ました。", "target_word": "アイデンティティー", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は、アイデンティティーを探[さが]す旅[たび]に出[で]ました。", "sentence_source": "generated"}, {"text": "母国の言葉は、私のアイデンティティーを支えています。", "target_word": "アイデンティティー", "complexity_tier": "T4", "furigana": "母国[ぼこく]の言葉[ことば]は、私[わたし]のアイデンティティーを支[ささ]えています。", "sentence_source": "generated"}], "morphological_forms": [{"form": "アイデンティティー", "label": "基本形"}], "register": "標準（丁寧体）", "sense_fingerprint": "自分は誰なのかという、その人らしさ", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a823ebd7-d8b4-4527-9bc5-56dd45c51f93') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35394, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "アイデンティティー", "is_correct": true, "explanation": "「自分は何者か」という意味の語で、「自分の〜を考えます」に入る。"}, {"text": "ウイルス", "is_correct": false, "explanation": "病原体の名前で、自分について考える文脈には入らない。"}, {"text": "ハンカチ", "is_correct": false, "explanation": "持ち物の名前で、「自分のハンカチを考えます」は文として成り立たない。"}, {"text": "サッカー", "is_correct": false, "explanation": "スポーツの名前で、自分について考える対象にはならない。"}], "explanations": {"アイデンティティー": "「自分は何者か」という意味の語で、「自分の〜を考えます」に入る。", "ウイルス": "病原体の名前で、自分について考える文脈には入らない。", "ハンカチ": "持ち物の名前で、「自分のハンカチを考えます」は文として成り立たない。", "サッカー": "スポーツの名前で、自分について考える対象にはならない。"}, "sentence_index": 0, "correct_answer": "アイデンティティー"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "空港の審査では、アイデンティティーを提示してください。", "explanation": "ここは身分証明書の意味。アイデンティティーは『自分が何者か』という意識のことで、書類は指さないので合わない。"}, {"text": "彼は毎朝のアイデンティティーとして、ジョギングを続けています。", "explanation": "ここは〈習慣〉の意味。アイデンティティーは自己認識のことで、毎日の行動の型としては使わないので合わない。"}, {"text": "彼は周りの意見に負けて、アイデンティティーを曲げてしまいました。", "explanation": "ここは〈信念〉の意味。信念は曲げるものだが、アイデンティティーは曲げる対象ではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19836b82-001c-42e6-ba97-1d1bf9ed206d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35394, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "アイデンティティー", "is_correct": true, "explanation": "作文の題材として、自分は何者かという意識をテーマにする語。"}, {"text": "シャンプー", "is_correct": false, "explanation": "洗髪料の名前で、作文の題材としては文が成り立たない。"}, {"text": "ゴム", "is_correct": false, "explanation": "輪ゴムなどの物の名前で、作文の題材としては不自然。"}, {"text": "ティッシュ", "is_correct": false, "explanation": "紙製品の名前で、作文の題材としては文が成り立たない。"}], "explanations": {"アイデンティティー": "作文の題材として、自分は何者かという意識をテーマにする語。", "シャンプー": "洗髪料の名前で、作文の題材としては文が成り立たない。", "ゴム": "輪ゴムなどの物の名前で、作文の題材としては不自然。", "ティッシュ": "紙製品の名前で、作文の題材としては文が成り立たない。"}, "sentence_index": 6, "correct_answer": "アイデンティティー"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "新しいクラスで、みんなの前でアイデンティティーをしました。", "explanation": "ここは〈自己紹介〉の意味。アイデンティティーは紹介するものではなく、「自己紹介をする」の代わりにならないので合わない。"}, {"text": "夏休みの計画を、アイデンティティーで立てました。", "explanation": "ここは〈方法〉の意味。アイデンティティーは自己認識のことで、計画を立てる方法や手段にはならないので合わない。"}, {"text": "今日の試験は、アイデンティティーが良くなかったです。", "explanation": "ここは〈成績・出来〉の場面。試験の出来はアイデンティティーで表さないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19836b82-001c-42e6-ba97-1d1bf9ed206d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35394, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "留学で、自分のアイデンティティーを悩みました。", "corrected_sentence": "留学で、自分のアイデンティティーに悩みました。", "error_description": "『悩む』は『〜に悩む』の形をとるので、『を』ではなく『に』が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19836b82-001c-42e6-ba97-1d1bf9ed206d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35394, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "移民の友人は、アイデンティティーで守るために努力しています。", "corrected_sentence": "移民の友人は、アイデンティティーを守るために努力しています。", "error_description": "『守る』は目的語に『を』をとるので、『で』は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19836b82-001c-42e6-ba97-1d1bf9ed206d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35395, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「守る」の目的語を示す。地域のアイデンティティーを守るという文になる。"}, {"text": "に", "is_correct": false, "explanation": "対象や方向を示すが、「守る」は目的語に『を』をとるので合わない。"}, {"text": "で", "is_correct": false, "explanation": "場所や手段を示すが、「守る」の目的語にはならないので合わない。"}, {"text": "と", "is_correct": false, "explanation": "相手や並列を示すが、「守る」の目的語にはならないので合わない。"}], "correct_answer": "を", "explanations": {"を": "「守る」の目的語を示す。地域のアイデンティティーを守るという文になる。", "に": "対象や方向を示すが、「守る」は目的語に『を』をとるので合わない。", "で": "場所や手段を示すが、「守る」の目的語にはならないので合わない。", "と": "相手や並列を示すが、「守る」の目的語にはならないので合わない。"}, "error_tags": {"に": "対象・方向", "で": "場所・手段", "と": "相手・並列"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19836b82-001c-42e6-ba97-1d1bf9ed206d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
