INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35395, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "ある個人や集団が、自分は何者であるかという認識や意識。自分らしさ。", "primary_collocate": null, "pronunciation": "あいでんてぃてぃー", "ipa": "aidentitiː", "syllable_count": 9, "sentences": [{"text": "移民の二世は、二つの文化の間でアイデンティティーに悩むことがあります。", "target_word": "アイデンティティー", "complexity_tier": "T4", "furigana": "移民[いみん]の二世[にせい]は、二[ふた]つの文化[ぶんか]の間[あいだ]でアイデンティティーに悩[なや]むことがあります。", "sentence_source": "generated"}, {"text": "この祭りは、地域のアイデンティティーを守る役割を果たしています。", "target_word": "アイデンティティー", "complexity_tier": "T4", "furigana": "この祭[まつ]りは、地域[ちいき]のアイデンティティーを守[まも]る役割[やくわり]を果[は]たしています。", "sentence_source": "generated"}, {"text": "企業は、独自のアイデンティティーを持つことで他社と差別化できます。", "target_word": "アイデンティティー", "complexity_tier": "T4", "furigana": "企業[きぎょう]は、独自[どくじ]のアイデンティティーを持[も]つことで他社[たしゃ]と差別化[さべつか]できます。", "sentence_source": "generated"}, {"text": "少数民族は、自分たちの言語にアイデンティティーを感じています。", "target_word": "アイデンティティー", "complexity_tier": "T4", "furigana": "少数民族[しょうすうみんぞく]は、自分[じぶん]たちの言語[げんご]にアイデンティティーを感[かん]じています。", "sentence_source": "generated"}, {"text": "思春期には、自分らしさ、つまりアイデンティティーを模索します。", "target_word": "アイデンティティー", "complexity_tier": "T4", "furigana": "思春期[ししゅんき]には、自分[じぶん]らしさ、つまりアイデンティティーを模索[もさく]します。", "sentence_source": "generated"}, {"text": "彼女の作品には、育った町のアイデンティティーが表れています。", "target_word": "アイデンティティー", "complexity_tier": "T4", "furigana": "彼女[かのじょ]の作品[さくひん]には、育[そだ]った町[まち]のアイデンティティーが表[あらわ]れています。", "sentence_source": "generated"}, {"text": "留学を通して、自分のアイデンティティーを見つめ直しました。", "target_word": "アイデンティティー", "complexity_tier": "T4", "furigana": "留学[りゅうがく]を通[とお]して、自分[じぶん]のアイデンティティーを見[み]つめ直[なお]しました。", "sentence_source": "generated"}, {"text": "文化の違いが、個人のアイデンティティーの形成に影響します。", "target_word": "アイデンティティー", "complexity_tier": "T4", "furigana": "文化[ぶんか]の違[ちが]いが、個人[こじん]のアイデンティティーの形成[けいせい]に影響[えいきょう]します。", "sentence_source": "generated"}, {"text": "国の歴史を学ぶと、国民のアイデンティティーが育ちます。", "target_word": "アイデンティティー", "complexity_tier": "T4", "furigana": "国[くに]の歴史[れきし]を学[まな]ぶと、国民[こくみん]のアイデンティティーが育[そだ]ちます。", "sentence_source": "generated"}, {"text": "職業が、その人のアイデンティティーのすべてではありません。", "target_word": "アイデンティティー", "complexity_tier": "T4", "furigana": "職業[しょくぎょう]が、その人[ひと]のアイデンティティーのすべてではありません。", "sentence_source": "generated"}], "morphological_forms": [{"form": "アイデンティティー", "label": "基本形"}], "register": "標準（丁寧体）", "sense_fingerprint": "個人や集団が持つ、自分は何者かという認識と自分らしさ", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a823ebd7-d8b4-4527-9bc5-56dd45c51f93') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35395, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "アイデンティティー", "is_correct": true, "explanation": "二つの文化の間で悩む対象になる、自分は何者かという意識を指す語。"}, {"text": "ワイン", "is_correct": false, "explanation": "飲み物の名前で、「〜に悩む」の対象にはならないので合わない。"}, {"text": "ハンカチ", "is_correct": false, "explanation": "持ち物の名前で、文化の間で悩む文脈には入らないので合わない。"}, {"text": "シャンプー", "is_correct": false, "explanation": "洗髪料の名前で、悩む対象としての文が成り立たないので合わない。"}], "explanations": {"アイデンティティー": "二つの文化の間で悩む対象になる、自分は何者かという意識を指す語。", "ワイン": "飲み物の名前で、「〜に悩む」の対象にはならないので合わない。", "ハンカチ": "持ち物の名前で、文化の間で悩む文脈には入らないので合わない。", "シャンプー": "洗髪料の名前で、悩む対象としての文が成り立たないので合わない。"}, "sentence_index": 0, "correct_answer": "アイデンティティー"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "空港の受付で、パスポートの代わりにアイデンティティーを見せました。", "explanation": "ここは身分証明書の意味。アイデンティティーは『自分が何者か』という意識のことで、書類の代わりにはならないので合わない。"}, {"text": "図書館で本を読んで、アイデンティティーを増やしました。", "explanation": "ここは〈知識〉の意味。アイデンティティーは自己認識のことで、本を読んで増やすものではないので合わない。"}, {"text": "彼は周りの反対に負けて、自分のアイデンティティーを撤回しました。", "explanation": "ここは〈主張〉の意味。撤回するのは主張や発言で、アイデンティティーは撤回できないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19836b82-001c-42e6-ba97-1d1bf9ed206d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35395, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "アイデンティティー", "is_correct": true, "explanation": "留学を通して見つめ直す対象になる、自分は何者かという意識を指す語。"}, {"text": "カレンダー", "is_correct": false, "explanation": "予定を書く物の名前で、自分を見つめ直す対象にはならないので合わない。"}, {"text": "ゴム", "is_correct": false, "explanation": "輪ゴムなどの物の名前で、自分を見つめ直す対象にはならないので合わない。"}, {"text": "リュック", "is_correct": false, "explanation": "かばんの名前で、自分を見つめ直す対象にはならないので合わない。"}], "explanations": {"アイデンティティー": "留学を通して見つめ直す対象になる、自分は何者かという意識を指す語。", "カレンダー": "予定を書く物の名前で、自分を見つめ直す対象にはならないので合わない。", "ゴム": "輪ゴムなどの物の名前で、自分を見つめ直す対象にはならないので合わない。", "リュック": "かばんの名前で、自分を見つめ直す対象にはならないので合わない。"}, "sentence_index": 6, "correct_answer": "アイデンティティー"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "面接の最初に、みなさんの前でアイデンティティーを紹介しました。", "explanation": "ここは〈自己紹介〉の意味。アイデンティティーは紹介するものではないので合わない。"}, {"text": "旅行の日程を、アイデンティティーで組みました。", "explanation": "ここは〈手順〉の意味。アイデンティティーは自己認識のことで、日程を組む手順にはならないので合わない。"}, {"text": "作文の評価は、アイデンティティーで決まりました。", "explanation": "ここは〈判断基準〉の意味。アイデンティティーは自己認識のことで、作文の評価を決める基準にはならないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19836b82-001c-42e6-ba97-1d1bf9ed206d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35395, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "移民の子どもは、二つの文化の間でアイデンティティーを悩みます。", "corrected_sentence": "移民の子どもは、二つの文化の間でアイデンティティーに悩みます。", "error_description": "『悩む』は『〜に悩む』の形をとるので、『を』は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19836b82-001c-42e6-ba97-1d1bf9ed206d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35395, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "子どもは、家族との会話からアイデンティティーで育てます。", "corrected_sentence": "子どもは、家族との会話からアイデンティティーを育てます。", "error_description": "『育てる』は『〜を育てる』の形をとるので、『で』は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19836b82-001c-42e6-ba97-1d1bf9ed206d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35407, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「彼の思想」で、思想の持ち主を示します。"}, {"text": "を", "is_correct": false, "explanation": "「彼を思想は」は文として成り立ちません。"}, {"text": "で", "is_correct": false, "explanation": "「彼で思想は」は文として成り立ちません。"}, {"text": "へ", "is_correct": false, "explanation": "「彼へ思想は」は文として成り立ちません。"}], "correct_answer": "の", "explanations": {"の": "「彼の思想」で、思想の持ち主を示します。", "を": "「彼を思想は」は文として成り立ちません。", "で": "「彼で思想は」は文として成り立ちません。", "へ": "「彼へ思想は」は文として成り立ちません。"}, "error_tags": {"を": "object_marker", "で": "means_or_place", "へ": "direction"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b982e327-9a99-4c05-941a-7fa6bf794c1e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35407, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「思想を比べる」で、比べる対象を示します。"}, {"text": "へ", "is_correct": false, "explanation": "「二つの思想へ比べてみた」は文として成り立ちません。"}, {"text": "が", "is_correct": false, "explanation": "「二つの思想が比べてみた」は文として成り立ちません。"}, {"text": "の", "is_correct": false, "explanation": "「二つの思想の比べてみた」は文として成り立ちません。"}], "correct_answer": "を", "explanations": {"を": "「思想を比べる」で、比べる対象を示します。", "へ": "「二つの思想へ比べてみた」は文として成り立ちません。", "が": "「二つの思想が比べてみた」は文として成り立ちません。", "の": "「二つの思想の比べてみた」は文として成り立ちません。"}, "error_tags": {"へ": "direction", "が": "subject_marker", "の": "possessive"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b982e327-9a99-4c05-941a-7fa6bf794c1e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35407, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "人間の頭の中にある、世界や社会についてのまとまった考え方や意見。", "primary_collocate": null, "pronunciation": "しそう", "ipa": "ɕisoː", "syllable_count": 3, "sentences": [{"text": "ミニマリストの思想に基づき、必要な要素だけを残すことで、居住者はより穏やかな日常を送ることができます。", "target_word": "思想", "complexity_tier": "T6", "furigana": "ミニマリストの思想[しそう]に基[もと]づき、必要[ひつよう]な要素[ようそ]だけを残[のこ]すことで、居住者[きょじゅうしゃ]はより穏[おだ]やかな日常[にちじょう]を送[おく]ることができます。", "sentence_source": "mined"}, {"text": "彼の思想は面白いです。", "target_word": "思想", "complexity_tier": "T2", "furigana": "彼[かれ]の思想[しそう]は面白[おもしろ]いです。", "sentence_source": "generated"}, {"text": "新しい思想を学びます。", "target_word": "思想", "complexity_tier": "T2", "furigana": "新[あたら]しい思想[しそう]を学[まな]びます。", "sentence_source": "generated"}, {"text": "この思想は多くの人に影響した。", "target_word": "思想", "complexity_tier": "T3", "furigana": "この思想[しそう]は多[おお]くの人[ひと]に影響[えいきょう]した。", "sentence_source": "generated"}, {"text": "昔の思想を本で読んでいる。", "target_word": "思想", "complexity_tier": "T3", "furigana": "昔[むかし]の思想[しそう]を本[ほん]で読[よ]んでいる。", "sentence_source": "generated"}, {"text": "思想の自由は大切だと思う。", "target_word": "思想", "complexity_tier": "T3", "furigana": "思想[しそう]の自由[じゆう]は大切[たいせつ]だと思[おも]う。", "sentence_source": "generated"}, {"text": "彼の思想を知れば、行動の理由がわかる。", "target_word": "思想", "complexity_tier": "T4", "furigana": "彼[かれ]の思想[しそう]を知[し]れば、行動[こうどう]の理由[りゆう]がわかる。", "sentence_source": "generated"}, {"text": "二つの思想を比べてみた。", "target_word": "思想", "complexity_tier": "T3", "furigana": "二[ふた]つの思想[しそう]を比[くら]べてみた。", "sentence_source": "generated"}, {"text": "戦争で思想を変えられた人もいる。", "target_word": "思想", "complexity_tier": "T4", "furigana": "戦争[せんそう]で思想[しそう]を変[か]えられた人[ひと]もいる。", "sentence_source": "generated"}, {"text": "思想と行動が一致していない。", "target_word": "思想", "complexity_tier": "T3", "furigana": "思想[しそう]と行動[こうどう]が一致[いっち]していない。", "sentence_source": "generated"}], "morphological_forms": [{"form": "思想家", "label": "派生"}, {"form": "思想的", "label": "派生"}, {"form": "思想界", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 世界や社会への体系的な考え方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5be06c00-e07b-4845-a5a1-5b9d6c46fb56') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
